const MAX_REQUEST_SIZE: usize = 1024 * 1024;
/// Default for `--max-connections` (issue #126): previously a fixed
/// constant with no way to tune it — small deployments couldn't lower
/// it, and large ones couldn't raise it.
pub(crate) const DEFAULT_MAX_CONNECTIONS: usize = 1024;
/// Default for `--max-connections-per-ip` (issue #126): a coarse cap on
/// how many live connections a single source IP may hold at once,
/// layered under the global `--max-connections` semaphore (issue: no
/// per-source-IP limit — a single misbehaving or compromised peer could
/// otherwise claim the entire connection budget by itself, starving
/// every other client, without the global semaphore ever reporting
/// anything unusual). Deliberately coarse, not a tight per-client
/// budget: a pooled application host — many worker processes or threads
/// sharing one egress IP, or a fleet behind one NAT — can legitimately
/// hold a large number of concurrent connections to this cache, and
/// this guard exists only to stop one source from monopolising the
/// whole server, not to bound ordinary legitimate concurrency. Behind
/// NAT or on Kubernetes, where many clients share one source IP, *this*
/// — not the global cap — is the effective fleet ceiling, which is
/// exactly why it's now a flag. See `try_acquire_per_ip`.
pub(crate) const DEFAULT_MAX_CONNECTIONS_PER_IP: usize = 256;

/// The two accepted-connection caps, resolved from `--max-connections` /
/// `--max-connections-per-ip` by `main.rs` (issue #126) and threaded to
/// the global semaphore, the per-IP reservation, and the metrics gauge.
#[derive(Clone, Copy)]
pub(crate) struct ConnectionLimits {
    pub(crate) max_connections: usize,
    pub(crate) max_connections_per_ip: usize,
    /// `--max-in-flight-bytes`: the node-wide budget for what client
    /// connections hold outside the cache — see `InFlightBudget`.
    pub(crate) max_in_flight_bytes: usize,
}

impl Default for ConnectionLimits {
    fn default() -> Self {
        Self {
            max_in_flight_bytes: DEFAULT_MAX_IN_FLIGHT_BYTES,
            max_connections: DEFAULT_MAX_CONNECTIONS,
            max_connections_per_ip: DEFAULT_MAX_CONNECTIONS_PER_IP,
        }
    }
}

/// Default for `--max-memory` (issue #19): the cap was previously a fixed
/// constant with no way to tune it, even though the capacity planner
/// (`tools/capacity-planner.html`) already modeled capacity as a function
/// of it.
pub(crate) const MAX_CACHE_MEMORY_BYTES: usize = 256 * 1024 * 1024;

/// Default for `--max-in-flight-bytes`: what client connections may hold
/// outside the cache budget, node-wide — reply buffers being written and
/// receive buffers of requests still arriving. `--max-memory` bounds the
/// cache only; these were bounded by nothing but the connection count,
/// and the product was the problem: 1,024 connections each holding a
/// 1 MiB unfinished frame, or a hundred holding a 16 MiB `M` reply they
/// do not read, is more than the 1 GiB task the deployment guides size
/// a 512 MiB cache into. Half of that cache budget; a task's memory has
/// to cover `--max-memory` plus this plus the process's own headroom.
pub(crate) const DEFAULT_MAX_IN_FLIGHT_BYTES: usize = 256 * 1024 * 1024;

/// Floor on `--max-in-flight-bytes`: one request-sized frame. A charge
/// above the budget takes the whole budget and runs alone, so a smaller
/// budget would serialise every large request rather than bound memory.
pub(crate) const MIN_MAX_IN_FLIGHT_BYTES: usize = MAX_REQUEST_SIZE;

/// A node-wide budget of bytes that client connections hold outside the
/// cache: a semaphore whose permits are bytes. A connection charges a
/// reply's bytes before encoding it (the encoded copy is what the write
/// holds for up to `WRITE_TIMEOUT` while a client does not read) and a
/// receive buffer's growth beyond `REQUEST_BUFFER_SHRINK_THRESHOLD`
/// before allocating it (an unfinished frame is held until the frame
/// deadline), and releases both as soon as the bytes are gone. A
/// multi-key frame also charges `MULTI_KEY_FRAME_BYTES_PER_KEY` for each
/// of its keys, held until its reply is written. A cost
/// above the budget is clamped to it, so such a request takes the whole
/// budget and runs alone rather than waiting forever; a connection that
/// cannot get its charge in time is closed, the way a stalled write or a
/// trickled frame is.
#[derive(Clone)]
pub(crate) struct InFlightBudget {
    permits: Arc<Semaphore>,
    bytes: usize,
}

impl InFlightBudget {
    pub(crate) fn new(bytes: usize) -> Self {
        Self {
            permits: Arc::new(Semaphore::new(bytes)),
            bytes,
        }
    }

    /// Reserves `cost` bytes (clamped to the budget), waiting for them.
    async fn charge(&self, cost: usize) -> tokio::sync::OwnedSemaphorePermit {
        self.charge_exact(self.clamp(cost)).await
    }

    /// `charge` without the clamp, for a holder that grows its charge in
    /// steps and clamps the total itself (`handle_connection`'s receive
    /// buffer) — clamping each step would let one holder ask for more
    /// than exists, waiting for itself.
    async fn charge_exact(&self, cost: usize) -> tokio::sync::OwnedSemaphorePermit {
        let permits = u32::try_from(cost).unwrap_or(u32::MAX);
        Arc::clone(&self.permits)
            .acquire_many_owned(permits)
            .await
            .expect("the in-flight budget is never closed")
    }

    /// The most one holder can charge: a cost above the budget takes
    /// all of it.
    fn clamp(&self, cost: usize) -> usize {
        cost.min(self.bytes)
    }

    #[cfg(test)]
    fn available(&self) -> usize {
        self.permits.available_permits()
    }
}

/// The bytes a reply's encoded copy will hold: the values of a `V` (a
/// `G`'s or a get-and-touch's) or `M`; every other reply is a short header
/// and is not charged.
fn reply_bytes(response: &Response) -> usize {
    match response {
        Response::Value(value) | Response::Touched(value, _) => value.len(),
        Response::Multi(entries) => entries
            .iter()
            .map(|entry| match entry {
                MultiEntry::Value(value) => value.len(),
                MultiEntry::Miss | MultiEntry::WrongNode => 0,
            })
            .sum(),
        _ => 0,
    }
}

/// What a multi-key frame (`m`, `o`, `y`) is charged against the in-flight
/// budget for each key, on top of its receive buffer and its reply. The
/// parser builds the key list (a `Bytes` handle, 32 bytes, per key) and the
/// arm then builds the hashes, the owned and forwarded splits, the result
/// vector and the reply entries. A frame of one-byte keys carries about
/// 350,000 keys in its 1 MiB, so that is tens of megabytes of working
/// memory that the buffer's own charge (about 1 MiB) does not account for.
/// Measured on the release build, a single frame costs 185 bytes per key
/// (`m`, `y`) to 194 (`o`) of resident memory at its peak; 256 covers that
/// with room for the allocator.
const MULTI_KEY_FRAME_BYTES_PER_KEY: usize = 256;

/// What an `o` frame adds to `MULTI_KEY_FRAME_BYTES_PER_KEY` for each key:
/// the second vector of handles, one per value.
const MULTI_SET_VALUE_BYTES_PER_KEY: usize = 32;

/// Charges a multi-key frame's per-key working memory against the
/// in-flight budget; the caller holds the permit until the reply is
/// written. It is called before the parser builds the frame's key vectors
/// (`parse_resumable`'s `ParseError::ChargeRequired`), so a connection
/// waiting here holds no uncharged per-key memory. A frame costing more
/// than the whole budget takes all of it and runs alone — the connection's
/// own receive-buffer charge is part of what it already holds, so it asks
/// only for the rest and does not wait for itself. Waits at most
/// `WRITE_TIMEOUT`, like a reply, and fails the connection if the budget
/// does not free in that time.
async fn charge_multi_key_frame(
    config: &ConnectionConfig,
    receive_charged: usize,
    keys: usize,
    values: bool,
) -> io::Result<tokio::sync::OwnedSemaphorePermit> {
    let per_key = MULTI_KEY_FRAME_BYTES_PER_KEY
        + if values {
            MULTI_SET_VALUE_BYTES_PER_KEY
        } else {
            0
        };
    let cost = keys.saturating_mul(per_key);
    let cost = config
        .in_flight_bytes
        .clamp(cost.saturating_add(receive_charged))
        .saturating_sub(receive_charged);
    timeout(WRITE_TIMEOUT, config.in_flight_bytes.charge_exact(cost))
        .await
        .map_err(|_| {
            io::Error::new(
                io::ErrorKind::TimedOut,
                "in-flight byte budget exhausted while serving a request",
            )
        })
}

/// Encodes and writes a reply that may carry values, holding its bytes
/// against the in-flight budget from before the encoded copy exists
/// until it has been written. Waits at most `WRITE_TIMEOUT` for the
/// budget — the same bound a stalled write gets — and fails the
/// connection like one if it runs out.
async fn write_reply(
    stream: &mut ServerStream,
    config: &ConnectionConfig,
    response: &Response,
    tag: Option<u32>,
) -> io::Result<()> {
    let bytes = reply_bytes(response);
    let _charge = if bytes == 0 {
        None
    } else {
        Some(
            timeout(WRITE_TIMEOUT, config.in_flight_bytes.charge(bytes))
                .await
                .map_err(|_| {
                    io::Error::new(
                        io::ErrorKind::TimedOut,
                        "in-flight byte budget exhausted while answering",
                    )
                })?,
        )
    };
    write_response(stream, &encode_response(response, tag)).await
}
/// How long a connection may go without completing a full request before
/// `handle_connection` disconnects it. Slowloris resistance: the deadline
/// this bounds is anchored to the last time a full command was *parsed*
/// (or to accept-time, before any command has completed) — not to the
/// last byte read. Resetting it on every read, as an earlier version did,
/// let a client that trickles in one byte just under this interval apart
/// hold a `DEFAULT_MAX_CONNECTIONS` permit forever without ever finishing a
/// request. The practical consequence: a legitimate request must arrive
/// in full within this long of the previous one completing, not merely
/// send *some* bytes that often.
const IDLE_TIMEOUT: Duration = Duration::from_secs(60);
/// While a connection to a node that requires a secret has not yet
/// authenticated, the most it may have buffered without completing its
/// `A` frame (mirrors `nanocached-discovery`'s own 4096-byte request cap
/// before a peer is identified). Before this, an unauthenticated
/// connection could make the node buffer — and, for an `M`, span-index —
/// up to `MAX_REQUEST_SIZE` (1 MiB) before the `authenticated` check ever
/// ran, times up to `DEFAULT_MAX_CONNECTIONS` connections. Only an `A`
/// frame is acceptable first (every legitimate peer — SDKs, the proxy,
/// discovery, other nodes — authenticates before anything else), so this
/// only bounds `A`'s own header and secret; once it completes, whatever
/// the client pipelined after it is subject to `MAX_REQUEST_SIZE` as
/// usual. Does not apply when no secret is configured.
pub(crate) const UNAUTHENTICATED_MAX_REQUEST_SIZE: usize = 4096;

/// Whether an `A` frame carrying a secret of `secret_len` bytes fits
/// `UNAUTHENTICATED_MAX_REQUEST_SIZE` (header sized for the longest form,
/// `A <len> T R`). `main` refuses to start with a secret that doesn't: no
/// peer could authenticate against it any more. (The discovery server
/// has always had the same 4096-byte request cap, so a secret that long
/// could not be shared with it either.)
pub(crate) fn auth_frame_fits(secret_len: usize) -> bool {
    format!("A {secret_len} T R\n").len() + secret_len <= UNAUTHENTICATED_MAX_REQUEST_SIZE
}
/// Bounds a response write (issue #4) — see `write_response`. Shorter
/// than `IDLE_TIMEOUT`: that one tolerates a normal gap between a
/// client's requests, but a peer that has simply stopped draining its
/// receive buffer is a distinct failure that shouldn't get to hold a
/// `DEFAULT_MAX_CONNECTIONS` permit for as long as an idle-but-otherwise-fine
/// connection is allowed to sit.
const WRITE_TIMEOUT: Duration = Duration::from_secs(10);
/// Base and per-entry components of how long after this node's own
/// handoff completes it keeps forwarding concurrent writes to the joiner
/// (issue #3) — sized the same way, and for the same reason, as
/// discovery's own size-derived migration timeout (size-derived migration timeout):
/// by the time it elapses the join has either completed cluster-wide
/// (the joiner is in `L`, clients route to it directly) or been
/// abandoned (an `X` cleared the slot), and a bigger handoff needs more
/// of either to happen. See `forwarding_grace`.
const FORWARDING_GRACE_BASE: Duration = Duration::from_secs(60);
const FORWARDING_GRACE_PER_ENTRY: Duration = Duration::from_millis(5);

/// This node's own size-derived forwarding grace (size-derived migration timeout),
/// computed from how many entries `run_migration` actually sent as part
/// of the handoff `entries_sent` came from — never anything reported by
/// another ready node. Saturates rather than overflows for a
/// pathologically large count.
fn forwarding_grace(entries_sent: usize) -> Duration {
    FORWARDING_GRACE_BASE
        + FORWARDING_GRACE_PER_ENTRY.saturating_mul(entries_sent.min(u32::MAX as usize) as u32)
}
/// How often the staged node join active-deletion sweep runs. See `run_sweep`.
const SWEEP_INTERVAL: Duration = Duration::from_secs(5);
/// Issue #582: how often `run_reclaim` looks for copies this node no
/// longer owns, and how long a copy must have been unowned — under every
/// membership discovery published in that time, see `RingHistory` — before
/// it goes. The grace is above the liveness eviction window (15 s), the
/// heartbeat (5 s) and a decommission drain budget, so a membership that
/// flips back (a joiner evicted, a leave that never completed) keeps the
/// copy live; a forwarding window still open on this node postpones the
/// pass altogether (`reclaim_checks`).
const RECLAIM_INTERVAL: Duration = Duration::from_secs(30);
const RECLAIM_GRACE: Duration = Duration::from_secs(120);
const SHUTDOWN_TIMEOUT: Duration = Duration::from_secs(10);
/// Outer bound on how long `run` waits, after the connections are drained,
/// for the heartbeat task to finish — it also carries any in-flight
/// re-replication and its roster fetch. Those are shutdown-aware, but a
/// leg they are mid-way through is only bounded by its own
/// `OUTBOUND_IO_TIMEOUT`, so without this one unresponsive peer could hold
/// the process past `SHUTDOWN_TIMEOUT` (and an orchestrator's stop grace,
/// which then kills it uncleanly) for a whole leg or more. A healthy task
/// finishes in well under a second; past this it is aborted — everything it
/// does is retried or recomputed after a restart.
const HEARTBEAT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
/// Tenth-pass audit (2026-09-02): how long the operator-override path (a
/// second Ctrl-C/SIGTERM while a decommission is draining, issue #407)
/// waits for `run_decommission`'s task to notice `shutdown_rx` and return
/// on its own — so it still gets a chance to send its `V` (clean
/// membership leave) — before that path gives up and aborts the task
/// outright. Short: every point `run_decommission` checks the signal at
/// is itself bounded by at most ~100ms sleeps, so a well-behaved task
/// should never need close to this long.
const DECOMMISSION_OVERRIDE_GRACE: Duration = Duration::from_secs(2);
const TLS_HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(10);

/// Issue #1028: the per-connection log lines (`INFO accepted connection
/// from …`, `WARN connection error from …`, the TLS handshake failures)
/// are each written at most this many times a second; the rest are counted
/// and reported in one summary line. Without the bound a connection flood
/// within the connection caps produced log volume proportional to the
/// flood, and since `println!` blocks the runtime thread, a log pipe that
/// pushed back stalled every request behind it. Accepts and errors have
/// separate budgets so a flood of one never hides the other.
const CONNECTION_LOG_LINES_PER_SECOND: u32 = 50;
static ACCEPT_LOG: LogLimiter =
    LogLimiter::new(CONNECTION_LOG_LINES_PER_SECOND, Duration::from_secs(1));
static CONNECTION_ERROR_LOG: LogLimiter =
    LogLimiter::new(CONNECTION_LOG_LINES_PER_SECOND, Duration::from_secs(1));
/// Bounds each individual outbound dial, write, and ack read this node
/// makes toward another node — the migration handoff (`run_migration`) and
/// the concurrent forwarding of client `S`/`D` to a joiner
/// (`set_on_joining_node`/`delete_on_joining_node`). Without it, a joiner
/// that accepts TCP but never answers (crashed-but-socket-open, a
/// blackholed route, no keepalive configured) blocks a single leg (the
/// dial, the TLS handshake, the auth round trip, or the write/ack)
/// forever while it still holds a `DEFAULT_MAX_CONNECTIONS` permit; enough such
/// requests during one stalled migration exhaust every permit. Mirrors
/// discovery's own `OUTBOUND_IO_TIMEOUT`.
///
/// This is a *per-leg* bound, not a bound on the whole forwarding call —
/// `connect_and_authenticate` (dial + optional TLS + optional auth) and
/// `send_set`/the delete equivalent each apply it separately, so a joiner
/// that's merely slow (rather than fully unresponsive) at every leg could
/// still stack up to several multiples of this before failing. See
/// `FORWARD_TIMEOUT` for the bound that actually caps the whole call.
const OUTBOUND_IO_TIMEOUT: Duration = Duration::from_secs(10);
/// Caps the *entire* forward-to-joiner operation — dial, TLS, auth, and
/// the write/ack — that `set_on_joining_node`/`delete_on_joining_node`
/// run synchronously inside a client's connection task while a migration
/// is forwarding concurrent writes (see the `S`/`D` handling in
/// `handle_connection`). Without this outer bound, those calls only had
/// `OUTBOUND_IO_TIMEOUT` applied per leg (connect, then TLS, then auth,
/// then the set/delete round trip), so a joiner that's merely slow — not
/// unresponsive — at every leg could stall the client's whole pipeline
/// for close to 4x `OUTBOUND_IO_TIMEOUT`. Set equal to `OUTBOUND_IO_TIMEOUT`
/// so the worst case for a client write during migration is one multiple
/// of it, not several; `run_migration`'s own connection (a background
/// task, not inline with a client) intentionally keeps the per-leg
/// bounds instead, since it already retries per `KEY_TRANSFER_ATTEMPTS`
/// and stalling it doesn't hold a client's connection open.
const FORWARD_TIMEOUT: Duration = Duration::from_secs(10);
/// Capacity of `ConnectionConfig::forward_tx`, the channel the per-target
/// forward drainers (`drain_forward_queue`) are handed to `run` through
/// (issue #219). A drainer is only handed over when a target's queue goes
/// from idle to active, so this channel carries a handful of items — one
/// per target being forwarded to, which is the joiner of the current
/// handoff or the entrants of a decommission — not one per write. The
/// capacity is generous for that; it is the channel `spawn_forward`'s
/// waiter path (see `MAX_PENDING_FORWARD_WAITERS`) backs up if a burst of
/// activations ever finds it full.
const FORWARD_CHANNEL_CAPACITY: usize = 256;
/// Caps the number of detached "waiter" tasks `spawn_forward` may have
/// outstanding at once — see `PENDING_FORWARD_WAITERS`. A drainer that
/// finds `forward_tx` full is not simply dropped (the target's queued
/// writes would then never be sent): a waiter task blocks on the channel's
/// ordinary `send(...).await` in the background until a slot frees up, so
/// the connection that triggered the forward still never blocks. This
/// bound exists only to cap task growth in a pathological case; past it
/// the queue is marked idle again (`ForwardQueues::deactivate`) so the
/// next forward to that target re-activates it, rather than leaving a
/// queue that nothing drains.
const MAX_PENDING_FORWARD_WAITERS: usize = 4096;
const READ_CHUNK_SIZE: usize = 1024;
/// How many times `run_migration` tries to transfer a single key to the
/// joining node (reconnecting between tries) before giving up on the
/// whole migration. See `run_migration`'s own doc comment.
const KEY_TRANSFER_ATTEMPTS: u32 = 3;
/// Bound on `wait_for_migration_slot_to_clear`'s poll for a still-
/// transferring handoff to actually unwind and drop its slot after `X`
/// sets `abort_requested` — see that function's own doc comment. Kept
/// *under* discovery's `OUTBOUND_IO_TIMEOUT` (10s, the time it waits
/// for the `X` ack before giving up on this node and moving on): an ack
/// that lands after that is one discovery never reads, so waiting longer
/// buys nothing — the slot-clearing this covers is the common case where
/// `run_migration` is between keys and sees `abort_requested` within one
/// key's send; a send stuck on an unresponsive joiner can hold the slot
/// for up to `KEY_TRANSFER_ATTEMPTS` × `OUTBOUND_IO_TIMEOUT` (30s), and
/// that case is left to `MigrationGuard::new`'s generation check.
const MIGRATION_ABANDON_DRAIN_WAIT: Duration = Duration::from_secs(8);
/// Issue #7: `handle_connection`'s read buffer grows (via `reserve`) to fit
/// whatever request it's mid-receiving, up to `MAX_REQUEST_SIZE`, but never
/// shrinks back on its own — a connection that ever sent one large request
/// keeps that capacity allocated for the rest of its (possibly long) life.
/// Once the buffer is fully drained (empty) and its capacity exceeds this,
/// it's reallocated back down rather than kept around on the chance of
/// another large request. Well above ordinary command sizes so typical
/// traffic never churns an allocation on every drained buffer.
const REQUEST_BUFFER_SHRINK_THRESHOLD: usize = 64 * 1024;
/// Tenth-pass audit (2026-09-02): once `ActiveMigration::pending_clears`
/// would hold more distinct namespaces than this, it degrades to a single
/// clear-all instead — see `PendingClears`.
const MAX_PENDING_CLEAR_NAMESPACES: usize = 1024;
/// The same degradation once the queued namespaces' *bytes* exceed this.
/// A queued namespace is a slice of the client's `c` frame, up to the
/// request-size limit, so the count cap alone bounded the queue at
/// 1,024 × ~1 MiB: one connection clearing distinct 1 MB namespaces
/// during a stalled handoff grew the node by a gigabyte, which the
/// deployment guides' 1 GiB task does not survive. Sixteen request-sized
/// frames is far more than any real set of namespaces cleared during
/// one handoff and small against any task size.
const MAX_PENDING_CLEAR_BYTES: usize = 16 * MAX_REQUEST_SIZE;

/// What one forward target's queue (`TargetQueue`) may hold, in the bytes
/// its writes pin (`TargetQueue::bytes`), before a connection with a
/// write for that target waits for room instead of queuing it. Per
/// target, not per node: a joiner that has stopped answering bounds what
/// its own queue costs, and what is queued for it waits in the clients
/// rather than in this process. The queue used to be unbounded, and a
/// client write holds slices of its request frame, so 186 tiny writes
/// under a 1 MB namespace queued for a paused joiner took a 256 MiB node
/// down.
const MAX_FORWARD_QUEUE_BYTES: usize = 64 * 1024 * 1024;

/// What a queued write costs beyond its key and value bytes: its
/// `OwnedForwardedWrite`, its `BTreeMap` node and its coalescing slot —
/// about 320 bytes per pair of a queued `o` frame, measured (45 MB of
/// queue for 140,000 pairs).
const FORWARD_ENTRY_OVERHEAD_BYTES: usize = 320;

/// Whether one frame of `size` bytes is over `MAX_REQUEST_SIZE`. A bound
/// on a frame, not on the receive buffer: `handle_connection` applies it
/// to the frame `parse` took, or to the front frame still arriving, never
/// to the buffer after a read (which also holds what was pipelined
/// behind that frame).
fn request_is_too_large(size: usize) -> bool {
    size > MAX_REQUEST_SIZE
}

/// A connection this process accepted, plaintext or TLS-terminated.
type ServerStream = infra::MaybeTls<TcpStream, tokio_rustls::server::TlsStream<TcpStream>>;
/// A connection this process opened outbound, plaintext or TLS-secured.
type ClientStream = infra::MaybeTls<TcpStream, tokio_rustls::client::TlsStream<TcpStream>>;

struct CacheRequest {
    command: Command,
    response_tx: oneshot::Sender<Response>,
}

/// A `run_migration` or `forward_with_retries` invocation, boxed so
/// `handle_connection` can hand it to `run`'s own loop over
/// `ConnectionConfig::migration_tx`/`forward_tx` instead of spawning it
/// directly — see those fields' doc comments for why.
type MigrationTask = Pin<Box<dyn Future<Output = ()> + Send>>;

/// Issue #266: a `spawn_or_supersede_rereplication` invocation, boxed so
/// `register_with_discovery` can hand it to `send_heartbeats`'s own
/// `JoinSet` over its `rereplication_tx` channel — same shape and
/// reasoning as `MigrationTask`, just a different producer/consumer pair.
type RereplicationTask = Pin<Box<dyn Future<Output = ()> + Send>>;

/// Per-connection settings that don't change once `run` starts, grouped so
/// `dispatch_connection`/`handle_connection` take one value instead of two.
#[derive(Clone)]
struct ConnectionConfig {
    idle_timeout: Duration,
    auth_secret: Option<Bytes>,
    /// The node-wide in-flight byte budget this connection charges its
    /// reply and receive buffers against.
    in_flight_bytes: InFlightBudget,
    /// When set, every accepted connection must complete a TLS handshake
    /// before speaking the cache protocol; there is no plaintext fallback.
    tls_acceptor: Option<TlsAcceptor>,
    /// Only present when this node is configured to register with a
    /// discovery server (staged node join / node identity decoupled from address) — an `M` arriving otherwise has
    /// nowhere sensible to report `C` to and is rejected.
    node_context: Option<NodeContext>,
    /// Where `handle_connection` hands off the one singleton `run_migration`
    /// future (from an incoming `M`) for `run`'s own loop to
    /// `connection_tasks.spawn` — spawning it directly from inside a
    /// connection task (as opposed to from `run`) would leave it untracked
    /// by `connection_tasks`, so graceful shutdown couldn't wait for it (or
    /// ask it to unwind cleanly) before the process exits. Kept small
    /// (see where `run` creates it) since only one bulk migration ever
    /// runs at a time.
    ///
    /// Per-write forwards (`forward_with_retries`) go through `forward_tx`
    /// instead — see that field and issue #219 for why sharing this one
    /// channel between the two used to cause head-of-line blocking.
    migration_tx: mpsc::Sender<MigrationTask>,
    /// Where `handle_connection` hands off a `forward_with_retries` future
    /// — one per concurrent `S`/`D`/`U`/`u`/`MultiSet`/`Incr`/`k`/`x`/`c`/`F`
    /// that lands on a key mid-handoff or mid-drain — for `run`'s own loop
    /// to `connection_tasks.spawn`, same tracking reason as `migration_tx`.
    ///
    /// Issue #219: this used to be the same channel as `migration_tx`,
    /// sized for "one migration in flight". That's fine for the singleton
    /// bulk-migration task, but every per-write forward shared it too, and
    /// each can occupy a slot for up to `KEY_TRANSFER_ATTEMPTS` x
    /// `FORWARD_TIMEOUT` when the peer is slow — so a handful of stalled
    /// forwards could leave a *different* client connection's
    /// `handle_connection` blocked on `send().await`, well after that
    /// connection's own write had already been acked. Splitting the
    /// channel bounds that stall to zero: `spawn_forward` sends with
    /// `try_send`, never `.await`, so the connection that triggered a
    /// forward never blocks on this channel either way.
    ///
    /// What travels through it is a per-target drainer
    /// (`drain_forward_queue`), not an individual write: the writes
    /// themselves wait in `forward_queues`, coalesced by key, so a burst of
    /// them can never overflow this channel and nothing is dropped for
    /// want of room — see `ForwardQueues`.
    forward_tx: mpsc::Sender<MigrationTask>,
    /// The writes waiting to be forwarded to each target, one coalescing
    /// queue per target connection — see `ForwardQueues`.
    forward_queues: Arc<ForwardQueues>,
}

/// Count of `spawn_forward` waiter tasks currently blocked on
/// `forward_tx.send(...).await`, waiting for a slot `forward_tx`'s
/// consumer frees up — see `MAX_PENDING_FORWARD_WAITERS`.
static PENDING_FORWARD_WAITERS: AtomicUsize = AtomicUsize::new(0);

/// Tenth-pass follow-up (2026-09-04): forward targets whose last forward
/// failed permanently (every attempt exhausted), keyed by `(address,
/// token)` — see below for why the token is part of the key — with when
/// that happened. While an entry is younger than
/// `FORWARD_FAIL_FAST_WINDOW`, later forwards to the same target make a
/// single attempt instead of `KEY_TRANSFER_ATTEMPTS`: `forward_with_retries`
/// holds the target's connection for its whole retry sequence (so
/// same-key forwards can't reorder), which means every forward queued
/// behind one against an unreachable target would otherwise each burn
/// the full `KEY_TRANSFER_ATTEMPTS` x `FORWARD_TIMEOUT` before the next
/// got its turn. A success clears the entry, so a target that comes back
/// gets its full retry budget again from the next forward on. Bounded by
/// the number of distinct targets (joiners and leave entrants), and
/// pruned of expired entries on every insert.
///
/// Issue (migration-generation-guard, LOW): keying by address alone used
/// to let a node that restarted on the same address within
/// `FORWARD_FAIL_FAST_WINDOW` inherit its predecessor's failure marker —
/// the fresh process would get a single fail-fast attempt instead of its
/// own full `KEY_TRANSFER_ATTEMPTS` budget, even though it's a different
/// incarnation entirely and may well be reachable now. `ForwardTarget::
/// token` (the target's membership token, unique per process
/// incarnation — see that field's own doc comment) tells the two apart:
/// a restart always registers with a new token, so keying on both means a
/// new incarnation always starts with a clean slate.
static RECENT_FORWARD_FAILURES: std::sync::OnceLock<Mutex<HashMap<(String, String), Instant>>> =
    std::sync::OnceLock::new();
const FORWARD_FAIL_FAST_WINDOW: Duration = Duration::from_secs(30);

fn recent_forward_failures() -> &'static Mutex<HashMap<(String, String), Instant>> {
    RECENT_FORWARD_FAILURES.get_or_init(|| Mutex::new(HashMap::new()))
}

/// How many attempts the next forward to `(addr, token)` gets — see
/// `RECENT_FORWARD_FAILURES`.
fn forward_attempts_for(addr: &str, token: &str) -> u32 {
    let failed_recently = recent_forward_failures()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(&(addr.to_string(), token.to_string()))
        .is_some_and(|failed_at| failed_at.elapsed() < FORWARD_FAIL_FAST_WINDOW);
    if failed_recently {
        1
    } else {
        KEY_TRANSFER_ATTEMPTS
    }
}

fn record_forward_failure(addr: &str, token: &str) {
    let now = Instant::now();
    let mut failures = recent_forward_failures()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    failures.retain(|_, failed_at| now.duration_since(*failed_at) < FORWARD_FAIL_FAST_WINDOW);
    failures.insert((addr.to_string(), token.to_string()), now);
}

fn clear_forward_failure(addr: &str, token: &str) {
    recent_forward_failures()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .remove(&(addr.to_string(), token.to_string()));
}

/// Queues a per-write forward (a `Set`/`Delete`/`Clear` racing a migration
/// or decommission drain) for `target` and makes sure a drainer is running
/// for it. Never drops the write, so the joiner/entrant does not miss it,
/// and never waits for the send itself (see issue #219) — but it does
/// wait for room in the target's queue when `MAX_FORWARD_QUEUE_BYTES` is
/// reached, which is why every caller runs it before writing the
/// client's response: a client whose write cannot be queued yet does not
/// get its ack yet, and the backlog waits in the clients, not here.
async fn spawn_forward(
    config: &ConnectionConfig,
    node_context: NodeContext,
    target: ForwardTarget,
    write: OwnedForwardedWrite,
) {
    enqueue_forwards(config, node_context, target, std::iter::once(write)).await;
}

/// What a client write left on this node, as a forward carries it: the
/// literal result, never the command that produced it. An `i`, `k` or `x`
/// is not replayed on the receiving node — a joiner that already holds the
/// key from an earlier transfer would double-apply the increment, and one
/// re-evaluating a condition against its own copy could reach a different
/// outcome than the primary just did — so those forward as the `Set` or
/// `Delete` they resulted in. A `t` is idempotent and could be replayed,
/// but a joiner may not hold the key yet and would drop it, and a frame of
/// its own would need a handoff form, a membership token and a slot in
/// the coalescing queue that must not replace a queued `Set`; it forwards
/// as the `Set` it amounts to, the value it left with its new TTL.
enum ForwardedResult {
    Set { value: Bytes, ttl: Option<Duration> },
    Delete,
}

/// Forwards a client write's `result` for `key` to every node that must
/// see it while a membership change is in flight, in this order:
///
/// * The joiner of a staged node join, if the key is one an in-progress
///   handoff is moving to it — see `migration_targets_for`. Handed to
///   `run`'s own loop via `forward_tx` (mirroring the `M` handler, which
///   uses `migration_tx`), not awaited inline — see
///   `forward_with_retries`'s own doc comment for why.
/// * The key's post-leave entrant of a decommission in flight (issue #124),
///   or the owner an eviction promoted — see `handoff_targets_for`. As a
///   `U`/`u`, not a plain `S`/`D`: until the post-leave roster publishes
///   the entrant doesn't own the key yet and answers `S` with `W`.
///
/// Every single-key client write (`S`, `D`, `i`, `k`, `x`, `t`) goes through
/// here, so one of them cannot forget either forward by omission (the
/// bulk `o` once did, issue #176). Two things deliberately do not: the
/// bulk `o` groups its keys per target and queues them with
/// `enqueue_forwards`, and a handoff frame this node received (`U`, `u`)
/// follows its own rules (`unconfirmed_join_target_for`, and an
/// `if_absent` that is passed on).
async fn forward_result(config: &ConnectionConfig, key: &Key, result: ForwardedResult) {
    let Some(node_context) = &config.node_context else {
        return;
    };

    for target in migration_targets_for(node_context, key) {
        let write = match &result {
            ForwardedResult::Set { value, ttl } => OwnedForwardedWrite::Set {
                key: key.clone(),
                value: value.clone(),
                ttl: *ttl,
            },
            ForwardedResult::Delete => OwnedForwardedWrite::Delete { key: key.clone() },
        };
        spawn_forward(config, node_context.clone(), target, write).await;
    }

    for target in handoff_targets_for(node_context, key) {
        let write = match &result {
            ForwardedResult::Set { value, ttl } => OwnedForwardedWrite::HandoffSet {
                key: key.clone(),
                value: value.clone(),
                ttl: *ttl,
                if_absent: false,
            },
            ForwardedResult::Delete => OwnedForwardedWrite::HandoffDelete { key: key.clone() },
        };
        spawn_forward(config, node_context.clone(), target, write).await;
    }
}

/// `spawn_forward` for many writes to one target, under a single hold of
/// the queue lock (a `MultiSet` can carry hundreds of thousands of keys).
async fn enqueue_forwards(
    config: &ConnectionConfig,
    node_context: NodeContext,
    target: ForwardTarget,
    writes: impl IntoIterator<Item = OwnedForwardedWrite>,
) {
    let Some(id) = config
        .forward_queues
        .push(&node_context, target, writes)
        .await
    else {
        return; // a drainer is already running for this target
    };

    let drainer: MigrationTask =
        Box::pin(drain_forward_queue(Arc::clone(&config.forward_queues), id));
    match config.forward_tx.try_send(drainer) {
        Ok(()) => {}
        // The consumer (`run`'s own loop) is gone: nothing will ever drain
        // this channel again regardless of how long a waiter waited.
        Err(mpsc::error::TrySendError::Closed(_)) => {}
        Err(mpsc::error::TrySendError::Full(drainer)) => {
            if PENDING_FORWARD_WAITERS.fetch_add(1, Ordering::SeqCst) < MAX_PENDING_FORWARD_WAITERS
            {
                let forward_tx = config.forward_tx.clone();
                let queues = Arc::clone(&config.forward_queues);
                tokio::spawn(async move {
                    // Issue #502: `run`'s shutdown drain keeps receiving
                    // while any waiter is pending, so a failed send only
                    // happens once the drain's own `SHUTDOWN_TIMEOUT` ran
                    // out; say so rather than lose the writes silently.
                    if forward_tx.send(drainer).await.is_err() {
                        queues.deactivate(id);
                        eprintln!(
                            "WARN dropped queued write forwards: the node shut down before \
                             forward_tx was drained"
                        );
                    }
                    PENDING_FORWARD_WAITERS.fetch_sub(1, Ordering::SeqCst);
                });
            } else {
                PENDING_FORWARD_WAITERS.fetch_sub(1, Ordering::SeqCst);
                // Nothing will drain this queue until the next forward to
                // the same target hands in a fresh drainer.
                config.forward_queues.deactivate(id);
                eprintln!(
                    "WARN could not hand a forward drainer to run: forward_tx is full and \
                     {MAX_PENDING_FORWARD_WAITERS} waiters are already queued behind it; the \
                     queued writes wait for the next forward to that target"
                );
            }
        }
    }
}

/// `run`'s shutdown drain: runs every connection task to completion
/// while still servicing `migration_rx`/`forward_rx`, exactly as the
/// main loop did — a connection task that is mid-request when shutdown
/// lands may still hand a forwarded write (or the tail of a handoff) to
/// one of these channels, and with the main loop gone nobody else would
/// spawn it: the client would have its `S`/`D` acked and the forward
/// silently dropped.
///
/// Issue #502: "until every connection task is done" is not the whole
/// condition. A forward can be sitting in `forward_rx` (or `migration_rx`)
/// with no connection task left to keep this loop going — the task that
/// queued it may have exited right after — and a forward that found the
/// channel full is held by a detached `spawn_forward` waiter that has
/// nothing to do with `connection_tasks` at all. Stopping on the task set
/// alone left both to be dropped when `run` returned and `forward_rx`
/// with it — the very loss `spawn_forward`'s waiter exists to prevent.
/// So this also drains whatever the channels still hold and, while any
/// waiter is still blocked on its `send`, keeps receiving so it can hand
/// its forward over. Bounded by the caller's `SHUTDOWN_TIMEOUT`, like
/// the tasks themselves.
async fn drain_connection_tasks(
    connection_tasks: &mut JoinSet<()>,
    migration_rx: &mut mpsc::Receiver<MigrationTask>,
    forward_rx: &mut mpsc::Receiver<MigrationTask>,
) {
    loop {
        // Queued forwards first: each one spawned keeps the task set
        // non-empty, which is what the join branch below keys off.
        while let Ok(task) = forward_rx.try_recv() {
            connection_tasks.spawn(task);
        }
        while let Ok(task) = migration_rx.try_recv() {
            connection_tasks.spawn(task);
        }
        let waiters_pending = PENDING_FORWARD_WAITERS.load(Ordering::SeqCst) > 0;
        if connection_tasks.is_empty() && !waiters_pending {
            return;
        }
        tokio::select! {
            result = connection_tasks.join_next(), if !connection_tasks.is_empty() => {
                if let Some(Err(error)) = result {
                    eprintln!("WARN connection task failed: {error}");
                }
            }
            Some(task) = migration_rx.recv() => {
                connection_tasks.spawn(task);
            }
            Some(task) = forward_rx.recv() => {
                connection_tasks.spawn(task);
            }
        }
    }
}

/// What an staged node join migration task (triggered by an incoming `M`) needs
/// beyond the cache itself: this node's own identity, and how to reach
/// the discovery server to report `C` once the handoff is done.
#[derive(Clone)]
struct NodeContext {
    /// Test-only hold points (`RunHooks::gates`).
    #[cfg(test)]
    gates: Arc<SimGates>,
    /// This node's own random per-process identity (node identity decoupled from address), needed to
    /// identify this node as the sender when it reports `C`.
    name: String,
    /// This node's per-process membership token (issue #34), generated
    /// alongside `name` with the same lifetime and never persisted or
    /// shared with anything but the discovery servers — presented on
    /// `J`/`P`/`H`/`C` so nothing that merely knows this node's public
    /// name (every `L` response lists it) can speak for it.
    token: String,
    discovery_addr: String,
    /// Set while `run_migration` is active, cleared when it finishes (see
    /// `MigrationGuard`). Serves two purposes: `run_sweep` checks it and
    /// skips its pass while it's `Some`, per staged node join — a marked-but-not-
    /// yet-swept key may still be needed as the authoritative source for
    /// a subsequent hop while a handoff is in flight — and an incoming
    /// `X` (cancel) uses it to find (by `joining_name`) and abort a
    /// matching in-flight handoff.
    active_migration: Arc<Mutex<Option<ActiveMigration>>>,
    /// This node's best current understanding of cluster membership, used
    /// to reject a client's `G`/`S`/`D` for a key this node no longer
    /// owns (see `wrong_node`) instead of silently serving stale local
    /// data forever to a client whose own view of `L` hasn't caught up
    /// yet. Updated once a handoff this node ran (successfully) finishes
    /// — not the moment `M` arrives — so this node keeps accepting
    /// writes for a key up through the handoff (propagating them, see
    /// `run_migration`) and only starts rejecting once its own share is
    /// actually done; updating any earlier would reject requests for a
    /// joining node that may not even be promoted yet. Runs for every
    /// `M`, whether or not any of this node's own keys route to the
    /// joiner, so it stays current with joins elsewhere in the cluster
    /// too. Also refreshed from the roster the primary discovery server
    /// returns with every heartbeat ack (issue #61, `adopt_membership`),
    /// which is how it follows liveness *evictions* — `M` only ever
    /// carries joins. `None` until the first of either — a lone or
    /// freshly-bootstrapped node has no membership to reject against
    /// yet (a joiner before promotion rejects everything regardless, see
    /// `promoted`).
    known_ring: KnownRing,
    /// The newest roster discovery published to this node, as a ring,
    /// whether or not `adopt_membership` took it: the heartbeat loop
    /// adopts a change only on its next tick and not at all while a join
    /// is pending here, and in that lag a client that already routes by
    /// the new `L` reaches this node for a key it will own. `wrong_node`
    /// accepts such a key (it never refuses one `known_ring` grants), so a
    /// replica write in the window after a leave or an eviction is stored
    /// instead of answered `W` and dropped by the SDK — the entrant used
    /// to keep the re-replicated older copy for the key's lifetime.
    latest_published: KnownRing,
    /// The on-demand refresh of `latest_published` — see
    /// `refresh_published_roster`.
    roster_refresh: Arc<RosterRefresh>,
    /// Whether discovery has promoted this node (the `R` to its `J`, see
    /// `register_with_discovery`). Until then no client's `L` names this
    /// node, so a key request that reaches it anyway arrived on a
    /// connection meant for someone else — in practice the previous
    /// occupant of this address: a member killed and evicted while a
    /// client's bootstrap dial to it was still pending (an SDK's connect
    /// dials every listed member and waits for all of them), with this
    /// process starting to listen on the same IP (a same-host restart)
    /// before that dial's deadline. The dial then completes, labelled with
    /// the evicted name. A node in its join handoff holds only what the
    /// migration has delivered so far, so answering locally returns `N`
    /// for a key that is live elsewhere; `wrong_node` answers `W` instead,
    /// and the client's forced refresh — `L` no longer lists the evicted
    /// name — lands the retry on a surviving owner. Set once, never
    /// cleared: a later re-registration (`P`) is of a member that already
    /// holds its share.
    promoted: Arc<AtomicBool>,
    auth_secret: Option<Bytes>,
    tls_connector: Option<TlsConnector>,
    request_tx: mpsc::Sender<CacheRequest>,
    /// Issue #124: set for the whole decommission (drain-out handoff +
    /// grace) — `leave_target_for` forwards concurrent writes through
    /// it, the `M` handler rejects new joins while it is set, and
    /// `/readyz` reports not-ready.
    leaving: Arc<Mutex<Option<LeaveState>>>,
    /// A re-replication's forwarding window — the writes this node must
    /// mirror to the owners an eviction newly promoted, during the pass
    /// and for a grace after it (see `RereplicationForward`).
    rereplication_forward: Arc<Mutex<Option<RereplicationForward>>>,
    /// Issue #266: a `run_rereplication` in flight, if any — set by
    /// `spawn_or_supersede_rereplication` when `adopt_membership` reports
    /// a ring change that dropped a member (an eviction, or a leave this
    /// node did not itself hand off for), cleared once that run finishes.
    /// `run_migration` waits (bounded) for this to clear before it starts
    /// marking dead copies, so a join's sweep can't reclaim the sender's
    /// only copy of a key the re-replication hasn't delivered to the
    /// ring's newly promoted owner yet — see both functions' doc
    /// comments.
    active_rereplication: Arc<Mutex<Option<Arc<ActiveRereplication>>>>,
    /// Issue #582: every membership discovery published to this node and
    /// when, for the ownership reclaim pass. Only `adopt_membership`'s
    /// result goes in — never the ring a handoff predicts at completion.
    ring_history: RingHistory,
    /// Issue #266: how a task that spawns a re-replication (either
    /// `register_with_discovery`, on an eviction-driven ring change, or
    /// `run_migration`, on the join-flip gap below) hands it to
    /// `send_heartbeats`'s own `JoinSet` — see that field's doc comment
    /// on `RereplicationTask` for why neither producer has a `JoinSet`
    /// of its own suitable for a possibly-long-running task like this.
    /// A clone of the same sender `run` creates once and threads to both
    /// this struct and `send_heartbeats`'s receiving end.
    rereplication_tx: mpsc::Sender<RereplicationTask>,
    /// This node's shutdown signal (the same `watch::Receiver` every
    /// other background task observes) — carried here so a task spawned
    /// well after `NodeContext` was built (`run_migration`'s own
    /// join-triggered re-replication, issue #266) can still stop
    /// promptly at shutdown without a bespoke parameter thread of its
    /// own.
    shutdown_rx: watch::Receiver<bool>,
}

/// Issue #124: a decommission in progress. The mirror of
/// `ActiveMigration`, but self-contained: the leaver computes, from the
/// roster alone, which single node newly enters each of its keys' top-R
/// once it is gone (removing a node from an HRW ranking can only
/// promote the previous rank-R+1 node), and hands that node the entry —
/// the surviving owners already hold their copies. Both rings are a
/// one-shot snapshot of membership at drain start, never recomputed —
/// see `run_decommission`'s doc comment for the concurrent-membership-
/// change window this accepts (issue #357).
struct LeaveState {
    /// The roster including this node — what routing looked like when
    /// the drain began.
    before_ring: Arc<HashRing>,
    /// The roster minus this node — where each key lives afterwards.
    after_ring: Arc<HashRing>,
    replication: usize,
    /// name → address for every member, to dial entrants.
    addresses: HashMap<String, String>,
    /// Issue #295: name → membership token for every member, so a
    /// concurrent write forwarded to an entrant (`leave_target_for`) can
    /// authorize its `U`/`u` the same way the bulk drain-out's own sends
    /// do — see `Command::HandoffSet::token`.
    tokens: HashMap<String, String>,
    /// One shared forwarding connection per entrant address, reused by
    /// every concurrent write forwarded during the drain (mirrors
    /// `ActiveMigration::forward_connection`).
    connections: Mutex<HashMap<String, Arc<AsyncMutex<Option<ClientStream>>>>>,
}

impl LeaveState {
    /// The node that newly enters `key`'s top-R when this node leaves —
    /// `None` when this node wasn't an owner (nothing moves) or the
    /// cluster is too small for a replacement (the survivors are all
    /// owners already).
    ///
    /// Takes the key's precomputed hash: this runs per key of a
    /// multi-key frame and hashes the key's (up to ~1 MiB) namespace
    /// otherwise, once per ring query.
    fn entrant_for(&self, key_hash: KeyHash, self_name: &str) -> Option<String> {
        if !self
            .before_ring
            .is_owner_hashed(key_hash, self_name, self.replication)
        {
            return None;
        }
        self.after_ring
            .owners_hashed(key_hash, self.replication)
            .into_iter()
            .find(|owner| {
                !self
                    .before_ring
                    .is_owner_hashed(key_hash, owner, self.replication)
            })
            .map(|owner| owner.to_string())
    }

    /// The forward target for survivor `name`: its address and token from
    /// the drain-start roster, and the one connection every forward to
    /// it shares (so the forward queue keeps them in order). `None` for a
    /// name the roster did not carry an address or token for.
    fn forward_target(&self, name: &str) -> Option<ForwardTarget> {
        let addr = self.addresses.get(name)?.clone();
        let token = self.tokens.get(name)?.clone();

        let connection = {
            let mut connections = self
                .connections
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            Arc::clone(
                connections
                    .entry(addr.clone())
                    .or_insert_with(|| Arc::new(AsyncMutex::new(None))),
            )
        };

        Some(ForwardTarget {
            addr,
            connection,
            token,
            revoked: Arc::new(AtomicBool::new(false)),
            as_handoff: false,
        })
    }
}

/// The forwarding window of a re-replication: after a ring change dropped
/// a member, the survivors that re-replicate a key (`rereplication_targets`)
/// also mirror the concurrent client writes of it to the owner the change
/// newly promoted, for as long as the pass runs and for `grace` after it.
/// Without it, a client still routing with the pre-eviction node list
/// writes only to the surviving old owners (its leg to the evicted one
/// fails and is swallowed), and the new owner keeps the copy the pass
/// handed it — the acknowledged write, delete or increment is missing on
/// that one owner until the key is written again. Every SDK refreshes its
/// node list after 30 s of staleness; the grace is twice that. Mirrors
/// `LeaveState` (the decommission's window): same one-shot ring snapshot,
/// same shared connection per target, same unconditional `U`/`u` frames.
struct RereplicationForward {
    /// The ring before the change — who owned each key, so this node can
    /// tell which keys it is an eligible sender for.
    before_ring: Arc<HashRing>,
    /// The ring after it — who owns each key now.
    after_ring: Arc<HashRing>,
    replication: usize,
    /// name → address and name → membership token for every member of
    /// `after_ring`, from the roster fetched for the pass.
    addresses: HashMap<String, String>,
    tokens: HashMap<String, String>,
    /// One shared forwarding connection per target address, so the
    /// forward queue keeps a target's writes in order.
    connections: Mutex<HashMap<String, Arc<AsyncMutex<Option<ClientStream>>>>>,
    /// Stamped when the pass returns; the window closes `grace` later.
    completed_at: Option<Instant>,
    grace: Duration,
}

impl RereplicationForward {
    fn forwarding_open(&self) -> bool {
        self.completed_at
            .is_none_or(|completed_at| completed_at.elapsed() < self.grace)
    }

    /// The forward target for member `name` — `None` for a name the
    /// roster carried no address or token for (skipped, like the pass
    /// itself skips such a target).
    fn forward_target(&self, name: &str) -> Option<ForwardTarget> {
        let addr = self.addresses.get(name)?.clone();
        let token = self.tokens.get(name)?.clone();
        let connection = {
            let mut connections = self
                .connections
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            Arc::clone(
                connections
                    .entry(addr.clone())
                    .or_insert_with(|| Arc::new(AsyncMutex::new(None))),
            )
        };
        Some(ForwardTarget {
            addr,
            connection,
            token,
            revoked: Arc::new(AtomicBool::new(false)),
            as_handoff: false,
        })
    }
}

/// Configuration for registering this node with discovery servers (see
/// `src/bin/nanocached-discovery.rs`). When set, `run` asks to join once
/// (staged node join) using a random per-process name (node identity decoupled from address) and, once
/// promoted, sends a heartbeat declaring that name on `interval`, well
/// under the discovery server's own liveness timeout.
pub(crate) struct HeartbeatConfig {
    /// One or more discovery replicas (discovery HA). The first is the
    /// primary — the only one this node ever sends `J` (and `C`) to;
    /// the rest learn about this node via `P` announces once the primary
    /// has promoted it. Never empty (main.rs validates).
    pub(crate) discovery_addrs: Vec<String>,
    /// The port this node serves on. `J`/`P` carry only this; the
    /// discovery server derives the full address from the registration
    /// connection's source IP (addresses derived from the registration connection), so there is nothing to
    /// configure in containerized deployments.
    pub(crate) port: u16,
    pub(crate) interval: Duration,
    /// Sent to the discovery server before the first heartbeat on each
    /// (re)connection, if the discovery server requires auth. This is the
    /// same shared secret this node uses to gate its own connections.
    pub(crate) auth_secret: Option<Bytes>,
    /// When set, the heartbeat connection to the discovery server is made
    /// over TLS, trusting only the CAs loaded into this connector. This is
    /// the same `--tls-ca` this node uses for any other outbound TLS
    /// connections it makes.
    pub(crate) tls_connector: Option<TlsConnector>,
}

/// A shutdown request: resolves when the process is asked to stop.
pub(crate) type ShutdownSignal = Pin<Box<dyn Future<Output = io::Result<()>> + Send>>;

/// What `run` takes from its caller instead of from the process, so a test
/// can run several nodes in one process (see `sim.rs`): when each of them is
/// asked to stop, and the name it registers under. The binary uses the
/// default: the process's own termination signals and a random name.
/// Test-only hold points inside a node, for the in-process simulator
/// (`sim.rs`): a scenario that needs one frame to land between two others
/// holds the task that would send it and releases it when the others have
/// landed. Open by default; a held gate stops the task before its next
/// send, nothing in flight is touched.
#[cfg(test)]
pub(crate) struct Gate(tokio::sync::watch::Sender<bool>);

#[cfg(test)]
impl Default for Gate {
    fn default() -> Self {
        Gate(tokio::sync::watch::channel(true).0)
    }
}

#[cfg(test)]
impl Gate {
    pub(crate) fn hold(&self) {
        self.0.send_replace(false);
    }

    pub(crate) fn release(&self) {
        self.0.send_replace(true);
    }

    /// Returns once the gate is open.
    pub(crate) async fn wait(&self) {
        let mut open = self.0.subscribe();
        while !*open.borrow_and_update() {
            if open.changed().await.is_err() {
                return;
            }
        }
    }
}

/// The gates a node consults, one per sending task.
#[cfg(test)]
#[derive(Default)]
pub(crate) struct SimGates {
    /// `drain_forward_queue`: a concurrent write forwarded to a joiner,
    /// a handoff relayed to it, a write mirrored through a window.
    pub(crate) forward: Gate,
    /// `run_migration`'s transfer of this node's keys to a joiner.
    pub(crate) transfer: Gate,
    /// `run_rereplication`: the put-if-absent copies a membership change
    /// sends to the owners it promoted.
    pub(crate) pass: Gate,
}

pub(crate) struct RunHooks {
    /// Called for the first signal and again each time one is taken (a
    /// second signal while draining overrides the drain, issue #407), so it
    /// returns a fresh future every call.
    pub(crate) shutdown: Box<dyn FnMut() -> ShutdownSignal + Send>,
    /// The name this node registers with discovery; random when `None`.
    pub(crate) node_name: Option<String>,
    /// A listener the caller already holds, used instead of binding
    /// `address`: a test that chose the port ahead of time keeps it bound
    /// until the node takes over, so nothing else can be handed it.
    pub(crate) listener: Option<TcpListener>,
    /// Hold points for a simulator scenario; open unless it holds one.
    #[cfg(test)]
    pub(crate) gates: Arc<SimGates>,
}

impl Default for RunHooks {
    fn default() -> Self {
        Self {
            shutdown: Box::new(|| Box::pin(shutdown_signal())),
            node_name: None,
            listener: None,
            #[cfg(test)]
            gates: Arc::default(),
        }
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) async fn run(
    address: &str,
    heartbeat: Option<HeartbeatConfig>,
    auth_secret: Option<Bytes>,
    tls_acceptor: Option<TlsAcceptor>,
    max_memory_bytes: usize,
    metrics_address: Option<String>,
    drain_timeout: Duration,
    limits: ConnectionLimits,
    namespace_budgets: Vec<(Bytes, usize)>,
) -> io::Result<()> {
    run_with_hooks(
        address,
        heartbeat,
        auth_secret,
        tls_acceptor,
        max_memory_bytes,
        metrics_address,
        drain_timeout,
        limits,
        namespace_budgets,
        RunHooks::default(),
    )
    .await
}

#[allow(clippy::too_many_arguments)]
pub(crate) async fn run_with_hooks(
    address: &str,
    heartbeat: Option<HeartbeatConfig>,
    auth_secret: Option<Bytes>,
    tls_acceptor: Option<TlsAcceptor>,
    max_memory_bytes: usize,
    metrics_address: Option<String>,
    drain_timeout: Duration,
    limits: ConnectionLimits,
    namespace_budgets: Vec<(Bytes, usize)>,
    mut hooks: RunHooks,
) -> io::Result<()> {
    let listener = match hooks.listener.take() {
        Some(listener) => listener,
        None => TcpListener::bind(address).await?,
    };
    infra::warn_if_exposed_without_secret(
        "nanocached-node",
        listener.local_addr()?,
        auth_secret.is_some(),
    );

    let (request_tx, request_rx) = mpsc::channel(1024);
    let connection_limit = Arc::new(Semaphore::new(limits.max_connections));
    let per_ip_connections: PerIpConnections = Arc::new(Mutex::new(HashMap::new()));
    let mut connection_tasks = JoinSet::new();
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let cache_task = tokio::spawn(run_cache(request_rx, max_memory_bytes, namespace_budgets));

    // Shared with `node_context` (when this node has one) so `run_sweep`
    // can tell whether an staged node join handoff this node is the source for is
    // currently in flight, regardless of discovery configuration — a node
    // running standalone never touches this beyond the initial `None`.
    let active_migration: Arc<Mutex<Option<ActiveMigration>>> = Arc::new(Mutex::new(None));

    // Shared with `node_context` so the heartbeat tasks can report the
    // replication factor half of this node's belief to discovery (issue
    // #30), the same belief `wrong_node` rejects client requests against.
    let known_ring: KnownRing = Arc::new(Mutex::new(None));

    // Issue #266: created once here (mirroring `migration_tx`/
    // `forward_tx` below) rather than inside `send_heartbeats`, so both
    // `NodeContext` (whose clones are how two different producers —
    // `register_with_discovery` on an eviction-driven ring change, and
    // `run_migration` on its own join-flip gap, see its doc comment —
    // hand a re-replication task off) and `send_heartbeats` (which
    // drains it into its own `JoinSet`) share the one channel.
    let (rereplication_tx, rereplication_rx) = mpsc::channel::<RereplicationTask>(4);

    // Generated once and kept for this process's lifetime (node identity decoupled from address): a
    // restarted node has no data to reclaim its old identity for, so
    // there's nothing a stable name would preserve across a restart that
    // isn't already lost anyway. Only meaningful when this node registers
    // with a discovery server at all.
    let mut node_name = hooks.node_name.take();
    #[cfg(test)]
    let gates = Arc::clone(&hooks.gates);
    let node_context = heartbeat.as_ref().map(|config| NodeContext {
        #[cfg(test)]
        gates: Arc::clone(&gates),
        name: node_name
            .take()
            .unwrap_or_else(|| Uuid::new_v4().to_string()),
        // A second, independent UUID: the name is public (`L` lists it),
        // so it can't double as the credential proving this node is the
        // one behind it (issue #34).
        token: Uuid::new_v4().to_string(),
        // The primary (discovery HA) — where `C` completion reports go,
        // matching where `J` was sent.
        discovery_addr: config.discovery_addrs[0].clone(),
        active_migration: Arc::clone(&active_migration),
        known_ring: Arc::clone(&known_ring),
        latest_published: Arc::new(Mutex::new(None)),
        roster_refresh: Arc::default(),
        promoted: Arc::new(AtomicBool::new(false)),
        auth_secret: config.auth_secret.clone(),
        tls_connector: config.tls_connector.clone(),
        request_tx: request_tx.clone(),
        leaving: Arc::new(Mutex::new(None)),
        active_rereplication: Arc::new(Mutex::new(None)),
        ring_history: RingHistory::default(),
        rereplication_tx: rereplication_tx.clone(),
        rereplication_forward: Arc::new(Mutex::new(None)),
        shutdown_rx: shutdown_rx.clone(),
    });
    // After `node_context`: the sweep judges a marked copy by the ring this
    // node has adopted (`Command::Sweep::owned`); standalone it has none.
    let sweep_task = tokio::spawn(run_sweep(
        request_tx.clone(),
        Arc::clone(&active_migration),
        node_context.as_ref().map(|node_context| {
            (
                Arc::clone(&node_context.known_ring),
                node_context.name.clone(),
                node_context.ring_history.clone(),
            )
        }),
        shutdown_rx.clone(),
    ));

    // Issue #582: the ownership reclaim pass, cluster mode only.
    let reclaim_task = node_context
        .as_ref()
        .map(|node_context| tokio::spawn(run_reclaim(node_context.clone(), shutdown_rx.clone())));
    // This function's own copy must go, or `send_heartbeats`'s drain of
    // `rereplication_rx` would never see the channel close — every real
    // producer holds its own clone via `NodeContext` (or a clone of it),
    // and this binding otherwise outlives even `heartbeat_task.await`
    // below, in `run`'s own shutdown sequence.
    drop(rereplication_tx);

    // Issue #124: the operations sidecar — Prometheus-format /metrics
    // plus /healthz//readyz probes on their own listener, so scraping
    // never competes for (or counts against) client connection permits.
    let metrics_task = match &metrics_address {
        Some(metrics_address) => {
            let metrics_listener = TcpListener::bind(metrics_address.as_str()).await?;
            println!("INFO metrics endpoint listening on {metrics_address}");
            // Issue #327: a dedicated, small cap on the metrics port's own
            // accepted connections — independent of, and much smaller
            // than, `connection_limit`/`limits.max_connections` above,
            // which this task only ever reads for the `/metrics` gauge.
            let metrics_connection_limit = Arc::new(Semaphore::new(METRICS_MAX_CONNECTIONS));
            Some(tokio::spawn(run_metrics_server(
                metrics_listener,
                request_tx.clone(),
                Arc::clone(&connection_limit),
                limits.max_connections,
                Arc::clone(&known_ring),
                node_context.is_some(),
                shutdown_rx.clone(),
                metrics_connection_limit,
            )))
        }
        None => None,
    };

    // Issue #124: the decommission needs every discovery replica, and
    // `heartbeat` is consumed by the task below — keep a copy.
    let discovery_addrs_for_leave = heartbeat
        .as_ref()
        .map(|config| config.discovery_addrs.clone());

    // Issue #124: heartbeats get their own stop signal, flipped either
    // at normal shutdown or the moment a decommission begins — a
    // heartbeat surviving past the leave would be answered as an
    // unknown node and re-register, quietly re-joining the cluster the
    // node just left.
    let (heartbeat_stop_tx, heartbeat_stop_rx) = watch::channel(false);
    let heartbeat_task = match (heartbeat, &node_context) {
        (Some(config), Some(node_context)) => Some(tokio::spawn(send_heartbeats(
            config,
            node_context.clone(),
            rereplication_rx,
            heartbeat_stop_rx,
        ))),
        _ => None,
    };

    // Buffered rather than unbounded: staged node join allows only one migration in
    // flight per node (see `NodeContext::active_migration`), so a handful of
    // slots is already more than a well-behaved cluster would ever need at
    // once. Per-write forwards do NOT go through this channel — see
    // `forward_tx` below and issue #219.
    let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(4);
    // Issue #219: a separate, more generously sized channel for per-write
    // forwards (`forward_with_retries`), so a burst of them stalled on a
    // slow peer can never delay the singleton bulk-migration task above —
    // or, before this split, block an unrelated client connection's
    // `spawn_forward` call outright. See `ConnectionConfig::forward_tx`.
    let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(FORWARD_CHANNEL_CAPACITY);

    let connection_config = ConnectionConfig {
        idle_timeout: IDLE_TIMEOUT,
        auth_secret,
        in_flight_bytes: InFlightBudget::new(limits.max_in_flight_bytes),
        tls_acceptor,
        node_context: node_context.clone(),
        migration_tx,
        forward_tx,
        forward_queues: Arc::new(ForwardQueues::default()),
    };

    // Issue #407: boxed and reassignable (rather than `tokio::pin!`'d
    // once) so a second signal while draining can be listened for again —
    // `shutdown_signal()`'s underlying future is consumed the moment it
    // resolves, and re-polling a completed future is not something the
    // `Future` contract allows, so "listening again" means installing a
    // fresh one, not reusing this one.
    let mut shutdown: Pin<Box<dyn Future<Output = io::Result<()>> + Send>> = (hooks.shutdown)();

    // Issue #124: set once the decommission has been spawned; its
    // completion signal re-enters the loop below to run the ordinary
    // shutdown. A second signal while draining falls through to the
    // immediate path (operator override, issue #407).
    let mut decommission_started = false;
    let (decommission_done_tx, mut decommission_done_rx) = watch::channel(false);
    // Tenth-pass audit (2026-09-02): the decommission task's own handle,
    // previously discarded. `run_decommission` now watches `shutdown_rx`
    // (via its `NodeContext` clone) and unwinds promptly on its own once
    // the override branch below flips it, but this is the hard backstop
    // — awaited briefly there, then aborted if it hasn't finished, so a
    // task that somehow doesn't notice the signal can never block
    // `cache_task.await` (and this function's own return) indefinitely.
    let mut decommission_task: Option<tokio::task::JoinHandle<()>> = None;

    loop {
        tokio::select! {
            biased;

            result = &mut shutdown => {
                result?;

                // Issue #407: a second Ctrl-C/SIGTERM while decommission
                // draining is already under way is the operator override
                // this branch's own comment above promises — stop waiting
                // on the drain budget (or a `decommission_done` that may
                // never come) and fall straight into the same immediate
                // shutdown path a non-clustered node's first signal takes.
                if decommission_started {
                    println!(
                        "INFO second shutdown signal received — overriding decommission drain"
                    );
                    // `run_decommission` clones `shutdown_rx` into its own
                    // `NodeContext`, so this is the same override signal
                    // it's watching for in its migration-wait, per-key
                    // transfer, and grace-sleep loops (see that
                    // function's own doc comments).
                    shutdown_tx.send_replace(true);
                    if let Some(migration) = active_migration
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .as_ref()
                    {
                        migration.abort_requested.store(true, Ordering::SeqCst);
                    }

                    // Tenth-pass audit (2026-09-02), issue #407 follow-up:
                    // give the task a brief window to notice the signal
                    // above and return on its own — it still needs to run
                    // `send_leave` for a clean membership departure rather
                    // than lingering until the peer's liveness timeout.
                    // The window is enough because every network await in
                    // `run_decommission`'s handoff path is raced against
                    // this same signal (see `shutdown_requested`), so the
                    // task reaches `send_leave` within milliseconds of it;
                    // only `send_leave` itself against an unresponsive
                    // discovery can outlast the window, and then there is
                    // nothing left worth waiting for. Then abort it outright so it can't block
                    // `cache_task.await` below regardless (a raw abort
                    // drops its `NodeContext` clone, including the
                    // `request_tx` that `cache_task` is waiting to see
                    // every sender drop).
                    if let Some(mut task) = decommission_task.take()
                        && timeout(DECOMMISSION_OVERRIDE_GRACE, &mut task)
                            .await
                            .is_err()
                    {
                        eprintln!(
                            "WARN decommission task did not stop within the override grace \
                             period — aborting it"
                        );
                        task.abort();
                    }

                    break;
                }

                // Issue #124: a clustered node with a drain budget
                // decommissions first — hand entries to their post-leave
                // owners, leave membership, then run this same shutdown.
                // The accept loop keeps running throughout (serving and
                // write-forwarding during the drain is the point), so
                // the decommission is spawned and its completion loops
                // back in via `decommission_done`.
                if let (Some(node_context), Some(discovery_addrs)) =
                    (&node_context, &discovery_addrs_for_leave)
                    && !drain_timeout.is_zero()
                {
                    println!(
                        "INFO shutdown signal received — decommissioning (budget {}s)",
                        drain_timeout.as_secs()
                    );
                    decommission_started = true;
                    // Stop heartbeating before anything else: a
                    // heartbeat landing after the V would re-register
                    // this node (see heartbeat_stop_tx above).
                    heartbeat_stop_tx.send_replace(true);
                    let node_context = node_context.clone();
                    let discovery_addrs = discovery_addrs.clone();
                    let done = decommission_done_tx.clone();
                    decommission_task = Some(tokio::spawn(async move {
                        run_decommission(node_context, discovery_addrs, drain_timeout).await;
                        let _ = done.send(true);
                    }));
                    // Issue #407: re-arm so a second signal during the
                    // drain is still noticed (see the boxed `shutdown`'s
                    // own doc comment above).
                    shutdown = (hooks.shutdown)();
                    continue;
                }

                println!("INFO shutdown signal received");
                heartbeat_stop_tx.send_replace(true);
                shutdown_tx.send_replace(true);

                // `run_migration` doesn't watch `shutdown_rx` itself (it's
                // driven entirely by `abort_requested`, the same flag an
                // incoming `X` uses) — ask it to unwind now rather than
                // letting `connection_tasks`'s drain-then-`abort_all`
                // below simply run out the clock on it. A raw task abort
                // wouldn't run `run_migration`'s own rollback of
                // `marked_this_run`, only `MigrationGuard::drop`'s slot
                // clear, so this in-band request is what lets the rest of
                // this shutdown path stay a normal bounded wait instead of
                // a forced kill.
                if let Some(migration) = active_migration
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .as_ref()
                {
                    migration.abort_requested.store(true, Ordering::SeqCst);
                }

                break;
            }

            _ = decommission_done_rx.changed(), if decommission_started => {
                println!("INFO decommission finished — shutting down");
                heartbeat_stop_tx.send_replace(true);
                shutdown_tx.send_replace(true);
                if let Some(migration) = active_migration
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .as_ref()
                {
                    migration.abort_requested.store(true, Ordering::SeqCst);
                }
                break;
            }

            result = connection_tasks.join_next(), if !connection_tasks.is_empty() => {
                if let Some(Err(error)) = result {
                    eprintln!("WARN connection task failed: {error}");
                }
            }

            Some(task) = migration_rx.recv() => {
                connection_tasks.spawn(task);
            }

            Some(task) = forward_rx.recv() => {
                connection_tasks.spawn(task);
            }

            result = listener.accept() => {
                let (stream, address) = match result {
                    Ok(pair) => pair,
                    Err(error) => {
                        // A single failed `accept` (ECONNABORTED, EMFILE,
                        // ENFILE, ENOBUFS, ...) used to be propagated with
                        // `?`, taking the whole listener — and every
                        // connection it was already serving — down over
                        // what is usually a transient, per-attempt
                        // condition. Log and keep the loop running instead.
                        eprintln!("WARN accept failed: {error}");

                        // EMFILE/ENFILE (Unix) mean this process (or the
                        // system) is out of file descriptors; looping
                        // straight back to `accept` would spin this
                        // branch hot until one frees up, so back off
                        // briefly rather than busy-looping. Non-Unix
                        // targets can't identify that specific condition
                        // (see `is_fd_exhaustion`) and back off on every
                        // accept error instead — see
                        // `should_backoff_after_accept_error`.
                        if should_backoff_after_accept_error(&error) {
                            sleep(ACCEPT_ERROR_BACKOFF).await;
                        }

                        continue;
                    }
                };

                dispatch_connection(
                    stream,
                    address,
                    request_tx.clone(),
                    Arc::clone(&connection_limit),
                    Arc::clone(&per_ip_connections),
                    limits.max_connections_per_ip,
                    connection_config.clone(),
                    shutdown_rx.clone(),
                    &mut connection_tasks,
                );
            }

        }
    }

    // Keep servicing `migration_rx`/`forward_rx` while draining: a
    // connection task that is mid-request when shutdown lands may still
    // hand a forwarded write (or the tail of a handoff) to one of these
    // channels, and with the main loop gone nobody would spawn it — the
    // client would have its `S`/`D` acked and the forward silently
    // dropped. `forward_tx` sends via `try_send` (see `spawn_forward`) so
    // it was never going to block a connection task regardless, but
    // draining it here still lets a forward queued right before shutdown
    // actually run instead of being dropped.
    let connections_finished = timeout(
        SHUTDOWN_TIMEOUT,
        drain_connection_tasks(&mut connection_tasks, &mut migration_rx, &mut forward_rx),
    )
    .await;

    if connections_finished.is_err() {
        eprintln!("WARN shutdown timeout reached");
        connection_tasks.abort_all();

        while connection_tasks.join_next().await.is_some() {}
    }

    drop(request_tx);
    // `connection_config` (specifically the `NodeContext.request_tx` clone
    // inside it, when this node has a discovery config) is otherwise not
    // dropped until `run` itself returns — after `cache_task.await` below,
    // which needs every sender dropped to see its channel close. Without
    // this, a discovery-configured node deadlocks on shutdown: `cache_task`
    // waits on a sender only `run`'s own return would drop, and `run` can't
    // return until `cache_task` resolves.
    drop(connection_config);
    // Same deadlock, second holder (issue #124): `connection_config` now
    // only *clones* the context (the decommission path needs its own
    // copy), so the original binding still holds a `request_tx` here.
    drop(node_context);

    cache_task
        .await
        .map_err(|error| io::Error::other(format!("cache task failed: {error}")))?;

    sweep_task
        .await
        .map_err(|error| io::Error::other(format!("sweep task failed: {error}")))?;

    if let Some(reclaim_task) = reclaim_task {
        reclaim_task
            .await
            .map_err(|error| io::Error::other(format!("reclaim task failed: {error}")))?;
    }

    if let Some(heartbeat_task) = heartbeat_task {
        join_heartbeat_task(heartbeat_task, HEARTBEAT_SHUTDOWN_WAIT).await?;
    }

    if let Some(metrics_task) = metrics_task {
        // The metrics server observes the same shutdown signal; nothing
        // to flush, just don't leave the task behind.
        metrics_task.abort();
        let _ = metrics_task.await;
    }

    Ok(())
}

/// Waits up to `wait` for `run`'s heartbeat task to finish, then aborts it
/// (see `HEARTBEAT_SHUTDOWN_WAIT`). A task that panicked or was cancelled
/// is still an error, as it was when this was a bare `.await`.
async fn join_heartbeat_task(
    mut heartbeat_task: tokio::task::JoinHandle<()>,
    wait: Duration,
) -> io::Result<()> {
    match timeout(wait, &mut heartbeat_task).await {
        Ok(result) => {
            result.map_err(|error| io::Error::other(format!("heartbeat task failed: {error}")))
        }
        Err(_) => {
            eprintln!(
                "WARN heartbeat task still running {}s after shutdown (an unresponsive peer?) — \
                 aborting it",
                wait.as_secs()
            );
            heartbeat_task.abort();
            let _ = heartbeat_task.await;
            Ok(())
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn dispatch_connection(
    stream: TcpStream,
    address: SocketAddr,
    request_tx: mpsc::Sender<CacheRequest>,
    connection_limit: Arc<Semaphore>,
    per_ip_connections: PerIpConnections,
    max_connections_per_ip: usize,
    config: ConnectionConfig,
    shutdown_rx: watch::Receiver<bool>,
    connection_tasks: &mut JoinSet<()>,
) {
    // Every request/response is small; without this, the kernel may delay
    // small writes waiting to coalesce with more data (Nagle's algorithm).
    let _ = stream.set_nodelay(true);

    // Everything below — the TLS handshake and the over-limit "Busy" reply —
    // runs inside the spawned task, never inline in `run`'s accept loop. A
    // client that stalls its handshake (or never reads its "Busy" reply) would
    // otherwise block `run`'s `select!`, freezing new-connection accepts,
    // shutdown detection, and task reaping for the whole server.
    connection_tasks.spawn(async move {
        // Issue #5: acquired *before* the TLS handshake (previously
        // after), so a peer can't spend handshake CPU/fds past
        // `DEFAULT_MAX_CONNECTIONS` just by dialing and stalling — only a
        // permit-holding connection ever performs one.
        let permit = match connection_limit.try_acquire_owned() {
            Ok(permit) => permit,
            Err(_) => {
                reject_over_limit(
                    stream,
                    address,
                    &config.tls_acceptor,
                    TLS_HANDSHAKE_TIMEOUT,
                    &Response::Busy.encode(),
                )
                .await;
                return;
            }
        };

        // No per-source-IP connection limit: without this, a single
        // source could hold `DEFAULT_MAX_CONNECTIONS` connections all by itself
        // and starve every other client, even though the global
        // semaphore above isn't literally exhausted until the very last
        // one. Reserved before the TLS handshake for the same reason as
        // the global permit (issue #5) — see `DEFAULT_MAX_CONNECTIONS_PER_IP`.
        let per_ip_permit =
            match try_acquire_per_ip(&per_ip_connections, address.ip(), max_connections_per_ip) {
                Some(permit) => permit,
                None => {
                    reject_over_limit(
                        stream,
                        address,
                        &config.tls_acceptor,
                        TLS_HANDSHAKE_TIMEOUT,
                        &Response::Busy.encode(),
                    )
                    .await;
                    return;
                }
            };

        let stream: ServerStream = match &config.tls_acceptor {
            Some(acceptor) => match timeout(TLS_HANDSHAKE_TIMEOUT, acceptor.accept(stream)).await {
                Ok(Ok(tls_stream)) => ServerStream::Tls(Box::new(tls_stream)),
                Ok(Err(error)) => {
                    log_connection_warning(format_args!(
                        "WARN TLS handshake with {address} failed: {error}"
                    ));
                    return;
                }
                Err(_) => {
                    log_connection_warning(format_args!(
                        "WARN TLS handshake with {address} timed out"
                    ));
                    return;
                }
            },
            None => ServerStream::Plain(stream),
        };

        if let Some(suppressed) = ACCEPT_LOG.admit() {
            if suppressed > 0 {
                println!("INFO {suppressed} more connections accepted (not logged individually)");
            }
            println!("INFO accepted connection from {address}");
        }

        let _connection_permit = permit;
        let _per_ip_permit = per_ip_permit;

        if let Err(error) =
            handle_connection(stream, address, request_tx, config, shutdown_rx).await
        {
            log_connection_error(&address, &error);
        }
    });
}

async fn execute_command(
    request_tx: &mpsc::Sender<CacheRequest>,
    command: Command,
) -> io::Result<Response> {
    let (response_tx, response_rx) = oneshot::channel();

    request_tx
        .send(CacheRequest {
            command,
            response_tx,
        })
        .await
        .map_err(|_| io::Error::other("cache task stopped"))?;

    response_rx
        .await
        .map_err(|_| io::Error::other("cache task dropped response"))
}

/// A peer that closes the TCP connection without a TLS `close_notify` —
/// which is how every SDK and node ends a connection — is reported by
/// rustls as an error, and logging that at WARN on every ordinary
/// disconnect buried real problems (issue #68). Noted at INFO instead;
/// everything else stays a WARN.
fn log_connection_error(address: &SocketAddr, error: &io::Error) {
    let text = error.to_string();
    if text.contains("close_notify") {
        log_connection_warning(format_args!(
            "INFO connection from {address} closed without TLS close_notify"
        ));
    } else {
        log_connection_warning(format_args!(
            "WARN connection error from {address}: {error}"
        ));
    }
}

/// One line about a connection that failed, through `CONNECTION_ERROR_LOG`
/// (issue #1028): written when the budget allows, counted otherwise, with
/// the count reported ahead of the next line written.
fn log_connection_warning(line: std::fmt::Arguments<'_>) {
    let Some(suppressed) = CONNECTION_ERROR_LOG.admit() else {
        return;
    };
    if suppressed > 0 {
        eprintln!("WARN {suppressed} more connection errors (not logged individually)");
    }
    eprintln!("{line}");
}

/// Bounds every response write in `handle_connection` (issue #4): the read
/// side already has `IDLE_TIMEOUT`, but an unbounded `write_all` let a peer
/// that stops reading (without closing the TCP connection — e.g. a full
/// receive buffer) hold this connection's `DEFAULT_MAX_CONNECTIONS` permit forever.
/// Uses `WRITE_TIMEOUT` rather than reusing `IDLE_TIMEOUT`: the two are
/// different failure modes (a normal gap between requests vs. a peer that
/// isn't draining its receive buffer at all), and reusing the 60s read
/// timeout let a stuck write hold a permit far longer than necessary.
async fn write_response(stream: &mut ServerStream, data: &[u8]) -> io::Result<()> {
    infra::write_all_within(stream, data, WRITE_TIMEOUT).await
}

/// How long `reject_oversized_request` keeps reading after its `En\n`
/// for the client to close first.
const REJECTED_REQUEST_DRAIN_WINDOW: Duration = Duration::from_secs(1);

/// A request this node will not run — one `parse` rejected, or one over
/// its size limit — is answered `En\n` before the connection closes, as
/// `docs/protocol.html` promises and as the proxy already does: a
/// hand-written client that only sees the close cannot tell a rejected
/// request from a dropped connection. The reply is best effort (a peer
/// that already went away gets nothing, and that is not worth reporting
/// over `reason`); the returned error is what the WARN line carries.
async fn reject_request(stream: &mut ServerStream, reason: String) -> io::Error {
    let _ = write_response(stream, &Response::Malformed.encode()).await;
    io::Error::new(io::ErrorKind::InvalidData, reason)
}

/// `reject_request` for a request the node stopped reading part-way
/// because it passed `MAX_REQUEST_SIZE`. The client has usually sent
/// more than was read, and closing a socket with unread bytes in its
/// receive buffer sends a reset, which can discard the `En\n` on the
/// client's side before it is read. So: reply, half-close (the client
/// sees the reply and EOF at once), then read and discard what is still
/// arriving — until the client closes, for at most
/// `REJECTED_REQUEST_DRAIN_WINDOW` and a request's worth of bytes —
/// before the socket is dropped. Not used for the unauthenticated form
/// of the same limit: a peer that has not authenticated does not get to
/// hold a connection permit for that long.
async fn reject_oversized_request(stream: &mut ServerStream, reason: String) -> io::Error {
    let error = reject_request(stream, reason).await;
    let _ = stream.shutdown().await;
    let drain = async {
        let mut sink = [0_u8; 8192];
        let mut discarded = 0;
        while discarded < MAX_REQUEST_SIZE {
            match stream.read(&mut sink).await {
                Ok(0) | Err(_) => break,
                Ok(n) => discarded += n,
            }
        }
    };
    let _ = timeout(REJECTED_REQUEST_DRAIN_WINDOW, drain).await;
    error
}

/// Echoed response tags: a `G`/`S`/`D` response on a tagged-mode connection echoes
/// the request's tag; untagged connections keep the original encoding.
/// Issue #124: the node's operations endpoint — a deliberately minimal,
/// dependency-free HTTP/1.1 responder (the server's zero-dependency
/// policy rules out an HTTP crate, and Prometheus' text exposition
/// format needs nothing more). Three paths:
///
/// - `GET /metrics` — Prometheus text format v0.0.4: memory, entries,
///   operation counters, connection occupancy, and one gauge pair per
///   live namespace (see `Cache::stats`).
/// - `GET /healthz` — liveness: `200` while the process serves at all.
/// - `GET /readyz` — readiness: `200` once this node can serve clients —
///   standalone immediately, a cluster node once it has adopted a
///   membership view (`known_ring`); `503` before that, so an
///   orchestrator keeps it out of rotation while it is still joining.
///
/// Runs on its own listener (`--metrics-port`): scrapes never compete
/// for, or count against, client connection permits, and the port can
/// stay unexposed to clients. No auth — the exposition is operational
/// telemetry, and the deployment guide says to keep the port internal.
#[allow(clippy::too_many_arguments)]
async fn run_metrics_server(
    listener: TcpListener,
    request_tx: mpsc::Sender<CacheRequest>,
    connection_limit: Arc<Semaphore>,
    max_connections: usize,
    known_ring: KnownRing,
    is_cluster: bool,
    mut shutdown_rx: watch::Receiver<bool>,
    metrics_connection_limit: Arc<Semaphore>,
) {
    // Tenth-pass audit (2026-09-02): these used to be bare detached
    // `tokio::spawn`s — a panic in `serve_metrics_connection`/
    // `render_node_metrics` went unobserved, and the tasks were untracked
    // at shutdown (nothing here awaited or aborted them; the process
    // exiting was the only thing that ever stopped one). Tracked in a
    // `JoinSet` instead, reaped as it goes — same shape as `run`'s own
    // `connection_tasks` — so a panic is logged and shutdown can abort
    // whatever's left. Bounded by `metrics_connection_limit` regardless,
    // so this never grows past that many outstanding at once.
    let mut connection_tasks: JoinSet<()> = JoinSet::new();

    loop {
        let accepted = tokio::select! {
            accepted = listener.accept() => accepted,

            result = connection_tasks.join_next(), if !connection_tasks.is_empty() => {
                if let Some(Err(error)) = result {
                    eprintln!("WARN metrics connection task failed: {error}");
                }
                continue;
            }

            _ = shutdown_rx.changed() => {
                // The task itself is aborted by dropping it (`abort_all`
                // is redundant with that, but says so explicitly rather
                // than relying on `JoinSet`'s drop behavior).
                connection_tasks.abort_all();
                return;
            }
        };
        let (stream, _) = match accepted {
            Ok(pair) => pair,
            Err(error) => {
                // Issue #184: mirrors `run`'s own accept loop (see
                // `should_backoff_after_accept_error`'s doc comment) — an
                // unadorned `continue` here would busy-loop this task hot
                // under EMFILE/ENFILE instead of backing off, making
                // recovery harder right when file descriptors are already
                // scarce.
                if should_backoff_after_accept_error(&error) {
                    sleep(ACCEPT_ERROR_BACKOFF).await;
                }
                continue;
            }
        };

        // Issue #327: this listener has no client-listener-style busy
        // reply (that's a cache-protocol response, meaningless to an
        // HTTP scraper) — cap it with its own small semaphore instead,
        // dropping the connection outright once it's exhausted rather
        // than spawning an unbounded number of handler tasks. Mirrors
        // `nanocached-proxy`'s `run_metrics_server` (issue #233).
        let Ok(metrics_permit) = Arc::clone(&metrics_connection_limit).try_acquire_owned() else {
            drop(stream);
            continue;
        };

        let request_tx = request_tx.clone();
        let connection_limit = Arc::clone(&connection_limit);
        let known_ring = Arc::clone(&known_ring);
        connection_tasks.spawn(async move {
            let _metrics_permit = metrics_permit;
            let _ = timeout(
                Duration::from_secs(5),
                serve_metrics_connection(
                    stream,
                    request_tx,
                    connection_limit,
                    max_connections,
                    known_ring,
                    is_cluster,
                ),
            )
            .await;
        });
    }
}

async fn serve_metrics_connection(
    mut stream: TcpStream,
    request_tx: mpsc::Sender<CacheRequest>,
    connection_limit: Arc<Semaphore>,
    max_connections: usize,
    known_ring: KnownRing,
    is_cluster: bool,
) -> io::Result<()> {
    let path = read_http_request_path(&mut stream).await?;

    let (status, body): (&str, String) = match path.as_str() {
        "/metrics" => match execute_command(
            &request_tx,
            Command::Stats {
                largest_namespaces: METRICS_MAX_NAMESPACE_SERIES,
            },
        )
        .await
        {
            Ok(Response::Stats(stats)) => {
                let connections =
                    max_connections.saturating_sub(connection_limit.available_permits());
                (
                    "200 OK",
                    render_node_metrics(&stats, connections, max_connections),
                )
            }
            _ => (
                "500 Internal Server Error",
                "cache actor unavailable\n".to_string(),
            ),
        },
        "/healthz" => ("200 OK", "ok\n".to_string()),
        "/readyz" => {
            let ready = !is_cluster
                || known_ring
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .is_some();
            if ready {
                ("200 OK", "ok\n".to_string())
            } else {
                ("503 Service Unavailable", "joining\n".to_string())
            }
        }
        _ => ("404 Not Found", "not found\n".to_string()),
    };

    write_http_response(&mut stream, status, &body).await
}

/// Prometheus label values allow any UTF-8 with `\\`, `\"` and newline
/// escaped; namespaces are arbitrary bytes, so non-UTF-8 goes through
/// lossy replacement first.
fn metrics_label_escape(raw: &[u8]) -> String {
    String::from_utf8_lossy(raw)
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
}

/// How many namespaces `/metrics` lists per-namespace series for: the
/// largest by bytes, with the rest counted in
/// `nanocached_node_namespaces_unlisted`. Any client that can write can
/// create a namespace, and its name can be up to the request-size limit,
/// so without this the size of a scrape was chosen by data-port clients:
/// three hundred 1 MB names made a body several times their size, built
/// in two or three copies, and a 1 GiB node was killed by one scrape.
const METRICS_MAX_NAMESPACE_SERIES: usize = 256;

/// The longest namespace name reproduced in a `namespace` label. A longer
/// one is cut to `METRICS_LABEL_KEEP_BYTES` and suffixed with the hash
/// of the whole name, so two long names that share a prefix still get
/// distinct labels, and the same name gets the same label on every
/// scrape. Together with `METRICS_MAX_NAMESPACE_SERIES` this bounds the
/// body at a few hundred bytes per listed namespace.
const METRICS_MAX_LABEL_BYTES: usize = 256;
const METRICS_LABEL_KEEP_BYTES: usize = 128;

/// The `namespace` label for a name: escaped, and elided past
/// `METRICS_MAX_LABEL_BYTES` (see the constant).
fn metrics_namespace_label(name: &[u8]) -> String {
    if name.len() <= METRICS_MAX_LABEL_BYTES {
        return metrics_label_escape(name);
    }
    // Cut on a char boundary of the lossy decoding, so the kept prefix
    // is valid text.
    let text = String::from_utf8_lossy(name);
    let mut keep = METRICS_LABEL_KEEP_BYTES.min(text.len());
    while !text.is_char_boundary(keep) {
        keep -= 1;
    }
    let mut hash: u64 = 0xcbf29ce484222325;
    for &byte in name {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!(
        "{}…[{} bytes, fnv1a {hash:016x}]",
        metrics_label_escape(text[..keep].as_bytes()),
        name.len()
    )
}

fn render_node_metrics(
    stats: &crate::cache::CacheStats,
    connections: usize,
    max_connections: usize,
) -> String {
    let mut out = String::new();
    let mut metric = |name: &str, kind: &str, help: &str, value: String| {
        out.push_str(&format!(
            "# HELP {name} {help}\n# TYPE {name} {kind}\n{value}"
        ));
    };

    metric(
        "nanocached_node_memory_used_bytes",
        "gauge",
        "Bytes of cache memory in use (keys + values + per-entry overhead).",
        format!("nanocached_node_memory_used_bytes {}\n", stats.used_bytes),
    );
    metric(
        "nanocached_node_memory_max_bytes",
        "gauge",
        "The --max-memory bound.",
        format!(
            "nanocached_node_memory_max_bytes {}\n",
            stats.max_memory_bytes
        ),
    );
    metric(
        "nanocached_node_entries",
        "gauge",
        "Live entries across every namespace.",
        format!("nanocached_node_entries {}\n", stats.entries),
    );
    metric(
        "nanocached_node_connections",
        "gauge",
        "Client connections currently held (of the connection limit).",
        format!("nanocached_node_connections {connections}\n"),
    );
    metric(
        "nanocached_node_connections_max",
        "gauge",
        "The --max-connections bound — the proxy exports the \
         same pair, so utilization dashboards can treat both tiers alike.",
        format!("nanocached_node_connections_max {max_connections}\n"),
    );
    metric(
        "nanocached_node_hits_total",
        "counter",
        "GET requests answered with a value.",
        format!("nanocached_node_hits_total {}\n", stats.hits),
    );
    metric(
        "nanocached_node_misses_total",
        "counter",
        "GET requests answered not-found (expired included).",
        format!("nanocached_node_misses_total {}\n", stats.misses),
    );
    metric(
        "nanocached_node_sets_total",
        "counter",
        "Stored client writes (S, s and o frames). Cluster-management \
         transfers travel as handoff frames (U/u) and are not counted \
         here — a staged join's migration, a decommissioning node's \
         drain-out and re-replication alike — so a joiner's entries \
         rise while this counter stays flat.",
        format!("nanocached_node_sets_total {}\n", stats.sets),
    );
    metric(
        "nanocached_node_deletes_total",
        "counter",
        "Client deletes (D and d frames) that removed a live entry. A \
         delete relayed from another owner during a join is not counted \
         here, like the handoff frames left out of sets_total.",
        format!("nanocached_node_deletes_total {}\n", stats.deletes),
    );
    metric(
        "nanocached_node_evictions_total",
        "counter",
        "Entries evicted by the memory bound.",
        format!("nanocached_node_evictions_total {}\n", stats.evictions),
    );
    metric(
        "nanocached_node_expirations_total",
        "counter",
        "Entries removed because their TTL passed.",
        format!("nanocached_node_expirations_total {}\n", stats.expirations),
    );
    metric(
        "nanocached_node_incrs_total",
        "counter",
        "Successful INCR operations — a stored value that \
         wasn't INCR's counter grammar, or an overflowing delta, isn't \
         counted here.",
        format!("nanocached_node_incrs_total {}\n", stats.incrs),
    );
    metric(
        "nanocached_node_cas_sets_total",
        "counter",
        "Successful k (compare-and-set) writes — a mismatched \
         condition isn't counted here, and neither are internal \
         re-replication handoffs: this counts client k \
         frames only.",
        format!("nanocached_node_cas_sets_total {}\n", stats.cas_sets),
    );
    metric(
        "nanocached_node_cas_deletes_total",
        "counter",
        "Successful x (compare-and-delete) removals — a \
         mismatched condition or missing key isn't counted here.",
        format!("nanocached_node_cas_deletes_total {}\n", stats.cas_deletes),
    );

    metric(
        "nanocached_node_touches_total",
        "counter",
        "Client touches handled, whether or not the key was there: each \
         t (touch and get-and-touch) frame and each key of a y (batch \
         touch) frame. A touch forwarded to a joining or \
         entering node travels as a handoff set and is not counted here, \
         like the handoff frames left out of sets_total. A t with G also \
         counts in hits_total or misses_total, as g does; a plain one \
         does not.",
        format!("nanocached_node_touches_total {}\n", stats.touches),
    );
    metric(
        "nanocached_node_touch_misses_total",
        "counter",
        "The touches counted in touches_total that found no live entry \
         (missing or expired). One with G is also in misses_total; a \
         plain one is only here.",
        format!(
            "nanocached_node_touch_misses_total {}\n",
            stats.touch_misses
        ),
    );

    // `stats.namespaces` holds the largest `METRICS_MAX_NAMESPACE_SERIES`
    // by bytes, largest first — the cache task cut the rest off before
    // sorting (`Cache::stats_top`), so the ones that matter for capacity
    // are listed and a node with a million namespaces does not sort them
    // all per scrape.
    let listed = stats.namespaces.len().min(METRICS_MAX_NAMESPACE_SERIES);
    metric(
        "nanocached_node_namespaces",
        "gauge",
        "Live namespaces (those holding at least one entry).",
        format!("nanocached_node_namespaces {}\n", stats.namespace_count),
    );
    metric(
        "nanocached_node_namespaces_unlisted",
        "gauge",
        "Live namespaces beyond the largest 256 by bytes, which have no \
         per-namespace series below; their entries and bytes are still \
         in the node-wide gauges.",
        format!(
            "nanocached_node_namespaces_unlisted {}\n",
            stats.namespace_count - listed
        ),
    );

    let mut namespace_entries = String::new();
    let mut namespace_bytes = String::new();
    let mut namespace_budgets = String::new();
    for namespace in &stats.namespaces[..listed] {
        let label = metrics_namespace_label(&namespace.namespace);
        namespace_entries.push_str(&format!(
            "nanocached_node_namespace_entries{{namespace=\"{label}\"}} {}\n",
            namespace.entries
        ));
        namespace_bytes.push_str(&format!(
            "nanocached_node_namespace_used_bytes{{namespace=\"{label}\"}} {}\n",
            namespace.used_bytes
        ));
        if let Some(budget) = namespace.budget_bytes {
            namespace_budgets.push_str(&format!(
                "nanocached_node_namespace_budget_bytes{{namespace=\"{label}\"}} {budget}\n",
            ));
        }
    }
    if listed > 0 {
        metric(
            "nanocached_node_namespace_entries",
            "gauge",
            "Live entries per namespace (empty label = the default namespace; \
             the largest 256 namespaces by bytes are listed, a name over 256 \
             bytes is cut and suffixed with its length and hash).",
            namespace_entries,
        );
        metric(
            "nanocached_node_namespace_used_bytes",
            "gauge",
            "Bytes per namespace.",
            namespace_bytes,
        );
    }
    if !namespace_budgets.is_empty() {
        metric(
            "nanocached_node_namespace_budget_bytes",
            "gauge",
            "The --namespace-budget cap, for namespaces that have one.",
            namespace_budgets,
        );
    }

    out
}

/// `c`/`F` (issue #106): applied to this node's own store unconditionally
/// — a clear isn't key-addressed, so there is no wrong-node check; the
/// client fans it out to every member and each drops its own sub-map —
/// then replayed on the joiner of an in-flight handoff, if any, so a
/// clear racing a migration can't resurrect entries there. See
/// `route_clear` for which path the replay takes.
async fn handle_clear(
    stream: &mut ServerStream,
    request_tx: &mpsc::Sender<CacheRequest>,
    config: &ConnectionConfig,
    scope: ClearScope,
    tag: Option<u32>,
) -> io::Result<()> {
    let command = match &scope {
        ClearScope::Namespace(namespace) => Command::Clear {
            namespace: namespace.clone(),
        },
        ClearScope::All => Command::ClearAll,
    };
    let response = execute_command(request_tx, command).await?;

    // Queued before the ack, like every forward (see `spawn_forward`).
    if let Some(node_context) = &config.node_context {
        // Issue #564: earlier joiners still inside their forwarding grace
        // need the clear as well, not just the slot's own joiner.
        for target in lingering_clear_targets(node_context) {
            spawn_forward(
                config,
                node_context.clone(),
                target,
                OwnedForwardedWrite::Clear(scope.clone()),
            )
            .await;
        }
        // A decommission in flight: a write this node acknowledged and
        // queued for an entrant must not outlive a clear the client then
        // sent to every node it knows, so the clear rides the same
        // per-entrant queue, behind that write.
        for target in leave_clear_targets(node_context) {
            spawn_forward(
                config,
                node_context.clone(),
                target,
                OwnedForwardedWrite::Clear(scope.clone()),
            )
            .await;
        }
        // An eviction's re-replication in flight: the same ordering for
        // the owners the change promoted, which this node mirrors its
        // client writes to (`rereplication_targets_for_hashed`).
        for target in rereplication_clear_targets(node_context) {
            spawn_forward(
                config,
                node_context.clone(),
                target,
                OwnedForwardedWrite::Clear(scope.clone()),
            )
            .await;
        }
        if let ClearRoute::Forward(target) = route_clear(node_context, &scope) {
            spawn_forward(
                config,
                node_context.clone(),
                target,
                OwnedForwardedWrite::Clear(scope),
            )
            .await;
        }
    }
    write_response(stream, &encode_response(&response, tag)).await?;

    Ok(())
}

/// Where a clear's replay to an in-flight handoff's joiner goes.
enum ClearRoute {
    /// No handoff is forwarding: nothing to replay.
    None,
    /// Queued on the slot for the transfer loop to replay in order — see
    /// `ActiveMigration::pending_clears`.
    Queued,
    /// This node's own transfer is done; forward on the shared
    /// connection like a concurrent `S`/`D`.
    Forward(ForwardTarget),
}

fn route_clear(node_context: &NodeContext, scope: &ClearScope) -> ClearRoute {
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());

    // Same lazy expiry as `migration_target_for`.
    if slot.as_ref().is_some_and(ActiveMigration::expired) {
        *slot = None;
    }

    let Some(active) = slot.as_mut() else {
        return ClearRoute::None;
    };

    if active.completed_at.is_none() {
        active.pending_clears.push(scope.clone());
        return ClearRoute::Queued;
    }

    if !active.forwarding_open() {
        return ClearRoute::None;
    }

    ClearRoute::Forward(ForwardTarget {
        addr: active.joining_addr.clone(),
        connection: Arc::clone(&active.forward_connection),
        token: active.joining_token.clone(),
        revoked: Arc::clone(&active.forward_revoked),
        as_handoff: false,
    })
}

fn encode_response(response: &Response, tag: Option<u32>) -> Vec<u8> {
    match tag {
        Some(tag) => response.encode_with_tag(tag),
        None => response.encode(),
    }
}

async fn handle_connection(
    mut stream: ServerStream,
    address: SocketAddr,
    request_tx: mpsc::Sender<CacheRequest>,
    config: ConnectionConfig,
    mut shutdown_rx: watch::Receiver<bool>,
) -> io::Result<()> {
    let mut received = BytesMut::new();
    // What `received`'s capacity beyond `REQUEST_BUFFER_SHRINK_THRESHOLD`
    // is charged against the in-flight budget, and the permit holding it
    // (see `InFlightBudget`): grown before the buffer is, shrunk with it.
    let mut receive_charge: Option<tokio::sync::OwnedSemaphorePermit> = None;
    let mut receive_charged = 0usize;
    // No secret configured means auth isn't required, so every connection
    // starts already authenticated.
    let mut authenticated = config.auth_secret.is_none();

    // Slowloris resistance: anchored to accept-time here, then re-anchored
    // to `now + config.idle_timeout` below every time `parse` completes a
    // full command — see the comment there and `IDLE_TIMEOUT`'s own doc
    // comment for why this is `now + idle_timeout` at those two moments
    // specifically, rather than on every byte read.
    let mut deadline = Instant::now() + config.idle_timeout;

    // Note for the pre-authentication phase: `deadline` is only ever
    // re-anchored by a fully parsed command, and before authenticating the
    // only one that doesn't end the connection is the `A` that
    // authenticates — so the accept-time deadline above is already a fixed,
    // non-resetting bound on authentication; trickling bytes cannot renew it.

    // Echoed response tags: set once an `A ... T` is accepted. From then on every
    // request must carry a trailing tag (`parse_tagged`) and every
    // `G`/`S`/`D` response echoes it, so the client's read loop can
    // verify request/response alignment before dispatching.
    let mut tagged = false;

    // See `command::parse_resumable`: reset by it on anything but
    // `Incomplete`, which is exactly when `received`'s front changes.
    let mut parse_progress = MigrateProgress::default();

    loop {
        // Before authenticating, only an `A` frame is acceptable, so
        // anything else is turned away on its first byte — without
        // parsing it or buffering the rest of it. (A client that
        // authenticates and pipelines commands behind the `A` in one
        // write is unaffected: it leads with `A`.)
        if !authenticated && received.first().is_some_and(|lead| *lead != b'A') {
            write_response(&mut stream, &Response::Unauthorized.encode()).await?;
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "command sent before authenticating",
            ));
        }

        let buffered_before = received.len();
        let mut parsed = parse_resumable(&mut received, tagged, &mut parse_progress, false);
        // A multi-key frame (`m`, `o`, `y`) is charged for its per-key
        // working memory before the parser builds its key vectors, not
        // after: a connection waiting for the budget would otherwise hold
        // those vectors (about 32 bytes per key) uncharged for as long as
        // it waits. The parse stopped short of building them; charge, then
        // parse again. The size limit comes first, so that a frame that is
        // refused does not wait for the budget either.
        let mut frame_charge = None;
        if let Err(ParseError::ChargeRequired {
            keys,
            values,
            frame_len,
        }) = parsed
        {
            if request_is_too_large(frame_len) {
                return Err(reject_oversized_request(
                    &mut stream,
                    "request is too large".to_string(),
                )
                .await);
            }
            frame_charge =
                Some(charge_multi_key_frame(&config, receive_charged, keys, values).await?);
            parsed = parse_resumable(&mut received, tagged, &mut parse_progress, true);
        }

        if parsed.is_ok() {
            // `MAX_REQUEST_SIZE` is a bound on one frame, so it is checked
            // against the frame `parse` just took off the front of
            // `received` — never against `received.len()` after a read,
            // which also holds whatever the client pipelined behind that
            // frame. A buffer grown past the limit by doubling (see the
            // `reserve` below) once took the tail of a valid 700 KiB frame
            // and the frames behind it in one read, and the sum was
            // refused as "too large" although no frame was. Through the
            // proxy's shared backend connection, where every client's
            // frames arrive back to back, that poisoned the connection
            // for the other clients.
            if request_is_too_large(buffered_before - received.len()) {
                return Err(reject_oversized_request(
                    &mut stream,
                    "request is too large".to_string(),
                )
                .await);
            }
            // Only a fully parsed command extends the deadline — an
            // `Incomplete` result (more bytes needed) leaves it untouched,
            // so a client that trickles bytes in without ever finishing a
            // command can't renew its own budget one byte at a time. See
            // `IDLE_TIMEOUT`'s doc comment.
            deadline = Instant::now() + config.idle_timeout;
        }

        match parsed {
            Ok((
                Command::Auth {
                    secret,
                    tagging,
                    // Issue #125: accepted so the `A ... T R` probe
                    // succeeds against a node without a fallback round
                    // trip, but unused — the node has no transient
                    // per-request failure to report and never emits `R`
                    // (the proxy is the emitter today).
                    retry_capable: _,
                },
                _,
            )) => {
                let accepted = match &config.auth_secret {
                    Some(expected) => constant_time_eq(&secret, expected),
                    None => true,
                };

                // The identity reply echoes the tag capability only to a
                // client that asked for it (echoed response tags) — a plain `A` keeps
                // the exact three-byte reply older SDKs hard-read.
                let identity = |response: &Response| {
                    if tagging {
                        response.encode_identity_tagged()
                    } else {
                        response.encode()
                    }
                };

                if accepted {
                    authenticated = true;
                    tagged = tagging;
                    write_response(&mut stream, &identity(&Response::AuthOk)).await?;
                    continue;
                }

                write_response(&mut stream, &identity(&Response::Unauthorized)).await?;
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "invalid auth secret",
                ));
            }
            Ok(_) if !authenticated => {
                write_response(&mut stream, &Response::Unauthorized.encode()).await?;
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "command sent before authenticating",
                ));
            }
            Ok((
                Command::Migrate {
                    token,
                    joining_name,
                    joining_addr,
                    joining_token,
                    joined,
                    replication,
                    generation,
                },
                _,
            )) => {
                let Some(node_context) = config.node_context.clone() else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "received M but this node isn't configured with a discovery server",
                    ));
                };

                // Issue #124: a decommissioning node must not take on a
                // new join handoff — its own drain-out is moving the
                // very entries a join would want it to send. Rejecting
                // lets discovery's retry land once this node has left.
                if node_context
                    .leaving
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .is_some()
                {
                    write_response(&mut stream, &Response::MigrationRejected.encode()).await?;
                    continue;
                }

                // The shared secret proves only "cluster member" (shared-secret authentication),
                // not "the discovery server" — so without this every client
                // holding it could send `M` and make this node stream its
                // cache to an attacker-chosen address. Discovery echoes this
                // node's own membership token (issue #34) on `M`; only a
                // discovery server this node registered with knows it (no
                // client does, and it's never sent back out — per-node membership tokens), so
                // a mismatch means the sender isn't discovery. Reject loudly.
                if !constant_time_eq(token.as_bytes(), node_context.token.as_bytes()) {
                    eprintln!(
                        "WARN rejected M from {address}: membership token mismatch \
                         (sender is not this node's discovery server)"
                    );
                    write_response(&mut stream, &Response::MigrationRejected.encode()).await?;
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        "M carried the wrong membership token",
                    ));
                }

                let (before_ring, after_ring) =
                    migration_rings(&node_context, &joining_name, &joined);
                let after_ring = Arc::new(after_ring);

                // Reserved *before* acknowledging `M`, not inside
                // `run_migration` after the fact: only this ordering lets
                // a conflicting `M` (issue #3 — this node's single
                // migration slot already occupied) be reported as
                // `MigrationRejected` on the same ack, instead of telling
                // the sender `MigrationAccepted` and then silently doing
                // nothing.
                let migration_guard = match MigrationGuard::new(
                    Arc::clone(&node_context.active_migration),
                    joining_name.clone(),
                    joining_addr.clone(),
                    joining_token.clone(),
                    Arc::clone(&after_ring),
                    replication,
                    generation,
                    &joined,
                    &node_context.known_ring,
                    &node_context.ring_history,
                ) {
                    MigrationOutcome::New { guard, restore } => {
                        // Issue #62: before the key snapshot below, so
                        // the restored copies are listed — and re-sent
                        // if this joiner owns them. One round trip for
                        // the lot: one per key kept discovery waiting
                        // past its ack timeout on a large restore.
                        unmark_migrated_many(&node_context.request_tx, restore).await;
                        guard
                    }
                    // A discovery retry of `M` for the handoff already
                    // running here (its ack was lost in transit) — re-ack
                    // with the same count the original `M` computed
                    // instead of starting a second migration. See
                    // `MigrationGuard::new`'s doc comment.
                    MigrationOutcome::DuplicateAcked(entries) => {
                        write_response(&mut stream, &Response::MigrationAccepted(entries).encode())
                            .await?;
                        continue;
                    }
                    MigrationOutcome::Conflict => {
                        write_response(&mut stream, &Response::MigrationRejected.encode()).await?;
                        continue;
                    }
                };

                // Size-derived migration timeout: sizes discovery's migration timeout.
                // Issue (perf): one `list_keys` snapshot here, reused by
                // both `entries_to_send_count` (for this count) and
                // `run_migration` (for the actual transfer) below,
                // instead of each independently cloning the whole cache —
                // see `entries_to_send_count`'s own comment. `None` if
                // the cache task is already gone (shutting down); 0 is a
                // safe default for the count here since `run_migration`
                // independently checks for the same `None` and aborts on
                // its own.
                let keys_snapshot = list_keys(&node_context.request_tx).await;
                let entries_to_send = match keys_snapshot.as_deref() {
                    Some(keys) => {
                        entries_to_send_count(
                            keys,
                            &before_ring,
                            &after_ring,
                            &node_context.name,
                            &joining_name,
                            replication,
                        )
                        .await
                    }
                    None => 0,
                };

                // Stamped before acking, not after, so a retry of this
                // same `M` arriving right after the ack goes out (but
                // before this stamp landed) still finds `acked_entries`
                // set — see `MigrationGuard::new`.
                migration_guard.ack(entries_to_send);

                write_response(
                    &mut stream,
                    &Response::MigrationAccepted(entries_to_send).encode(),
                )
                .await?;

                // Handed to `run`'s own loop rather than spawned here
                // directly, so it ends up tracked by `connection_tasks` —
                // see `ConnectionConfig::migration_tx`. If the receiving
                // end is already gone (`run` has moved past its select
                // loop into its own shutdown drain), there's nothing left
                // to hand this to; the migration is simply not started,
                // matching how a same-timing `M` arriving a moment later
                // would find the listener already closed.
                let _ = config
                    .migration_tx
                    .send(Box::pin(run_migration(
                        node_context,
                        joining_name,
                        joining_addr,
                        joining_token,
                        generation,
                        replication,
                        before_ring,
                        after_ring,
                        migration_guard,
                        keys_snapshot,
                    )))
                    .await;

                continue;
            }
            Ok((
                Command::CancelMigration {
                    token,
                    joining_name,
                },
                _,
            )) => {
                let Some(node_context) = config.node_context.clone() else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "received X but this node isn't configured with a discovery server",
                    ));
                };

                // Same authorization as `M` (see there): without the token
                // check any client holding the shared secret could abort a
                // legitimate in-flight handoff just by sending `X`.
                if !constant_time_eq(token.as_bytes(), node_context.token.as_bytes()) {
                    eprintln!(
                        "WARN rejected X from {address}: membership token mismatch \
                         (sender is not this node's discovery server)"
                    );
                    // Send an explicit rejection frame before closing, the
                    // same shape `M`/`U` use on a token mismatch, so the
                    // caller reads a rejection rather than only observing a
                    // bare connection reset.
                    write_response(&mut stream, &Response::MigrationRejected.encode()).await?;
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        "X carried the wrong membership token",
                    ));
                }

                // A safe no-op if there's no active migration, or it's for
                // a different `joining_name` (already finished, or this
                // cancel arrived late) — `run_migration` alone decides
                // whether to actually stop.
                match abandon_migration(&node_context, &joining_name) {
                    AbandonOutcome::Completed(restore) => {
                        eprintln!(
                            "WARN join of {joining_name} abandoned by discovery after this \
                             node's handoff completed; restoring {} dead copies",
                            restore.len()
                        );
                        unmark_migrated_many(&node_context.request_tx, restore).await;
                    }
                    // Still transferring: wait for `run_migration`'s own
                    // unwind to actually clear the slot before acking —
                    // see `wait_for_migration_slot_to_clear`'s doc
                    // comment for why acking immediately here would let
                    // discovery race a same-name retry (a fast rejoin)
                    // into a slot that isn't free yet.
                    AbandonOutcome::Aborting => {
                        wait_for_migration_slot_to_clear(&node_context, &joining_name).await;
                    }
                    AbandonOutcome::NoMatch => {}
                }

                write_response(&mut stream, &Response::MigrationCancelled.encode()).await?;

                continue;
            }
            Ok((Command::Get { key }, tag)) => {
                if let Some(node_context) = &config.node_context
                    && wrong_node_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response = execute_command(&request_tx, Command::Get { key }).await?;
                write_reply(&mut stream, &config, &response, tag).await?;

                continue;
            }
            // Issue #128 measurement prototype: per-key wrong-node
            // filtering happens here, before the actor ever sees the
            // frame — same check `Get`'s arm makes per key, just batched.
            // Keys this node owns go to the actor as one `Command::MultiGet`
            // (one round trip for all of them); keys it doesn't are
            // answered `MultiEntry::WrongNode` without ever reaching the
            // actor. Results are spliced back into the original request
            // order before replying — the client never sees the owned/
            // not-owned split.
            Ok((Command::MultiGet { namespace, keys }, tag)) => {
                let _frame_charge = frame_charge;
                let mut entries: Vec<Option<MultiEntry>> = vec![None; keys.len()];
                let mut owned_positions = Vec::with_capacity(keys.len());
                let mut owned_keys = Vec::with_capacity(keys.len());
                // The namespace is shared by every key of the frame and may
                // be ~1 MiB, so its share of the key hash is computed once
                // (`KeyHasher`), not per key.
                let mut hasher = KeyHasher::default();
                let hashes: Vec<KeyHash> = keys
                    .iter()
                    .map(|name| hasher.hash(&Key::new(namespace.clone(), name.clone())))
                    .collect();
                let wrong = match &config.node_context {
                    Some(node_context) => wrong_nodes_refreshed(node_context, &hashes).await,
                    None => vec![false; keys.len()],
                };

                for (position, name) in keys.into_iter().enumerate() {
                    if wrong[position] {
                        entries[position] = Some(MultiEntry::WrongNode);
                    } else {
                        owned_positions.push(position);
                        owned_keys.push(name);
                    }
                }

                if !owned_keys.is_empty() {
                    let response = execute_command(
                        &request_tx,
                        Command::MultiGet {
                            namespace,
                            keys: owned_keys,
                        },
                    )
                    .await?;

                    let Response::Multi(results) = response else {
                        unreachable!("Command::MultiGet always answers with Response::Multi");
                    };

                    for (position, result) in owned_positions.into_iter().zip(results) {
                        entries[position] = Some(result);
                    }
                }

                let entries = entries
                    .into_iter()
                    .map(|entry| entry.expect("every position filled by one of the two branches"))
                    .collect();
                write_reply(&mut stream, &config, &Response::Multi(entries), tag).await?;

                continue;
            }
            // Issue #150: same per-key wrong-node filtering as
            // `MultiGet`'s arm above — keys this node owns go to the
            // actor as one `Command::MultiSet`; keys it doesn't are
            // answered `MultiAckEntry::WrongNode` without ever reaching
            // the actor.
            Ok((
                Command::MultiSet {
                    namespace,
                    keys,
                    values,
                    ttl,
                },
                tag,
            )) => {
                let _frame_charge = frame_charge;
                let mut entries: Vec<Option<MultiAckEntry>> = vec![None; keys.len()];
                let mut owned_positions = Vec::with_capacity(keys.len());
                let mut owned_keys = Vec::with_capacity(keys.len());
                let mut owned_values = Vec::with_capacity(keys.len());
                // See `MultiGet`'s arm: the namespace's share of each key's
                // hash is computed once per frame.
                let mut hasher = KeyHasher::default();
                let hashes: Vec<KeyHash> = keys
                    .iter()
                    .map(|name| hasher.hash(&Key::new(namespace.clone(), name.clone())))
                    .collect();
                let wrong = match &config.node_context {
                    Some(node_context) => wrong_nodes_refreshed(node_context, &hashes).await,
                    None => vec![false; keys.len()],
                };

                for (position, (name, value)) in keys.into_iter().zip(values).enumerate() {
                    if wrong[position] {
                        entries[position] = Some(MultiAckEntry::WrongNode);
                    } else {
                        owned_positions.push(position);
                        owned_keys.push(name);
                        owned_values.push(value);
                    }
                }

                if !owned_keys.is_empty() {
                    // Kept for the forwarding loop below — `owned_keys`/
                    // `owned_values` are moved into the `Command::MultiSet`
                    // call, and `Bytes::clone` is a cheap refcount bump.
                    // Issue #233: skip the clone entirely when there's no
                    // `node_context` to forward through — the loop below
                    // never runs in that case.
                    //
                    // Tenth-pass audit (2026-09-02), issue #408 regression:
                    // issue #408 additionally skipped the clone whenever
                    // `active_migration`/`leaving` were both empty *before*
                    // `execute_command` ran, on the theory that
                    // `migration_target_for`/`leave_target_for` would find
                    // nothing after the write either. That's a snapshot
                    // race: a join migration or decommission can start
                    // *while* the actor is processing this write (the
                    // request channel hop and the actor's own processing
                    // both yield), so the pre-write snapshot can read empty
                    // while the post-write lookup would find a target — and
                    // with no clone kept, the write is silently never
                    // forwarded (the class of bug issue #176 fixed for the
                    // single-key `Set` path below, which always re-checks
                    // after the write). Clone unconditionally whenever
                    // `node_context.is_some()`, same as before #408; a
                    // `Bytes::clone` is a cheap refcount bump, so this
                    // trades a bump per key for correctness rather than
                    // saving a bump per key at the cost of losing writes.
                    let forward = config
                        .node_context
                        .is_some()
                        .then(|| (owned_keys.clone(), owned_values.clone()));

                    let response = execute_command(
                        &request_tx,
                        Command::MultiSet {
                            namespace: namespace.clone(),
                            keys: owned_keys,
                            values: owned_values,
                            ttl,
                        },
                    )
                    .await?;

                    let Response::MultiAck(results) = response else {
                        unreachable!("Command::MultiSet always answers with Response::MultiAck");
                    };

                    // Issue #176: `Set` (below) forwards a write on a key
                    // caught mid-handoff (staged join) or mid-drain
                    // (decommission) so it isn't lost once `known_ring`
                    // flips — `MultiSet` never did, so a bulk write during
                    // either window silently vanished. Mirror it here, per
                    // owned key, once the local write is confirmed stored
                    // (`execute` only ever answers `Stored` for an owned
                    // key, but check anyway rather than assume it).
                    //
                    // The matching keys are gathered per target and queued
                    // for it in one go (`enqueue_forwards`). Each one lands
                    // in the target's coalescing queue, so a frame with
                    // >100k keys costs one map insert per key and nothing is
                    // dropped for want of room: a later write to a key
                    // replaces an earlier one still waiting.
                    if let (Some(node_context), Some((forward_names, forward_values))) =
                        (&config.node_context, forward)
                    {
                        let mut join_batches: Vec<ForwardBatch> = Vec::new();
                        let mut leave_batches: Vec<ForwardBatch> = Vec::new();

                        for ((name, value), result) in forward_names
                            .into_iter()
                            .zip(forward_values)
                            .zip(results.iter())
                        {
                            if !matches!(result, MultiAckEntry::Stored) {
                                continue;
                            }
                            let key = Key::new(namespace.clone(), name);
                            let key_hash = hasher.hash(&key);

                            // Staged node join — see `migration_targets_for`.
                            for target in migration_targets_for_hashed(node_context, key_hash) {
                                ForwardBatch::add(
                                    &mut join_batches,
                                    target,
                                    key.name.clone(),
                                    value.clone(),
                                );
                            }

                            // Decommission drain — see `leave_target_for`.
                            for target in handoff_targets_for_hashed(node_context, key_hash) {
                                ForwardBatch::add(
                                    &mut leave_batches,
                                    target,
                                    key.name.clone(),
                                    value.clone(),
                                );
                            }
                        }

                        for (batches, handoff) in [(join_batches, false), (leave_batches, true)] {
                            for batch in batches {
                                let writes = batch.items.into_iter().map(|(name, value)| {
                                    let key = Key::new(namespace.clone(), name);
                                    if handoff {
                                        OwnedForwardedWrite::HandoffSet {
                                            key,
                                            value,
                                            ttl,
                                            if_absent: false,
                                        }
                                    } else {
                                        OwnedForwardedWrite::Set { key, value, ttl }
                                    }
                                });
                                enqueue_forwards(
                                    &config,
                                    node_context.clone(),
                                    batch.target,
                                    writes,
                                )
                                .await;
                            }
                        }
                    }

                    for (position, result) in owned_positions.into_iter().zip(results) {
                        entries[position] = Some(result);
                    }
                }

                let entries = entries
                    .into_iter()
                    .map(|entry| entry.expect("every position filled by one of the two branches"))
                    .collect();
                write_response(
                    &mut stream,
                    &encode_response(&Response::MultiAck(entries), tag),
                )
                .await?;

                continue;
            }
            Ok((Command::Set { key, value, ttl }, tag)) => {
                if let Some(node_context) = &config.node_context
                    && wrong_node_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response = execute_command(
                    &request_tx,
                    Command::Set {
                        key: key.clone(),
                        value: value.clone(),
                        ttl,
                    },
                )
                .await?;
                forward_result(&config, &key, ForwardedResult::Set { value, ttl }).await;

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((
                Command::HandoffSet {
                    key,
                    value,
                    ttl,
                    if_absent,
                    token,
                    ahead_of_ring: _,
                },
                tag,
            )) => {
                let Some(node_context) = config.node_context.clone() else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "received U but this node isn't configured with a discovery server",
                    ));
                };

                // Issue #295: `U` skips the wrong-node check below by
                // design (see this arm's own doc comment), so without
                // this it's the only thing standing between "any
                // shared-secret client" and "write any key here,
                // regardless of ring ownership" — the same gap `M`/`X`
                // close with their own `token` check (see
                // `Command::HandoffSet::token`'s doc comment). Same
                // rejection shape as `M`'s.
                if !constant_time_eq(token.as_bytes(), node_context.token.as_bytes()) {
                    eprintln!(
                        "WARN rejected U from {address}: membership token mismatch \
                         (sender is not a legitimate handoff source for this node)"
                    );
                    write_response(
                        &mut stream,
                        &encode_response(&Response::MigrationRejected, tag),
                    )
                    .await?;
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        "U carried the wrong membership token",
                    ));
                }

                // Issue #124: a decommissioning peer handing this node an
                // entry it is about to own — stored without the
                // wrong-node check (ownership becomes true when the
                // post-leave roster publishes, deliberately after this).
                // Issue #266: also how a survivor re-replicates a key to
                // the owner an eviction promoted, in which case
                // `if_absent` is set and a key already present here wins.
                // Issue #601: only a key this node does not own yet under
                // the membership it has adopted arrived ahead of its ring
                // — the case the reclaim pass's handoff pause exists for.
                // One it already owns is, to that pass, a client write.
                let ahead_of_ring = !owns_under_known_ring(&node_context, &key);
                let response = execute_command(
                    &request_tx,
                    Command::HandoffSet {
                        key: key.clone(),
                        value: value.clone(),
                        ttl,
                        if_absent,
                        token,
                        ahead_of_ring,
                    },
                )
                .await?;
                // Issue #975: a put-if-absent copy — a re-replication pass
                // promoting this node under the ring it saw — that lands
                // after this node's own join handoff took its key snapshot
                // is a copy of a key that handoff's ring has already moved
                // to the joiner. The relay below gets it to the joiner;
                // this node's copy is marked like the keys the snapshot did
                // send, or it stays a live copy of a key this node does not
                // own, reached by no write (clients route by the published
                // ring, no window covers it), and goes on to the next
                // joiner holding whatever it had before the owners deleted
                // or expired the key. An unconditional handoff is left
                // alone: a leaver's drain can make this node an owner under
                // a ring newer than the slot's, which cannot be told apart
                // here.
                if if_absent
                    && matches!(response, Response::Stored)
                    && let Some(node_context) = &config.node_context
                    && join_took(node_context, &key)
                {
                    mark_migrated(&request_tx, &key).await;
                }
                // If this node has a join for the key that discovery has
                // not confirmed yet, relay it to that joiner too — and only
                // to that one, see `unconfirmed_join_target_for`: whoever
                // sent this handoff reached every confirmed joiner itself,
                // and a relay there sent the frame around in circles.
                //
                // An ordinary (unconditional) handoff relays as an
                // unconditional `S`, exactly like a client `Set`.
                //
                // A put-if-absent handoff (re-replication after an
                // eviction, issue #266) relays as another put-if-absent
                // `U`, never as an unconditional overwrite — the pass-7
                // audit found that skipping it entirely could strand a key
                // on the joining owner. Re-replication computes its targets
                // once, at task start, so a node that joins while it runs is
                // never sent the key directly; and if the `U` reaches here
                // after this node's own handoff snapshot for that joiner was
                // taken (the wait for re-replication to clear can time out
                // and proceed anyway), the snapshot missed it too. Relaying
                // as `U` closes both gaps without the staleness risk of an
                // unconditional overwrite: if the joiner already holds a
                // value it keeps it, and if it holds nothing it finally
                // gets this key instead of missing it permanently.
                if let Some(node_context) = &config.node_context
                    && let Some(target) = unconfirmed_join_target_for(node_context, &key)
                {
                    let forward = if if_absent {
                        OwnedForwardedWrite::HandoffSet {
                            key: key.clone(),
                            value: value.clone(),
                            ttl,
                            if_absent: true,
                        }
                    } else {
                        OwnedForwardedWrite::Set {
                            key: key.clone(),
                            value: value.clone(),
                            ttl,
                        }
                    };
                    spawn_forward(&config, node_context.clone(), target, forward).await;
                }

                // And to the entrant of a decommission this node is
                // running, exactly as the `S` arm does: a `U` reaches a
                // draining node from a lingering joiner's old owner
                // (`ForwardTarget::as_handoff`), from a peer whose own
                // drain-out chains into this one, or from a survivor
                // re-replicating after an eviction, and in each case a
                // write landing after this node's drain snapshot would
                // otherwise stay here and leave with it. Same frame
                // onward (`if_absent` kept), same reasoning as the join
                // relay above.
                // Only a handoff that changed something here goes on to the
                // entrant. This node's own drain comes back to it: the
                // entrant applies a drained key and relays it to its join
                // targets, which this node still is while the entrant's
                // forwarding window for it is open — and relaying that
                // echo on again circled the drained value between the two
                // until the entrant's heartbeat revoked the forward,
                // overwriting on each pass whatever a client had written
                // to the entrant in between. An echo changes nothing here
                // (the value is this node's own), a write that landed after
                // the drain snapshot does; `StoredUnchanged` tells them
                // apart (`Cache::handoff_set`).
                if matches!(response, Response::Stored) {
                    for target in handoff_targets_for(&node_context, &key) {
                        spawn_forward(
                            &config,
                            node_context.clone(),
                            target,
                            OwnedForwardedWrite::HandoffSet {
                                key: key.clone(),
                                value: value.clone(),
                                ttl,
                                if_absent,
                            },
                        )
                        .await;
                    }
                }

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((Command::HandoffDelete { key, token }, tag)) => {
                let Some(node_context) = config.node_context.clone() else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "received u but this node isn't configured with a discovery server",
                    ));
                };

                // Issue #295: same authorization gap and fix as `U` —
                // see that arm's own comment.
                if !constant_time_eq(token.as_bytes(), node_context.token.as_bytes()) {
                    eprintln!(
                        "WARN rejected u from {address}: membership token mismatch \
                         (sender is not a legitimate handoff source for this node)"
                    );
                    write_response(
                        &mut stream,
                        &encode_response(&Response::MigrationRejected, tag),
                    )
                    .await?;
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        "u carried the wrong membership token",
                    ));
                }

                // Issue #124: a decommissioning peer forwarding a client's
                // delete for a key this node is about to own — applied
                // without the wrong-node check, same reasoning as `U`.
                let response = execute_command(
                    &request_tx,
                    Command::HandoffDelete {
                        key: key.clone(),
                        token,
                    },
                )
                .await?;
                // If this node has a join still unconfirmed for the key,
                // propagate there — and only there, see
                // `unconfirmed_join_target_for`.
                if let Some(node_context) = &config.node_context
                    && let Some(target) = unconfirmed_join_target_for(node_context, &key)
                {
                    spawn_forward(
                        &config,
                        node_context.clone(),
                        target,
                        OwnedForwardedWrite::Delete { key: key.clone() },
                    )
                    .await;
                }

                // Decommission mirror, as for `U` above and the `D` arm
                // below: a delete that lands after this node's drain
                // snapshot must reach the entrant too, or it comes back.
                // As for `U`: a delete that found nothing here (`N`) is an
                // echo or a repeat, and nothing of it is left to leave with
                // this node.
                if matches!(response, Response::Deleted) {
                    for target in handoff_targets_for(&node_context, &key) {
                        spawn_forward(
                            &config,
                            node_context.clone(),
                            target,
                            OwnedForwardedWrite::HandoffDelete { key: key.clone() },
                        )
                        .await;
                    }
                }

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((Command::Delete { key }, tag)) => {
                if let Some(node_context) = &config.node_context
                    && wrong_node_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response =
                    execute_command(&request_tx, Command::Delete { key: key.clone() }).await?;
                forward_result(&config, &key, ForwardedResult::Delete).await;

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((Command::Incr { key, delta }, tag)) => {
                if let Some(node_context) = &config.node_context
                    && not_the_primary_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response = execute_command(
                    &request_tx,
                    Command::Incr {
                        key: key.clone(),
                        delta,
                    },
                )
                .await?;
                // Issue #129: only a `Response::Incremented` — i.e. INCR
                // actually wrote a new value — needs forwarding;
                // `NotFound`/`NotNumeric` changed nothing. The remaining
                // TTL rides along so the receiving node's copy doesn't
                // come back TTL-less.
                if let Response::Incremented(ref value, ttl) = response {
                    let result = ForwardedResult::Set {
                        value: value.clone(),
                        ttl,
                    };
                    forward_result(&config, &key, result).await;
                }

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((
                Command::CasSet {
                    key,
                    condition,
                    value,
                    ttl,
                },
                tag,
            )) => {
                if let Some(node_context) = &config.node_context
                    && not_the_primary_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response = execute_command(
                    &request_tx,
                    Command::CasSet {
                        key: key.clone(),
                        condition,
                        value: value.clone(),
                        ttl,
                    },
                )
                .await?;
                // Issue #141: only `Response::Stored` — i.e. the condition
                // held and CAS actually wrote — needs forwarding; a
                // `NotFound` (mismatch) changed nothing (see
                // `Cache::cas_set`'s doc comment).
                if matches!(response, Response::Stored) {
                    forward_result(&config, &key, ForwardedResult::Set { value, ttl }).await;
                }

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((
                Command::CasDelete {
                    key,
                    expected_digest,
                },
                tag,
            )) => {
                if let Some(node_context) = &config.node_context
                    && not_the_primary_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response = execute_command(
                    &request_tx,
                    Command::CasDelete {
                        key: key.clone(),
                        expected_digest,
                    },
                )
                .await?;
                // Same rule as `CasSet`: only a delete that happened.
                if matches!(response, Response::Deleted) {
                    forward_result(&config, &key, ForwardedResult::Delete).await;
                }

                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            // `t` for a batch of keys of one namespace, with the per-key
            // wrong-node filtering of `MultiGet`'s arm and, for the keys it
            // touched, the forwarding of `MultiSet`'s: a key caught
            // mid-handoff (staged join) or mid-drain (decommission) gets
            // the value it holds with its new TTL, as the single-key `t`
            // arm sends it. A key that was not there changed nothing and is
            // not forwarded.
            Ok((
                Command::MultiTouch {
                    namespace,
                    keys,
                    ttl,
                    get,
                },
                tag,
            )) => {
                let _frame_charge = frame_charge;
                let mut entries: Vec<Option<MultiEntry>> = vec![None; keys.len()];
                let mut owned_positions = Vec::with_capacity(keys.len());
                let mut owned_keys = Vec::with_capacity(keys.len());
                let mut hasher = KeyHasher::default();
                let hashes: Vec<KeyHash> = keys
                    .iter()
                    .map(|name| hasher.hash(&Key::new(namespace.clone(), name.clone())))
                    .collect();
                let wrong = match &config.node_context {
                    Some(node_context) => wrong_nodes_refreshed(node_context, &hashes).await,
                    None => vec![false; keys.len()],
                };

                for (position, name) in keys.into_iter().enumerate() {
                    if wrong[position] {
                        entries[position] = Some(MultiEntry::WrongNode);
                    } else {
                        owned_positions.push(position);
                        owned_keys.push(name);
                    }
                }

                if !owned_keys.is_empty() {
                    // Kept for the forwarding loop below, which looks for
                    // targets after the touch, not before it (see the
                    // `MultiSet` arm on why a snapshot taken first can miss
                    // a handoff that starts meanwhile).
                    let forward_names = config.node_context.is_some().then(|| owned_keys.clone());

                    let response = execute_command(
                        &request_tx,
                        Command::MultiTouch {
                            namespace: namespace.clone(),
                            keys: owned_keys,
                            ttl,
                            get,
                        },
                    )
                    .await?;

                    let Response::Multi(results) = response else {
                        unreachable!("Command::MultiTouch always answers with Response::Multi");
                    };

                    if let (Some(node_context), Some(forward_names)) =
                        (&config.node_context, forward_names)
                    {
                        let mut join_batches: Vec<ForwardBatch> = Vec::new();
                        let mut leave_batches: Vec<ForwardBatch> = Vec::new();

                        for (name, result) in forward_names.into_iter().zip(results.iter()) {
                            let MultiEntry::Value(value) = result else {
                                continue;
                            };
                            let key = Key::new(namespace.clone(), name);
                            let key_hash = hasher.hash(&key);

                            for target in migration_targets_for_hashed(node_context, key_hash) {
                                ForwardBatch::add(
                                    &mut join_batches,
                                    target,
                                    key.name.clone(),
                                    value.clone(),
                                );
                            }
                            for target in handoff_targets_for_hashed(node_context, key_hash) {
                                ForwardBatch::add(
                                    &mut leave_batches,
                                    target,
                                    key.name.clone(),
                                    value.clone(),
                                );
                            }
                        }

                        for (batches, handoff) in [(join_batches, false), (leave_batches, true)] {
                            for batch in batches {
                                let writes = batch.items.into_iter().map(|(name, value)| {
                                    let key = Key::new(namespace.clone(), name);
                                    if handoff {
                                        OwnedForwardedWrite::HandoffSet {
                                            key,
                                            value,
                                            ttl,
                                            if_absent: false,
                                        }
                                    } else {
                                        OwnedForwardedWrite::Set { key, value, ttl }
                                    }
                                });
                                enqueue_forwards(
                                    &config,
                                    node_context.clone(),
                                    batch.target,
                                    writes,
                                )
                                .await;
                            }
                        }
                    }

                    for (position, result) in owned_positions.into_iter().zip(results) {
                        entries[position] = Some(result);
                    }
                }

                let entries: Vec<MultiEntry> = entries
                    .into_iter()
                    .map(|entry| entry.expect("every position filled by one of the two branches"))
                    .collect();
                if get {
                    write_reply(&mut stream, &config, &Response::Multi(entries), tag).await?;
                } else {
                    let roster = entries
                        .into_iter()
                        .map(|entry| match entry {
                            MultiEntry::Value(_) => MultiTouchEntry::Touched,
                            MultiEntry::Miss => MultiTouchEntry::Miss,
                            MultiEntry::WrongNode => MultiTouchEntry::WrongNode,
                        })
                        .collect();
                    write_response(
                        &mut stream,
                        &encode_response(&Response::MultiTouch(roster), tag),
                    )
                    .await?;
                }

                continue;
            }
            Ok((Command::Touch { key, ttl, get }, tag)) => {
                // Not primary-only like `i`/`k`/`x`: a touch is idempotent
                // (see `Command::Touch`), so every owner accepts it, as
                // for `S`, and the client sends it to all of them.
                if let Some(node_context) = &config.node_context
                    && wrong_node_refreshed(node_context, &key).await
                {
                    write_response(&mut stream, &encode_response(&Response::WrongNode, tag))
                        .await?;
                    continue;
                }

                let response = execute_command(
                    &request_tx,
                    Command::Touch {
                        key: key.clone(),
                        ttl,
                        get,
                    },
                )
                .await?;
                // A touch that found nothing changed nothing. One that did
                // is forwarded as the literal result, the `Set` it amounts
                // to, like `i`/`k`/`x` (see `ForwardedResult`): the
                // remaining TTL is the one just set.
                let Response::Touched(value, remaining_ttl) = response else {
                    write_response(&mut stream, &encode_response(&response, tag)).await?;
                    continue;
                };
                let result = ForwardedResult::Set {
                    value: value.clone(),
                    ttl: remaining_ttl,
                };
                forward_result(&config, &key, result).await;

                if get {
                    let reply = Response::Touched(value, remaining_ttl);
                    write_reply(&mut stream, &config, &reply, tag).await?;
                } else {
                    write_response(&mut stream, &encode_response(&Response::Stored, tag)).await?;
                }

                continue;
            }
            Ok((Command::Clear { namespace }, tag)) => {
                let scope = ClearScope::Namespace(namespace);
                handle_clear(&mut stream, &request_tx, &config, scope, tag).await?;

                continue;
            }
            Ok((Command::ClearAll, tag)) => {
                handle_clear(&mut stream, &request_tx, &config, ClearScope::All, tag).await?;

                continue;
            }
            Ok((
                Command::HandoffClear {
                    all,
                    namespace,
                    token,
                },
                tag,
            )) => {
                let Some(node_context) = config.node_context.clone() else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "received f but this node isn't configured with a discovery server",
                    ));
                };
                if !constant_time_eq(token.as_bytes(), node_context.token.as_bytes()) {
                    eprintln!(
                        "WARN rejected f from {address}: membership token mismatch \
                         (sender is not a legitimate handoff source for this node)"
                    );
                    write_response(
                        &mut stream,
                        &encode_response(&Response::MigrationRejected, tag),
                    )
                    .await?;
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        "f carried the wrong membership token",
                    ));
                }
                let scope = if all {
                    ClearScope::All
                } else {
                    ClearScope::Namespace(namespace.clone())
                };
                let response = execute_command(
                    &request_tx,
                    Command::HandoffClear {
                        all,
                        namespace,
                        token,
                    },
                )
                .await?;
                // A forwarded clear goes on through this node's join
                // targets exactly as a client's does — the slot's joiner
                // (queued behind the transfer, or on the forwarding
                // connection) and the joiners still inside their grace —
                // whether or not discovery has confirmed them: the client
                // writes this node relayed to a joiner sit on that
                // joiner's queue, and the clear must follow them there
                // (the ordering #688 arranged), and a client whose list
                // predates the joiner reaches it only through this chain.
                // Join targets form a DAG, so this never comes back.
                //
                // Through this node's own windows — a decommission's
                // entrants, an eviction's promoted owners — a forwarded
                // clear goes on only when it removed something here, the
                // clear's twin of the `U` arm's `StoredUnchanged` guard: a
                // leaver's entrant forwards to the leaver (its confirmed
                // joiner) and the leaver mirrors to the entrant, so an
                // ungated mirror sent one clear around that pair until a
                // window closed, wiping every write in between. The gate
                // ends it on the pass that removes nothing. (It also
                // skips a mirror for a key this node had mirrored and then
                // lost to a delete or expiry — that one write can come
                // back on the entrant, bounded by the next write or TTL.)
                for target in lingering_clear_targets(&node_context) {
                    spawn_forward(
                        &config,
                        node_context.clone(),
                        target,
                        OwnedForwardedWrite::Clear(scope.clone()),
                    )
                    .await;
                }
                if let ClearRoute::Forward(target) = route_clear(&node_context, &scope) {
                    spawn_forward(
                        &config,
                        node_context.clone(),
                        target,
                        OwnedForwardedWrite::Clear(scope.clone()),
                    )
                    .await;
                }
                if matches!(response, Response::Cleared(removed) if removed > 0) {
                    for target in leave_clear_targets(&node_context)
                        .into_iter()
                        .chain(rereplication_clear_targets(&node_context))
                    {
                        spawn_forward(
                            &config,
                            node_context.clone(),
                            target,
                            OwnedForwardedWrite::Clear(scope.clone()),
                        )
                        .await;
                    }
                }
                write_response(&mut stream, &encode_response(&response, tag)).await?;

                continue;
            }
            Ok((command, _)) => {
                // `ListEntries`/`MarkMigrated`/`UnmarkMigratedMany`/`Sweep`/
                // `PeekEntry`: internal-only, constructed directly by
                // server-side tasks, never by `parse()` — this arm exists
                // only so the match stays exhaustive.
                let response = execute_command(&request_tx, command).await?;
                write_response(&mut stream, &response.encode()).await?;

                continue;
            }
            Err(ParseError::Incomplete) => {
                // An `A` frame still short of complete: its header line
                // and secret together must fit — see
                // `UNAUTHENTICATED_MAX_REQUEST_SIZE`.
                if !authenticated && received.len() > UNAUTHENTICATED_MAX_REQUEST_SIZE {
                    return Err(reject_request(
                        &mut stream,
                        "unauthenticated request is too large".to_string(),
                    )
                    .await);
                }
                // `parse` leaves `received` untouched on `Incomplete` and
                // every complete frame before this one has been taken off,
                // so what is buffered here is the front frame alone: the
                // one place the limit can be applied to a frame still
                // arriving (the complete-frame case is handled above).
                if request_is_too_large(received.len()) {
                    return Err(reject_oversized_request(
                        &mut stream,
                        "request is too large".to_string(),
                    )
                    .await);
                }
            }
            Err(error) => {
                return Err(reject_request(&mut stream, format!("{error:?}")).await);
            }
        }

        // Issue #6: checked here — only once `parse` has drained every
        // complete command already buffered (an `Incomplete` result means
        // there isn't one) — rather than at the top of the loop, so a
        // shutdown signal that arrives mid-pipeline doesn't silently drop
        // a second/third request that arrived in the same read as the
        // first and needs no further I/O to answer.
        if *shutdown_rx.borrow() {
            return Ok(());
        }

        // Issue #7: release an oversized buffer once its unparsed
        // remainder drops back under the threshold, instead of only when
        // it's exactly empty — a connection whose next command's lead
        // byte always lands in the same read as the previous command's
        // tail would otherwise never hit an exact-empty check and carry
        // the oversized allocation for the rest of the connection's life.
        if received.capacity() > REQUEST_BUFFER_SHRINK_THRESHOLD
            && received.len() <= REQUEST_BUFFER_SHRINK_THRESHOLD
        {
            let mut shrunk = BytesMut::with_capacity(received.len());
            shrunk.extend_from_slice(&received);
            received = shrunk;
        }
        // The released capacity is released from the budget too. A buffer
        // whose capacity fell to the free threshold on its own is not
        // shrunk but holds nothing chargeable either: `split_to` leaves a
        // frame's bytes with the frame, so a 256 KiB buffer that gave up
        // a 200 KB frame has 56 KiB left. Its charge goes as well, or an
        // idle connection would pin up to a frame's worth of the shared
        // budget until it closed.
        if received.capacity() <= REQUEST_BUFFER_SHRINK_THRESHOLD {
            receive_charge = None;
            receive_charged = 0;
        }

        // Bounded by time remaining until `deadline`, not by a fresh
        // `config.idle_timeout` on every read — see `deadline`'s own
        // comment above. If `deadline` has already passed (a trickled
        // read landed after it), `remaining` is zero and this fires
        // immediately instead of granting another read.
        let remaining = deadline.saturating_duration_since(Instant::now());

        // Grow the buffer under control: a doubling, charged against the
        // in-flight budget *before* it is allocated, so that what a
        // thousand connections mid-frame hold is bounded by the budget
        // rather than by the connection count. The first 64 KiB of every
        // connection are free; a connection that cannot get the growth
        // by its frame deadline is closed, like one that trickled.
        if received.capacity() - received.len() < READ_CHUNK_SIZE {
            let grown = (received.capacity() * 2).max(received.len() + READ_CHUNK_SIZE);
            let want = config
                .in_flight_bytes
                .clamp(grown.saturating_sub(REQUEST_BUFFER_SHRINK_THRESHOLD));
            if want > receive_charged {
                let more = timeout(
                    remaining,
                    config.in_flight_bytes.charge_exact(want - receive_charged),
                )
                .await
                .map_err(|_| {
                    io::Error::new(
                        io::ErrorKind::TimedOut,
                        "in-flight byte budget exhausted while receiving a request",
                    )
                })?;
                receive_charged = want;
                receive_charge = Some(match receive_charge.take() {
                    Some(mut held) => {
                        held.merge(more);
                        held
                    }
                    None => more,
                });
            }
            received.reserve(grown - received.len());
        }
        let remaining = deadline.saturating_duration_since(Instant::now());

        let bytes_read = tokio::select! {
            _ = shutdown_rx.changed() => return Ok(()),

            result = timeout(remaining, stream.read_buf(&mut received)) => {
                result.map_err(|_| {
                    io::Error::new(
                    io::ErrorKind::TimedOut,
                    "connection idle timeout",
                )
                })??
            }
        };

        if bytes_read == 0 {
            if received.is_empty() {
                return Ok(());
            }

            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request was complete",
            ));
        }
    }
}

async fn run_cache(
    mut request_rx: mpsc::Receiver<CacheRequest>,
    max_memory_bytes: usize,
    namespace_budgets: Vec<(Bytes, usize)>,
) {
    let mut cache = Cache::with_budgets(max_memory_bytes, namespace_budgets);

    while let Some(request) = request_rx.recv().await {
        let response = request.command.execute(&mut cache);

        let _ = request.response_tx.send(response);
    }
}

/// Staged node join: sent once per connection, before any heartbeat. `name` is
/// this node's random per-process identity (node identity decoupled from address); `port` is where it
/// serves — the discovery server composes the reachable address from this
/// connection's own source IP plus that port (addresses derived from the registration connection). Discovery holds
/// this connection open and pushes `R\n` on it once this node is promoted
/// to `Joined`.
/// `token` is this node's per-process membership token (issue #34),
/// generated alongside `name` and presented on every command naming this
/// node — the discovery server binds it to `name` at registration and
/// rejects any later `P`/`H`/`C` for the name that doesn't present it.
///
/// `letter` is `J` for a staged join, or `P` (discovery HA) to declare an
/// already-promoted member — same shape, no handoff orchestration on the
/// other end.
fn registration_message(letter: char, name: &str, port: u16, token: &str) -> Vec<u8> {
    let mut message = format!("{letter} {} {port} {}\n", name.len(), token.len()).into_bytes();
    message.extend_from_slice(name.as_bytes());
    message.extend_from_slice(token.as_bytes());
    message
}

/// `H <name-len> <replication> <token-len> [<joiner-len>]\n<name><token>[<joiner>]`.
///
/// Only valid once this node has been promoted to `Joined` (staged node
/// join); the address was already established by `join_message` on this
/// connection, so a heartbeat only needs to carry `name` to refresh
/// liveness. `replication` is this node's current belief about the
/// cluster's replication factor (issue #30), encoded as `0` when it doesn't
/// have one yet — never a real replication factor (discovery validates
/// every `--replication-factor` is at least 1), so it's an unambiguous
/// "unknown" sentinel on the wire. The trailing field (issue #571) names
/// the joiner of a handoff this node completed but has not seen in a
/// roster yet, and asks discovery to follow the ack with a verdict line —
/// see `read_pending_joiner_verdict`.
fn heartbeat_message(
    name: &str,
    replication: Option<usize>,
    token: &str,
    pending_joiner: Option<&str>,
) -> Vec<u8> {
    let mut header = format!(
        "H {} {} {}",
        name.len(),
        replication.unwrap_or(0),
        token.len()
    );
    if let Some(joiner) = pending_joiner {
        header.push_str(&format!(" {}", joiner.len()));
    }
    header.push('\n');
    let mut message = header.into_bytes();
    message.extend_from_slice(name.as_bytes());
    message.extend_from_slice(token.as_bytes());
    if let Some(joiner) = pending_joiner {
        message.extend_from_slice(joiner.as_bytes());
    }
    message
}

/// Issue #571: the joiner of this node's handoff slot if the handoff is
/// done but discovery has not listed the joiner in any roster this node
/// saw — the one state a sender cannot resolve on its own (see
/// `read_pending_joiner_verdict`). `None` for a running transfer (the
/// joiner is Waiting; an abandon arrives as `X`), for a confirmed slot and
/// for lingering entries (confirmed by construction).
///
/// Returned with the slot's identity (its `forward_revoked` flag, unique
/// per `M`), so the answer is applied to this slot and no other: an `X`
/// can abandon it and a same-name retry's `M` install a new one while
/// the heartbeat is in flight, and the old `G` must not touch that one.
fn unconfirmed_completed_joiner(node_context: &NodeContext) -> Option<(String, Arc<AtomicBool>)> {
    node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .filter(|active| active.completed_at.is_some() && !active.confirmed)
        .map(|active| {
            (
                active.joining_name.clone(),
                Arc::clone(&active.forward_revoked),
            )
        })
}

/// `abandon_migration` for a `G` verdict (issue #571): takes the slot only
/// if it is still the very instance the heartbeat asked about
/// (`identity`, see `unconfirmed_completed_joiner`) and still a completed
/// handoff — never a transfer that a same-name retry started meanwhile,
/// and never the remnant an `X` left behind (issue #595): a remnant
/// carries the `forward_revoked` of the slot it was cut from (so the
/// forwards already queued against that slot stay revoked), which is the
/// very identity the heartbeat went out with, but it is not a handoff —
/// taking it would schedule a re-replication over a ring nobody left,
/// superseding whichever real one is in flight.
/// Returns its dead copies to restore and the post-join ring it was
/// built on, for the re-replication the caller schedules.
fn abandon_departed_slot(
    node_context: &NodeContext,
    identity: &Arc<AtomicBool>,
) -> Option<(Vec<Key>, Arc<HashRing>)> {
    match take_abandoned_slot(node_context, |active| {
        Arc::ptr_eq(&active.forward_revoked, identity)
            && active.completed_at.is_some()
            && !active.remnant
    }) {
        TakenSlot::Completed(taken) => {
            revert_known_ring_after_abandon(node_context, &taken);
            Some((taken.marked_keys, taken.after_ring))
        }
        // The predicate requires a completed handoff, so `Aborting` cannot
        // occur; treated like no match either way.
        TakenSlot::Aborting | TakenSlot::NoMatch => None,
    }
}

enum TakenSlot {
    NoMatch,
    /// Still transferring: `run_migration` will notice the abort and roll
    /// back its own marks; it hasn't flipped `known_ring` yet, so there is
    /// nothing to revert — but the slot is also not free yet, so an `X`'s
    /// caller must wait rather than ack immediately.
    Aborting,
    /// The completed handoff, taken out (`take_slot_keeping_lingering`).
    Completed(Box<ActiveMigration>),
}

/// The one abandon core behind `abandon_migration` (an `X`) and
/// `abandon_departed_slot` (a `G`, issue #571): the slot that satisfies
/// `matches` is told to stop and its forwards are revoked; a completed
/// handoff is taken out, a running transfer is left to unwind.
fn take_abandoned_slot(
    node_context: &NodeContext,
    matches: impl Fn(&ActiveMigration) -> bool,
) -> TakenSlot {
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    match slot.as_ref() {
        Some(active) if matches(active) => {
            active.abort_requested.store(true, Ordering::SeqCst);
            active.forward_revoked.store(true, Ordering::SeqCst);
            if active.completed_at.is_none() {
                return TakenSlot::Aborting;
            }
        }
        _ => return TakenSlot::NoMatch,
    }
    TakenSlot::Completed(Box::new(
        take_slot_keeping_lingering(&mut slot)
            .expect("the matched arm above saw a `Some` completed slot"),
    ))
}

/// Takes the slot's own handoff out — for an abandon, an eviction or an
/// aborted transfer — without taking the earlier joiners' forwarding
/// windows with it (issue #564): a lingering joiner is a confirmed member
/// still owed its grace, and a client whose node list has not caught up
/// keeps writing to the old owners for it. The still-open `lingering`
/// entries stay behind in a closed remnant of the slot — own window shut
/// (`forwarding_grace` zero), `confirmed`, no marks, its ring the slot's
/// minus the departed joiner — which `expired()` clears once their
/// windows end and the next `M` carries them over as it does for any
/// slot. Closed entries are revoked here. Returns the taken slot with
/// its `lingering` drained.
fn take_slot_keeping_lingering(slot: &mut Option<ActiveMigration>) -> Option<ActiveMigration> {
    let mut taken = slot.take()?;
    let mut lingering = Vec::new();
    for older in std::mem::take(&mut taken.lingering) {
        if older.forwarding_open() {
            lingering.push(older);
        } else {
            older.forward_revoked.store(true, Ordering::SeqCst);
        }
    }
    if !lingering.is_empty() {
        let nodes: Vec<String> = taken
            .after_ring
            .nodes()
            .iter()
            .filter(|name| **name != taken.joining_name)
            .cloned()
            .collect();
        *slot = Some(ActiveMigration {
            joining_name: taken.joining_name.clone(),
            joining_addr: taken.joining_addr.clone(),
            joining_token: taken.joining_token.clone(),
            after_ring: Arc::new(HashRing::new(nodes)),
            replication: taken.replication,
            generation: taken.generation,
            completed_at: Some(Instant::now()),
            forwarding_grace: Duration::ZERO,
            acked_entries: taken.acked_entries,
            abort_requested: Arc::clone(&taken.abort_requested),
            marked_keys: Vec::new(),
            confirmed: true,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::clone(&taken.forward_connection),
            forward_revoked: Arc::clone(&taken.forward_revoked),
            lingering,
            remnant: true,
        });
    }
    Some(taken)
}

/// Issue #93: a handoff's flip of `known_ring` to its post-join ring is
/// undone when the handoff is abandoned — but only if `known_ring` still
/// holds *this* handoff's ring (a later membership update wins).
fn revert_known_ring_after_abandon(node_context: &NodeContext, taken: &ActiveMigration) {
    let mut guard = node_context
        .known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if guard
        .as_ref()
        .is_some_and(|current| Arc::ptr_eq(&current.ring, &taken.after_ring))
    {
        *guard = taken.pre_completion_ring.clone();
        node_context.ring_history.touch();
    }
}

enum PendingJoinerVerdict {
    Known,
    Gone,
}

/// Issue #571: the line discovery appends to its ack when the heartbeat
/// named a pending joiner. `K` — still registered, or at least not known
/// to have gone: keep waiting for the roster. `G` — on record as having
/// left, been evicted or abandoned, and not registered since. A joiner
/// promoted and gone again between two of this node's heartbeats never
/// appears in a roster this node sees, so `adopt_membership` reads its
/// absence as "not promoted yet" and the slot would otherwise keep
/// forwarding to it for the whole grace and hold its marks until the
/// next `M`.
async fn read_pending_joiner_verdict<S: AsyncBufReadExt + Unpin>(
    stream: &mut S,
) -> io::Result<PendingJoinerVerdict> {
    let mut line = Vec::new();
    infra::read_line_bounded(stream, 2, outbound_line_deadline(), &mut line).await?;
    match line.as_slice() {
        b"K\n" => Ok(PendingJoinerVerdict::Known),
        b"G\n" => Ok(PendingJoinerVerdict::Gone),
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "malformed pending-joiner verdict",
        )),
    }
}

/// Issue #571: discovery answered `G` for `joining_name` — the same
/// abandon this node runs for an `X` (`abandon_departed_slot`): the
/// slot's forwards are revoked, its dead copies restored (this node owns
/// those keys again; a leaver's drain handoff already re-sent them, an
/// abandon never moved them) and `known_ring` reverted if it still holds
/// the abandoned post-join ring. Returns that post-join ring so the caller
/// can schedule the re-replication the roster path will not: with
/// `known_ring` reverted, the next roster shows no dropped member, yet a
/// key written while the joiner was an owner now has one copy fewer if it
/// was evicted rather than drained (a leave re-sent every key, and the
/// put-if-absent pass is then a no-op).
async fn abandon_departed_joiner(
    node_context: &NodeContext,
    joining_name: &str,
    identity: &Arc<AtomicBool>,
    discovery_addr: &str,
) -> Option<Arc<HashRing>> {
    let (restore, after_ring) = abandon_departed_slot(node_context, identity)?;
    eprintln!(
        "WARN joiner {joining_name} left the cluster before this node saw it in a roster from \
         discovery at {discovery_addr}; closing its forwarding window and restoring {} dead \
         copies",
        restore.len()
    );
    // One round trip for the lot: this runs inline in the heartbeat loop,
    // so one per key delayed the next heartbeat by the whole restore.
    unmark_migrated_many(&node_context.request_tx, restore).await;
    Some(after_ring)
}

fn auth_message(secret: &[u8]) -> Vec<u8> {
    let mut message = format!("A {}\n", secret.len()).into_bytes();
    message.extend_from_slice(secret);
    message
}

/// Connects out to `addr` as a client — either the discovery server (for
/// heartbeats, staged node join's `J`/`C`) or another node (for staged node join's
/// `SET`-based handoff) — upgrading to TLS first if `tls_connector` is
/// set. There is no plaintext fallback: if TLS is configured and the
/// handshake fails, the connection attempt fails too.
async fn connect_client_stream(
    addr: &str,
    tls_connector: Option<&TlsConnector>,
) -> io::Result<ClientStream> {
    infra::connect_client_stream(
        addr,
        tls_connector,
        OUTBOUND_IO_TIMEOUT,
        TLS_HANDSHAKE_TIMEOUT,
    )
    .await
}

/// This registration task's relationship to one discovery replica
/// (discovery HA). The primary is the only one ever sent `J` — the staged node join
/// join, with its data handoff — and flips the shared `promoted` flag
/// once `R` arrives for it. Standbys (and the primary itself, on any
/// re-registration after that first promotion) send `P` announces, which
/// upsert this node as a member with no handoff.
enum DiscoveryRole {
    Primary(Arc<watch::Sender<bool>>),
    Standby(watch::Receiver<bool>),
}

/// Registers this node with every configured discovery replica
/// (discovery HA): one `register_with_discovery` task per address, sharing a
/// `promoted` watch so standbys hold off announcing until the primary's
/// Staged node join join has actually completed. `name` is this node's own
/// Node identity decoupled from address identity, generated once by `run` and shared with
/// `ConnectionConfig`'s `NodeContext` — not generated here, so a
/// migration task triggered by an incoming `M` on some other connection
/// reports `C` under the same name these tasks register as.
async fn send_heartbeats(
    config: HeartbeatConfig,
    node_context: NodeContext,
    mut rereplication_rx: mpsc::Receiver<RereplicationTask>,
    shutdown_rx: watch::Receiver<bool>,
) {
    let (promoted_tx, promoted_rx) = watch::channel(false);
    let promoted_tx = Arc::new(promoted_tx);

    let mut tasks = JoinSet::new();
    for (index, discovery_addr) in config.discovery_addrs.iter().enumerate() {
        let role = if index == 0 {
            DiscoveryRole::Primary(Arc::clone(&promoted_tx))
        } else {
            DiscoveryRole::Standby(promoted_rx.clone())
        };

        tasks.spawn(register_with_discovery(
            discovery_addr.clone(),
            config.port,
            config.interval,
            config.auth_secret.clone(),
            config.tls_connector.clone(),
            node_context.clone(),
            role,
            shutdown_rx.clone(),
        ));
    }
    // This function's own copy must go, or its later drain of
    // `rereplication_rx` would deadlock waiting for a channel it is
    // itself still holding a sender to (`NodeContext::rereplication_tx`)
    // — every real producer (each `register_with_discovery` task above,
    // and any spawned re-replication task) holds its own clone instead,
    // and `node_context` isn't needed again in this function.
    drop(node_context);

    // Issue #266: drains any re-replication task a ring change
    // triggered — either here, via `register_with_discovery`'s own
    // `adopt_membership` detecting an eviction, or from `run_migration`
    // (a completely different task, spawned off `run`'s own
    // `migration_tx`) via its shared `NodeContext::rereplication_tx` —
    // into the same `JoinSet` the registration connections themselves
    // run in, so shutdown (via `heartbeat_task.await` in `run`) waits
    // for it exactly as it already waits for those. `biased` so a task
    // that arrived just as the last registration connection exited is
    // still picked up before the `else` branch (both disabled) ends the
    // loop; the channel closes once every clone of
    // `NodeContext::rereplication_tx` this process holds has dropped —
    // see `run`'s own `drop(rereplication_tx)`.
    loop {
        tokio::select! {
            biased;

            Some(task) = rereplication_rx.recv() => {
                tasks.spawn(task);
            }

            result = tasks.join_next(), if !tasks.is_empty() => {
                if let Some(Err(error)) = result {
                    eprintln!("WARN heartbeat task failed: {error}");
                }
            }

            else => break,
        }
    }
}

/// Holds one long-lived connection to a single discovery replica:
/// registers (`J` for the primary's first time, `P` otherwise — see
/// `DiscoveryRole`), then sends a heartbeat on it every `interval`,
/// reconnecting (and re-registering under the same name) on any I/O
/// error after waiting out the interval.
#[allow(clippy::too_many_arguments)]
async fn register_with_discovery(
    discovery_addr: String,
    port: u16,
    interval: Duration,
    auth_secret: Option<Bytes>,
    tls_connector: Option<TlsConnector>,
    node_context: NodeContext,
    mut role: DiscoveryRole,
    mut shutdown_rx: watch::Receiver<bool>,
) {
    let join = registration_message('J', &node_context.name, port, &node_context.token);
    let announce = registration_message('P', &node_context.name, port, &node_context.token);

    // A standby must not announce a node the primary hasn't promoted yet:
    // that would make it visible in the standby's `L` before its staged node join
    // handoff has run, which is exactly the state `J`'s staging exists to
    // prevent.
    if let DiscoveryRole::Standby(promoted_rx) = &mut role {
        while !*promoted_rx.borrow() {
            tokio::select! {
                _ = shutdown_rx.changed() => return,
                result = promoted_rx.changed() => {
                    if result.is_err() {
                        return;
                    }
                }
            }
        }
    }

    loop {
        if *shutdown_rx.borrow() {
            return;
        }

        // Bounded by `OUTBOUND_IO_TIMEOUT` + `TLS_HANDSHAKE_TIMEOUT` on its
        // own, but that is longer than `SHUTDOWN_TIMEOUT` and `run` awaits
        // this task without one — so also give up the moment shutdown
        // lands, rather than making a node whose discovery server is
        // unreachable take ~30s to exit.
        let connected = tokio::select! {
            _ = shutdown_rx.changed() => return,
            result = connect_client_stream(&discovery_addr, tls_connector.as_ref()) => result,
        };

        match connected {
            Ok(stream) => {
                // Buffered for the heartbeat ack's line-oriented roster
                // (issue #61, `read_heartbeat_ack`); writes pass straight
                // through.
                let mut stream = tokio::io::BufReader::new(stream);
                let authenticated = match &auth_secret {
                    Some(secret) => {
                        let auth = auth_message(secret);
                        // Bounded so a discovery server that accepts TCP but
                        // never drains can't wedge this task forever (and,
                        // via `heartbeat_task.await`, hang shutdown).
                        let exchange = timeout(OUTBOUND_IO_TIMEOUT, async {
                            stream.write_all(&auth).await?;
                            let mut ack = [0u8; 3];
                            stream.read_exact(&mut ack).await?;
                            io::Result::Ok(ack)
                        })
                        .await;
                        // Only an explicit `Ed` is a rejected secret. A
                        // dropped connection or garbage instead (issue #68)
                        // is most often a node speaking plaintext to a
                        // TLS discovery server — `--tls-ca` missing — and
                        // saying "rejected the auth secret" for that sent
                        // operators to the wrong knob.
                        match exchange {
                            Ok(Ok(ack)) if &ack == b"Od\n" => true,
                            Ok(Ok(ack)) if &ack == b"Ed\n" => {
                                eprintln!(
                                    "WARN discovery server at {discovery_addr} rejected the auth \
                                     secret"
                                );
                                false
                            }
                            Ok(Ok(ack)) => {
                                eprintln!(
                                    "WARN discovery server at {discovery_addr} answered the auth \
                                     handshake with {:?} instead of Od/Ed — if it requires TLS, \
                                     this node needs --tls-ca",
                                    String::from_utf8_lossy(&ack)
                                );
                                false
                            }
                            Ok(Err(error)) => {
                                eprintln!(
                                    "WARN auth handshake with discovery server at {discovery_addr} \
                                     failed: {error} — if it requires TLS, this node needs --tls-ca"
                                );
                                false
                            }
                            Err(_) => {
                                eprintln!(
                                    "WARN auth handshake with discovery server at {discovery_addr} \
                                     timed out"
                                );
                                false
                            }
                        }
                    }
                    None => true,
                };

                let sending_join = matches!(
                    &role,
                    DiscoveryRole::Primary(promoted_tx) if !*promoted_tx.borrow()
                );
                let registration = if sending_join { &join } else { &announce };

                let registration_sent = authenticated
                    && infra::write_all_within(&mut stream, registration, OUTBOUND_IO_TIMEOUT)
                        .await
                        .is_ok();
                if registration_sent {
                    // For `J`, staged node join: this connection is held open by
                    // discovery (no idle timeout applies) until this node
                    // is promoted, which may take an unbounded amount of
                    // time if another join is already in progress. For
                    // `P`, the same `R\n` comes back immediately.
                    let mut promoted = [0u8; 2];
                    let read_promoted = tokio::select! {
                        _ = shutdown_rx.changed() => return,
                        result = stream.read_exact(&mut promoted) => result,
                    };

                    if read_promoted.is_ok() && &promoted == b"R\n" {
                        if sending_join {
                            println!("INFO joined the cluster via discovery at {discovery_addr}");
                        } else {
                            println!("INFO re-registered with discovery at {discovery_addr}");
                        }

                        if let DiscoveryRole::Primary(promoted_tx) = &role {
                            promoted_tx.send_replace(true);
                            // From here on client key requests are served
                            // (`wrong_node`); the membership view that
                            // check needs follows with the first ack
                            // below.
                            node_context.promoted.store(true, Ordering::SeqCst);
                        }

                        loop {
                            // Rebuilt every tick, not precomputed once:
                            // this node's belief starts unknown and is set
                            // only once it has sent its own first client-side replication
                            // handoff `M` (issue #30) — a stale precomputed
                            // buffer would keep reporting "unknown" forever.
                            let replication = node_context
                                .known_ring
                                .lock()
                                .unwrap_or_else(|poisoned| poisoned.into_inner())
                                .as_ref()
                                .map(|membership| membership.replication);
                            // Issue #571: asked of the primary only — a
                            // standby never sees a Waiting joiner, so its
                            // answer would mean nothing.
                            let pending_joiner = match &role {
                                DiscoveryRole::Primary(_) => {
                                    unconfirmed_completed_joiner(&node_context)
                                }
                                DiscoveryRole::Standby(_) => None,
                            };
                            let heartbeat = heartbeat_message(
                                &node_context.name,
                                replication,
                                &node_context.token,
                                pending_joiner.as_ref().map(|(name, _)| name.as_str()),
                            );

                            if infra::write_all_within(&mut stream, &heartbeat, OUTBOUND_IO_TIMEOUT)
                                .await
                                .is_err()
                            {
                                break;
                            }

                            // Timed out like the write above: without this,
                            // a discovery server that accepts the
                            // heartbeat but never acks (crashed-but-
                            // socket-open, blackholed route) would hang
                            // this loop forever instead of falling through
                            // to the redial below.
                            let read_ack = tokio::select! {
                                _ = shutdown_rx.changed() => return,
                                result = timeout(OUTBOUND_IO_TIMEOUT, read_heartbeat_ack(&mut stream)) => result,
                            };

                            let roster = match read_ack {
                                Ok(Ok(roster)) => roster,
                                _ => break,
                            };

                            // Issue #571: one more line whenever the
                            // heartbeat asked, grace or not. A `G` abandons
                            // the slot now; the re-replication it calls for
                            // is scheduled below, once this ack's roster
                            // has been adopted.
                            let mut departed_ring: Option<Arc<HashRing>> = None;
                            if let Some((joiner, identity)) = pending_joiner.as_ref() {
                                let verdict = tokio::select! {
                                    _ = shutdown_rx.changed() => return,
                                    result = timeout(OUTBOUND_IO_TIMEOUT, read_pending_joiner_verdict(&mut stream)) => result,
                                };
                                match verdict {
                                    Ok(Ok(PendingJoinerVerdict::Known)) => {}
                                    Ok(Ok(PendingJoinerVerdict::Gone)) => {
                                        departed_ring = abandon_departed_joiner(
                                            &node_context,
                                            joiner,
                                            identity,
                                            &discovery_addr,
                                        )
                                        .await;
                                    }
                                    _ => break,
                                }
                            }

                            // Issue #61: only the primary's view is
                            // adopted — replicas never reconcile with each
                            // other (discovery HA), and flip-flopping
                            // between two replicas' views would be worse
                            // than either.
                            if let Some((members, replication)) = roster
                                && matches!(role, DiscoveryRole::Primary(_))
                            {
                                let published = members.clone();
                                note_published_roster(
                                    &node_context.latest_published,
                                    &published,
                                    replication,
                                );
                                node_context.roster_refresh.note_heartbeat();
                                let change = adopt_membership(
                                    &node_context.known_ring,
                                    &node_context.active_migration,
                                    &discovery_addr,
                                    members,
                                    replication,
                                );
                                // Issue #582: this is the only place a
                                // discovery-published membership enters
                                // the reclaim pass's history. No change
                                // means either the roster is what this
                                // node already holds — usually the ring a
                                // handoff it ran installed at completion,
                                // which discovery has now published — or
                                // it was withheld while this node's own
                                // join is pending; only the former counts.
                                if let Some(membership) = published_membership(
                                    change.as_ref(),
                                    &node_context.known_ring,
                                    &published,
                                    replication,
                                ) {
                                    node_context.ring_history.record_if_new(membership);
                                }

                                // Issue #266: a ring change that dropped a
                                // member — an eviction, or a leave this
                                // node did not itself hand off for —
                                // leaves the cluster under-replicated
                                // until someone re-replicates the keys
                                // the change promoted a new owner into.
                                // Handed to `send_heartbeats`'s own
                                // `JoinSet` (this task has none of its
                                // own) rather than run inline: it can
                                // scan every key this node holds, which
                                // must not stall this connection's own
                                // heartbeat ticks.
                                if let Some(change) = change
                                    && change.dropped_a_member()
                                {
                                    let before_ring = change
                                        .before
                                        .expect("dropped_a_member() implies before is Some")
                                        .ring
                                        .clone();
                                    let task: RereplicationTask =
                                        Box::pin(spawn_or_supersede_rereplication(
                                            node_context.clone(),
                                            discovery_addr.clone(),
                                            before_ring,
                                            Arc::clone(&change.after),
                                            shutdown_rx.clone(),
                                        ));
                                    if node_context.rereplication_tx.send(task).await.is_err() {
                                        eprintln!(
                                            "WARN re-replication: could not queue the task for a \
                                             ring change (shutting down); a later ring change \
                                             will retrigger it if the cluster is still \
                                             under-replicated"
                                        );
                                    }
                                }
                            }

                            // Issue #571: the departed joiner's keys are
                            // re-ranked from its post-join ring to the
                            // membership this node holds now (this ack's
                            // roster, or the pre-join ring the abandon
                            // reverted to) — the drop the roster path
                            // above could not see.
                            if let Some(before_ring) = departed_ring {
                                let after = node_context
                                    .known_ring
                                    .lock()
                                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                                    .clone();
                                match after {
                                    Some(after) => {
                                        let task: RereplicationTask =
                                            Box::pin(spawn_or_supersede_rereplication(
                                                node_context.clone(),
                                                discovery_addr.clone(),
                                                before_ring,
                                                after,
                                                shutdown_rx.clone(),
                                            ));
                                        if node_context.rereplication_tx.send(task).await.is_err() {
                                            eprintln!(
                                                "WARN re-replication: could not queue the task \
                                                 for a departed joiner (shutting down)"
                                            );
                                        }
                                    }
                                    None => eprintln!(
                                        "WARN re-replication for a departed joiner skipped: no \
                                         membership view yet; the next ring change picks up \
                                         any key it left under-replicated"
                                    ),
                                }
                            }

                            if wait_or_shutdown(interval, &mut shutdown_rx).await {
                                return;
                            }
                        }
                    }
                }
            }
            Err(error) => {
                eprintln!(
                    "WARN failed to connect to discovery server at {discovery_addr}: {error}"
                );
            }
        }

        if wait_or_shutdown(interval, &mut shutdown_rx).await {
            return;
        }
    }
}

/// Upper bounds on what a heartbeat ack's roster (issue #61) may claim,
/// so a misbehaving discovery server can't make this node allocate
/// without bound: mirror `nanocached-discovery`'s own `MAX_REGISTRY_SIZE`
/// and `MAX_REQUEST_SIZE` (the two binaries share no modules by design).
const MAX_ROSTER_ENTRIES: usize = 1 << 16;
const MAX_ROSTER_FIELD_LEN: usize = 4096;
/// Cap on a single heartbeat-ack *line* — the header `A <count> <repl>\n`
/// and each entry's `<name-len> <addr-len>\n` length prefix (issue #92).
/// Both are only ever a keyword and/or two decimal integers, so 64 bytes
/// is generous (a full `A 65536 65536\n` is 14). The read itself is bounded
/// by this, so a hostile/misconfigured discovery that streams a line
/// without ever sending `\n` errors out instead of growing this node's
/// heartbeat task memory until it OOMs. The name/addr *bytes* aren't read
/// this way — they come via a `read_exact` already sized by the
/// `MAX_ROSTER_FIELD_LEN`-checked lengths below.
const MAX_ROSTER_LINE_LEN: usize = 64;

/// The deadline for reading one outbound exchange's lines: the same bound
/// `OUTBOUND_IO_TIMEOUT` puts around the whole exchange, so a peer that
/// trickles a line in cannot outlast it (`infra::read_line_bounded`).
fn outbound_line_deadline() -> tokio::time::Instant {
    tokio::time::Instant::now() + OUTBOUND_IO_TIMEOUT
}

/// Reads one heartbeat ack. A bare `A\n` means "no membership update"
/// (the discovery server is in its startup grace, or its replication
/// factor is disputed — see the `H` entry in `nanocached-discovery`'s
/// module docs); `A <count> <replication>\n` is followed by `count`
/// `<name-len> <addr-len>\n<name><addr>\n` entries — the current `Joined`
/// roster — returned as `Some((names, replication))`. Anything else is an
/// error, on which the caller redials. Addresses are parsed but dropped:
/// this node only needs names to build a ring.
async fn read_heartbeat_ack<S: AsyncBufReadExt + Unpin>(
    stream: &mut S,
) -> io::Result<Option<(Vec<String>, usize)>> {
    read_roster(stream, b'A', b"A\n", "malformed heartbeat ack").await
}

/// Reads the `L` response: what clients route by, in the heartbeat ack's
/// layout under tag `N` (`build_roster_response` in
/// `nanocached-discovery`). `B\n` — discovery in its startup grace, or
/// its replication factor disputed — is `None`, as a bare `A\n` is for
/// the ack.
async fn read_published_roster<S: AsyncBufReadExt + Unpin>(
    stream: &mut S,
) -> io::Result<Option<(Vec<String>, usize)>> {
    read_roster(stream, b'N', b"B\n", "malformed L response").await
}

/// The roster layout the heartbeat ack and `L` share: `<tag> <count>
/// <replication>\n` then `count` `<name-len> <addr-len>\n<name><addr>\n`
/// entries; `withheld` alone (`A\n`, `B\n`) is `None`.
async fn read_roster<S: AsyncBufReadExt + Unpin>(
    stream: &mut S,
    tag: u8,
    withheld: &[u8],
    what: &'static str,
) -> io::Result<Option<(Vec<String>, usize)>> {
    let malformed = || io::Error::new(io::ErrorKind::InvalidData, what);

    let deadline = outbound_line_deadline();
    let mut line = Vec::new();
    infra::read_line_bounded(stream, MAX_ROSTER_LINE_LEN, deadline, &mut line).await?;
    if line == withheld {
        return Ok(None);
    }
    let header = line
        .strip_prefix(&[tag, b' '][..])
        .and_then(|rest| rest.strip_suffix(b"\n"))
        .and_then(|rest| std::str::from_utf8(rest).ok())
        .ok_or_else(malformed)?;
    let mut fields = header.split(' ');
    let count: usize = fields
        .next()
        .and_then(|raw| raw.parse().ok())
        .filter(|count| *count <= MAX_ROSTER_ENTRIES)
        .ok_or_else(malformed)?;
    // Issue #408: upper-bounded like `count` just above — a replication
    // factor can never sensibly exceed the roster size, and leaving it
    // unbounded is asymmetric with how `count` is validated right here.
    let replication: usize = fields
        .next()
        .and_then(|raw| raw.parse().ok())
        .filter(|replication| (1..=MAX_ROSTER_ENTRIES).contains(replication))
        .ok_or_else(malformed)?;
    if fields.next().is_some() {
        return Err(malformed());
    }

    let mut names = Vec::with_capacity(count.min(1024));
    for _ in 0..count {
        infra::read_line_bounded(stream, MAX_ROSTER_LINE_LEN, deadline, &mut line).await?;
        let entry = line
            .strip_suffix(b"\n")
            .and_then(|rest| std::str::from_utf8(rest).ok())
            .ok_or_else(malformed)?;
        let mut lengths = entry.split(' ');
        let name_len: usize = lengths
            .next()
            .and_then(|raw| raw.parse().ok())
            .filter(|len| *len <= MAX_ROSTER_FIELD_LEN)
            .ok_or_else(malformed)?;
        let addr_len: usize = lengths
            .next()
            .and_then(|raw| raw.parse().ok())
            .filter(|len| *len <= MAX_ROSTER_FIELD_LEN)
            .ok_or_else(malformed)?;
        if lengths.next().is_some() {
            return Err(malformed());
        }
        // `<name><addr>\n`
        let mut body = vec![0u8; name_len + addr_len + 1];
        stream.read_exact(&mut body).await?;
        if body[name_len + addr_len] != b'\n' {
            return Err(malformed());
        }
        let name = std::str::from_utf8(&body[..name_len]).map_err(|_| malformed())?;
        names.push(name.to_string());
    }

    Ok(Some((names, replication)))
}

/// Issue #61: replaces this node's membership belief with the roster its
/// primary discovery server just reported, if it differs. Until this, a
/// node's `known_ring` changed only when it finished a join handoff (`M`),
/// so after a liveness eviction every survivor kept the dead node in its
/// ring: keys that had re-homed to a survivor were answered `W` there
/// (R=1: every client error, permanently, until the next join), and with
/// R>1 writes quietly ran one copy short.
///
/// Skipped while a handoff this node is running is in flight or still
/// forwarding writes (`migration_target_for`'s window) AND the roster
/// doesn't list that handoff's joiner yet: discovery's roster is `Joined`
/// nodes only, so until every source has reported `C` it lacks a joiner
/// this node's `after_ring` already includes, and reverting to the
/// pre-join ring for that gap would only flap. Once the roster names the
/// joiner the join is over from discovery's view and the roster is
/// authoritative again — the forwarding window outlives the join by
/// `forwarding_grace` (a minute or more), and an eviction landing inside
/// it must not be ignored for that long. An abandoned join (`X`) clears
/// the slot; and if that `X` was lost, the window is bounded regardless.
///
/// Returns the ring change this call actually applied, if any — `None`
/// while a join is still pending or the roster matches what was already
/// believed. Issue #266: the caller (`register_with_discovery`) uses this
/// to detect a ring change that dropped a member — an eviction, or a
/// leave this node did not itself hand off for — and spawn a
/// re-replication task; `before` is `None` on the very first membership
/// this node ever adopts, which by definition drops nothing.
fn adopt_membership(
    known_ring: &KnownRing,
    active_migration: &Arc<Mutex<Option<ActiveMigration>>>,
    discovery_addr: &str,
    mut members: Vec<String>,
    replication: usize,
) -> Option<RingChange> {
    // Issue #408: every message below is printed only after its lock is
    // dropped — `active_migration`/`known_ring` are both also locked from
    // the GET/SET hot path (`migration_target_for` and friends), so a
    // backpressured stdout/stderr must not stall it, matching
    // `MigrationGuard::new`'s own already-fixed sibling branch.
    let mut confirmed_msg: Option<(String, usize)> = None;
    let mut evicted_msg: Option<String> = None;
    let mut evicted_lingering: Vec<String> = Vec::new();

    let join_still_pending = {
        let mut slot = active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let (pending, joiner_evicted) = match slot.as_mut() {
            Some(active) => {
                let joiner_listed = members.contains(&active.joining_name);
                // Issue #62: the roster naming the joiner is discovery's
                // word that the join completed — this handoff's dead
                // copies may now be swept (`run_sweep`).
                if joiner_listed && active.completed_at.is_some() && !active.confirmed {
                    active.confirmed = true;
                    confirmed_msg = Some((active.joining_name.clone(), active.marked_keys.len()));
                }
                // A joiner discovery already confirmed and later dropped
                // from its roster was *evicted*, not "not yet joined": the
                // forwarding window that outlives the join must not hide
                // that eviction (the doc comment above), so only an
                // unconfirmed join keeps the roster at bay.
                // A confirmed joiner missing from the roster was evicted;
                // closing its window early only means something while it
                // is open — a slot whose own window has ended (or a
                // remnant left by `take_slot_keeping_lingering`) just
                // waits for `expired()`.
                let joiner_gone = active.confirmed && !joiner_listed;
                if joiner_gone {
                    // Issue #474: whatever is still queued for it must not
                    // reach whoever answers at its address next — queued
                    // forwards can outlive the grace, and the drainer
                    // checks this flag, not the window.
                    active.forward_revoked.store(true, Ordering::SeqCst);
                }
                (
                    active.forwarding_open() && !joiner_listed && !active.confirmed,
                    joiner_gone && active.forwarding_open(),
                )
            }
            None => (false, false),
        };
        // Issue #267: the forwarding window is for a joiner that is still
        // there to receive the writes. Once discovery has evicted it,
        // every forward would only dial a dead address — one a new
        // container may already have been given — and burn
        // KEY_TRANSFER_ATTEMPTS x FORWARD_TIMEOUT each, so close the
        // window now instead of letting it lapse. The slot's marks were
        // released to the sweep at confirmation, so taking it is exactly
        // what the grace expiring would have done.
        // Issue #564: an earlier joiner kept for its forwarding grace
        // (`ActiveMigration::lingering`) was confirmed, so a roster that no
        // longer lists it means it was evicted or left — the same reasons
        // as above to stop forwarding at once (issues #267, #474).
        if let Some(active) = slot.as_mut() {
            active.lingering.retain(|lingering| {
                if members.contains(&lingering.joining_name) {
                    return true;
                }
                lingering.forward_revoked.store(true, Ordering::SeqCst);
                evicted_lingering.push(lingering.joining_name.clone());
                false
            });
        }
        if joiner_evicted && let Some(taken) = take_slot_keeping_lingering(&mut slot) {
            // Issue #474: forwards already queued for the evicted joiner
            // must not land on whoever gets its address next.
            taken.forward_revoked.store(true, Ordering::SeqCst);
            evicted_msg = Some(taken.joining_name);
        }
        pending
    };

    if let Some((joining_name, marked_len)) = confirmed_msg {
        println!(
            "INFO join of {joining_name} confirmed by discovery at {discovery_addr}; \
             {marked_len} dead copies released to the sweep"
        );
    }
    for joining_name in evicted_msg.into_iter().chain(evicted_lingering) {
        println!(
            "INFO joiner {joining_name} evicted by discovery at {discovery_addr}; closing its \
             forwarding window early"
        );
    }

    if join_still_pending {
        return None;
    }

    members.sort_unstable();
    members.dedup();

    let mut guard = known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let unchanged = guard
        .as_ref()
        .is_some_and(|current| same_members(current, &members, replication));
    if unchanged {
        return None;
    }

    let member_count = members.len();
    let before = guard.as_ref().cloned();
    let after = Arc::new(Membership {
        ring: Arc::new(HashRing::new(members)),
        replication,
    });
    *guard = Some(Arc::clone(&after));
    drop(guard);

    println!(
        "INFO membership updated from discovery at {discovery_addr}: {member_count} member(s), \
         replication factor {replication}"
    );

    Some(RingChange { before, after })
}

/// True if `membership` is exactly the roster `members` (any order,
/// duplicates ignored) at `replication`: `adopt_membership`'s "nothing to
/// change" test, and how the heartbeat ack tells a roster that merely
/// confirms the ring a handoff already installed from one it withheld
/// (issue #582).
fn same_members(membership: &Membership, members: &[String], replication: usize) -> bool {
    if membership.replication != replication {
        return false;
    }
    let mut known: Vec<&String> = membership.ring.nodes().iter().collect();
    known.sort_unstable();
    let mut wanted: Vec<&String> = members.iter().collect();
    wanted.sort_unstable();
    wanted.dedup();
    known == wanted
}

/// Issue #582: the membership a heartbeat ack just published, as the
/// reclaim history should see it — `change.after` when `adopt_membership`
/// applied the roster, else the membership this node already holds when
/// the roster merely repeats it (the ring a handoff this node ran
/// installed at completion, now published), and `None` when the roster
/// was withheld because this node's own join is still pending (it then
/// differs from what the node holds) or the node has no ring yet.
fn published_membership(
    change: Option<&RingChange>,
    known_ring: &KnownRing,
    roster: &[String],
    replication: usize,
) -> Option<Arc<Membership>> {
    if let Some(change) = change {
        return Some(Arc::clone(&change.after));
    }
    let current = known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .clone()?;
    same_members(&current, roster, replication).then_some(current)
}

/// What `adopt_membership` actually applied — see its own doc comment.
/// Records the roster discovery just published as `NodeContext::latest_published`,
/// ahead of (and regardless of) its adoption — see that field.
fn note_published_roster(latest_published: &KnownRing, roster: &[String], replication: usize) {
    let mut latest = latest_published
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if latest
        .as_ref()
        .is_some_and(|current| same_members(current, roster, replication))
    {
        return;
    }
    *latest = Some(Arc::new(Membership {
        ring: Arc::new(HashRing::new(roster.to_vec())),
        replication,
    }));
}

struct RingChange {
    before: Option<Arc<Membership>>,
    after: Arc<Membership>,
}

impl RingChange {
    /// Issue #266: true if `after` is missing at least one member
    /// `before` had — an eviction, or a leave this node did not itself
    /// hand off for (an ordinary decommission already transferred every
    /// affected key before it left, so re-triggering for it too is
    /// harmless — the put-if-absent handoff (`U … A`) makes a redundant
    /// send a no-op — just not free; simplicity over precision). `false`
    /// when `before` is `None` (this node's very first membership) or
    /// when the change only ever added members.
    fn dropped_a_member(&self) -> bool {
        self.before
            .as_ref()
            .is_some_and(|before| ring_dropped_a_member(&before.ring, &self.after.ring))
    }
}

/// Issue #266: true if `before`'s member set contains a name `after`
/// doesn't — the "was a member evicted (or otherwise dropped) between
/// these two rings" test both re-replication trigger sites use:
/// `RingChange::dropped_a_member` (an eviction-driven ring change,
/// `before` = the primary's previous heartbeat-ack roster) and
/// `run_migration`'s own join-flip trigger (`before` = this node's last
/// `known_ring` belief, which the flip below is about to replace —
/// see that function's own doc comment for why that belief can still
/// list a member the `M` itself never saw).
fn ring_dropped_a_member(before: &HashRing, after: &HashRing) -> bool {
    before
        .nodes()
        .iter()
        .any(|node| !after.nodes().contains(node))
}

/// Waits for `duration`, or returns `true` early if shutdown is signaled.
async fn wait_or_shutdown(duration: Duration, shutdown_rx: &mut watch::Receiver<bool>) -> bool {
    tokio::select! {
        _ = sleep(duration) => false,
        _ = shutdown_rx.changed() => true,
    }
}

/// The `S`/`s` frame that transfers or forwards `key` to a joining node.
/// A key in the default namespace goes out as the legacy `S` frame —
/// byte-identical to what pre-namespace nodes sent — so a rolling
/// upgrade's mixed-version handoff keeps working for legacy traffic;
/// only a namespaced key needs the `s` form (issue #105), which every
/// node must understand before namespaces are put to use.
fn set_message(key: &Key, value: &[u8], ttl: Option<Duration>) -> Vec<u8> {
    let mut header = if key.is_namespaced() {
        format!(
            "s {} {} {}",
            key.namespace.len(),
            key.name.len(),
            value.len()
        )
    } else {
        format!("S {} {}", key.name.len(), value.len())
    };

    if let Some(ttl) = ttl {
        header.push_str(&format!(" {}", ttl_wire_seconds(ttl)));
    }

    header.push('\n');

    let mut message = header.into_bytes();
    message.extend_from_slice(&key.namespace);
    message.extend_from_slice(&key.name);
    message.extend_from_slice(value);
    message
}

/// Staged node join: propagates a client's `D` for a key an in-progress handoff
/// is moving to the joining node too (see `forward_delete_to_joining_node`).
/// Same legacy-vs-namespaced frame choice as `set_message`.
fn delete_message(key: &Key) -> Vec<u8> {
    trace!(&key.name, "send_D key={}", crate::trace::name(&key.name));
    let mut message = if key.is_namespaced() {
        format!("d {} {}\n", key.namespace.len(), key.name.len()).into_bytes()
    } else {
        format!("D {}\n", key.name.len()).into_bytes()
    };
    message.extend_from_slice(&key.namespace);
    message.extend_from_slice(&key.name);
    message
}

/// Staged node join: reports to discovery that this node (identified by `name`,
/// Node identity decoupled from address) has finished handing off its share of the current join.
/// `C <name-len> <joining-len> <token-len> [<generation>]\n<name><joining><token>`
/// — the completion report names both the reporting node and the join it
/// is for (issue #5): a bare name let a stale report from an abandoned
/// handoff be credited to whatever join happened to be pending next.
/// `token` proves the report really comes from `name` (issue #34).
///
/// `generation` (tenth-pass audit, 2026-09-02, issue #421(c)) is the join
/// generation this handoff's own `M` carried
/// (`Command::Migrate::generation`), a trailing plain (not
/// length-prefixed) field echoed back unchanged so discovery can tell
/// this report apart from one for a since-abandoned-and-superseded join
/// that reused the same `joining_name` — see `nanocached-discovery`'s
/// `handle_complete`. Naming `joining_name` alone (issue #5's original
/// fix) isn't enough: a node whose join was abandoned can immediately
/// re-register under that very name and start a fresh `PendingJoin`
/// before this node's own already-in-flight `C` for the old one arrives.
///
/// `None` when the `M` that started this handoff itself carried no
/// generation (an old, not-yet-upgraded discovery server) — this falls
/// back to the legacy, generation-free three-field form, which such a
/// discovery server still understands. During a rolling upgrade this
/// means the new generation-based protection only actually holds once
/// every node AND discovery replica has picked up this fix; until then a
/// legacy `C` (from a node that itself hasn't upgraded yet, or one whose
/// in-flight handoff started under an old discovery) is accepted the
/// same way it always was, name+token only.
fn complete_message(
    name: &str,
    joining_name: &str,
    token: &str,
    generation: Option<u64>,
) -> Vec<u8> {
    let mut message = match generation {
        Some(generation) => format!(
            "C {} {} {} {generation}\n",
            name.len(),
            joining_name.len(),
            token.len()
        )
        .into_bytes(),
        None => format!("C {} {} {}\n", name.len(), joining_name.len(), token.len()).into_bytes(),
    };
    message.extend_from_slice(name.as_bytes());
    message.extend_from_slice(joining_name.as_bytes());
    message.extend_from_slice(token.as_bytes());
    message
}

/// This node's view of cluster membership plus the replication factor it
/// came with (client-side replication) — the two always travel together, since "is this
/// key mine to serve" is a top-R question and R arrived on the same `M`
/// that carried the roster.
struct Membership {
    ring: Arc<HashRing>,
    replication: usize,
}

/// Shared handle to a node's current `Membership` belief, if it has one
/// yet (see `NodeContext::known_ring`) — also handed to the heartbeat
/// tasks so they can report the replication factor half of it to
/// discovery (issue #30).
type KnownRing = Arc<Mutex<Option<Arc<Membership>>>>;

/// Issue #582: the memberships discovery published to this node, each
/// with the instant it was adopted. The ownership reclaim pass judges a
/// key against every ring that was in force at any point during
/// `RECLAIM_GRACE`, so a copy that any of them gave this node is kept —
/// a join that displaced it may be followed within the grace by a leave or
/// an eviction that hands it back, and the chaos trace behind the issue
/// was exactly a key owned under R0, not under R1 for eight seconds, and
/// owned again under R2.
#[derive(Clone, Default)]
struct RingHistory(Arc<RingHistoryShared>);

#[derive(Default)]
struct RingHistoryShared {
    inner: Mutex<RingHistoryInner>,
    /// Issue #970: woken by every `record` and `touch`, so the mark sweep
    /// re-judges its dead copies as soon as the membership moves instead of
    /// up to `SWEEP_INTERVAL` later (`run_sweep`).
    changed: tokio::sync::Notify,
}

#[derive(Default)]
struct RingHistoryInner {
    /// Oldest first.
    epochs: Vec<(Instant, Arc<Membership>)>,
    /// Bumped on every `record`, so a pass can tell the membership moved
    /// under it and stop rather than finish against a view that is gone.
    generation: u64,
}

impl RingHistory {
    /// Records `membership` as in force from now — unless it is the
    /// newest epoch already (same members, same replication): every
    /// heartbeat ack re-reports the ring, and a repeat is not a change.
    fn record_if_new(&self, membership: Arc<Membership>) {
        self.record_if_new_at(membership, Instant::now());
    }

    fn record_if_new_at(&self, membership: Arc<Membership>, now: Instant) {
        let mut inner = self
            .0
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some((_, newest)) = inner.epochs.last()
            && (Arc::ptr_eq(newest, &membership)
                || same_members(newest, membership.ring.nodes(), membership.replication))
        {
            return;
        }
        inner.epochs.push((now, membership));
        inner.generation += 1;
        drop(inner);
        self.0.changed.notify_one();
    }

    #[cfg(test)]
    fn record_at(&self, membership: Arc<Membership>, now: Instant) {
        let mut inner = self
            .0
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        inner.epochs.push((now, membership));
        inner.generation += 1;
    }

    /// Issue #594: bumps the generation without recording anything — for
    /// an abandon that reverts `known_ring` to the pre-join ring. The
    /// published rings did not change, but the keys this node admitted
    /// while `known_ring` held the handoff's unpublished post-join ring
    /// did: the next reclaim pass must look again rather than trust the
    /// last one (`ReclaimMark`).
    fn touch(&self) {
        let mut inner = self
            .0
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        inner.generation += 1;
        drop(inner);
        self.0.changed.notify_one();
    }

    /// Issue #970: the memberships in the history other than `current`,
    /// newest first — the rings the mark sweep judges a dead copy's other
    /// owners against (`SweepOwnership::since`). Empty for a fresh node or
    /// a membership that has stood longer than the reclaim grace keeps
    /// rings for.
    fn rings_before(&self, current: &Membership) -> Vec<Arc<Membership>> {
        let inner = self
            .0
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        inner
            .epochs
            .iter()
            .rev()
            .map(|(_, membership)| membership)
            .filter(|membership| {
                !std::ptr::eq(membership.as_ref(), current)
                    && !same_members(membership, current.ring.nodes(), current.replication)
            })
            .cloned()
            .collect()
    }

    /// Resolves when the history next moves (`record_if_new`, `touch`) —
    /// or at once if it moved since the last wait.
    async fn changed(&self) {
        self.0.changed.notified().await;
    }

    #[cfg(test)]
    fn generation(&self) -> u64 {
        self.0
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .generation
    }

    /// One `OwnerCheck` per membership in force at some point during the
    /// last `grace`, plus the generation they were read at — or `None`
    /// when the history does not reach back that far (a fresh node, or a
    /// first roster that arrived less than `grace` ago): with no ring known
    /// for part of the window nothing can be called unowned. Memberships
    /// older than the one in force at the window's start are dropped.
    fn checks_within(&self, grace: Duration, name: &str) -> Option<(Vec<OwnerCheck>, u64)> {
        self.checks_within_at(grace, name, Instant::now())
    }

    fn checks_within_at(
        &self,
        grace: Duration,
        name: &str,
        now: Instant,
    ) -> Option<(Vec<OwnerCheck>, u64)> {
        let mut inner = self
            .0
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let cutoff = now.checked_sub(grace)?;
        // The newest membership adopted at or before the cutoff is the one
        // in force when the window opened; without one, the window is not
        // covered.
        let start = inner
            .epochs
            .iter()
            .rposition(|(since, _)| *since <= cutoff)?;
        inner.epochs.drain(..start);
        let checks = inner
            .epochs
            .iter()
            .map(|(_, membership)| OwnerCheck {
                ring: Arc::clone(&membership.ring),
                name: name.to_string(),
                replication: membership.replication,
            })
            .collect();
        Some((checks, inner.generation))
    }
}

/// Tenth-pass audit (2026-09-02): `ActiveMigration::pending_clears`,
/// collapsed rather than a plain queue so an authenticated client issuing
/// many `c`/`F` while a join is in flight can't grow this — and the
/// serial, one-round-trip-each replay `drain_pending_clears` does at
/// handoff completion — without bound.
///
/// A clear only removes entries and replaying one twice has the same
/// effect as replaying it once, so collapsing is safe in every direction:
///
/// - `ClearScope::All` supersedes everything queued before or after it —
///   nothing a later clear could add isn't already covered, so pushing it
///   discards every queued namespace and any further namespace push is a
///   no-op.
/// - Duplicate `ClearScope::Namespace` scopes collapse to one.
/// - Past `MAX_PENDING_CLEAR_NAMESPACES` distinct namespaces, or past
///   `MAX_PENDING_CLEAR_BYTES` of their names, the queue degrades to a
///   single clear-all. This clears more than the client asked for on the
///   joining node, but that's a harmless miss there — never a
///   resurrection or a stale read — so it's a safe way to bound both
///   memory and the replay's round-trip count regardless of how many, or
///   how large, the distinct namespaces a client clears during one
///   handoff are.
#[derive(Default)]
struct PendingClears {
    all: bool,
    namespaces: HashSet<Bytes>,
    /// The queued names' bytes, what `MAX_PENDING_CLEAR_BYTES` bounds.
    bytes: usize,
}

impl PendingClears {
    /// Queues one clear, collapsing per the type's own doc comment.
    fn push(&mut self, scope: ClearScope) {
        if self.all {
            return;
        }
        match scope {
            ClearScope::All => self.collapse_to_all(),
            ClearScope::Namespace(namespace) => {
                let length = namespace.len();
                if self.namespaces.insert(namespace) {
                    self.bytes += length;
                }
                if self.namespaces.len() > MAX_PENDING_CLEAR_NAMESPACES
                    || self.bytes > MAX_PENDING_CLEAR_BYTES
                {
                    self.collapse_to_all();
                }
            }
        }
    }

    fn collapse_to_all(&mut self) {
        self.all = true;
        self.namespaces.clear();
        self.bytes = 0;
    }

    #[cfg(test)]
    fn is_empty(&self) -> bool {
        !self.all && self.namespaces.is_empty()
    }

    /// Takes every queued clear, leaving this empty — the collapsed
    /// counterpart of `std::mem::take` on the old `Vec<ClearScope>`.
    fn take(&mut self) -> Vec<ClearScope> {
        self.bytes = 0;
        if self.all {
            self.all = false;
            self.namespaces.clear();
            vec![ClearScope::All]
        } else {
            self.namespaces.drain().map(ClearScope::Namespace).collect()
        }
    }
}

/// A `run_migration` in flight: which handoff it's for, where the joining
/// node is, the ring this handoff computed (so a concurrent client write
/// on another connection can tell whether *its* key is one this handoff
/// is moving — see `handle_connection`'s forwarding of `S`/`D`), and the
/// flag an incoming `X` (cancel) sets to ask it to stop. See
/// `NodeContext::active_migration`.
struct ActiveMigration {
    joining_name: String,
    joining_addr: String,
    /// Issue #295: the joining node's own membership token, carried by
    /// the `M` that started this handoff (`Command::Migrate::
    /// joining_token`) — what this node presents on any `U`/`u` it needs
    /// to send the joiner (a concurrent client write forwarded via
    /// `migration_target_for`, or issue #266's own re-replication loop in
    /// `run_migration`), so the joiner can tell it apart from an ordinary
    /// shared-secret client forging a handoff frame (see
    /// `Command::HandoffSet::token`).
    joining_token: String,
    after_ring: Arc<HashRing>,
    /// Client-side replication: discovery's replication factor, carried by the `M` that
    /// started this handoff — membership in the joining node's copy set
    /// is "in the key's top-R", not "is the key's owner".
    replication: usize,
    /// The join generation this handoff's own `M` carried
    /// (`Command::Migrate::generation`) — `None` for a legacy sender that
    /// never parsed one (an old, not-yet-upgraded discovery process; see
    /// that field's own doc comment on the rolling-upgrade rationale).
    /// `MigrationGuard::new` compares this against an incoming `M`'s own
    /// `generation` to tell a discovery *retry* of this exact handoff
    /// (same name, same generation — a lost `A` ack) from a *new* join
    /// for the same `joining_name` that supersedes it (same name,
    /// different generation — a crash + fast restart of the joining node
    /// under the same identity racing this handoff's own slot). Without
    /// this, the second case was indistinguishable from the first: the
    /// new `M` was answered with a stale `DuplicateAcked`/`Conflict` for
    /// a handoff to a joining-node instance that no longer exists, and
    /// the join stalled until `migration_timeout_for` reaped it.
    generation: Option<u64>,
    /// `None` while this node's own transfer is running; `Some(when)`
    /// once it finished successfully. Issue #3: discovery only publishes
    /// the joiner after EVERY ready node reports `C`, so this node must
    /// keep forwarding concurrent writes to the joiner after its own
    /// share is done — a still-stale client that can't see the joiner in
    /// `L` yet would otherwise write to this node without the joiner ever
    /// learning of it. The window is bounded by `forwarding_grace`
    /// (matching discovery's migration timeout: past it the join has
    /// either completed cluster-wide or been abandoned).
    completed_at: Option<Instant>,
    /// This handoff's own size-derived grace window (`forwarding_grace`),
    /// set together with `completed_at` — not a shared constant, since
    /// different handoffs move different amounts of data. Meaningless
    /// (left at `Duration::ZERO`) until `completed_at` is `Some`.
    forwarding_grace: Duration,
    /// Stamped by `MigrationGuard::ack` once the `M` handler has computed
    /// the entry count it acks (`entries_to_send_count`) — that snapshot
    /// happens after this slot is reserved, so it can't be filled in at
    /// construction. `None` for the brief window before that stamp lands.
    /// Lets `MigrationGuard::new` answer a duplicate `M` for this same
    /// `joining_name` (a discovery retry after a lost ack) with the same
    /// `A <entries>` ack again — see `MigrationOutcome::DuplicateAcked`.
    acked_entries: Option<usize>,
    abort_requested: Arc<AtomicBool>,
    /// Issue #62: the dead copies this handoff marked (`mark_migrated`),
    /// kept here after completion so they can be rolled back if the join
    /// is abandoned after this node's own share was done — an `X` on a
    /// completed slot, or a later `M` whose roster shows the joiner never
    /// made it. Until `confirmed`, `run_sweep` leaves marked entries
    /// alone (`Command::Sweep { marked: false, owned: None }`).
    marked_keys: Vec<Key>,
    /// Issue #62: discovery has completed this join — the joiner showed
    /// up in the primary's heartbeat-ack roster (`adopt_membership`) or
    /// in the `joined` roster of a subsequent `M`. Only then are this
    /// handoff's `marked_keys` safe to sweep, and only then does the slot
    /// expire on its own once `forwarding_grace` has passed; an
    /// unconfirmed completed slot stops forwarding after the grace but
    /// stays put, holding its marks back from the sweep, until something
    /// decides the join one way or the other.
    confirmed: bool,
    /// Issue #93: the `known_ring` value this handoff replaced when it
    /// flipped to the post-join topology on completion (`run_migration`).
    /// If the join is later abandoned (`X`) after this node's own share
    /// completed but before discovery confirmed it cluster-wide, the
    /// post-join ring never became real — the abandon path restores this
    /// snapshot so `wrong_node` stops answering `W` for the (now live
    /// again) restored keys immediately, instead of waiting for the next
    /// heartbeat's `adopt_membership` to correct `known_ring`. `None`
    /// until `completed()` stamps it.
    pre_completion_ring: Option<Arc<Membership>>,
    /// Issue #106: clears (`c`/`F`) that arrived while this node's own
    /// transfer was still running, waiting for `run_migration` to replay
    /// them on its transfer stream. A clear can't be forwarded the way a
    /// concurrent `S`/`D` is (on the shared forwarding connection) while
    /// keys are still being sent on the transfer connection: the two
    /// streams have no ordering between them, so a key peeked before the
    /// clear could land on the joiner *after* the forwarded clear and
    /// resurrect there. Queued here instead and drained by the transfer
    /// loop onto its own stream, where the order is real. Only filled
    /// while `completed_at` is `None` (both under this slot's lock), so
    /// the final drain after `completed()` is stamped sees everything;
    /// from then on clears forward like any other write.
    pending_clears: PendingClears,
    /// Persistent connection to the joining node, shared by every
    /// `set_on_joining_node`/`delete_on_joining_node` call this handoff's
    /// concurrent client writes trigger (see `migration_target_for` and
    /// `ForwardTarget`) — issue: those two used to call
    /// `connect_and_authenticate` fresh per forwarded write, opening (and
    /// leaking to TIME_WAIT) a new TCP+TLS+Auth connection every time,
    /// the same ephemeral-port exhaustion `run_migration`'s own bulk
    /// transfer already learned to avoid by reusing one connection for
    /// every key (see this struct's own doc comment on that, and
    /// `run_migration`'s). `None` when there is no live connection yet,
    /// or right after an I/O error drops the last one; the next forward
    /// reconnects. A `tokio::sync::Mutex`, not `std::sync`, since a
    /// connection is held across the `.await`s of writing a command and
    /// reading its ack, one forwarded write at a time (concurrent
    /// forwards for this same handoff simply queue behind each other —
    /// they'd have to serialize on the wire regardless, being one TCP
    /// stream). Deliberately scoped per-`ActiveMigration`, not shared
    /// across migrations: a fresh migration means a different joining
    /// node, so it must start with no connection rather than possibly
    /// reusing one dialed to whatever node the previous handoff targeted.
    forward_connection: Arc<AsyncMutex<Option<ClientStream>>>,
    /// Issue #474: flipped to `true` when this slot stops being the
    /// handoff this node forwards for (evicted joiner, abandoned join,
    /// superseded by a later `M`), so forwards already resolved against
    /// it are dropped instead of delivered to whoever now answers at
    /// `joining_addr` — see `ForwardTarget::revoked`.
    forward_revoked: Arc<AtomicBool>,
    /// Issue #564: earlier joiners this node finished handing off to, whose
    /// join discovery has confirmed, and whose forwarding grace is still
    /// open when a later `M` took this slot over. Kept so that a client
    /// whose node list still routes to the old owners keeps reaching them
    /// — see `LingeringForward`.
    lingering: Vec<LingeringForward>,
    /// Left by `take_slot_keeping_lingering`: not a handoff at all any
    /// more, only the carrier of `lingering` until their windows end. An
    /// `M` must never mistake it for the handoff it was cut from — the
    /// name, generation and `acked_entries` it still carries would answer
    /// a retried `M` with a duplicate ack for a transfer nobody is
    /// running — so `MigrationGuard::new` skips its duplicate check for
    /// one and replaces it like any superseded slot.
    remnant: bool,
}

/// Issue #564: the forwarding half of an `ActiveMigration` that a later `M`
/// superseded while its forwarding grace was still open and its join was
/// confirmed. The grace exists so that writes still routed to the old
/// owners by a client with a stale node list reach the joiner; a second
/// join starting inside that window used to drop the first joiner from
/// `migration_target_for` altogether (its `forward_revoked` was set), so
/// the joiner silently stopped receiving writes it owns.
///
/// Whether a given key still goes to a lingering joiner is decided by the
/// *current* slot's ring (`migration_targets_for_hashed`): that ring
/// contains every confirmed joiner, so it says whether the joiner owns
/// the key now, not whether it did when its own join ran.
///
/// Never kept for an abandoned join (its marks are restored and its
/// forwards revoked, as before), for the same joiner name at a new
/// generation (that is a restart, possibly at another address), or after
/// discovery evicted the joiner (`adopt_membership` revokes it — issues
/// #267, #474: a dead joiner's address may already belong to someone
/// else).
struct LingeringForward {
    joining_name: String,
    joining_addr: String,
    joining_token: String,
    completed_at: Instant,
    forwarding_grace: Duration,
    /// The superseded slot's own connection and revocation flag, moved
    /// over unchanged so forwards already queued against it keep working.
    forward_connection: Arc<AsyncMutex<Option<ClientStream>>>,
    forward_revoked: Arc<AtomicBool>,
}

impl LingeringForward {
    fn forwarding_open(&self) -> bool {
        self.completed_at.elapsed() < self.forwarding_grace
    }

    fn target(&self) -> ForwardTarget {
        ForwardTarget {
            addr: self.joining_addr.clone(),
            connection: Arc::clone(&self.forward_connection),
            token: self.joining_token.clone(),
            revoked: Arc::clone(&self.forward_revoked),
            // A lingering joiner is a confirmed member with a ring view
            // of its own, which may lag the slot's — see
            // `ForwardTarget::as_handoff`.
            as_handoff: true,
        }
    }
}

impl ActiveMigration {
    /// Still moving keys, or completed but within `forwarding_grace` —
    /// the window during which concurrent client writes are forwarded
    /// to the joiner (`migration_target_for`).
    fn forwarding_open(&self) -> bool {
        self.completed_at
            .is_none_or(|completed_at| completed_at.elapsed() < self.forwarding_grace)
    }

    /// Nothing left for this slot to do: the join is confirmed (its
    /// marks can be swept without it) and the forwarding window has
    /// closed. Cleared lazily by whoever notices.
    fn expired(&self) -> bool {
        self.confirmed
            && !self.forwarding_open()
            && self
                .lingering
                .iter()
                .all(|lingering| !lingering.forwarding_open())
    }
}

/// Issue #266: a `run_rereplication` in flight — the re-replication
/// counterpart of `ActiveMigration`, held in `NodeContext::active_rereplication`.
/// Wrapped in an `Arc` (rather than living directly in the slot, as
/// `ActiveMigration` does) because `spawn_or_supersede_rereplication`
/// needs to hand a superseded run's own handle to the code asking it to
/// stop *after* it has already replaced the slot's contents with the new
/// run — there is no single lock scope in which both "read the old
/// value" and "write the new one" can happen while also holding a
/// reference to the old value to poll afterward.
struct ActiveRereplication {
    /// Set by a later ring change's task to ask this run to stop early —
    /// checked in `run_rereplication`'s per-key loop, same idiom as
    /// `ActiveMigration::abort_requested`.
    abort_requested: AtomicBool,
    /// Set once `run_rereplication` returns (whether it finished,
    /// aborted, or gave up on the roster fetch) — `Instant`-free, unlike
    /// `ActiveMigration::completed_at`: nothing here needs to measure a
    /// forwarding grace, only to know the run is over.
    done: AtomicBool,
}

/// Occupies `slot` with an `ActiveMigration` for this guard's lifetime
/// (cleared back to `None` on drop — including an early return or panic),
/// so `run_sweep` can tell to pause, an incoming `X` can find this
/// handoff to cancel it, and a concurrent client write can find it to
/// forward. Exposes `abort_requested` so `run_migration` can poll it
/// directly without re-locking `slot` on every entry. Holds an owned
/// clone of `NodeContext::active_migration`'s `Arc` (rather than
/// borrowing `NodeContext`) so `handle_connection` can create and hold
/// this guard *before* handing the migration off to `run_migration` —
/// see the accept/reject ordering note on `Response::MigrationRejected`.
struct MigrationGuard {
    slot: Arc<Mutex<Option<ActiveMigration>>>,
    abort_requested: Arc<AtomicBool>,
    /// Set by `completed()` so `Drop` leaves the slot's completion info
    /// (stamped by `completed()` itself) intact instead of clearing it.
    completed: bool,
}

/// What `MigrationGuard::new` found when it tried to reserve `slot` for
/// an incoming `M` — see its doc comment for the reasoning behind each
/// case.
enum MigrationOutcome {
    /// A fresh slot was reserved; the caller should ack with the entry
    /// count it computes, then stamp it via `MigrationGuard::ack`.
    New {
        guard: MigrationGuard,
        /// Issue #62: dead copies left marked by a previous, completed
        /// handoff that this `M`'s roster reveals was abandoned (its
        /// joiner isn't `Joined`); the caller must `unmark_migrated`
        /// each before listing keys, so they're live again — and re-sent
        /// if the new joiner owns them.
        restore: Vec<Key>,
    },
    /// This `M` names the same `joining_name` as the handoff already
    /// occupying the slot, and that handoff has already stamped what it
    /// acked — a discovery retry after a lost ack. The caller should
    /// resend `MigrationAccepted` with this same count rather than start
    /// a second migration.
    DuplicateAcked(usize),
    /// The slot is occupied by a handoff for a different `joining_name`,
    /// or by the same `joining_name` whose `acked_entries` hasn't been
    /// stamped yet. The caller should reject with `MigrationRejected`.
    Conflict,
}

#[cfg(test)]
impl MigrationOutcome {
    /// Test-only convenience: most tests only care about the successful
    /// path, so this saves a `match` at every one of those call sites.
    fn unwrap_new(self) -> MigrationGuard {
        match self {
            MigrationOutcome::New { guard, .. } => guard,
            MigrationOutcome::DuplicateAcked(entries) => {
                panic!("expected a new migration guard, got a duplicate ack for {entries} entries")
            }
            MigrationOutcome::Conflict => panic!("expected a new migration guard, got a conflict"),
        }
    }
}

impl MigrationGuard {
    /// Reserves `slot` for a new handoff, or reports why it couldn't
    /// (issue #3): unconditionally overwriting an occupied slot would
    /// clobber the active migration's
    /// `completed_at`/`forwarding_grace`/`abort_requested` out from under
    /// its own still-running `run_migration` task (or its post-completion
    /// forwarding window), corrupting `migration_target_for` and `X`/`C`
    /// matching for whichever migration loses the slot.
    ///
    /// A second `M` for the same `joining_name` *and* the same
    /// `generation` — a discovery retry after a lost ack
    /// (`send_migrate_with_retry`) — is the expected way to hit an
    /// occupied slot, and is handled idempotently: once the original
    /// `M`'s handler has stamped `acked_entries` (see
    /// `MigrationGuard::ack`), the retry gets back
    /// `MigrationOutcome::DuplicateAcked` carrying the same entry count
    /// the first ack reported, so the caller can resend the same `A
    /// <entries>` ack instead of starting a second migration or
    /// rejecting a retry that's really just a replay. In the brief
    /// window before that stamp lands, this returns
    /// `MigrationOutcome::Conflict` so the caller rejects with `R\n` —
    /// the next retry will find `acked_entries` stamped. A `None` on
    /// either side (a legacy peer that never parsed/sent a `generation`)
    /// is treated as a match, preserving this same-name-is-enough
    /// behavior for a rolling upgrade — see `Command::Migrate::
    /// generation`'s own doc comment.
    ///
    /// A same-`joining_name` `M` carrying a *different* generation is a
    /// genuinely new join for that name superseding the one already
    /// occupying the slot (a crash + fast restart of the joining node
    /// under the same identity — see this struct's own `generation`
    /// field doc comment). Still transferring, it's handled the same as
    /// a different `joining_name` while one is active: `abort_requested`
    /// is set (so the stale transfer unwinds instead of racing the new
    /// one to completion) and this returns `MigrationOutcome::Conflict`.
    /// Already completed (forwarding grace or not), it falls into the
    /// same issue #62/#93 supersede logic below that a genuinely
    /// different `joining_name` does — whether its marks are restored or
    /// kept depends on `joined`, exactly as for a different name.
    ///
    /// Reuses `migration_target_for`'s lazy-expiry check first: a slot
    /// left by a prior handoff that finished *and* whose forwarding grace
    /// has already elapsed is stale, not "still active" — without this, a
    /// completed slot that no client `GET`/`SET` has touched since (the
    /// only other place that lazily clears it) would wrongly block the
    /// very next join.
    ///
    /// Issue #218: an abandoned previous handoff (`!previous_confirmed`
    /// below) also reverts `known_ring` to its `pre_completion_ring`, the
    /// same way the explicit `X` path (`abandon_migration`) does — guarded
    /// by the same `Arc::ptr_eq` check so a newer membership update isn't
    /// clobbered. Without it, `wrong_node` would keep routing to the
    /// phantom joiner until the next heartbeat's `adopt_membership`.
    // Returns `MigrationOutcome`, not `Self`, on purpose: reserving the
    // slot can produce an idempotent re-ack or a rejection instead of a
    // guard — see `MigrationOutcome`.
    #[allow(clippy::new_ret_no_self)]
    #[allow(clippy::too_many_arguments)]
    fn new(
        slot: Arc<Mutex<Option<ActiveMigration>>>,
        joining_name: String,
        joining_addr: String,
        joining_token: String,
        after_ring: Arc<HashRing>,
        replication: usize,
        generation: Option<u64>,
        joined: &[(String, String)],
        known_ring: &KnownRing,
        ring_history: &RingHistory,
    ) -> MigrationOutcome {
        let mut guard = slot.lock().unwrap_or_else(|poisoned| poisoned.into_inner());

        if guard.as_ref().is_some_and(ActiveMigration::expired) {
            *guard = None;
        }

        let mut restore = Vec::new();
        let mut abandoned_known_ring: Option<(Arc<HashRing>, Option<Arc<Membership>>)> = None;
        // Issue #408: message for the abandoned-handoff branch below,
        // printed only after `guard` is dropped (same reasoning as the
        // `completed_at.is_none()` branch just above it: `slot` is also
        // locked by `migration_target_for` on every GET/SET, so a
        // backpressured stderr must not stall that hot path). Captures its
        // own copy of `joining_name` since the parameter is moved into the
        // new `ActiveMigration` below, before this can be printed.
        let mut abandoned_msg: Option<(String, usize, String)> = None;
        if let Some(existing) = guard.as_ref() {
            let same_name = existing.joining_name == joining_name;
            // `None` on either side (a legacy peer) can't disagree — see
            // this fn's own doc comment on the rolling-upgrade rationale.
            let same_generation = match (existing.generation, generation) {
                (Some(existing_generation), Some(generation)) => existing_generation == generation,
                _ => true,
            };

            if same_name && same_generation && !existing.remnant {
                // Same-name, same-generation retry: re-ack idempotently
                // once the original `M` has computed what to ack,
                // otherwise ask the caller to reject — the next retry
                // will find it stamped.
                return match existing.acked_entries {
                    Some(acked_entries) => MigrationOutcome::DuplicateAcked(acked_entries),
                    None => MigrationOutcome::Conflict,
                };
            }

            if existing.completed_at.is_none() {
                // Still transferring, and this `M` is not a retry of the
                // exact same handoff — either a genuinely different
                // `joining_name`, or the same name at a new generation
                // superseding the one running here. Either way the slot
                // can't be handed over synchronously (only
                // `run_migration`'s own unwind can safely drop it
                // mid-transfer): ask it to stop and reject this `M`,
                // trusting the caller (discovery, on `X`'s `abandon_
                // migration` path) to wait for the slot to actually
                // clear before it lets a same-name retry land — see
                // `wait_for_migration_slot_to_clear`.
                if same_name {
                    existing.abort_requested.store(true, Ordering::SeqCst);
                    existing.forward_revoked.store(true, Ordering::SeqCst);
                }
                let conflicting_joining_name = existing.joining_name.clone();
                let conflicting_generation = existing.generation;
                // Dropped before logging (unlike the lock this replaced,
                // which held it across the `eprintln!`) since `slot` is
                // also locked by `migration_target_for` on every GET/SET
                // — a backpressured stderr shouldn't stall the hot path.
                drop(guard);
                if same_name {
                    eprintln!(
                        "WARN M for {joining_name} (generation {generation:?}) supersedes a \
                         still-transferring handoff for the same name at generation \
                         {conflicting_generation:?}; requesting it stop and rejecting this M \
                         until the slot clears"
                    );
                } else {
                    eprintln!(
                        "WARN ignoring M for {joining_name}: a migration to \
                         {conflicting_joining_name} is already active"
                    );
                }
                return MigrationOutcome::Conflict;
            }

            // Issue #62: a completed handoff (forwarding or not) doesn't
            // block the next join — whether the slot's previous occupant
            // was a different `joining_name`, or the same name at an
            // older generation. Discovery serializes joins, so a new `M`
            // here means the previous join has been decided — and
            // `joined` says which way: the previous joiner listed there
            // completed (its dead copies here are really dead), otherwise
            // it was abandoned and those copies are live again. Rejecting
            // here instead is what made discovery abandon back-to-back
            // joins for a whole forwarding window, and sweeping those
            // marks regardless is what lost the keys.
            let previous_confirmed = existing.confirmed
                || joined
                    .iter()
                    .any(|(name, _)| *name == existing.joining_name);
            if !previous_confirmed {
                restore = existing.marked_keys.clone();
                abandoned_known_ring = Some((
                    Arc::clone(&existing.after_ring),
                    existing.pre_completion_ring.clone(),
                ));
                abandoned_msg = Some((
                    existing.joining_name.clone(),
                    restore.len(),
                    joining_name.clone(),
                ));
            }
        }

        // Issue #474: whatever handoff the slot held until now is being
        // superseded; forwards still queued against it must not be
        // delivered to whoever answers at its address later.
        //
        // Issue #564: unless that joiner is still there and still owed its
        // forwarding window — its join confirmed, its grace not over, and
        // not the same name at a new generation (a restart, possibly at
        // another address). Then the forwarding half moves to the new
        // slot's `lingering` list with its connection and revocation flag
        // untouched, so a client that still writes to the old owners keeps
        // reaching it until the grace ends or discovery evicts it
        // (`adopt_membership`).
        let mut lingering: Vec<LingeringForward> = Vec::new();
        if let Some(existing) = guard.as_mut() {
            for older in std::mem::take(&mut existing.lingering) {
                if older.forwarding_open() {
                    lingering.push(older);
                } else {
                    older.forward_revoked.store(true, Ordering::SeqCst);
                }
            }
            let keep = abandoned_msg.is_none()
                && existing.joining_name != joining_name
                && existing.forwarding_open()
                && existing.completed_at.is_some();
            match existing.completed_at {
                Some(completed_at) if keep => lingering.push(LingeringForward {
                    joining_name: existing.joining_name.clone(),
                    joining_addr: existing.joining_addr.clone(),
                    joining_token: existing.joining_token.clone(),
                    completed_at,
                    forwarding_grace: existing.forwarding_grace,
                    forward_connection: Arc::clone(&existing.forward_connection),
                    forward_revoked: Arc::clone(&existing.forward_revoked),
                }),
                _ => existing.forward_revoked.store(true, Ordering::SeqCst),
            }
        }

        let abort_requested = Arc::new(AtomicBool::new(false));

        *guard = Some(ActiveMigration {
            joining_name,
            joining_addr,
            joining_token,
            after_ring,
            replication,
            generation,
            completed_at: None,
            forwarding_grace: Duration::ZERO,
            acked_entries: None,
            abort_requested: Arc::clone(&abort_requested),
            marked_keys: Vec::new(),
            confirmed: false,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering,
            remnant: false,
        });
        drop(guard);

        if let Some((abandoned_joining_name, restored_count, joining_name)) = abandoned_msg {
            eprintln!(
                "WARN previous handoff to {abandoned_joining_name} was abandoned (not in the \
                 roster M for {joining_name} carries); restoring {restored_count} dead copies"
            );
        }

        // Locked only after the slot lock above is dropped — never both at
        // once (matches `abandon_migration`'s ordering).
        if let Some((after_ring, pre_completion_ring)) = abandoned_known_ring {
            let mut known_ring_guard = known_ring
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            if known_ring_guard
                .as_ref()
                .is_some_and(|current| Arc::ptr_eq(&current.ring, &after_ring))
            {
                *known_ring_guard = pre_completion_ring;
                ring_history.touch();
            }
        }

        MigrationOutcome::New {
            guard: Self {
                slot,
                abort_requested,
                completed: false,
            },
            restore,
        }
    }

    /// Stamps the entry count this handoff acks (`entries_to_send_count`,
    /// computed by the caller after this guard exists — the snapshot it
    /// needs isn't available yet at `new`'s call site) into the slot, so
    /// a same-`joining_name` retry of `M` can be answered with the same
    /// ack again — see `MigrationGuard::new`'s doc comment.
    fn ack(&self, entries: usize) {
        if let Some(active) = self
            .slot
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .as_mut()
        {
            active.acked_entries = Some(entries);
        }
    }

    /// The marks `join_took` recorded in this guard's own slot while the
    /// transfer ran, taken out for an abort to roll back: the slot is
    /// cleared when the guard drops, and `run_migration` knows only the
    /// marks it made itself. Empty when the slot is no longer this guard's
    /// (another handoff replaced it; its marks are its own).
    fn take_join_marks(&self) -> Vec<Key> {
        let mut slot = self
            .slot
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match slot.as_mut() {
            Some(active) if Arc::ptr_eq(&active.abort_requested, &self.abort_requested) => {
                std::mem::take(&mut active.marked_keys)
            }
            _ => Vec::new(),
        }
    }

    /// Consumes the guard after a successful transfer: instead of
    /// clearing the slot (which would close the write-forwarding window
    /// the moment THIS node finishes — issue #3), it stamps the
    /// completion time and this handoff's own size-derived grace (from
    /// `entries_sent`, size-derived migration timeout) so `migration_target_for` keeps
    /// forwarding until that grace passes or the slot is
    /// replaced/cancelled.
    fn completed(
        mut self,
        entries_sent: usize,
        marked_keys: Vec<Key>,
        pre_completion_ring: Option<Arc<Membership>>,
    ) {
        if let Some(active) = self
            .slot
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .as_mut()
        {
            active.completed_at = Some(Instant::now());
            active.forwarding_grace = forwarding_grace(entries_sent);
            // Added to, not replaced: `join_took` records the copies it
            // marks while this transfer is still running, and an abandon
            // rolls back the marks listed here.
            active.marked_keys.extend(marked_keys);
            active.pre_completion_ring = pre_completion_ring;
        }
        self.completed = true;
    }
}

impl Drop for MigrationGuard {
    fn drop(&mut self) {
        if self.completed {
            return;
        }
        // An aborted or failed transfer clears its slot — but not the
        // earlier joiners' windows the `M` carried into it (issue #564).
        let mut slot = self
            .slot
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let _ = take_slot_keeping_lingering(&mut slot);
    }
}

/// Computes this handoff's before/after hash rings from `joined` +
/// `joining_name`, folding this node's own name into the "before" set —
/// discovery always lists this node in the roster (it only sends `M` to
/// `Joined` members), but the sender/displaced computations downstream
/// are meaningless without self in the "before" set, so this makes that
/// structural rather than trusted. Called once by `handle_connection`
/// (to reserve `MigrationGuard` before acknowledging `M` — see
/// `Response::MigrationRejected`, and to size `entries_to_send_count`),
/// with the resulting rings then also handed to `run_migration`.
fn migration_rings(
    node_context: &NodeContext,
    joining_name: &str,
    joined: &[(String, String)],
) -> (HashRing, HashRing) {
    let mut before_members: Vec<String> = joined.iter().map(|(name, _)| name.clone()).collect();
    if !before_members.iter().any(|name| name == &node_context.name) {
        before_members.push(node_context.name.clone());
    }
    // Issue #328: `joined` is a snapshot of a live discovery roster, with
    // no guarantee it's free of duplicate names — `adopt_membership`
    // (`known_ring`'s own update path) applies this identical
    // `sort_unstable` + `dedup` to its membership list before building a
    // `HashRing` from it; this path built one straight from `joined`
    // without it. A duplicate here silently breaks `HashRing::is_owner`
    // and `owners` agreeing with each other (see their doc comments),
    // which is exactly what this function's before/after rings decide
    // handoff roles from. `HashRing::new` now also dedupes defensively,
    // but doing it here too keeps `before_members`/`after_members`
    // themselves accurate for anything that inspects them directly.
    before_members.sort_unstable();
    before_members.dedup();

    let mut after_members = before_members.clone();
    after_members.push(joining_name.to_string());
    after_members.sort_unstable();
    after_members.dedup();

    (HashRing::new(before_members), HashRing::new(after_members))
}

/// Size-derived migration timeout: counts how many of `keys` this node will actually
/// send to the joining node, mirroring the predicate `run_migration`
/// computes for real (issue #266: every old owner that holds an
/// affected key sends it — not just a single designated "primary" — so
/// this is "this node was one of the key's old owners", not "this node
/// was the highest-ranked one"). Purely to size discovery's migration
/// timeout — not a transfer plan.
///
/// Takes `keys` (a `list_keys` snapshot) rather than fetching its own:
/// this and `run_migration`'s own transfer loop used to each call
/// `list_entries` (then a full key+value+TTL clone, see `Cache::keys`'s
/// doc comment) independently — two full clones of the cache off of the
/// single-threaded cache actor per `M`, back to back, each blocking
/// every other request the actor handles for its duration. `M`'s caller
/// (`handle_connection`) now takes one snapshot and passes it to both,
/// halving that stall. This does mean a concurrent write racing the
/// snapshot could shift the true count slightly by the time transfer
/// actually happens — already true before this change (the snapshot was
/// never a transfer plan either way; `run_migration` re-checks every
/// key's live value before sending it regardless, see its own comment).
/// A chunked/budgeted listing (mirroring `sweep`'s `SWEEP_BUDGET`) would
/// avoid the clone-the-whole-cache cost entirely, but needs the
/// migration protocol to support resuming a partial listing — a larger
/// change than this bug fix warrants.
///
/// The count itself hashes every key twice against a ring, about 60 ms
/// per million keys (issue #1027), and used to run to completion on the
/// single runtime thread right after the snapshot, so a node with
/// millions of keys served no client and sent no heartbeat for that long
/// on top of the snapshot's own pause. It now walks the snapshot in
/// `SWEEP_BUDGET`-sized chunks and yields between them, as the sweep and
/// the reclaim pass do, so other tasks interleave; the `M` ack is a little
/// later, the stall is gone.
async fn entries_to_send_count(
    keys: &[Key],
    before_ring: &HashRing,
    after_ring: &HashRing,
    self_name: &str,
    joining_name: &str,
    replication: usize,
) -> usize {
    let mut hasher = KeyHasher::default();
    let mut count = 0;
    for chunk in keys.chunks(SWEEP_BUDGET) {
        count += chunk
            .iter()
            .filter(|key| {
                let key_hash = hasher.hash(key);
                after_ring.is_owner_hashed(key_hash, joining_name, replication)
                    && before_ring.is_owner_hashed(key_hash, self_name, replication)
            })
            .count();
        tokio::task::yield_now().await;
    }
    count
}

/// Staged node join (generalized by client-side replication): triggered by an incoming `M`.
/// Computes, using the same rendezvous-hash algorithm clients use
/// (`HashRing` here is `src/hash_ring.rs`'s copy, see TLS support), how each
/// of this node's own entries' top-R owner set changes when the joining
/// node is added. Adding exactly one node can only insert it into a key's
/// ranking, never reorder the existing nodes relative to each other, so
/// per affected key exactly one role can apply to the node displaced from
/// rank R to R+1 (if any — there is at most one): its now-dead copy is
/// marked for the post-handoff sweep. This node may hold that role, or
/// not, independently of whether it sends.
///
/// Issue #266: **every** pre-join owner of an affected key that actually
/// holds it sends its copy to the joiner — not just a single designated
/// "old primary". That used to be safe to optimize away (client writes
/// fan out to every owner, so all owners were assumed equally
/// up to date) until re-replication-after-eviction made it possible for
/// an old owner to be a *ring-computed* owner without actually holding
/// live data yet (a promotion whose re-replication hasn't caught up).
/// Electing only the primary to send then risked a silent no-op — the
/// primary's `peek_entry` comes back empty, nothing is transferred, and
/// the *other* old owner (who does hold the real copy) gets marked
/// displaced and swept anyway, destroying the only copy. Every owner
/// sending instead means the joiner gets a copy as long as *any* old
/// owner still has one. Sent as a put-if-absent `U … A`
/// (`ForwardedWrite::HandoffSet`'s `if_absent`), not a plain `SET`, since
/// more than one node may now send the same key: idempotent, so a
/// redundant send from a second holder — or a concurrent client write
/// racing the same joiner on the shared forwarding connection
/// (`migration_target_for`, still an unconditional `SET` there since a
/// live write is always the freshest) — never clobbers whichever arrives
/// first; every one is still acked `S\n`. A displaced holder marks its
/// copy dead only *after* its own send here actually succeeds — not
/// merely because ring math says it's displaced — so a holder that
/// failed to send (or never had the data to begin with) never has
/// something reclaimed out from under a copy the joiner never received.
/// There's no need to compare more than a pre-join ring.
///
/// All transfers for one migration share a single connection to the
/// joining node instead of opening (and tearing down) one per key —
/// with tens of thousands of keys, one-connection-per-key was observed
/// to exhaust the ephemeral port range mid-migration, at which point
/// every further key was silently skipped while the migration still
/// went on to flip `known_ring` and report completion, quietly losing
/// whatever didn't make it across. A key whose transfer fails is retried
/// up to `KEY_TRANSFER_ATTEMPTS` times, reconnecting each time (the
/// connection's state after a failed write/read is unknown, so it isn't
/// reused as-is). If a key still can't be transferred after that, this
/// gives up on the whole migration: it rolls back every mark from this
/// run (same as the `abort_requested` path below) and returns without
/// flipping `known_ring` or reporting `C`, leaving discovery's own
/// size-derived migration timeout (size-derived migration timeout) to reap the
/// stalled join rather than have this node claim success over a joining
/// node that's missing data. A lost discovery connection for the final
/// `C` is a separate, already-terminal failure (the transfer itself
/// succeeded) and is just logged.
///
/// Takes `migration_guard` (and the `before_ring`/`after_ring` it was
/// created from) already reserved by `handle_connection`, rather than
/// reserving them itself: the guard has to exist *before* `M` is
/// acknowledged, so a rejection (see `Response::MigrationRejected`) can
/// be reported on the same ack instead of the caller being told
/// `MigrationAccepted` and then silently getting nothing.
///
/// Also takes `keys` already fetched by `handle_connection` (the same
/// `list_keys` snapshot it used to compute `entries_to_send_count`),
/// rather than fetching its own — see `entries_to_send_count`'s comment
/// on why one snapshot is now shared instead of each side cloning the
/// whole cache independently. `None` here means the cache task was
/// already unavailable when `handle_connection` took the snapshot. Only
/// ever the key of each candidate entry (never a value or TTL, see
/// `Cache::keys`'s doc comment): this loop re-peeks the live value/TTL
/// for every key it actually sends, below.
#[allow(clippy::too_many_arguments)]
async fn run_migration(
    node_context: NodeContext,
    joining_name: String,
    joining_addr: String,
    // Issue #295: the joiner's own membership token (`Command::Migrate::
    // joining_token`) — presented on every `U`/`u` this node sends the
    // joiner below, so it can tell this handoff apart from a forged
    // shared-secret frame (see `Command::HandoffSet::token`).
    joining_token: String,
    // Tenth-pass audit (2026-09-02), issue #421(c): the dispatching
    // `PendingJoin`'s generation (`Command::Migrate::generation`),
    // echoed unchanged in this handoff's own `C` report — see
    // `report_complete`/`complete_message`.
    generation: Option<u64>,
    replication: usize,
    before_ring: HashRing,
    after_ring: Arc<HashRing>,
    migration_guard: MigrationGuard,
    keys: Option<Vec<Key>>,
) {
    println!("INFO migration started: handoff to {joining_name} at {joining_addr}");

    let keys = match keys {
        Some(keys) => keys,
        None => {
            eprintln!("WARN migration to {joining_name} aborted: cache task is unavailable");
            return;
        }
    };

    // Issue #266: a re-replication from an earlier ring change may still
    // be delivering a copy this migration is about to mark dead (see
    // `wait_for_rereplication_to_clear`'s own doc comment) — wait for it
    // to clear before this handoff starts moving/marking anything.
    wait_for_rereplication_to_clear(&node_context, &migration_guard.abort_requested).await;

    let mut marked_this_run = Vec::new();
    let mut sent_count = 0usize;
    let mut stream: Option<ClientStream> = None;

    let self_name = node_context.name.as_str();

    // `keys` arrive grouped by namespace, and a namespace can be ~1 MiB:
    // hash each distinct one once rather than per key.
    let mut hasher = KeyHasher::default();

    for key in keys {
        if migration_guard.abort_requested.load(Ordering::SeqCst) {
            break;
        }

        let key_hash = hasher.hash(&key);

        // A key is affected only if the joiner cracks its top-R (HRW
        // insertion can't change the set any other way).
        if !after_ring.is_owner_hashed(key_hash, &joining_name, replication) {
            continue;
        }

        // Issue #266: every old owner that holds this key sends it — see
        // this function's own doc comment for why electing just one
        // ("the old primary") is no longer safe. A key this node was
        // never an old owner of is neither this node's to send nor to
        // mark: skip it outright.
        if !before_ring.is_owner_hashed(key_hash, self_name, replication) {
            continue;
        }
        // The (at most one) node the joiner displaced from rank R: its
        // copy is dead once the join completes — marked for the sweep
        // below, but only once this node's own send actually succeeds.
        let displaced = !after_ring.is_owner_hashed(key_hash, self_name, replication);

        // Re-checked live rather than trusting `entries()`'s snapshot: a
        // concurrent client write racing this key's turn (see
        // `handle_connection`'s own forwarding of `S`/`D` for a key this
        // migration is moving) must win over whatever was true when the
        // snapshot was taken, or its update would ship stale to the
        // joining node. If the key is gone by now (deleted, expired, or
        // already forwarded-and-since-removed), there's nothing to send —
        // `handle_connection`'s own delete-forwarding path (or nothing
        // ever existing to send in the first place) already covers it.
        // Issue #106: a clear that arrived since the last key went out
        // is replayed on this same stream *before* the next key, so the
        // joiner applies them in the order this node did. (A clear that
        // races this key's peek is caught by the next iteration's drain,
        // which then lands after the stale key and wipes it.)
        if !drain_pending_clears(&node_context, &joining_addr, &mut stream).await {
            // One round trip for the lot: one per key kept the migration slot
            // occupied for the whole restore.
            let restore: Vec<Key> = marked_this_run
                .into_iter()
                .chain(migration_guard.take_join_marks())
                .collect();
            unmark_migrated_many(&node_context.request_tx, restore).await;

            return;
        }

        // Issue #970: a copy an earlier join took away (dead, awaiting
        // the sweep) is not handed to this joiner — the owners have the
        // live state. The slot is this run's own, so no mark is held.
        let Some((_, value, ttl)) =
            peek_entry_for_handoff(&node_context.request_tx, &key, true).await
        else {
            continue;
        };

        #[cfg(test)]
        node_context.gates.transfer.wait().await;
        let sent = transfer_with_retries(
            &node_context,
            &joining_addr,
            &mut stream,
            ForwardedWrite::HandoffSet {
                key: &key,
                value: &value,
                ttl,
                if_absent: true,
                token: &joining_token,
            },
        )
        .await;

        if !sent {
            // One round trip for the lot: one per key kept the migration slot
            // occupied for the whole restore.
            let restore: Vec<Key> = marked_this_run
                .into_iter()
                .chain(migration_guard.take_join_marks())
                .collect();
            unmark_migrated_many(&node_context.request_tx, restore).await;

            return;
        }

        sent_count += 1;

        // A sender that stays in the key's top-R keeps its copy (it's
        // still a live replica, client-side replication); only a displaced copy is dead.
        if displaced {
            mark_migrated(&node_context.request_tx, &key).await;
            marked_this_run.push(key);
        }
    }

    if migration_guard.abort_requested.load(Ordering::SeqCst) {
        // One round trip for the lot: one per key kept the migration slot
        // occupied for the whole restore.
        let restore: Vec<Key> = marked_this_run
            .into_iter()
            .chain(migration_guard.take_join_marks())
            .collect();
        unmark_migrated_many(&node_context.request_tx, restore).await;

        eprintln!("WARN migration to {joining_addr} cancelled by discovery; rolled back its marks");

        return;
    }

    // From here on, this node considers the post-join top-R authoritative
    // for every key — see `NodeContext::known_ring`. The value it replaces
    // is snapshotted into the slot (issue #93) so the abandon path can put
    // it back if this join never becomes real cluster-wide.
    let pre_completion_ring = {
        let mut guard = node_context
            .known_ring
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        guard.replace(Arc::new(Membership {
            // Cloned, not moved: this function's own join-flip
            // re-replication trigger (issue #266, below) needs
            // `after_ring` again once the migration is done.
            ring: Arc::clone(&after_ring),
            replication,
        }))
    };

    println!(
        "INFO migration completed: {joining_name} (sent {sent_count} keys, marked {} dead \
         copies, kept until discovery confirms the join; forwarding writes for {}s)",
        marked_this_run.len(),
        forwarding_grace(sent_count).as_secs()
    );

    // Keep the write-forwarding window open past this node's own share
    // (issue #3) — see `MigrationGuard::completed`. Stamped BEFORE `C`
    // goes out (issue #62): discovery may start the next join the moment
    // this `C` lands and have its `M` here before this task gets past the
    // ack read — a slot still reading as in-flight would reject it.
    // Issue #106: whatever clears queued up after the last key's drain
    // go out before the slot flips to "completed" ...
    if !drain_pending_clears(&node_context, &joining_addr, &mut stream).await {
        // One round trip for the lot: one per key kept the migration slot
        // occupied for the whole restore.
        let restore: Vec<Key> = marked_this_run
            .into_iter()
            .chain(migration_guard.take_join_marks())
            .collect();
        unmark_migrated_many(&node_context.request_tx, restore).await;

        return;
    }

    // Cloned, not moved: this function's own join-flip re-replication
    // trigger (issue #266, below) needs `pre_completion_ring` again too.
    migration_guard.completed(sent_count, marked_this_run, pre_completion_ring.clone());

    // ... and one more drain after the stamp catches a clear that slipped
    // in between: `route_clear` queues only while `completed_at` is
    // `None`, under the same lock `completed()` stamps it, so anything
    // not in this drain was forwarded on the shared connection instead.
    // Too late to abandon the join here (it is already completed on this
    // node); a permanent failure is logged like a failed forward.
    if !drain_pending_clears(&node_context, &joining_addr, &mut stream).await {
        eprintln!(
            "WARN migration to {joining_addr} completed but a clear that raced its completion \
             could not be replayed on the joining node"
        );
    }

    if let Err(error) = report_complete(&node_context, &joining_name, generation).await {
        eprintln!(
            "WARN migration to {joining_addr} finished but reporting completion to {} failed: {error}",
            node_context.discovery_addr
        );
    }

    // Issue #266: the flip above may have silently absorbed an eviction
    // this node's own `known_ring` hadn't caught up to yet — a
    // restart+rejoin can outrace this node's next heartbeat ack, so
    // `before_ring` (computed from the `M` itself, which only ever
    // reflects discovery's *current*, already-post-eviction roster)
    // never saw it either. Left alone, that eviction's promotion would
    // never re-replicate: `known_ring` jumps straight from this node's
    // stale pre-eviction belief to the post-join ring, so the next
    // heartbeat ack matches it exactly and `adopt_membership` reports no
    // change. Compare this node's own *last* belief (`pre_completion_ring`,
    // which may still list the dead member) against the post-join ring
    // instead, and trigger the same re-replication an eviction would
    // have if it dropped one. Deliberately after `report_complete`
    // above: this must never delay the `C` report, and by this point the
    // migration is unambiguously done.
    //
    // Issue #295: `run_rereplication` needs a membership token per target
    // it may send `U`/`u` to (see `Command::HandoffSet::token`), and the
    // `M` that started this handoff only ever carries the *joiner's* own
    // token (`joining_token`) — a target that turns out to be one of the
    // OTHER `joined` members is a real, expected outcome here (this
    // trigger fires because THIS node's own belief was stale, so the
    // promoted owner for a given key is just as likely to be an existing
    // member as the joiner). So, unlike the old "reuse what `M` already
    // carried" shortcut, this now pays for the same `fetch_roster_once`
    // (issue #295: self-authenticated, tokens included) fetch
    // `spawn_or_supersede_rereplication` does — a failure here just skips
    // this trigger (logged), same as that function's own failure
    // handling: the next ring-changing event retries.
    if let Some(previous_membership) = pre_completion_ring {
        let previous_ring = Arc::clone(&previous_membership.ring);
        if ring_dropped_a_member(&previous_ring, &after_ring) {
            let (addresses, tokens): (HashMap<String, String>, HashMap<String, String>) =
                match timeout(
                    OUTBOUND_IO_TIMEOUT,
                    fetch_roster_once(&node_context, &node_context.discovery_addr),
                )
                .await
                {
                    Ok(Ok((members, _replication))) => members
                        .into_iter()
                        .map(|(name, addr, token)| ((name.clone(), addr), (name, token)))
                        .unzip(),
                    Ok(Err(error)) => {
                        eprintln!(
                            "WARN re-replication: fetching the roster with addresses for the \
                             join-flip trigger failed: {error} — giving up; a later ring \
                             change will retrigger it if the cluster is still \
                             under-replicated"
                        );
                        return;
                    }
                    Err(_) => {
                        eprintln!(
                            "WARN re-replication: fetching the roster with addresses for the \
                             join-flip trigger timed out — giving up; a later ring change will \
                             retrigger it if the cluster is still under-replicated"
                        );
                        return;
                    }
                };
            let task: RereplicationTask = Box::pin(run_superseding_rereplication(
                node_context.clone(),
                previous_ring,
                Arc::clone(&after_ring),
                replication,
                addresses,
                tokens,
                node_context.shutdown_rx.clone(),
            ));
            if node_context.rereplication_tx.send(task).await.is_err() {
                eprintln!(
                    "WARN re-replication: could not queue the join-flip task (shutting down); \
                     a later ring change will retrigger it if the cluster is still \
                     under-replicated"
                );
            }
        }
    }
}

/// `run_migration`'s per-item retry loop, shared by key transfers and
/// replayed clears (issue #106): up to `KEY_TRANSFER_ATTEMPTS` attempts,
/// reconnecting `stream` after a failure since its state is then
/// unknown (e.g. a partial write) — the next attempt must not risk a
/// desynced stream. Returns whether the item was delivered; on `false`
/// the caller abandons the join for discovery's migration-timeout to
/// reap, after rolling back its marks.
async fn transfer_with_retries(
    node_context: &NodeContext,
    joining_addr: &str,
    stream: &mut Option<ClientStream>,
    write: ForwardedWrite<'_>,
) -> bool {
    let what = match &write {
        ForwardedWrite::Set { .. }
        | ForwardedWrite::Delete { .. }
        | ForwardedWrite::HandoffSet { .. }
        | ForwardedWrite::HandoffDelete { .. } => "a key",
        ForwardedWrite::Clear { .. } => "a clear",
    };

    for attempt in 1..=KEY_TRANSFER_ATTEMPTS {
        if stream.is_none() {
            match connect_and_authenticate(node_context, joining_addr, AuthPeer::Node).await {
                Ok(connected) => *stream = Some(connected),
                Err(error) => {
                    eprintln!(
                        "WARN migration to {joining_addr} failed to connect \
                         (attempt {attempt}/{KEY_TRANSFER_ATTEMPTS}): {error}"
                    );
                    continue;
                }
            }
        }

        let active_stream = match stream.as_mut() {
            Some(active_stream) => active_stream,
            None => continue,
        };

        let result = match &write {
            // `send_set` carries its own `OUTBOUND_IO_TIMEOUT`.
            ForwardedWrite::Set { key, value, ttl } => {
                send_set(active_stream, key, value, *ttl).await
            }
            ForwardedWrite::Delete { key } => timeout(
                OUTBOUND_IO_TIMEOUT,
                ForwardedWrite::Delete { key }.send(active_stream),
            )
            .await
            .unwrap_or_else(|_| {
                Err(io::Error::new(
                    io::ErrorKind::TimedOut,
                    "outbound delete timed out",
                ))
            }),
            ForwardedWrite::Clear { scope, token } => timeout(
                OUTBOUND_IO_TIMEOUT,
                ForwardedWrite::Clear { scope, token }.send(active_stream),
            )
            .await
            .unwrap_or_else(|_| {
                Err(io::Error::new(
                    io::ErrorKind::TimedOut,
                    "outbound clear timed out",
                ))
            }),
            // Issue #266: `run_migration`'s own bulk transfer carries
            // this too now (`if_absent: true`), alongside the
            // decommission's leave-forwards (`if_absent: false`, which go
            // through `forward_on_shared_connection` instead of this
            // function — this arm exists for exhaustiveness on that
            // side).
            ForwardedWrite::HandoffSet {
                key,
                value,
                ttl,
                if_absent,
                token,
            } => timeout(
                OUTBOUND_IO_TIMEOUT,
                ForwardedWrite::HandoffSet {
                    key,
                    value,
                    ttl: *ttl,
                    if_absent: *if_absent,
                    token,
                }
                .send(active_stream),
            )
            .await
            .unwrap_or_else(|_| {
                Err(io::Error::new(
                    io::ErrorKind::TimedOut,
                    "outbound handoff set timed out",
                ))
            }),
            ForwardedWrite::HandoffDelete { key, token } => timeout(
                OUTBOUND_IO_TIMEOUT,
                ForwardedWrite::HandoffDelete { key, token }.send(active_stream),
            )
            .await
            .unwrap_or_else(|_| {
                Err(io::Error::new(
                    io::ErrorKind::TimedOut,
                    "outbound handoff delete timed out",
                ))
            }),
        };

        match result {
            Ok(()) => return true,
            Err(error) => {
                eprintln!(
                    "WARN migration to {joining_addr} failed to transfer {what} \
                     (attempt {attempt}/{KEY_TRANSFER_ATTEMPTS}): {error}"
                );
                *stream = None;
            }
        }
    }

    eprintln!(
        "WARN migration to {joining_addr} permanently failed to transfer {what} after \
         {KEY_TRANSFER_ATTEMPTS} attempts; abandoning the join for discovery's \
         migration-timeout to reap"
    );

    false
}

/// Issue #106: takes every clear queued on the slot since the last call
/// (`ActiveMigration::pending_clears`) and replays it on the transfer
/// stream, in arrival order. `false` if one could not be delivered.
async fn drain_pending_clears(
    node_context: &NodeContext,
    joining_addr: &str,
    stream: &mut Option<ClientStream>,
) -> bool {
    let (pending, joining_token) = {
        let mut slot = node_context
            .active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match slot.as_mut() {
            Some(active) => (active.pending_clears.take(), active.joining_token.clone()),
            None => (Vec::new(), String::new()),
        }
    };

    for scope in &pending {
        if !transfer_with_retries(
            node_context,
            joining_addr,
            stream,
            ForwardedWrite::Clear {
                scope,
                token: &joining_token,
            },
        )
        .await
        {
            return false;
        }
    }

    true
}

/// Issue #124: the whole decommission, run on SIGTERM (see `run`'s
/// signal arm). Self-contained by design: removing one node from an HRW
/// ranking can only promote the previous rank-R+1 node into each key's
/// top-R, so the leaver alone can compute every key's single new owner
/// and hand the entry over — the surviving owners already hold theirs.
/// Sequence:
///
/// 1. Ask any in-flight join handoff to abort (its marks roll back;
///    discovery retries the join after this node is gone) and wait
///    briefly for the slot to clear.
/// 2. Fetch the roster (`L`) — names AND addresses; `known_ring` holds
///    only names — and install `LeaveState`, which (a) starts
///    forwarding concurrent writes to each key's entrant and (b) makes
///    the `M` handler reject new joins.
/// 3. Transfer: for every held key this node owns, re-peek the live
///    value and send it to the key's entrant via `U` (the handoff
///    store: the receiver isn't the owner *yet*, so a plain `S` would
///    be answered `W`).
/// 4. Tell every discovery replica this node is leaving (`V`): the
///    post-leave roster publishes, clients' `W`-refresh routes them to
///    the entrants — which now hold the data.
/// 5. A short forwarding grace (bounded by what's left of the drain
///    budget), then return; the caller runs the ordinary shutdown.
///
/// The whole run is budgeted by `--drain-timeout`: if the budget runs
/// out mid-transfer this logs what was left behind and still sends `V`
/// (the process is exiting either way; clean membership beats a
/// liveness-timeout ghost), degrading to today's crash semantics for
/// the untransferred remainder.
///
/// Issue #357 — a documented tradeoff, not a defect: the ring pair from
/// step 2 is one roster snapshot, never recomputed, and nothing tells a
/// survivor's `run_rereplication` that a draining node intends to
/// leave. Two membership changes landing inside one drain window — most
/// plausibly two nodes scaled in at once, or an eviction while a third
/// drains — can therefore leave keys transiently below R: each leaver
/// picks entrants from a roster that still lists the other, so a key
/// whose top-R contained both comes out of the double-leave with one
/// handoff nobody performed (and at R=1, a handoff chained through the
/// other leaver can be dropped outright — the recipient's own snapshot
/// predates this node's `V`, so it classifies the key `NotOwned`).
/// Accepted because the failure mode is bounded by cache semantics:
/// a put-if-absent handoff never overwrites a newer value the receiver
/// already holds, reads keep landing on the surviving copies via
/// `W`-refresh, and a key that does lose its last copy is a miss. (It
/// carries no version, though: when two survivors hold different
/// copies and both re-replicate, the first to arrive is kept — issue
/// #563.) There is no full
/// anti-entropy: the gap closes per key as a later ring change re-ranks
/// it, a client rewrites it, or its TTL turns it over. Operators avoid
/// the window entirely by scaling in one node at a time — see
/// docs/deployment.html ("Node: decommission").
/// Issue #233: how `run_decommission`'s transfer loop disposes of one key
/// — extracted so the deadline-vs-ownership ordering has a unit test that
/// doesn't need a full network harness. A key this node never owned is
/// never this node's handoff to miss, so it must be filtered out *before*
/// the deadline check, not after — otherwise a drain that overruns its
/// budget inflates `left_behind` with keys that were always someone
/// else's responsibility.
#[derive(Debug, PartialEq, Eq)]
enum DecommissionKeyOutcome {
    NotOwned,
    DeadlinePassed,
    Owned,
}

fn classify_decommission_key(
    key_hash: KeyHash,
    before_ring: &HashRing,
    self_name: &str,
    replication: usize,
    deadline_passed: bool,
) -> DecommissionKeyOutcome {
    if !before_ring.is_owner_hashed(key_hash, self_name, replication) {
        return DecommissionKeyOutcome::NotOwned;
    }
    if deadline_passed {
        return DecommissionKeyOutcome::DeadlinePassed;
    }
    DecommissionKeyOutcome::Owned
}

/// Resolves once `shutdown_rx` reads `true`, including when it already
/// does. Never resolves if the sender is gone: a bare `changed()` on a
/// dropped sender resolves immediately, which in the `select!`s of
/// `run_decommission` would turn "no override will ever come" into
/// "override now" and abandon a perfectly healthy handoff.
async fn shutdown_requested(shutdown_rx: &mut watch::Receiver<bool>) {
    if shutdown_rx.wait_for(|requested| *requested).await.is_err() {
        std::future::pending::<()>().await;
    }
}

async fn run_decommission(
    node_context: NodeContext,
    discovery_addrs: Vec<String>,
    drain_budget: Duration,
) {
    let deadline = Instant::now() + drain_budget;
    // Tenth-pass audit (2026-09-02), issue #407 follow-up: this node's own
    // shutdown signal, so the operator-override path (a second Ctrl-C/
    // SIGTERM while draining) can actually cut this run short instead of
    // running out `drain_budget` regardless — see the loops below and the
    // caller in `run`, which now keeps this task's `JoinHandle` and awaits
    // (then aborts) it on override rather than discarding it.
    let mut shutdown_rx = node_context.shutdown_rx.clone();

    // 1. No new joins (the flag isn't set yet, so flip abort first) and
    // wind down the active one.
    if let Some(active) = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
    {
        active.abort_requested.store(true, Ordering::SeqCst);
    }
    // Issue #407: tied to `deadline` (this whole decommission's own
    // `drain_budget`), not a fixed iteration count unrelated to it — a
    // bare `0..50` (a fixed 5s) could cut this wait short well before a
    // generous drain budget elapses, capping it far below what the
    // operator actually asked for. Named/logged like the sibling waits,
    // `wait_for_rereplication_to_clear`/`wait_for_migration_to_clear`,
    // whose own comments point at this exact `completed_at.is_none()`
    // check.
    //
    // Tenth-pass audit (2026-09-02): two follow-up fixes to the above.
    // (a) Issue #422 precedent: `wait_for_migration_to_clear` treats the
    // occupying migration's own `abort_requested` as "not really busy"
    // once it's set, because `run_migration` is already on its way to
    // unwinding and clearing the slot — the same is true here, and more
    // so, since the `store(true, ..)` immediately above is what set it:
    // this wait's job is to give that unwind a moment to land, not to
    // babysit a migration this same function just told to stop. (b) Even
    // so, bound the wait to a fraction of `drain_budget` rather than the
    // whole thing — a migration that ignores `abort_requested` (stuck on
    // an unresponsive peer, say) must not be able to consume the entire
    // budget here and leave nothing for the actual handoff below, which
    // is the part `classify_decommission_key`'s `DeadlinePassed` check
    // exists to protect.
    let migration_wait_budget = (drain_budget / 4).min(Duration::from_secs(5));
    let migration_wait_deadline = Instant::now() + migration_wait_budget;
    let mut overridden = false;
    loop {
        let busy = node_context
            .active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .as_ref()
            .is_some_and(|active| {
                active.completed_at.is_none() && !active.abort_requested.load(Ordering::SeqCst)
            });
        if !busy {
            break;
        }
        if Instant::now() >= migration_wait_deadline {
            eprintln!(
                "WARN decommission: an in-flight join migration was still active after the \
                 capped wait ({}s, out of a {}s drain budget) elapsed; proceeding with the \
                 handoff anyway",
                migration_wait_budget.as_secs(),
                drain_budget.as_secs()
            );
            break;
        }
        tokio::select! {
            _ = sleep(Duration::from_millis(100)) => {}
            _ = shutdown_rx.changed() => {
                if *shutdown_rx.borrow() {
                    overridden = true;
                }
                break;
            }
        }
    }

    if overridden {
        println!(
            "INFO decommission: second shutdown signal received during the join-migration \
             wait — leaving without a handoff"
        );
        send_leave(&node_context, &discovery_addrs).await;
        return;
    }

    // 2. Roster with addresses.
    // Tenth-pass follow-up (2026-09-04): every await below that can sit
    // in network I/O for up to `OUTBOUND_IO_TIMEOUT` — this roster fetch,
    // and the connect/handoff pair per attempt in the transfer loop — is
    // raced against the override signal. `run`'s
    // `DECOMMISSION_OVERRIDE_GRACE` (2s) is far shorter than those I/O
    // bounds, so without the race an override landing mid-I/O would abort
    // this task before `send_leave` ever ran — membership left dangling
    // until the peer's liveness timeout, the very thing the override
    // path's clean-leave promise exists to avoid.
    let fetched = tokio::select! {
        biased;
        _ = shutdown_requested(&mut shutdown_rx) => None,
        result = fetch_roster_for_leave(&node_context, &discovery_addrs) => Some(result),
    };
    let roster = match fetched {
        None => {
            eprintln!(
                "WARN decommission: shutdown override while fetching the roster; leaving \
                 without a handoff"
            );
            send_leave(&node_context, &discovery_addrs).await;
            return;
        }
        Some(Ok(roster)) => roster,
        Some(Err(error)) => {
            eprintln!(
                "WARN decommission: fetching the roster failed ({error}); leaving without a \
                 handoff"
            );
            send_leave(&node_context, &discovery_addrs).await;
            return;
        }
    };
    let (members, replication) = roster;
    let self_name = node_context.name.clone();
    if !members.iter().any(|(name, _, _)| *name == self_name) {
        // Not a member (already expired, or never joined): nothing to
        // hand off.
        send_leave(&node_context, &discovery_addrs).await;
        return;
    }
    let survivors: Vec<(String, String, String)> = members
        .iter()
        .filter(|(name, _, _)| *name != self_name)
        .cloned()
        .collect();
    if survivors.is_empty() {
        println!("INFO decommission: last member — nothing to hand off");
        send_leave(&node_context, &discovery_addrs).await;
        return;
    }

    let before_ring = Arc::new(HashRing::new(
        members.iter().map(|(name, _, _)| name.clone()).collect(),
    ));
    let after_ring = Arc::new(HashRing::new(
        survivors.iter().map(|(name, _, _)| name.clone()).collect(),
    ));
    let addresses: HashMap<String, String> = members
        .iter()
        .map(|(name, addr, _)| (name.clone(), addr.clone()))
        .collect();
    // Issue #295: name -> membership token, one per entrant `leave_target_for`
    // may need to authorize a `U`/`u` to — see `Command::HandoffSet::token`.
    let tokens: HashMap<String, String> = members
        .iter()
        .map(|(name, _, token)| (name.clone(), token.clone()))
        .collect();

    *node_context
        .leaving
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(LeaveState {
        before_ring: Arc::clone(&before_ring),
        after_ring: Arc::clone(&after_ring),
        replication,
        addresses: addresses.clone(),
        tokens: tokens.clone(),
        connections: Mutex::new(HashMap::new()),
    });

    // 3. Transfer.
    let Some(keys) = list_keys(&node_context.request_tx).await else {
        eprintln!("WARN decommission: cache task unavailable; leaving without a handoff");
        send_leave(&node_context, &discovery_addrs).await;
        return;
    };
    // Issue #970: dead copies stay out of this handoff unless their marks are still held.
    let skip_dead = marks_released(&node_context.active_migration);
    let mut streams: HashMap<String, ClientStream> = HashMap::new();
    let mut sent = 0usize;
    let mut left_behind = 0usize;

    // Tenth-pass audit (2026-09-02): consumed by hand (not a `for` over
    // `keys` directly) so that on a shutdown override mid-transfer the
    // remaining, still-owned keys can be folded into `left_behind` — the
    // same accounting a key whose deadline had already passed gets below
    // — instead of just vanishing from both counters.
    let mut keys_iter = keys.into_iter();
    // `keys` arrive grouped by namespace, and a namespace can be ~1 MiB:
    // hash each distinct one once rather than per key.
    let mut hasher = KeyHasher::default();
    while let Some(key) = keys_iter.next() {
        if *shutdown_rx.borrow() {
            println!(
                "INFO decommission: second shutdown signal received during key transfer — \
                 stopping early"
            );
            let mut hasher = KeyHasher::default();
            left_behind += std::iter::once(key)
                .chain(keys_iter)
                .filter(|key| {
                    before_ring.is_owner_hashed(hasher.hash(key), &self_name, replication)
                })
                .count();
            break;
        }
        let key_hash = hasher.hash(&key);
        match classify_decommission_key(
            key_hash,
            &before_ring,
            &self_name,
            replication,
            Instant::now() >= deadline,
        ) {
            DecommissionKeyOutcome::NotOwned => continue,
            DecommissionKeyOutcome::DeadlinePassed => {
                left_behind += 1;
                continue;
            }
            DecommissionKeyOutcome::Owned => {}
        }
        let Some(entrant) = after_ring
            .owners_hashed(key_hash, replication)
            .into_iter()
            .find(|owner| !before_ring.is_owner_hashed(key_hash, owner, replication))
            .map(str::to_string)
        else {
            continue;
        };
        let Some(addr) = addresses.get(&entrant) else {
            continue;
        };
        let Some(entrant_token) = tokens.get(&entrant) else {
            continue;
        };

        // Live re-peek, same reasoning as the join transfer: a client
        // write racing this key's turn must win.
        let Some((_, value, ttl)) =
            peek_entry_for_handoff(&node_context.request_tx, &key, skip_dead).await
        else {
            continue;
        };

        let mut delivered = false;
        let mut overridden = false;
        for attempt in 0..KEY_TRANSFER_ATTEMPTS {
            let mut connected = streams.contains_key(addr);
            if !connected {
                // See the roster fetch above for why this (and the
                // handoff send below) is raced against the override.
                let outcome = tokio::select! {
                    biased;
                    _ = shutdown_requested(&mut shutdown_rx) => None,
                    result = connect_and_authenticate(&node_context, addr, AuthPeer::Node) => {
                        Some(result)
                    }
                };
                match outcome {
                    None => {
                        overridden = true;
                        break;
                    }
                    Some(Ok(stream)) => {
                        streams.insert(addr.clone(), stream);
                        connected = true;
                    }
                    Some(Err(error)) => {
                        eprintln!("WARN decommission: connecting to {addr} failed: {error}");
                    }
                }
            }
            if connected && let Some(stream) = streams.get_mut(addr) {
                let outcome = tokio::select! {
                    biased;
                    _ = shutdown_requested(&mut shutdown_rx) => None,
                    result = send_handoff_set(stream, &key, &value, ttl, false, entrant_token) => {
                        Some(result)
                    }
                };
                match outcome {
                    None => {
                        overridden = true;
                        break;
                    }
                    Some(Ok(())) => {
                        delivered = true;
                    }
                    Some(Err(error)) => {
                        eprintln!("WARN decommission: transfer to {addr} failed: {error}");
                        streams.remove(addr);
                    }
                }
            }
            if delivered {
                break;
            }
            // Tenth-pass audit (2026-09-02): a short, linearly increasing
            // backoff before the next attempt — without it a target
            // fast-failing (e.g. ECONNREFUSED) gets hit `KEY_TRANSFER_ATTEMPTS`
            // times back-to-back. Skipped after the last attempt (nothing
            // waits on it), and itself interruptible by a shutdown
            // override so it can't eat into that path's "return promptly"
            // promise either.
            if attempt + 1 < KEY_TRANSFER_ATTEMPTS {
                tokio::select! {
                    _ = sleep(Duration::from_millis(100 * u64::from(attempt + 1))) => {}
                    _ = shutdown_rx.changed() => {}
                }
            }
        }
        if overridden {
            // Same accounting as the top-of-loop check: this key and every
            // still-owned one after it are left behind.
            println!(
                "INFO decommission: second shutdown signal received mid-handoff — stopping \
                 early"
            );
            let mut hasher = KeyHasher::default();
            left_behind += std::iter::once(key)
                .chain(keys_iter)
                .filter(|key| {
                    before_ring.is_owner_hashed(hasher.hash(key), &self_name, replication)
                })
                .count();
            break;
        }
        if delivered {
            sent += 1;
        } else {
            left_behind += 1;
        }
    }

    if left_behind > 0 {
        eprintln!(
            "WARN decommission: {left_behind} entr(ies) could not be handed off within the \
             drain budget — the surviving replicas (R={replication}) are their only copies now"
        );
    }
    println!("INFO decommission: handed off {sent} entr(ies)");

    // 4. Leave.
    send_leave(&node_context, &discovery_addrs).await;

    // 5. Grace: keep forwarding concurrent writes while clients refresh
    // onto the post-leave roster.
    let grace = forwarding_grace(sent).min(deadline.saturating_duration_since(Instant::now()));
    println!(
        "INFO decommission: forwarding window open for {}s",
        grace.as_secs()
    );
    // Tenth-pass audit (2026-09-02): interruptible by a shutdown override
    // too — membership is already given up by this point (`send_leave`
    // above), so there's nothing left for a second signal to do but cut
    // this grace window short.
    // `shutdown_requested` rather than `changed()`: the races above mark
    // the flipped value as seen, after which `changed()` would never fire
    // again and an already-overridden run would sit out this whole window.
    tokio::select! {
        biased;
        _ = shutdown_requested(&mut shutdown_rx) => {
            println!(
                "INFO decommission: second shutdown signal received during the forwarding \
                 window — closing it early"
            );
        }
        _ = sleep(grace) => {}
    }
}

/// `V <name-len> <token-len>` to every discovery replica — membership
/// removal is immediate on each replica that hears it (they don't
/// gossip); one refusing/unreachable replica only means that replica
/// serves this node until its liveness timeout.
async fn send_leave(node_context: &NodeContext, discovery_addrs: &[String]) {
    for addr in discovery_addrs {
        let result = timeout(OUTBOUND_IO_TIMEOUT, async {
            let mut stream =
                connect_and_authenticate(node_context, addr, AuthPeer::Discovery).await?;
            let mut frame = format!(
                "V {} {}\n",
                node_context.name.len(),
                node_context.token.len()
            )
            .into_bytes();
            frame.extend_from_slice(node_context.name.as_bytes());
            frame.extend_from_slice(node_context.token.as_bytes());
            stream.write_all(&frame).await?;
            let mut ack = [0u8; 2];
            stream.read_exact(&mut ack).await?;
            if &ack != b"R\n" {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "discovery did not acknowledge the leave",
                ));
            }
            io::Result::Ok(())
        })
        .await
        .unwrap_or_else(|_| Err(io::Error::new(io::ErrorKind::TimedOut, "leave timed out")));

        if let Err(error) = result {
            eprintln!("WARN decommission: leave notification to {addr} failed: {error}");
        }
    }
}

/// The `U` frame (issue #124) — `set_message`'s shape with the handoff
/// letter and the namespace length always present. `if_absent` (issue
/// #266) appends the trailing `A` token that asks the receiver for
/// put-if-absent semantics instead of an unconditional overwrite — set by
/// re-replication after an eviction, never by an ordinary decommission
/// handoff (`send_handoff_set`'s callers pass `false`).
///
/// Issue #295: `token` is the receiving node's own membership token (see
/// `Command::HandoffSet::token`) — carried as `<token-len>` in the header
/// and leads the body (before `namespace`/`key`/`value`), same ordering
/// as `X`'s `<token><joining_name>`, so the receiver can verify it before
/// touching anything else.
fn handoff_message(
    key: &Key,
    value: &[u8],
    ttl: Option<Duration>,
    if_absent: bool,
    token: &str,
) -> Vec<u8> {
    trace!(
        &key.name,
        "send_U key={} ttl={:?} if_absent={} token={}",
        crate::trace::name(&key.name),
        ttl.map(|t| t.as_secs()),
        if_absent,
        &token[..token.len().min(8)]
    );
    let mut header = format!(
        "U {} {} {} {}",
        key.namespace.len(),
        key.name.len(),
        value.len(),
        token.len()
    );
    if let Some(ttl) = ttl {
        header.push_str(&format!(" {}", ttl_wire_seconds(ttl)));
    }
    if if_absent {
        header.push_str(" A");
    }
    header.push('\n');
    let mut message = header.into_bytes();
    message.extend_from_slice(token.as_bytes());
    message.extend_from_slice(&key.namespace);
    message.extend_from_slice(&key.name);
    message.extend_from_slice(value);
    message
}

/// The `u` frame (issue #124) — `delete_message`'s namespaced shape with
/// the handoff letter, mirroring `handoff_message` for `U`, including its
/// issue #295 `token` field and body ordering.
fn handoff_delete_message(key: &Key, token: &str) -> Vec<u8> {
    trace!(
        &key.name,
        "send_u key={} token={}",
        crate::trace::name(&key.name),
        &token[..token.len().min(8)]
    );
    let mut message = format!(
        "u {} {} {}\n",
        key.namespace.len(),
        key.name.len(),
        token.len()
    )
    .into_bytes();
    message.extend_from_slice(token.as_bytes());
    message.extend_from_slice(&key.namespace);
    message.extend_from_slice(&key.name);
    message
}

async fn send_handoff_set(
    stream: &mut ClientStream,
    key: &Key,
    value: &[u8],
    ttl: Option<Duration>,
    if_absent: bool,
    token: &str,
) -> io::Result<()> {
    timeout(OUTBOUND_IO_TIMEOUT, async {
        stream
            .write_all(&handoff_message(key, value, ttl, if_absent, token))
            .await?;
        let mut ack = [0u8; 2];
        stream.read_exact(&mut ack).await?;
        if &ack != b"S\n" {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "peer did not acknowledge the handed-off entry",
            ));
        }
        io::Result::Ok(())
    })
    .await
    .map_err(|_| io::Error::new(io::ErrorKind::TimedOut, "handoff transfer timed out"))?
}

/// Issue #124: a roster-with-addresses fetch for the decommission —
/// `known_ring` holds names only, and the drain needs addresses to dial
/// entrants. Issue #295: also needs every survivor's own membership
/// token, to authorize the `U`/`u` frames the drain sends them (see
/// `Command::HandoffSet::token`) — `fetch_roster_once` carries both.
/// Bounded parse mirroring the SDKs'/harness's.
async fn fetch_roster_for_leave(
    node_context: &NodeContext,
    discovery_addrs: &[String],
) -> io::Result<(Vec<(String, String, String)>, usize)> {
    let mut last_error = io::Error::other("no discovery replicas configured");

    for addr in discovery_addrs {
        match timeout(OUTBOUND_IO_TIMEOUT, fetch_roster_once(node_context, addr)).await {
            Ok(Ok(roster)) => return Ok(roster),
            Ok(Err(error)) => last_error = error,
            Err(_) => {
                last_error = io::Error::new(
                    io::ErrorKind::TimedOut,
                    format!("T fetch from {addr} timed out"),
                )
            }
        }
    }

    Err(last_error)
}

/// Issue #295: `T <name-len> <token-len>\n<name><token>` — a
/// self-authenticated roster fetch, unlike the public, client-facing `L`
/// (which deliberately never carries tokens — see `NodeInfo::token`'s
/// doc comment in `nanocached-discovery`). This node presents its own
/// name+token (the same credential `H`/`C` already use) to prove to
/// discovery it's a genuinely registered node, not merely a
/// shared-secret-holding client; only then does discovery hand back every
/// registered node's address *and* token. The two callers
/// (`fetch_roster_for_leave`'s decommission drain, and
/// `spawn_or_supersede_rereplication`'s eviction-triggered re-replication)
/// both need those tokens to authorize the `U`/`u` frames they may send —
/// see `Command::HandoffSet::token`.
async fn fetch_roster_once(
    node_context: &NodeContext,
    addr: &str,
) -> io::Result<(Vec<(String, String, String)>, usize)> {
    const MAX_ROSTER_ENTRIES: usize = 4096;
    const MAX_NAME_ADDR_OR_TOKEN_LENGTH: usize = 1024;

    let stream = connect_and_authenticate(node_context, addr, AuthPeer::Discovery).await?;
    // Buffered so the bounded line reads below (`infra::read_line_bounded`)
    // and the fixed-size body `read_exact`s share one buffer: any bytes the
    // line read already buffered past a line's `\n` are still there for the
    // next read, exactly as `read_heartbeat_ack` relies on.
    let mut stream = tokio::io::BufReader::new(stream);
    let mut request = format!(
        "T {} {}\n",
        node_context.name.len(),
        node_context.token.len()
    )
    .into_bytes();
    request.extend_from_slice(node_context.name.as_bytes());
    request.extend_from_slice(node_context.token.as_bytes());
    stream.write_all(&request).await?;

    let bad = || io::Error::new(io::ErrorKind::InvalidData, "bad T response");

    let deadline = outbound_line_deadline();
    let mut line = Vec::new();
    infra::read_line_bounded(&mut stream, MAX_ROSTER_LINE_LEN, deadline, &mut line).await?;
    if line == b"B\n" {
        return Err(io::Error::new(
            io::ErrorKind::WouldBlock,
            "discovery is in its startup grace",
        ));
    }
    let header = line
        .strip_suffix(b"\n")
        .map(|rest| String::from_utf8_lossy(rest).into_owned())
        .ok_or_else(bad)?;
    let mut parts = header.strip_prefix("N ").ok_or_else(bad)?.split(' ');
    let count: usize = parts
        .next()
        .and_then(|part| part.parse().ok())
        .ok_or_else(bad)?;
    let replication: usize = parts
        .next()
        .and_then(|part| part.parse().ok())
        .ok_or_else(bad)?;
    if count > MAX_ROSTER_ENTRIES || replication == 0 {
        return Err(bad());
    }

    let mut members = Vec::with_capacity(count);
    for _ in 0..count {
        infra::read_line_bounded(&mut stream, MAX_ROSTER_LINE_LEN, deadline, &mut line).await?;
        let entry_header = line
            .strip_suffix(b"\n")
            .map(|rest| String::from_utf8_lossy(rest).into_owned())
            .ok_or_else(bad)?;
        let mut parts = entry_header.split(' ');
        let name_length: usize = parts
            .next()
            .and_then(|part| part.parse().ok())
            .ok_or_else(bad)?;
        let addr_length: usize = parts
            .next()
            .and_then(|part| part.parse().ok())
            .ok_or_else(bad)?;
        let token_length: usize = parts
            .next()
            .and_then(|part| part.parse().ok())
            .ok_or_else(bad)?;
        if name_length > MAX_NAME_ADDR_OR_TOKEN_LENGTH
            || addr_length > MAX_NAME_ADDR_OR_TOKEN_LENGTH
            || token_length > MAX_NAME_ADDR_OR_TOKEN_LENGTH
        {
            return Err(bad());
        }
        // Body + trailing newline.
        let mut body = vec![0u8; name_length + addr_length + token_length + 1];
        stream.read_exact(&mut body).await?;
        members.push((
            String::from_utf8_lossy(&body[..name_length]).into_owned(),
            String::from_utf8_lossy(&body[name_length..name_length + addr_length]).into_owned(),
            String::from_utf8_lossy(
                &body[name_length + addr_length..name_length + addr_length + token_length],
            )
            .into_owned(),
        ));
    }

    Ok((members, replication))
}

/// Issue #266: how long `run_migration` waits for an in-flight
/// re-replication to clear before it starts marking dead copies, and how
/// long a re-replication waits for an in-flight join migration to
/// complete before it starts sending — see both functions' doc comments.
/// Generous relative to a single handoff's own transfer time (this is a
/// last-resort bound, not the expected wait) since giving up early
/// defeats the point of waiting at all; either side proceeding anyway
/// after this elapses just means one more, slightly-late ring-change
/// cycle to reconcile, not lost data.
const RING_CHANGE_HANDOFF_WAIT: Duration = Duration::from_secs(60);

/// Issue #266: bounded wait for `node_context.active_rereplication` to
/// clear, so `run_migration` doesn't mark a copy dead (releasing it to
/// the sweep) that a re-replication in flight has not yet delivered to
/// the ring's newly promoted owner — the two would otherwise race to
/// leave that key on only the joiner, exactly the under-replication this
/// issue exists to close. Not shutdown-aware, unlike `run_rereplication`
/// itself: this runs inside an already-bounded handoff (`run_migration`),
/// not a background task of its own, so it has nothing better to do
/// while shutdown is pending than keep waiting out its own bound.
///
/// Issue #422: also polls `abort_requested` — this handoff's *own*
/// abort flag (`MigrationGuard::abort_requested`), not the
/// re-replication's — and returns early once it's set. Without this, a
/// handoff `abandon_migration` cancels while it's blocked in here isn't
/// noticed until this wait returns on its own (up to
/// `RING_CHANGE_HANDOFF_WAIT`, 60s): `run_migration`'s own abort check
/// lives inside its `for key in keys` loop, which this wait runs ahead
/// of, and `run_sweep` pauses entirely for as long as
/// `active_migration.completed_at.is_none()` — true the whole time this
/// abandoned handoff sits here, for no reason.
async fn wait_for_rereplication_to_clear(node_context: &NodeContext, abort_requested: &AtomicBool) {
    let deadline = Instant::now() + RING_CHANGE_HANDOFF_WAIT;
    loop {
        if abort_requested.load(Ordering::SeqCst) {
            return;
        }
        let busy = node_context
            .active_rereplication
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .is_some();
        if !busy {
            return;
        }
        if Instant::now() >= deadline {
            eprintln!(
                "WARN migration: a re-replication was still in flight after {}s; proceeding \
                 anyway",
                RING_CHANGE_HANDOFF_WAIT.as_secs()
            );
            return;
        }
        sleep(Duration::from_millis(100)).await;
    }
}

/// Issue #266: the mirror wait, on the re-replication side — a join
/// migration in flight is about to change `known_ring` again (and,
/// symmetrically, may itself want to mark this node's copy dead once it
/// completes), so a re-replication computed against the ring as it stood
/// a moment ago waits for the migration to finish rather than racing it
/// with a stale before/after pair.
///
/// "In flight" means still transferring — `completed_at.is_none()`, the
/// same check `run_decommission`'s own abort-wait loop uses — not merely
/// "the slot is occupied": a completed handoff's slot stays `Some` for
/// its whole `forwarding_grace` afterglow (up to ~100s for a large
/// transfer, comfortably longer than this wait's own bound), and that
/// window has nothing left to race — `known_ring` already flipped to
/// `after_ring` the moment the transfer finished. Treating the slot's
/// mere presence as "busy" made this wait time out on essentially every
/// call shortly after any join, for no reason.
///
/// Issue #422: also treats the occupying migration's own
/// `abort_requested` as "not really busy" — once `abandon_migration` has
/// flagged it, `run_migration` is already on its way to unwinding and
/// clearing the slot (see `MigrationGuard::drop`); there is nothing left
/// here worth waiting the full `RING_CHANGE_HANDOFF_WAIT` for.
///
/// Issue #498: also stops at shutdown. This runs inside a re-replication
/// task in `send_heartbeats`'s `JoinSet`, which `run` awaits with no
/// bound of its own after the connection drain — so a wait here that
/// ignored `shutdown_rx` could hold process exit for the whole 60s
/// deadline (twice that, with `run_superseding_rereplication`'s own
/// wait behind it), well past `SHUTDOWN_TIMEOUT` and past the stop
/// grace ECS/EKS give a task before SIGKILL. `run_rereplication` itself
/// checks `shutdown_rx` before every send, so returning early here just
/// lets it fall through to that check. A closed `shutdown_rx` (its
/// sender lives in `run`) means `run` has already returned — nothing
/// left to wait for either.
async fn wait_for_migration_to_clear(node_context: &NodeContext) {
    let deadline = Instant::now() + RING_CHANGE_HANDOFF_WAIT;
    let mut shutdown_rx = node_context.shutdown_rx.clone();
    loop {
        let busy = node_context
            .active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .as_ref()
            .is_some_and(|active| {
                active.completed_at.is_none() && !active.abort_requested.load(Ordering::SeqCst)
            });
        if !busy {
            return;
        }
        if *shutdown_rx.borrow() {
            return;
        }
        if Instant::now() >= deadline {
            eprintln!(
                "WARN re-replication: a join migration was still in flight after {}s; \
                 proceeding with the ring as adopted",
                RING_CHANGE_HANDOFF_WAIT.as_secs()
            );
            return;
        }
        tokio::select! {
            _ = sleep(Duration::from_millis(100)) => {}
            changed = shutdown_rx.changed() => {
                if changed.is_err() {
                    return;
                }
            }
        }
    }
}

/// Issue #266: which addresses (empty if none) this node must
/// re-replicate `key` to after a ring change dropped at least one
/// member — pure so the sender-election + target computation has a fast
/// unit test that needs no network harness, mirroring
/// `classify_decommission_key` for the decommission's own transfer loop.
///
/// Sender: every one of `key`'s owners under `before` that is still a
/// member of `after` is eligible to send — not just the highest-ranked
/// survivor. `self_name` must itself be an owner under `before` and
/// still be a member under `after`, or this returns empty (nothing to
/// send if this node wasn't an old owner, or didn't survive the change,
/// to begin with).
///
/// Issue #405: this used to elect only the single highest-ranked
/// surviving old owner as "the" sender, mirroring how `run_migration`
/// used to elect only "the old primary" before issue #266 fixed that.
/// The same failure mode applies here: after consecutive ring changes,
/// the highest-ranked survivor can itself have been promoted by an
/// *earlier* change and not hold the data yet (its own re-replication
/// hasn't caught up). Electing only it risked the exact same silent
/// no-op #266 fixed for migration — `run_rereplication`'s live
/// `peek_entry` re-check comes back empty, nothing is sent, and the key
/// stays under-replicated with nothing left to retrigger it. Every
/// surviving old owner being eligible instead means the promoted node
/// gets a copy as long as *any* surviving old owner still has one — each
/// node decides this independently for itself (this function is called
/// once per node, with that node's own name as `self_name`), and sends
/// are idempotent put-if-absent (`send_handoff_set`'s `if_absent`), so
/// more than one real sender is safe.
///
/// Targets: `after`'s owners minus `before`'s — the ranks this ring
/// change newly promoted into `key`'s top-R. A survivor that was already
/// an owner stays one (removing one node from an HRW ranking can only
/// ever promote others, never demote a survivor — see the ranking's own
/// properties), so this never needs to ask "did I just lose ownership":
/// unlike a join, a re-replication never marks anything dead.
fn rereplication_targets(
    before: &HashRing,
    after: &HashRing,
    key_hash: KeyHash,
    replication: usize,
    self_name: &str,
) -> Vec<String> {
    if !before.is_owner_hashed(key_hash, self_name, replication) {
        return Vec::new();
    }
    if !after.nodes().iter().any(|node| node.as_str() == self_name) {
        return Vec::new();
    }

    let old_owners = before.owners_hashed(key_hash, replication);
    after
        .owners_hashed(key_hash, replication)
        .into_iter()
        .filter(|owner| !old_owners.contains(owner))
        .map(str::to_string)
        .collect()
}

/// Issue #275: installs `state` into `slot` and hands back whatever
/// occupied it a moment ago, both under one lock acquisition — the fix
/// for the check-then-act race `run_superseding_rereplication` used to
/// have, where reading the previous occupant and writing the new one
/// were two separate lock acquisitions with an `.await` in between.
/// Two triggers landing in that window could both read the same
/// `previous`, both wait on its `done`, and then both install
/// themselves — the loser's run would keep going untracked, with
/// nothing left pointing at it to abort.
///
/// Doing the swap atomically instead makes every trigger claim the slot
/// the instant it runs, with no window in which two callers can observe
/// the same occupant: whichever of two racing callers reaches the lock
/// first becomes the other's `previous`, so the two chain — the second
/// waits on the first's `done`, not on some third run's — rather than
/// racing. That preserves the at-most-one-running invariant for any
/// number of concurrent triggers, since each new state can only ever be
/// superseded by the one state that actually swapped it out.
fn take_over_rereplication_slot(
    slot: &Arc<Mutex<Option<Arc<ActiveRereplication>>>>,
    state: &Arc<ActiveRereplication>,
) -> Option<Arc<ActiveRereplication>> {
    let mut slot = slot.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    slot.replace(Arc::clone(state))
}

/// Issue #266: shared core for both re-replication trigger sites —
/// supersedes (aborts, then waits briefly for) any re-replication
/// already in flight for an earlier ring change (at most one runs at a
/// time per node, so two runs can never interleave their sends),
/// installs a fresh `ActiveRereplication` slot, runs `run_rereplication`
/// against the given ring change and address map, then clears the slot
/// (if a later ring change hasn't already claimed it). Takes everything
/// by value so it can be boxed as a `RereplicationTask` and hand off
/// through `NodeContext::rereplication_tx` — see that field's doc
/// comment on why every producer goes through the same channel into
/// `send_heartbeats`'s `JoinSet` rather than spawning directly.
///
/// Two callers: `spawn_or_supersede_rereplication` (an eviction-driven
/// ring change — fetches the address map itself via `L`, and waits out
/// any join migration in progress first) and `run_migration`'s own
/// join-flip trigger (which already has the addresses from the `M` it
/// just handled, plus the joiner's own, and runs only after its own
/// transfer has completed — so neither of those two steps applies there).
///
/// Issue #275: the install (`take_over_rereplication_slot`) happens
/// *before* the wait on the previous occupant's `done`, not after — see
/// that function's doc comment for why this ordering is what keeps
/// concurrent triggers from racing to install their state. The
/// completion guard below (`Arc::ptr_eq` against `slot`'s current
/// occupant) still does the right thing under this scheme: by the time
/// this run finishes, a later trigger may already have swapped its own
/// state in, in which case `slot` no longer points at `state` and this
/// is correctly a no-op — clearing would otherwise erase a successor's
/// still-active state out from under it.
async fn run_superseding_rereplication(
    node_context: NodeContext,
    before_ring: Arc<HashRing>,
    after_ring: Arc<HashRing>,
    replication: usize,
    addresses: HashMap<String, String>,
    // Issue #295: name -> membership token, one per `addresses` entry
    // this run genuinely has a token for — see `Command::HandoffSet::
    // token` and `run_rereplication`'s own doc comment.
    tokens: HashMap<String, String>,
    mut shutdown_rx: watch::Receiver<bool>,
) {
    let state = Arc::new(ActiveRereplication {
        abort_requested: AtomicBool::new(false),
        done: AtomicBool::new(false),
    });
    let previous = take_over_rereplication_slot(&node_context.active_rereplication, &state);
    if let Some(previous) = previous {
        previous.abort_requested.store(true, Ordering::SeqCst);
        // Issue #498: bounded by the deadline *and* by shutdown — see
        // `wait_for_migration_to_clear`'s doc comment for why a wait in
        // this task must not sit out its deadline once shutdown is
        // pending. The previous run is itself shutdown-aware
        // (`run_rereplication`), so it is on its way out too; and
        // `run_rereplication` below bails on its first key check, so
        // leaving early here can't start a second transfer alongside it.
        let deadline = Instant::now() + RING_CHANGE_HANDOFF_WAIT;
        while !previous.done.load(Ordering::SeqCst)
            && !*shutdown_rx.borrow()
            && Instant::now() < deadline
        {
            tokio::select! {
                _ = sleep(Duration::from_millis(100)) => {}
                changed = shutdown_rx.changed() => {
                    if changed.is_err() {
                        break;
                    }
                }
            }
        }
    }

    // The forwarding window opens with the pass — a later ring change's
    // pass replaces it with its own, newer, snapshot.
    *node_context
        .rereplication_forward
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(RereplicationForward {
        before_ring: Arc::clone(&before_ring),
        after_ring: Arc::clone(&after_ring),
        replication,
        addresses: addresses.clone(),
        tokens: tokens.clone(),
        connections: Mutex::new(HashMap::new()),
        completed_at: None,
        grace: FORWARDING_GRACE_BASE,
    });

    run_rereplication(
        &node_context,
        &before_ring,
        &after_ring,
        replication,
        &addresses,
        &tokens,
        &state.abort_requested,
        &mut shutdown_rx,
    )
    .await;

    state.done.store(true, Ordering::SeqCst);
    {
        // Stamp this pass's own window only: a later pass may already
        // have put its own in the slot.
        let mut window = node_context
            .rereplication_forward
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(window) = window.as_mut()
            && Arc::ptr_eq(&window.after_ring, &after_ring)
        {
            window.completed_at = Some(Instant::now());
        }
    }
    let mut slot = node_context
        .active_rereplication
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if slot
        .as_ref()
        .is_some_and(|current| Arc::ptr_eq(current, &state))
    {
        *slot = None;
    }
}

/// Issue #266: the task `register_with_discovery` hands to
/// `send_heartbeats`'s `JoinSet` when `adopt_membership` reports a ring
/// change that dropped a member. Fetches the roster with addresses (the
/// heartbeat ack carries names only) and waits out any join migration in
/// progress (`wait_for_migration_to_clear`) before handing off to
/// `run_superseding_rereplication` for the rest.
async fn spawn_or_supersede_rereplication(
    node_context: NodeContext,
    discovery_addr: String,
    before_ring: Arc<HashRing>,
    after: Arc<Membership>,
    shutdown_rx: watch::Receiver<bool>,
) {
    let (addresses, tokens): (HashMap<String, String>, HashMap<String, String>) = match timeout(
        OUTBOUND_IO_TIMEOUT,
        fetch_roster_once(&node_context, &discovery_addr),
    )
    .await
    {
        Ok(Ok((members, _replication))) => members
            .into_iter()
            .map(|(name, addr, token)| ((name.clone(), addr), (name, token)))
            .unzip(),
        Ok(Err(error)) => {
            eprintln!(
                "WARN re-replication: fetching the roster with addresses from {discovery_addr} \
                 failed: {error} — giving up; a later ring change will retrigger it if the \
                 cluster is still under-replicated"
            );
            return;
        }
        Err(_) => {
            eprintln!(
                "WARN re-replication: fetching the roster with addresses from {discovery_addr} \
                 timed out — giving up; a later ring change will retrigger it if the cluster is \
                 still under-replicated"
            );
            return;
        }
    };

    wait_for_migration_to_clear(&node_context).await;

    let after_ring = Arc::clone(&after.ring);
    run_superseding_rereplication(
        node_context,
        before_ring,
        after_ring,
        after.replication,
        addresses,
        tokens,
        shutdown_rx,
    )
    .await;
}

/// Issue #266: after a ring change dropped a member, streams every key
/// this node is an eligible sender for (`rereplication_targets` — issue
/// #405: every surviving old owner, not just the highest-ranked one) to the
/// owner(s) the change newly promoted — mirrors `run_decommission`'s
/// handoff loop, with one shared, reused connection per target address,
/// sent as a put-if-absent `U … A` (`send_handoff_set`'s `if_absent`) so
/// this can never regress a newer client write that raced it. Returns
/// once every key has been considered, `abort_requested` is set (a
/// superseding ring change), or shutdown lands.
///
/// Issue #357: this heals exactly the keys the triggering ring change
/// re-ranked (`rereplication_targets` diffs `before_ring` against
/// `after_ring`) — it is not anti-entropy, and it has no idea a member
/// still present in both rings is mid-decommission. A key left below R
/// by an earlier, unrelated window (see `run_decommission`'s doc
/// comment) is only picked up here if a later change happens to re-rank
/// it.
///
/// Issue #295: a target this node has no membership token for (missing
/// from `tokens`) is skipped exactly like a target with no address —
/// counted in `skipped`, not sent to. Both callers (`spawn_or_supersede_
/// rereplication`'s eviction trigger and `run_migration`'s own join-flip
/// trigger) fetch a token for every target up front (`fetch_roster_once`,
/// issue #295), so this is a defensive fallback for a target that
/// dropped out of the registry between that fetch and this send, not the
/// expected common case.
#[allow(clippy::too_many_arguments)]
async fn run_rereplication(
    node_context: &NodeContext,
    before_ring: &HashRing,
    after_ring: &HashRing,
    replication: usize,
    addresses: &HashMap<String, String>,
    tokens: &HashMap<String, String>,
    abort_requested: &AtomicBool,
    shutdown_rx: &mut watch::Receiver<bool>,
) {
    let Some(keys) = list_keys(&node_context.request_tx).await else {
        eprintln!("WARN re-replication: cache task is unavailable");
        return;
    };
    // Issue #970: dead copies stay out of this handoff unless their marks are still held.
    let skip_dead = marks_released(&node_context.active_migration);
    // Issue #975: even while the marks are held, a dead copy never goes to
    // the joiner whose handoff took it (the slot's own, or a lingering
    // one): that joiner got the key from the handoff itself, so this is at
    // best a repeat and at worst — a client having deleted or expired the
    // key on the joiner since — a put-if-absent that brings it back. The
    // other new owners of a ring change that also dropped a member may
    // hold nothing yet and still get it.
    let joiners: HashSet<String> = {
        let slot = node_context
            .active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match slot.as_ref() {
            Some(active) if !active.expired() => std::iter::once(active.joining_name.clone())
                .chain(
                    active
                        .lingering
                        .iter()
                        .map(|lingering| lingering.joining_name.clone()),
                )
                .collect(),
            _ => HashSet::new(),
        }
    };

    let self_name = node_context.name.as_str();
    let mut streams: HashMap<String, ClientStream> = HashMap::new();
    let mut sent = 0usize;
    let mut skipped = 0usize;
    let mut owners_reached: HashSet<String> = HashSet::new();

    // `keys` arrive grouped by namespace, and a namespace can be ~1 MiB:
    // hash each distinct one once rather than per key.
    let mut hasher = KeyHasher::default();

    for key in keys {
        if abort_requested.load(Ordering::SeqCst) || *shutdown_rx.borrow() {
            break;
        }

        let targets = rereplication_targets(
            before_ring,
            after_ring,
            hasher.hash(&key),
            replication,
            self_name,
        );
        if targets.is_empty() {
            continue;
        }

        // Live re-peek, same reasoning as the join transfer and the
        // decommission's own: a concurrent client write must win over
        // whatever this snapshot held.
        let Some((_, value, ttl)) =
            peek_entry_for_handoff(&node_context.request_tx, &key, skip_dead).await
        else {
            continue;
        };
        let dead = !skip_dead
            && !joiners.is_empty()
            && peek_entry_for_handoff(&node_context.request_tx, &key, true)
                .await
                .is_none();

        for target in targets {
            if dead && joiners.contains(&target) {
                skipped += 1;
                continue;
            }
            let Some(addr) = addresses.get(&target) else {
                skipped += 1;
                continue;
            };
            let Some(token) = tokens.get(&target) else {
                skipped += 1;
                continue;
            };

            if *shutdown_rx.borrow() {
                break;
            }

            let mut delivered = false;
            for attempt in 1..=KEY_TRANSFER_ATTEMPTS {
                if abort_requested.load(Ordering::SeqCst) || *shutdown_rx.borrow() {
                    break;
                }
                if !streams.contains_key(addr) {
                    // Raced against shutdown: the dial/TLS/auth legs are
                    // each bounded by `OUTBOUND_IO_TIMEOUT`, but only
                    // *between* attempts was shutdown noticed, so a target
                    // that stopped answering held the exit (and with it the
                    // heartbeat task `run` awaits) for a whole leg or more.
                    // Same shape as `run_decommission`'s.
                    let connected = tokio::select! {
                        biased;
                        _ = shutdown_requested(shutdown_rx) => break,
                        result = connect_and_authenticate(node_context, addr, AuthPeer::Node) => {
                            result
                        }
                    };
                    match connected {
                        Ok(stream) => {
                            streams.insert(addr.clone(), stream);
                        }
                        Err(error) => {
                            eprintln!(
                                "WARN re-replication: connecting to {addr} failed (attempt \
                                 {attempt}/{KEY_TRANSFER_ATTEMPTS}): {error}"
                            );
                            continue;
                        }
                    }
                }
                let Some(stream) = streams.get_mut(addr) else {
                    continue;
                };
                #[cfg(test)]
                node_context.gates.pass.wait().await;
                let sent_one = tokio::select! {
                    biased;
                    _ = shutdown_requested(shutdown_rx) => None,
                    result = send_handoff_set(stream, &key, &value, ttl, true, token) => {
                        Some(result)
                    }
                };
                match sent_one {
                    // Interrupted mid-send: the stream's state is unknown.
                    None => {
                        streams.remove(addr);
                        break;
                    }
                    Some(Ok(())) => {
                        delivered = true;
                        break;
                    }
                    Some(Err(error)) => {
                        eprintln!(
                            "WARN re-replication: transfer to {addr} failed (attempt \
                             {attempt}/{KEY_TRANSFER_ATTEMPTS}): {error}"
                        );
                        streams.remove(addr);
                    }
                }
            }

            if delivered {
                sent += 1;
                owners_reached.insert(target);
            } else {
                skipped += 1;
            }
        }
    }

    println!(
        "INFO re-replication after membership change: sent {sent} entries to {} owner(s) ({} \
         skipped)",
        owners_reached.len(),
        skipped
    );
}

async fn list_keys(request_tx: &mpsc::Sender<CacheRequest>) -> Option<Vec<Key>> {
    match execute_command(request_tx, Command::ListEntries).await {
        Ok(Response::Keys(keys)) => Some(keys),
        _ => None,
    }
}

/// The live re-peek a handoff sender does right before sending a key
/// (`Cache::peek_entry`). With `skip_dead` (issue #970), a copy this node
/// holds dead — `migrated`-marked since a join took the key away — reads
/// as absent, so it is never passed on; `marks_released` says when that is
/// safe.
async fn peek_entry_for_handoff(
    request_tx: &mpsc::Sender<CacheRequest>,
    key: &Key,
    skip_dead: bool,
) -> Option<(Key, Bytes, Option<Duration>)> {
    let command = if skip_dead {
        Command::PeekLiveEntry { key: key.clone() }
    } else {
        Command::PeekEntry { key: key.clone() }
    };
    match execute_command(request_tx, command).await {
        Ok(Response::Entries(mut entries)) => entries.pop(),
        _ => None,
    }
}

/// Issue #970: whether this node's dead copies may be left out of a
/// handoff it sends. Marks are held — the copies they name may become
/// live again — only while the join that made them is undecided (a
/// completed slot discovery has not confirmed, issue #62); once confirmed
/// they are released to the sweep, and a decommission drain or a
/// re-replication pass that runs before the sweep got to them must not
/// hand them on as if live. With no slot there are no held marks.
fn marks_released(active_migration: &Arc<Mutex<Option<ActiveMigration>>>) -> bool {
    !active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .is_some_and(|active| active.completed_at.is_some() && !active.confirmed)
}

async fn mark_migrated(request_tx: &mpsc::Sender<CacheRequest>, key: &Key) {
    let _ = execute_command(request_tx, Command::MarkMigrated { key: key.clone() }).await;
}

/// Reverses `mark_migrated` for a whole restore in one cache round trip —
/// see `Cache::unmark_migrated_many` for why one per key was too slow.
async fn unmark_migrated_many(request_tx: &mpsc::Sender<CacheRequest>, keys: Vec<Key>) {
    if keys.is_empty() {
        return;
    }
    let _ = execute_command(request_tx, Command::UnmarkMigratedMany { keys }).await;
}

/// What `abandon_migration` found for `joining_name` in `active_migration`.
enum AbandonOutcome {
    /// No matching handoff — a safe no-op: already finished and cleared
    /// its slot, this cancel is for some other join, or nothing was ever
    /// active.
    NoMatch,
    /// Matched a handoff that had already completed its own share
    /// (forwarding grace or not, issue #3/#62): the slot was taken
    /// immediately, along with reverting `known_ring` (issue #93) — these
    /// are its dead copies to restore.
    Completed(Vec<Key>),
    /// Matched a handoff still transferring: `abort_requested` was set,
    /// but the slot can't be handed back synchronously here — only
    /// `run_migration`'s own unwind, noticing the flag, can safely drop
    /// it mid-transfer. The caller should wait for that unwind to
    /// actually finish (`wait_for_migration_slot_to_clear`) before
    /// treating this cancel as done — see that function's own doc
    /// comment for why acking `X` before the slot is really free is
    /// unsafe (issue: migration-generation-guard).
    Aborting,
}

/// Handles an incoming `X` (discovery abandoning a join) against this
/// node's migration slot. Always requests abort on a matching in-flight
/// handoff (whether or not it has completed), so a still-running transfer
/// stops. A safe no-op if there's no active migration, or it's for a
/// different `joining_name` — a cancel that arrived after this handoff
/// already finished and cleared its slot, or for some other join.
///
/// For a handoff that had already completed this node's own share (so it
/// only lingered to forward writes, issue #3, and hold its dead copies'
/// marks, issue #62), the abandon ends both: the slot is taken, and its
/// `known_ring` flip to the post-join topology is reverted (issue #93) —
/// but only if `known_ring` still holds *this* handoff's post-join ring,
/// so a newer membership update (e.g. a heartbeat that adopted a fresh
/// roster once the grace lapsed) is never clobbered.
fn abandon_migration(node_context: &NodeContext, joining_name: &str) -> AbandonOutcome {
    let taken =
        match take_abandoned_slot(node_context, |active| active.joining_name == joining_name) {
            TakenSlot::NoMatch => return AbandonOutcome::NoMatch,
            TakenSlot::Aborting => return AbandonOutcome::Aborting,
            TakenSlot::Completed(taken) => taken,
        };
    revert_known_ring_after_abandon(node_context, &taken);
    AbandonOutcome::Completed(taken.marked_keys)
}

/// Issue (migration-generation-guard): after `abandon_migration` sets
/// `abort_requested` on a still-transferring handoff (`AbandonOutcome::
/// Aborting`) rather than taking the slot itself — only `run_migration`'s
/// own unwind can safely do that mid-transfer — waits for that unwind to
/// actually finish and drop its `MigrationGuard` (clearing the slot, or
/// leaving it occupied by a different `joining_name` that raced in) before
/// this node acks `X` with `MigrationCancelled`.
///
/// Without this wait, discovery's `abandon_current_join` proceeds straight
/// to `try_begin_next_join` the moment the `MigrationCancelled` ack lands.
/// If the very next join reuses this same `joining_name` (a crash + fast
/// restart of the joining node under the same identity), its `M` can
/// arrive here before `run_migration`'s unwind has actually cleared the
/// slot. `MigrationGuard::new`'s generation check (see its own doc
/// comment) correctly tells this apart from a same-generation retry and
/// rejects it — but that rejection can bounce for longer than discovery's
/// `send_migrate_with_retry` covers: `MIGRATE_SEND_ATTEMPTS` (3, in
/// `src/bin/nanocached-discovery.rs`) retries back-to-back with no delay
/// between them, nowhere close to the worst-case time `run_migration` can
/// still be blocked inside one stuck send — up to `KEY_TRANSFER_ATTEMPTS`
/// (3) × `OUTBOUND_IO_TIMEOUT` (10s) — before it even re-checks `abort_requested`.
/// So instead of hoping the retries outlast that window, this wait closes
/// the *common* case at the source: `run_migration` checks
/// `abort_requested` between keys, so unless it is mid-send to a joiner
/// that has stopped answering, the slot is free within one key's send
/// and the ack goes out with it already empty. The stuck-send case is
/// not closed here and cannot be: discovery reads the `X` ack for only
/// `OUTBOUND_IO_TIMEOUT` (10s) and then calls `try_begin_next_join`
/// regardless, so `MIGRATION_ABANDON_DRAIN_WAIT` stays under that and a
/// slot still held by a 30s stuck send is left to `MigrationGuard::new`'s
/// generation check, which rejects the new-generation `M` with
/// `Conflict` rather than mistaking it for a retry.
///
/// Bounded, never indefinite (this codebase's rule for every wait on
/// another task), and it also stops at shutdown: this runs inside the
/// `X` connection's task, which `run`'s shutdown sequence gives
/// `SHUTDOWN_TIMEOUT` to finish before aborting *every* connection task
/// together — a wait here that ignored `shutdown_rx` could push the
/// whole drain past that and take unrelated, otherwise-finishing
/// connections down with it. Past the bound this logs and acks anyway.
async fn wait_for_migration_slot_to_clear(node_context: &NodeContext, joining_name: &str) {
    let deadline = Instant::now() + MIGRATION_ABANDON_DRAIN_WAIT;
    let mut shutdown_rx = node_context.shutdown_rx.clone();
    loop {
        let still_present = node_context
            .active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .as_ref()
            .is_some_and(|active| {
                active.joining_name == joining_name && active.completed_at.is_none()
            });
        if !still_present {
            return;
        }
        if *shutdown_rx.borrow() {
            return;
        }
        if Instant::now() >= deadline {
            eprintln!(
                "WARN abandon of {joining_name}: the handoff was still unwinding after {}s; \
                 acking the cancel anyway",
                MIGRATION_ABANDON_DRAIN_WAIT.as_secs()
            );
            return;
        }
        tokio::select! {
            _ = sleep(Duration::from_millis(100)) => {}
            _ = shutdown_rx.changed() => {}
        }
    }
}

/// Issue #582: the ownership reclaim pass. A join leaves the displaced
/// node holding copies it no longer owns; the mark sweep (`run_sweep`)
/// reclaims the ones a client never rewrote, but a rewrite releases the
/// mark (issue #2) and that copy stayed for good — more memory than the
/// node's share, and an old value that comes back as authoritative when a
/// later eviction makes the node an owner again (issue #563). This pass
/// removes, every `RECLAIM_INTERVAL`, each key this node has owned under
/// no membership discovery published during the last `RECLAIM_GRACE`
/// (`RingHistory::checks_within`); the cache refuses while a handoff write
/// is more recent than that (`Cache::reclaim_unowned`), and the pass does
/// not run at all while this node is unpromoted, leaving, mid-handoff or
/// still forwarding for a join (`reclaim_checks`). Marking a copy dead at
/// write time instead was tried and lost live copies when a decommission
/// overlapped the join (issue #582): the ring a handoff predicts is not
/// the ring discovery ends up publishing, and only the published ones
/// count here.
///
/// Issue #594: a pass is not free — its key snapshot (`Cache::keys`)
/// stalls the cache task for about 25 ms per million keys and holds
/// 64 bytes per key outside `--max-memory` (183 MiB at 3M), and the
/// ownership checks cost the task several hundred milliseconds more —
/// so it runs only when something could have changed its answer
/// (`ReclaimMark`). In steady state that is never: a few passes per
/// membership change, not one every interval.
async fn run_reclaim(node_context: NodeContext, mut shutdown_rx: watch::Receiver<bool>) {
    let mut settled: Option<ReclaimMark> = None;
    loop {
        if wait_or_shutdown(RECLAIM_INTERVAL, &mut shutdown_rx).await {
            return;
        }
        if let Some(removed) = reclaim_pass(&node_context, &shutdown_rx, &mut settled).await
            && removed > 0
        {
            println!(
                "INFO reclaimed {removed} entr(ies) this node has owned under no membership \
                 of the last {}s",
                RECLAIM_GRACE.as_secs()
            );
        }
    }
}

/// Issue #594: what the last *fully completed* reclaim pass judged
/// against. A key this node holds can only become unowned-under-every-ring
/// through one of three events, each of which moves one of these fields:
///
/// - discovery publishes a membership, or a handoff's ring is reverted on
///   an abandon (`RingHistory::generation`, bumped by `record` and
///   `touch`);
/// - an old membership ages out of the grace window, so a key it alone
///   gave this node is no longer covered (`epochs`, the number of rings in
///   the window — only ever appended with a generation bump, only ever
///   dropped from the front as the window moves, so `(generation,
///   epochs)` identifies the exact set of rings a pass sees);
/// - a handoff write lands, which can carry a key under a ring this node
///   has not seen published (`handoff_writes`, the cache's count as of
///   *before* the pass took its snapshot, so a key that arrived during the
///   pass and is missing from the snapshot makes the next pass run).
///
/// A plain client write cannot: `wrong_node` admits a key only if this
/// node owns it under `known_ring`, which is a published ring, a
/// handoff's own post-join ring that discovery is about to publish (a new
/// generation either way), or — through `serving_locally_for_unconfirmed_join`
/// — the pre-join published ring. While all three stand still, the keys a
/// completed pass left are exactly the keys the next would leave.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct ReclaimMark {
    generation: u64,
    epochs: usize,
    handoff_writes: u64,
}

/// One pass of `run_reclaim`: `None` when it could not run (see
/// `reclaim_checks`), else how many entries it removed — `Some(0)` without
/// touching the keys when nothing has moved since the pass `settled`
/// records (issue #594). Works from a snapshot of the keys in
/// `SWEEP_BUDGET` chunks, yielding between them, and stops early if the
/// membership moves under it (the history's generation changed) or the
/// cache reports a recent handoff; what is left waits for the next
/// interval, and only a pass that ran every chunk updates `settled`.
/// Ownership is re-evaluated per key at removal, so the snapshot being
/// stale is harmless.
async fn reclaim_pass(
    node_context: &NodeContext,
    shutdown_rx: &watch::Receiver<bool>,
    settled: &mut Option<ReclaimMark>,
) -> Option<usize> {
    let (checks, generation) = reclaim_checks(node_context)?;
    let probe = Command::ReclaimUnowned {
        keys: Vec::new(),
        checks: Vec::new(),
        handoff_quiet_for: RECLAIM_GRACE,
    };
    let handoff_writes = match execute_command(&node_context.request_tx, probe).await {
        Ok(Response::Reclaimed {
            paused: false,
            handoff_writes,
            ..
        }) => handoff_writes,
        _ => return Some(0),
    };
    let mark = ReclaimMark {
        generation,
        epochs: checks.len(),
        handoff_writes,
    };
    if *settled == Some(mark) {
        return Some(0);
    }

    let keys = list_keys(&node_context.request_tx).await?;
    let mut removed = 0;
    let mut completed = true;
    for chunk in keys.chunks(SWEEP_BUDGET) {
        if *shutdown_rx.borrow() {
            completed = false;
            break;
        }
        if reclaim_checks(node_context).map(|(_, generation)| generation) != Some(generation) {
            completed = false;
            break;
        }
        match execute_command(
            &node_context.request_tx,
            Command::ReclaimUnowned {
                keys: chunk.to_vec(),
                checks: checks.clone(),
                handoff_quiet_for: RECLAIM_GRACE,
            },
        )
        .await
        {
            Ok(Response::Reclaimed {
                removed: count,
                paused: false,
                ..
            }) => removed += count,
            _ => {
                completed = false;
                break;
            }
        }
        tokio::task::yield_now().await;
    }
    if completed {
        *settled = Some(mark);
    }
    Some(removed)
}

/// The ownership checks a reclaim pass may use right now, with the
/// history generation they came from — or `None` while reclaiming is not
/// safe: this node is not promoted (a restart under a dead name serves
/// nothing yet), it is leaving (a draining node adopts rosters without
/// itself and would reclaim what it is still forwarding), a handoff it
/// runs is in flight or unconfirmed, a forwarding window is still open
/// (its own slot's or an earlier joiner's: the system's own definition of
/// "this join is still settling"), or the history does not cover the
/// grace.
fn reclaim_checks(node_context: &NodeContext) -> Option<(Vec<OwnerCheck>, u64)> {
    if !node_context.promoted.load(Ordering::SeqCst) {
        return None;
    }
    if node_context
        .leaving
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .is_some()
    {
        return None;
    }
    {
        let slot = node_context
            .active_migration
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(active) = slot.as_ref()
            && (active.completed_at.is_none()
                || !active.confirmed
                || active.forwarding_open()
                || active
                    .lingering
                    .iter()
                    .any(LingeringForward::forwarding_open))
        {
            return None;
        }
    }
    node_context
        .ring_history
        .checks_within(RECLAIM_GRACE, &node_context.name)
}

/// Staged node join's active-deletion background task: every `SWEEP_INTERVAL`,
/// reclaims migrated-marked and TTL-expired entries. `Cache::sweep`
/// removes at most `SWEEP_BUDGET` entries per call so it can't stall other
/// cache commands queued behind it on the single-threaded actor for long
/// (measured: ~500ns per removal, so a full-cache sweep over a backlog of
/// hundreds of thousands of entries would otherwise block for 100ms+) — a
/// call that hits that cap likely left more behind, so this loops back
/// immediately (no `SWEEP_INTERVAL` wait) until a call reports less than a
/// full budget removed, meaning the backlog is drained for now. Skips
/// (and doesn't drain a backlog) while `active_migration` is `Some` — this
/// node is the source for an in-progress handoff, so a marked-but-not-yet-
/// swept key may still be needed as the authoritative source for a
/// subsequent hop (see `NodeContext::active_migration`). Also watches
/// `shutdown_rx` while draining a backlog, so a large backlog can't delay
/// this task from dropping its `request_tx` clone past `SHUTDOWN_TIMEOUT`
/// — without it, `run`'s shutdown drain would just be waiting on this task
/// to notice on its own, one `SWEEP_BUDGET`-sized chunk at a time.
async fn run_sweep(
    request_tx: mpsc::Sender<CacheRequest>,
    active_migration: Arc<Mutex<Option<ActiveMigration>>>,
    ownership: Option<(KnownRing, String, RingHistory)>,
    mut shutdown_rx: watch::Receiver<bool>,
) {
    loop {
        // Issue #970: a membership change can make this node an owner of
        // keys it holds dead copies of; judge those (`SweepOwnership`) as
        // soon as the ring moves rather than up to an interval later,
        // during which a dead copy of a deleted key would be served live.
        let membership_moved = async {
            match &ownership {
                Some((_, _, history)) => history.changed().await,
                None => std::future::pending::<()>().await,
            }
        };
        tokio::select! {
            _ = sleep(SWEEP_INTERVAL) => {}
            _ = membership_moved => {}
            _ = shutdown_rx.changed() => return,
        }

        loop {
            // Pause only while a transfer is actually running: a
            // completed entry lingering for its forwarding grace
            // (issue #3) must not stall TTL sweeping for a minute. Its
            // *marks*, though (issue #62), are held back until discovery
            // has confirmed the join they belong to — see
            // `ActiveMigration::confirmed`.
            let (migration_active, marks_held) = {
                let slot = active_migration
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                match slot.as_ref() {
                    Some(active) => (active.completed_at.is_none(), !active.confirmed),
                    None => (false, false),
                }
            };

            if migration_active {
                break;
            }

            // The ring as adopted now and the published one before it: a
            // marked copy of a key this node owns again is kept only when
            // no other current owner saw the writes it missed
            // (`SweepOwnership`, issue #970); otherwise it is reclaimed and
            // that owner's re-replication brings the key back if it still
            // exists.
            let owned = ownership.as_ref().and_then(|(known_ring, name, history)| {
                let membership = known_ring
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .as_ref()
                    .map(Arc::clone)?;
                let check = |ring: &Arc<HashRing>, replication: usize| OwnerCheck {
                    ring: Arc::clone(ring),
                    name: name.clone(),
                    replication,
                };
                // The handoff this node last sent installed its post-join
                // ring here at completion; discovery may publish that ring
                // later, or the next heartbeat may already carry a later
                // one, so it goes in front of the published history.
                let handoff_ring = active_migration
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .as_ref()
                    .filter(|active| {
                        !same_members(&membership, active.after_ring.nodes(), active.replication)
                    })
                    .map(|active| check(&active.after_ring, active.replication));
                let since = handoff_ring
                    .into_iter()
                    .chain(
                        history
                            .rings_before(&membership)
                            .iter()
                            .map(|older| check(&older.ring, older.replication)),
                    )
                    .collect();
                Some(SweepOwnership {
                    now: check(&membership.ring, membership.replication),
                    since,
                })
            });
            tokio::select! {
                result = sweep(&request_tx, !marks_held, owned) => match result {
                    Some(removed) if removed >= SWEEP_BUDGET => continue,
                    _ => break,
                },
                _ = shutdown_rx.changed() => return,
            }
        }
    }
}

async fn sweep(
    request_tx: &mpsc::Sender<CacheRequest>,
    marked: bool,
    owned: Option<SweepOwnership>,
) -> Option<usize> {
    let (response_tx, response_rx) = oneshot::channel();

    request_tx
        .send(CacheRequest {
            command: Command::Sweep { marked, owned },
            response_tx,
        })
        .await
        .ok()?;

    match response_rx.await.ok()? {
        Response::Swept(removed) => Some(removed),
        _ => None,
    }
}

/// Which kind of peer an outbound connection is for. A node acks the `A`
/// handshake with `On`, a discovery server with `Od` (each names itself so
/// a client can tell them apart from the first reply) — so an outbound
/// connection has to know who it is dialling to accept the right ack.
/// Before this distinction the decommission path's roster fetch and leave
/// notification dialled discovery expecting a node's `On`, and with
/// `NANOCACHED_AUTH_SECRET` set every SIGTERM-driven scale-in gave up on
/// the handoff ("joining node rejected the auth secret"); the entries were
/// lost with the task and the leave arrived as a liveness eviction.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AuthPeer {
    Node,
    Discovery,
}

impl AuthPeer {
    fn auth_ack(self) -> &'static [u8; 3] {
        match self {
            AuthPeer::Node => b"On\n",
            AuthPeer::Discovery => b"Od\n",
        }
    }

    fn describe(self) -> &'static str {
        match self {
            AuthPeer::Node => "joining node",
            AuthPeer::Discovery => "discovery server",
        }
    }
}

/// Connects to `addr` and, if `node_context.auth_secret` is set, performs
/// the auth handshake it expects before accepting any other command —
/// shared by every place that opens an outbound connection to another
/// node (`run_migration`'s own persistent connection, the one-shot
/// `set_on_joining_node`/`delete_on_joining_node` calls used to forward a
/// racing client write mid-migration, the decommission handoff) and to a
/// discovery server (the decommission's roster fetch and leave). `peer`
/// selects the ack to expect.
async fn connect_and_authenticate(
    node_context: &NodeContext,
    addr: &str,
    peer: AuthPeer,
) -> io::Result<ClientStream> {
    let mut stream = connect_client_stream(addr, node_context.tls_connector.as_ref()).await?;

    if let Some(secret) = &node_context.auth_secret {
        timeout(OUTBOUND_IO_TIMEOUT, async {
            stream.write_all(&auth_message(secret)).await?;

            let mut ack = [0u8; 3];
            stream.read_exact(&mut ack).await?;

            if &ack != peer.auth_ack() {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    format!("{} rejected the auth secret", peer.describe()),
                ));
            }
            io::Result::Ok(())
        })
        .await
        .map_err(|_| io::Error::new(io::ErrorKind::TimedOut, "outbound auth timed out"))??;
    }

    Ok(stream)
}

async fn send_set(
    stream: &mut ClientStream,
    key: &Key,
    value: &[u8],
    ttl: Option<Duration>,
) -> io::Result<()> {
    trace!(
        &key.name,
        "send_S key={} ttl={:?}",
        crate::trace::name(&key.name),
        ttl.map(|t| t.as_secs())
    );
    timeout(OUTBOUND_IO_TIMEOUT, async {
        stream.write_all(&set_message(key, value, ttl)).await?;

        let mut ack = [0u8; 2];
        stream.read_exact(&mut ack).await?;

        if &ack != b"S\n" {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "joining node did not acknowledge the transferred key (answered {:?})",
                    String::from_utf8_lossy(&ack)
                ),
            ));
        }
        io::Result::Ok(())
    })
    .await
    .map_err(|_| io::Error::new(io::ErrorKind::TimedOut, "outbound set timed out"))?
}

/// What a concurrent client write needs to forward itself to an
/// in-flight handoff's joining node (see `migration_target_for`):
/// where to reach it, and the persistent connection to reuse for the
/// forward — shared with every other forwarded write for this same
/// migration (`ActiveMigration::forward_connection`) rather than each
/// dialing its own.
struct ForwardTarget {
    addr: String,
    connection: Arc<AsyncMutex<Option<ClientStream>>>,
    /// Issue #295: the target's own membership token — carried on any
    /// `U`/`u` this forward sends (see `Command::HandoffSet::token`).
    /// Unused for a plain `Set`/`Delete` forward (the slot's own joiner
    /// gets those), but always populated: `migration_targets_for` sources
    /// it from `ActiveMigration::joining_token` (and a lingering joiner's
    /// from `LingeringForward::joining_token`, which sends `U`/`u` — see
    /// `as_handoff`), `leave_target_for` from `LeaveState::tokens`.
    token: String,
    /// Issue #474: set once the handoff this target was resolved from is
    /// no longer the one this node is forwarding for — its joiner was
    /// evicted (`adopt_membership`'s early close), the join was abandoned
    /// (`abandon_migration`), or the slot was superseded by a later `M`
    /// (`MigrationGuard::new`). A forward is resolved to its target when
    /// it is *spawned* but runs only once it wins the target's connection
    /// lock, and behind a dead peer that can be tens of seconds later
    /// (each earlier forward burns up to `FORWARD_TIMEOUT` per attempt);
    /// by then the address may belong to a different process — Docker,
    /// and any orchestrator that recycles IPs, hands a killed node's
    /// address to the next one started — which would receive a `U` with
    /// a stale token (rejected, but thousands of times) or a plain `S`
    /// for a key it doesn't own (accepted). `forward_with_retries` checks
    /// this before every attempt and drops the forward silently: the
    /// data is safe either way (the write is applied locally and the
    /// replacement join re-homes it), only the delivery to a peer that
    /// stopped being the target is skipped. Shared per `ActiveMigration`
    /// (`forward_revoked`); `leave_target_for` hands out a fresh `false`
    /// — a leaver's own targets are not recycled under it.
    revoked: Arc<AtomicBool>,
    /// Send a forwarded client `Set`/`Delete` to this target as a `U`/`u`
    /// (unconditional handoff frame) rather than a plain `S`/`D`. Set for
    /// a join's targets — the slot's own joiner (`migration_targets_for`)
    /// and a lingering one (`LingeringForward::target`) — not for a
    /// decommission's entrant (`leave_target_for`'s callers pick the frame
    /// themselves) or a clear (not subject to the wrong-node check).
    /// Applied at the one place every forward passes through,
    /// `ForwardQueues::push`.
    ///
    /// Why: a plain `S` is subject to the receiver's own `wrong_node`
    /// check, and each kind of joiner answers `W` to one at some point of
    /// the forwarding window. The slot's own joiner refuses every plain
    /// client frame until discovery promotes it (`NodeContext::promoted`),
    /// which comes after the handoff — so a plain `S` forwarded during the
    /// transfer would be refused outright. A lingering joiner is a
    /// confirmed member whose `known_ring` follows its own heartbeat acks,
    /// up to a heartbeat interval behind. The sender picks it as a target
    /// by the current slot's ring (the latest `M`'s roster), and in the
    /// window between a membership change and the joiner's next ack —
    /// seen as a kill, its eviction, and a restart whose `M` lands within
    /// a second — the joiner's ring still names the evicted node above it
    /// for some keys, so it answers `W` and the forward is dropped after
    /// its retries (all within the same second, so none can outlast the
    /// lag). Like the decommission's leave-forward (issue #124), a `U`
    /// skips that check: the sender's ring is the one that decided the
    /// joiner owns the key, and the `U` handler stores it as is.
    ///
    /// Why that cannot plant a copy the joiner does not own: the slot's
    /// ring is from the latest `M`, which every join delivers to every
    /// ready node before it starts; anything the joiner can have learned
    /// *sooner* than the sender arrives over heartbeat acks and is a
    /// removal (an eviction or a leave), and a removal never takes a key
    /// away from a surviving owner. The only way the joiner stops owning
    /// a key the sender's ring says it owns is a later join — and that
    /// join's `M` reaches the sender too, replacing the slot's ring.
    as_handoff: bool,
}

/// Bounded by `FORWARD_TIMEOUT` as a single whole — see that constant's
/// doc comment for why this can't just rely on `connect_and_authenticate`
/// and `send_set`'s own per-leg `OUTBOUND_IO_TIMEOUT`s.
///
/// Issue: this used to call `connect_and_authenticate` fresh on every
/// call, opening (and, once dropped, leaking into TIME_WAIT) a brand new
/// TCP+TLS+Auth connection per forwarded write — the same ephemeral-port
/// exhaustion `run_migration`'s own bulk transfer already learned to
/// avoid (see `ActiveMigration`'s doc comment on
/// `forward_connection`). Reuses `target.connection` instead, connecting
/// only when there isn't already a live connection there.
///
/// Tenth-pass audit (2026-09-02): test-only now. `forward_with_retries`
/// (the only production path a concurrent client write's forward takes —
/// see `spawn_forward`) no longer calls this: it needs `target.connection`
/// held across its *entire* retry sequence, not locked fresh per attempt
/// the way this lone-attempt primitive does, so its `attempt()` calls
/// `forward_on_locked_connection` directly instead. Kept (with
/// `forward_on_shared_connection` and `delete_on_joining_node`) as the
/// simplest way to exercise the single-attempt/connection-reuse/
/// timeout-bounding behavior in isolation, without the retry loop or its
/// own timing, in the tests that already did — see
/// `forward_on_shared_connection`'s and `forward_on_locked_connection`'s
/// own doc comments for how the two paths now share their actual I/O.
#[cfg(test)]
async fn set_on_joining_node(
    node_context: &NodeContext,
    target: &ForwardTarget,
    key: &Key,
    value: &[u8],
    ttl: Option<Duration>,
) -> io::Result<()> {
    forward_on_shared_connection(
        node_context,
        target,
        ForwardedWrite::Set { key, value, ttl },
    )
    .await
}

/// A client write being forwarded to the joining node during its
/// handoff — the two kinds `forward_on_shared_connection` knows how to
/// put on the shared connection.
enum ForwardedWrite<'a> {
    Set {
        key: &'a Key,
        value: &'a [u8],
        ttl: Option<Duration>,
    },
    Delete {
        key: &'a Key,
    },
    /// Issue #124: the decommission's forwarded write — a `U` frame
    /// rather than a plain `S`, because until discovery publishes the
    /// post-leave roster the receiving entrant doesn't own the key yet
    /// and would answer a plain `S` with `W`. Also (issue #266) how
    /// `run_migration`'s own bulk transfer sends a key to the joiner:
    /// `if_absent` is `true` there (every old owner that holds the key
    /// sends it, so more than one send for the same key is now possible
    /// and must not clobber whichever arrives first — see
    /// `run_migration`'s doc comment) and always `false` for the
    /// decommission's unconditional handoff.
    HandoffSet {
        key: &'a Key,
        value: &'a [u8],
        ttl: Option<Duration>,
        if_absent: bool,
        /// Issue #295: the receiving node's own membership token — see
        /// `Command::HandoffSet::token`.
        token: &'a str,
    },
    /// Issue #124: the decommission's forwarded delete (`u`), same
    /// wrong-node reasoning as `HandoffSet`.
    HandoffDelete {
        key: &'a Key,
        /// Issue #295: see `HandoffSet::token` above.
        token: &'a str,
    },
    Clear {
        scope: &'a ClearScope,
        token: &'a str,
    },
}

/// What a `c`/`F` clears (issue #106): one namespace, or everything.
#[derive(Clone, Debug, PartialEq, Eq)]
enum ClearScope {
    Namespace(Bytes),
    All,
}

impl ClearScope {
    /// The `f` frame that replays this clear on another node, carrying
    /// that node's membership `token` — see `Command::HandoffClear`. Not
    /// a `c`/`F`: the receiver must know this clear was forwarded, so it
    /// passes it on through its join targets as a client's clear, but
    /// through its own decommission's or re-replication's window only
    /// when it removed something there — never around a pair of nodes
    /// it changed nothing on.
    fn handoff_message(&self, token: &str) -> Vec<u8> {
        match self {
            ClearScope::Namespace(namespace) => {
                let mut message = format!("f {} {}\n", namespace.len(), token.len()).into_bytes();
                message.extend_from_slice(token.as_bytes());
                message.extend_from_slice(namespace);
                message
            }
            ClearScope::All => {
                let mut message = format!("f 0 {} A\n", token.len()).into_bytes();
                message.extend_from_slice(token.as_bytes());
                message
            }
        }
    }
}

impl ForwardedWrite<'_> {
    fn timed_out_message(&self) -> &'static str {
        match self {
            ForwardedWrite::Set { .. } | ForwardedWrite::HandoffSet { .. } => {
                "forwarding the write to the joining node timed out"
            }
            ForwardedWrite::Delete { .. } | ForwardedWrite::HandoffDelete { .. } => {
                "forwarding the delete to the joining node timed out"
            }
            ForwardedWrite::Clear { .. } => "forwarding the clear to the joining node timed out",
        }
    }

    async fn send(self, stream: &mut ClientStream) -> io::Result<()> {
        match self {
            ForwardedWrite::Set { key, value, ttl } => send_set(stream, key, value, ttl).await,
            ForwardedWrite::HandoffSet {
                key,
                value,
                ttl,
                if_absent,
                token,
            } => {
                stream
                    .write_all(&handoff_message(key, value, ttl, if_absent, token))
                    .await?;

                let mut ack = [0u8; 2];
                stream.read_exact(&mut ack).await?;

                if &ack != b"S\n" {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "peer did not acknowledge the handed-off entry",
                    ));
                }
                Ok(())
            }
            ForwardedWrite::HandoffDelete { key, token } => {
                stream
                    .write_all(&handoff_delete_message(key, token))
                    .await?;

                let mut ack = [0u8; 2];
                stream.read_exact(&mut ack).await?;

                // `D` (present there too) or `N` (this delete raced ahead
                // of the drain's own transfer of the key) both mean the
                // entrant won't serve a stale copy.
                if &ack != b"D\n" && &ack != b"N\n" {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "peer did not acknowledge the forwarded delete",
                    ));
                }
                Ok(())
            }
            ForwardedWrite::Delete { key } => {
                stream.write_all(&delete_message(key)).await?;

                let mut ack = [0u8; 2];
                stream.read_exact(&mut ack).await?;

                if &ack != b"D\n" && &ack != b"N\n" {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "joining node did not acknowledge the forwarded delete",
                    ));
                }
                Ok(())
            }
            ForwardedWrite::Clear { scope, token } => {
                stream.write_all(&scope.handoff_message(token)).await?;

                let mut ack = [0u8; 2];
                stream.read_exact(&mut ack).await?;

                if &ack != b"C\n" {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "joining node did not acknowledge the forwarded clear",
                    ));
                }
                Ok(())
            }
        }
    }
}

/// The keys (and values) of one `MultiSet` bound for a single forward
/// target — gathered so they are queued for it under one lock hold.
struct ForwardBatch {
    target: ForwardTarget,
    items: Vec<(Bytes, Bytes)>,
}

impl ForwardBatch {
    /// Adds `name`/`value` to the batch for `target`'s address, starting
    /// one if this is the first key bound there. A frame's keys go to a
    /// handful of distinct targets at most (one joiner, or the entrants
    /// of a decommission), so the linear search is over a tiny list.
    fn add(batches: &mut Vec<ForwardBatch>, target: ForwardTarget, name: Bytes, value: Bytes) {
        match batches
            .iter_mut()
            .find(|batch| batch.target.addr == target.addr)
        {
            Some(batch) => batch.items.push((name, value)),
            None => batches.push(ForwardBatch {
                target,
                items: vec![(name, value)],
            }),
        }
    }
}

/// Owned counterpart to `ForwardedWrite`, for a forward that must outlive
/// the client connection task that triggered it. `handle_connection`'s
/// `S`/`D` handling hands one of these to `forward_with_retries`, which
/// (see that function's own doc comment) is spawned via `migration_tx`
/// rather than run inline — a spawned `MigrationTask` is `'static`, so it
/// can't borrow `key`/`value` off `handle_connection`'s own stack frame
/// the way the single-shot `ForwardedWrite` does.
enum OwnedForwardedWrite {
    Set {
        key: Key,
        value: Bytes,
        ttl: Option<Duration>,
    },
    Delete {
        key: Key,
    },
    /// Issue #124: a decommission's leave-forward — sent as `U`/`u`
    /// frames (see `ForwardedWrite::HandoffSet`/`HandoffDelete` for why
    /// plain `S`/`D` won't do). `if_absent` is `false` for those (a
    /// concurrent client write must win unconditionally) and `true` only
    /// for the join relay of a re-replication put-if-absent (pass-7 audit),
    /// which must not overwrite a value the joining owner already holds.
    HandoffSet {
        key: Key,
        value: Bytes,
        ttl: Option<Duration>,
        if_absent: bool,
    },
    HandoffDelete {
        key: Key,
    },
    Clear(ClearScope),
}

impl OwnedForwardedWrite {
    /// Attempts this write once via `forward_on_locked_connection`, on a
    /// connection guard the caller (`forward_with_retries`) already
    /// holds — see that function's own doc comment and
    /// `forward_on_locked_connection`'s for why this doesn't lock
    /// `target.connection` itself the way the old single-attempt
    /// primitives (`set_on_joining_node`/`delete_on_joining_node`) still
    /// do for their own, lone-attempt callers.
    async fn attempt(
        &self,
        node_context: &NodeContext,
        target: &ForwardTarget,
        connection: &mut Option<ClientStream>,
    ) -> io::Result<()> {
        // Fresh per attempt: the lock (held by the caller across every
        // attempt) is never what this budgets — only this attempt's own
        // reconnect-plus-send.
        let deadline = tokio::time::Instant::now() + FORWARD_TIMEOUT;

        match self {
            OwnedForwardedWrite::Set { key, value, ttl } => {
                forward_on_locked_connection(
                    node_context,
                    &target.addr,
                    connection,
                    ForwardedWrite::Set {
                        key,
                        value,
                        ttl: *ttl,
                    },
                    deadline,
                )
                .await
            }
            OwnedForwardedWrite::Delete { key } => {
                forward_on_locked_connection(
                    node_context,
                    &target.addr,
                    connection,
                    ForwardedWrite::Delete { key },
                    deadline,
                )
                .await
            }
            OwnedForwardedWrite::HandoffSet {
                key,
                value,
                ttl,
                if_absent,
            } => {
                forward_on_locked_connection(
                    node_context,
                    &target.addr,
                    connection,
                    ForwardedWrite::HandoffSet {
                        key,
                        value,
                        ttl: *ttl,
                        // `false` for a decommission leave-forward (a
                        // concurrent client write must win unconditionally —
                        // see `ForwardedWrite::HandoffSet`'s own doc
                        // comment); `true` for the join relay of a
                        // re-replication put-if-absent, so the joining owner
                        // keeps any value it already holds.
                        if_absent: *if_absent,
                        // Issue #295: `target`'s own token, not this
                        // node's — see `Command::HandoffSet::token`.
                        token: &target.token,
                    },
                    deadline,
                )
                .await
            }
            OwnedForwardedWrite::HandoffDelete { key } => {
                forward_on_locked_connection(
                    node_context,
                    &target.addr,
                    connection,
                    ForwardedWrite::HandoffDelete {
                        key,
                        token: &target.token,
                    },
                    deadline,
                )
                .await
            }
            OwnedForwardedWrite::Clear(scope) => {
                forward_on_locked_connection(
                    node_context,
                    &target.addr,
                    connection,
                    ForwardedWrite::Clear {
                        scope,
                        token: &target.token,
                    },
                    deadline,
                )
                .await
            }
        }
    }

    /// The same write as the frame a target with
    /// `ForwardTarget::as_handoff` set must receive: a plain `Set` becomes
    /// an unconditional `U` (a concurrent client write wins, exactly like
    /// the decommission's leave-forward), a `Delete` a `u`. A put-if-absent
    /// relay, a handoff frame already, and a clear (not subject to the
    /// wrong-node check) are unchanged.
    fn into_handoff_frame(self) -> Self {
        match self {
            OwnedForwardedWrite::Set { key, value, ttl } => OwnedForwardedWrite::HandoffSet {
                key,
                value,
                ttl,
                if_absent: false,
            },
            OwnedForwardedWrite::Delete { key } => OwnedForwardedWrite::HandoffDelete { key },
            other => other,
        }
    }

    /// Names the write kind for the WARN logs `forward_with_retries`
    /// emits — mirrors the `SET`/`DELETE` wire command letters informally,
    /// not the actual `S`/`D` protocol bytes.
    fn kind(&self) -> &'static str {
        match self {
            OwnedForwardedWrite::Set { .. } | OwnedForwardedWrite::HandoffSet { .. } => "SET",
            OwnedForwardedWrite::Delete { .. } | OwnedForwardedWrite::HandoffDelete { .. } => {
                "DELETE"
            }
            OwnedForwardedWrite::Clear(_) => "CLEAR",
        }
    }
}

/// Combines writes waiting for the same target. `Some(key)` for the
/// unconditional single-key writes (`Set`, `Delete`, and the leave-forward
/// `HandoffSet`/`HandoffDelete`): each overwrites whatever the target holds
/// for `key`, so of several waiting for the same key only the last matters.
/// `None` for the ones that must keep their place in the order: a
/// put-if-absent relay (its effect depends on what the target holds when it
/// arrives) and a clear.
fn coalescing_key(write: &OwnedForwardedWrite) -> Option<&Key> {
    match write {
        OwnedForwardedWrite::Set { key, .. }
        | OwnedForwardedWrite::Delete { key }
        | OwnedForwardedWrite::HandoffSet {
            key,
            if_absent: false,
            ..
        }
        | OwnedForwardedWrite::HandoffDelete { key } => Some(key),
        OwnedForwardedWrite::HandoffSet {
            if_absent: true, ..
        }
        | OwnedForwardedWrite::Clear(_) => None,
    }
}

impl ForwardTarget {
    fn duplicate(&self) -> ForwardTarget {
        ForwardTarget {
            addr: self.addr.clone(),
            connection: Arc::clone(&self.connection),
            token: self.token.clone(),
            revoked: Arc::clone(&self.revoked),
            as_handoff: self.as_handoff,
        }
    }
}

/// The writes waiting to be forwarded to one target, in the order they
/// must be sent. A write to a key that already has one waiting *replaces*
/// it (see `coalescing_key`), so the queue is bounded by the number of
/// distinct keys written while the target is slow or busy, never by the
/// number of writes: forwarding a burst to a slow target loses nothing and
/// does not grow without bound.
///
/// Why replacing is safe: only the last write to a key decides what the
/// target ends up holding, and the entry keeps the *position* of the first
/// one, which is no later than where the new write would have gone. The
/// two things that would make that wrong both break the slot instead of
/// being coalesced across: a clear (it empties `slots`, so nothing queued
/// before it is replaced by something after it) and a put-if-absent relay
/// (it removes its own key's slot, since replacing an earlier `Set` with a
/// later `Delete` across it would let the relay store its older value).
struct TargetQueue {
    node_context: NodeContext,
    target: ForwardTarget,
    ops: BTreeMap<u64, Queued>,
    next_seq: u64,
    /// What the queued writes pin, as `MAX_FORWARD_QUEUE_BYTES` counts
    /// it: each write's key name and value plus
    /// `FORWARD_ENTRY_OVERHEAD_BYTES`, and each namespace allocation
    /// once — the keys of one frame share theirs, and a client write's
    /// slices pin its frame whether one key references it or a hundred
    /// thousand do. Kept exact by `charge`/`release`.
    bytes: usize,
    /// Namespace allocations the queued writes reference, by (pointer,
    /// length), with how many writes share each: the namespace's bytes
    /// are charged when the first arrives and released when the last
    /// leaves.
    namespaces: HashMap<(usize, usize), usize>,
    /// For each key, the sequence number of the write in `ops` that a new
    /// write to it replaces.
    slots: HashMap<SlotKey, u64>,
    /// Hashes the slot keys: a namespace is hashed once per run of keys
    /// sharing its allocation (a multi-key frame's keys do), not once
    /// per lookup — see `SlotKey`.
    hasher: KeyHasher,
    /// A drainer (`drain_forward_queue`) is running or has been handed to
    /// `run`; at most one runs per queue, which is what keeps the order.
    draining: bool,
}

/// `TargetQueue::slots`' key: the key plus its canonical hash, which is
/// what the map hashes and compares first. `Key`'s derived `Hash` feeds
/// the whole namespace to the map's hasher on every `get`/`insert`/
/// `remove`, so queuing the keys of one `o` frame under a 100 KB
/// namespace cost 2 × keys × 100 KB of hashing on the thread that serves
/// every connection — an 8 s stall for 100,000 keys. The canonical hash
/// is computed once per key by the queue's `KeyHasher`, and equality
/// checks the namespace by allocation identity before its bytes.
#[derive(Debug)]
struct SlotKey {
    hash: u64,
    key: Key,
}

impl SlotKey {
    fn of(hasher: &mut KeyHasher, key: &Key) -> Self {
        Self {
            hash: hasher.hash(key).as_u64(),
            key: key.clone(),
        }
    }
}

impl std::hash::Hash for SlotKey {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        state.write_u64(self.hash);
    }
}

impl PartialEq for SlotKey {
    fn eq(&self, other: &Self) -> bool {
        self.hash == other.hash
            && self.key.name == other.key.name
            && (self.key.namespace.as_ptr() == other.key.namespace.as_ptr()
                && self.key.namespace.len() == other.key.namespace.len()
                || self.key.namespace == other.key.namespace)
    }
}

impl Eq for SlotKey {}

/// A write in a `TargetQueue` with what it was charged (`entry_bytes`
/// at the time), so its release is exact whatever the write is replaced
/// by or popped as.
struct Queued {
    write: OwnedForwardedWrite,
    bytes: usize,
}

/// What `write` costs a queue on its own: its key name and value (a
/// clear's namespace name), plus `FORWARD_ENTRY_OVERHEAD_BYTES`. The
/// namespace is charged separately, once per allocation — see
/// `TargetQueue::namespaces`.
fn entry_bytes(write: &OwnedForwardedWrite) -> usize {
    let own = match write {
        OwnedForwardedWrite::Set { key, value, .. }
        | OwnedForwardedWrite::HandoffSet { key, value, .. } => key.name.len() + value.len(),
        OwnedForwardedWrite::Delete { key } | OwnedForwardedWrite::HandoffDelete { key } => {
            key.name.len()
        }
        OwnedForwardedWrite::Clear(ClearScope::Namespace(namespace)) => namespace.len(),
        OwnedForwardedWrite::Clear(ClearScope::All) => 0,
    };
    own + FORWARD_ENTRY_OVERHEAD_BYTES
}

/// The namespace allocation `write` references, as `TargetQueue::namespaces`
/// keys it; none for the default namespace or a clear.
fn namespace_allocation(write: &OwnedForwardedWrite) -> Option<(usize, usize)> {
    let key = match write {
        OwnedForwardedWrite::Set { key, .. }
        | OwnedForwardedWrite::HandoffSet { key, .. }
        | OwnedForwardedWrite::Delete { key }
        | OwnedForwardedWrite::HandoffDelete { key } => key,
        OwnedForwardedWrite::Clear(_) => return None,
    };
    if key.namespace.is_empty() {
        return None;
    }
    Some((key.namespace.as_ptr() as usize, key.namespace.len()))
}

/// What a batch of writes will add to a queue's `bytes` if queued now:
/// every write's `entry_bytes`, and each namespace allocation in the
/// batch once. Over by a namespace the queue already holds; never under.
fn batch_bytes(writes: &[OwnedForwardedWrite]) -> usize {
    let mut namespaces = std::collections::HashSet::new();
    writes
        .iter()
        .map(|write| {
            entry_bytes(write)
                + namespace_allocation(write)
                    .filter(|allocation| namespaces.insert(*allocation))
                    .map_or(0, |(_, len)| len)
        })
        .sum()
}

impl TargetQueue {
    fn new(node_context: NodeContext, target: ForwardTarget) -> Self {
        Self {
            node_context,
            target,
            ops: BTreeMap::new(),
            next_seq: 0,
            bytes: 0,
            namespaces: HashMap::new(),
            slots: HashMap::new(),
            hasher: KeyHasher::default(),
            draining: false,
        }
    }

    /// Accounts `write` into `bytes`; returns what the entry itself was
    /// charged, to hand back to `release` with it.
    fn charge(&mut self, write: &OwnedForwardedWrite) -> usize {
        let bytes = entry_bytes(write);
        self.bytes += bytes;
        if let Some(allocation) = namespace_allocation(write) {
            let sharers = self.namespaces.entry(allocation).or_insert(0);
            if *sharers == 0 {
                self.bytes += allocation.1;
            }
            *sharers += 1;
        }
        bytes
    }

    fn release(&mut self, write: &OwnedForwardedWrite, bytes: usize) {
        self.bytes -= bytes;
        if let Some(allocation) = namespace_allocation(write)
            && let Some(sharers) = self.namespaces.get_mut(&allocation)
        {
            *sharers -= 1;
            if *sharers == 0 {
                self.namespaces.remove(&allocation);
                self.bytes -= allocation.1;
            }
        }
    }

    fn append(&mut self, queued: Queued) -> u64 {
        let seq = self.next_seq;
        self.next_seq += 1;
        self.ops.insert(seq, queued);
        seq
    }

    fn push(&mut self, write: OwnedForwardedWrite) {
        let bytes = self.charge(&write);
        if let Some(key) = coalescing_key(&write) {
            let slot = SlotKey::of(&mut self.hasher, key);
            if let Some(waiting) = self.slots.get(&slot).and_then(|seq| self.ops.get_mut(seq)) {
                let replaced = std::mem::replace(waiting, Queued { write, bytes });
                self.release(&replaced.write, replaced.bytes);
                return;
            }
            let seq = self.append(Queued { write, bytes });
            self.slots.insert(slot, seq);
            return;
        }
        match &write {
            OwnedForwardedWrite::Clear(_) => self.slots.clear(),
            OwnedForwardedWrite::HandoffSet { key, .. } => {
                let slot = SlotKey::of(&mut self.hasher, key);
                self.slots.remove(&slot);
            }
            _ => {}
        }
        self.append(Queued { write, bytes });
    }

    fn pop(&mut self) -> Option<OwnedForwardedWrite> {
        let (seq, queued) = self.ops.pop_first()?;
        self.release(&queued.write, queued.bytes);
        if let Some(key) = coalescing_key(&queued.write) {
            let slot = SlotKey::of(&mut self.hasher, key);
            if self.slots.get(&slot) == Some(&seq) {
                self.slots.remove(&slot);
            }
        }
        Some(queued.write)
    }
}

/// Every target's `TargetQueue`, by the address of its shared connection
/// (`ForwardTarget::connection`; the queue holds a clone of the target, so
/// the address cannot be reused while the entry exists). An entry exists
/// only while it has writes waiting or a drainer working on it.
#[derive(Default)]
struct ForwardQueues {
    targets: Mutex<HashMap<usize, TargetQueue>>,
    /// Woken whenever a queue gives bytes back (a pop, a removal), for
    /// the pushes waiting on `MAX_FORWARD_QUEUE_BYTES`.
    room: tokio::sync::Notify,
}

impl ForwardQueues {
    /// Queues `writes` for `target`, waiting while the target's queue is
    /// at `MAX_FORWARD_QUEUE_BYTES` until a drainer has popped enough
    /// for the batch to fit (a batch larger than the whole bound is
    /// admitted into an empty queue, so it can never wait forever).
    /// Returns the queue's id if the caller must now start a drainer for
    /// it, `None` if one is already running.
    ///
    /// A full queue with no drainer is admitted into as well: the wait
    /// is for a drainer to make room, and a queue `deactivate` left
    /// non-empty — its drainer could not be handed to `run` — has none,
    /// so a push that waited on it waited forever, and with it the
    /// client connection that made it (a push runs before the ack).
    /// Admitting it lets this push hand in the drainer that works the
    /// queue down.
    async fn push(
        &self,
        node_context: &NodeContext,
        target: ForwardTarget,
        writes: impl IntoIterator<Item = OwnedForwardedWrite>,
    ) -> Option<usize> {
        let id = Arc::as_ptr(&target.connection) as usize;
        // Decided by the target this push resolved, not the one the queue
        // was created with: the same connection serves a joiner first as
        // the slot's own and later as a lingering one.
        let as_handoff = target.as_handoff;
        let writes: Vec<OwnedForwardedWrite> = writes
            .into_iter()
            .map(|write| {
                if as_handoff {
                    write.into_handoff_frame()
                } else {
                    write
                }
            })
            .collect();
        let wanted = batch_bytes(&writes);
        let mut target = Some(target);
        loop {
            // Registered before the lock is taken, so a pop between the
            // check and the wait still wakes this.
            let room = self.room.notified();
            {
                let mut targets = self
                    .targets
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                let (used, draining) = targets
                    .get(&id)
                    .map_or((0, false), |queue| (queue.bytes, queue.draining));
                if used == 0 || !draining || used + wanted <= MAX_FORWARD_QUEUE_BYTES {
                    let queue = targets.entry(id).or_insert_with(|| {
                        TargetQueue::new(
                            node_context.clone(),
                            target.take().expect("the queue is created once"),
                        )
                    });
                    for write in writes {
                        queue.push(write);
                    }
                    return if std::mem::replace(&mut queue.draining, true) {
                        None
                    } else {
                        Some(id)
                    };
                }
            }
            room.await;
        }
    }

    /// The next write for queue `id`, with what is needed to send it; when
    /// there is none the queue is removed (under the same lock a `push`
    /// takes, so a write cannot slip in between and be left undrained).
    fn next(&self, id: usize) -> Option<(NodeContext, ForwardTarget, OwnedForwardedWrite)> {
        let mut targets = self
            .targets
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let queue = targets.get_mut(&id)?;
        let next = match queue.pop() {
            Some(write) => Some((queue.node_context.clone(), queue.target.duplicate(), write)),
            None => {
                targets.remove(&id);
                None
            }
        };
        drop(targets);
        self.room.notify_waiters();
        next
    }

    /// Marks queue `id` as having no drainer, so the next `push` starts
    /// one. Used when a drainer could not be handed over or died.
    fn deactivate(&self, id: usize) {
        let mut targets = self
            .targets
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(queue) = targets.get_mut(&id) {
            queue.draining = false;
            if queue.ops.is_empty() {
                targets.remove(&id);
            }
        }
        drop(targets);
        self.room.notify_waiters();
    }
}

/// Sends queue `id`'s writes, one at a time in order, until it is empty.
/// One of these runs per target with writes waiting, spawned by `run`.
async fn drain_forward_queue(queues: Arc<ForwardQueues>, id: usize) {
    // Whatever ends this task early (a panic, or `run` dropping it at
    // shutdown) must not leave the queue marked as being drained.
    struct Deactivate(Arc<ForwardQueues>, usize);
    impl Drop for Deactivate {
        fn drop(&mut self) {
            self.0.deactivate(self.1);
        }
    }
    let _guard = Deactivate(Arc::clone(&queues), id);

    while let Some((node_context, target, write)) = queues.next(id) {
        #[cfg(test)]
        node_context.gates.forward.wait().await;
        forward_with_retries(node_context, target, write).await;
    }
}

/// The one place a forwarded write touches `ForwardTarget::connection`:
/// takes the shared connection (dialing it if there is none), sends
/// `write` on it, and — crucially — resets the slot to `None` whenever
/// the stream's state is no longer known to be clean: after the send
/// fails, and after the whole forward times out.
///
/// The timeout case is why the guard is taken *outside* the
/// `timeout_at`: cancelling a future that holds the guard drops the
/// guard but runs none of its cleanup, so a forward that timed out
/// mid-write (a partial `S` frame on the wire) would have left the
/// desynced stream in place for the next forward to reuse, which would
/// then read the *previous* forward's late ack as its own. Holding the
/// guard across the deadline lets the timeout branch clear the slot
/// itself. Waiting for the guard still counts against the same
/// `FORWARD_TIMEOUT` deadline, so the call as a whole stays bounded even
/// when another forward is holding the connection.
///
/// Tenth-pass audit (2026-09-02): test-only now, alongside
/// `set_on_joining_node`/`delete_on_joining_node` — see
/// `set_on_joining_node`'s doc comment for why the production path
/// (`forward_with_retries`) no longer reaches this, and
/// `forward_on_locked_connection` for the actual I/O both paths share.
#[cfg(test)]
async fn forward_on_shared_connection(
    node_context: &NodeContext,
    target: &ForwardTarget,
    write: ForwardedWrite<'_>,
) -> io::Result<()> {
    let timed_out_message = write.timed_out_message();
    let timed_out = || io::Error::new(io::ErrorKind::TimedOut, timed_out_message);
    let deadline = tokio::time::Instant::now() + FORWARD_TIMEOUT;

    let mut connection = tokio::time::timeout_at(deadline, target.connection.lock())
        .await
        .map_err(|_| timed_out())?;

    forward_on_locked_connection(node_context, &target.addr, &mut connection, write, deadline).await
}

/// `forward_on_shared_connection`'s guts — reconnect-if-needed, send,
/// clear the slot on anything but a clean success — factored out so a
/// caller that must hold `target.connection`'s guard across *more* than
/// one attempt (`forward_with_retries`, below) can call this directly
/// instead of going through `forward_on_shared_connection`, which insists
/// on locking `target.connection` itself. Locking it again while a guard
/// from an outer scope is already held would deadlock —
/// `tokio::sync::Mutex` isn't reentrant — which is exactly the shape
/// `forward_with_retries`'s per-attempt loop needs to avoid now that it
/// holds the lock across every attempt (Tenth-pass audit, 2026-09-02;
/// see that function's own doc comment).
///
/// `deadline` is the caller's to set: `forward_on_shared_connection`
/// passes through the same one it used to bound the lock wait — one
/// `FORWARD_TIMEOUT` for the whole call, unchanged — while
/// `forward_with_retries` gives each attempt its own fresh
/// `FORWARD_TIMEOUT` (the lock is already held by the time it's called,
/// so there's no wait to fold into that budget).
async fn forward_on_locked_connection(
    node_context: &NodeContext,
    addr: &str,
    connection: &mut Option<ClientStream>,
    write: ForwardedWrite<'_>,
    deadline: tokio::time::Instant,
) -> io::Result<()> {
    let timed_out_message = write.timed_out_message();
    let timed_out = || io::Error::new(io::ErrorKind::TimedOut, timed_out_message);

    let result = tokio::time::timeout_at(deadline, async {
        if connection.is_none() {
            *connection = Some(connect_and_authenticate(node_context, addr, AuthPeer::Node).await?);
        }
        // Just ensured `Some` above (and nothing else can steal the slot
        // back to `None` while this guard is held).
        let stream = connection
            .as_mut()
            .expect("connection was just established");
        write.send(stream).await
    })
    .await;

    match result {
        Ok(Ok(())) => Ok(()),
        Ok(Err(error)) => {
            // The connection's state after a failed write/read is
            // unknown (e.g. a partial write) — drop it so the next
            // forward reconnects rather than risk a desynced stream,
            // mirroring `run_migration`'s own per-key retry on its
            // separate connection.
            *connection = None;
            Err(error)
        }
        Err(_elapsed) => {
            *connection = None;
            Err(timed_out())
        }
    }
}

/// Retries a forwarded write's `forward_on_shared_connection` call up to
/// `KEY_TRANSFER_ATTEMPTS` times — the same budget `run_migration`'s bulk
/// transfer gives each key (see `KEY_TRANSFER_ATTEMPTS`). Previously the
/// concurrent-write forward path (`handle_connection`'s `S`/`D` handling,
/// via `set_on_joining_node`/`delete_on_joining_node`) called
/// `forward_on_shared_connection` exactly once and only logged on
/// failure, unlike the bulk transfer's own per-key retry loop — a single
/// transient failure on the shared forwarding connection (a reset TCP
/// connection, a joining node that's momentarily too busy to ack) would
/// permanently drop a concurrent client's write, even though the exact
/// same blip is tolerated during the bulk handoff.
///
/// Spawned via `spawn_forward`/`forward_tx` (mirroring how the `M` handler
/// hands `run_migration` itself to `run`'s own loop via `migration_tx` —
/// see `ConnectionConfig::forward_tx` for why this gets its own channel
/// rather than sharing that one, issue #219) rather than awaited inline in
/// `handle_connection`, which is where `set_on_joining_node`/
/// `delete_on_joining_node` used to be called from directly.
/// `forward_on_shared_connection` is deliberately bounded to a single
/// `FORWARD_TIMEOUT` specifically so a client's connection is never
/// stalled by more than one multiple of it (see that constant's own doc
/// comment, which spells out the same "worst case: one multiple, not
/// several" reasoning this respects); retrying it up to
/// `KEY_TRANSFER_ATTEMPTS` times *inline*, the way this now does to match
/// `run_migration`'s own per-key resilience, would multiply that worst
/// case by up to 3x and hold up every command queued behind it on this
/// connection. Running the retries in the background — the client's own
/// `S`/`D` response was already written before this is spawned — keeps
/// this connection's stall at zero while still giving the forward the
/// same retry budget the bulk transfer gets. The trade-off: a client that
/// immediately re-reads the same key from a *different* node than the one
/// this forward eventually reaches can observe a brief window where the
/// forward hasn't landed yet — already true of the single-attempt design
/// this replaces (see `forwarding_grace`, which exists precisely because
/// that window isn't instant), just now bounded by up to
/// `KEY_TRANSFER_ATTEMPTS` x `FORWARD_TIMEOUT` instead of one.
///
/// Tenth-pass audit (2026-09-02): `target.connection`'s guard is acquired
/// once here, before the retry loop, and held for every attempt in it —
/// not reacquired per attempt the way a lone call through
/// `forward_on_shared_connection` does. Before this, two concurrent
/// forwards to the *same* key (e.g. a client overwriting a key twice in
/// quick succession while it's mid-handoff) could interleave their
/// attempts: forward A's attempt 1 fails and drops the connection: before
/// A's attempt 2 runs, forward B — a newer write to the same key, spawned
/// moments later — could acquire the now-free connection, send, and
/// succeed, landing *before* A's own retry lands moments after it. On the
/// target that's a stale value winning over a fresher one, silently
/// violating last-writer-wins.
///
/// Holding the lock for the whole sequence fixes this only if forwards
/// actually reach `target.connection.lock()` in the same order they were
/// enqueued — verified true here: `spawn_forward` hands each forward to
/// `run`'s `forward_rx` consumer in the order `try_send`/the waiter's
/// `send` succeeded, which is the order `handle_connection` issued the
/// underlying writes in (each connection's own writes are already
/// serialized, one in flight at a time); that consumer spawns each into
/// `connection_tasks` in the order it receives them from the channel
/// (FIFO); and the whole process runs `#[tokio::main(flavor =
/// "current_thread")]` (see `main.rs`) — one OS thread, cooperative
/// scheduling, no other `.await` between a task being spawned and this
/// function's very first line — so freshly spawned forward tasks reach
/// `target.connection.lock().await` in spawn order, and `tokio::sync::
/// Mutex`'s FIFO-fair wait queue keeps that the acquisition order too.
/// (A multi-threaded runtime would need a dedicated per-target ordered
/// worker instead of this reasoning — noted here since it's the kind of
/// invariant a runtime-flavor change could silently break.)
///
/// Deliberately *not* bounded by a timeout: a forward waiting for its
/// turn on a busy target isn't stuck or failed, just queued — timing out
/// the wait and giving up would let a later-enqueued forward jump ahead
/// of it, exactly the reordering this exists to prevent. The wait is
/// still finite in practice, bounded by how many forwards to the same
/// target are outstanding at once (`MAX_IN_FLIGHT_FORWARDS` parked tasks,
/// plus `FORWARD_CHANNEL_CAPACITY` + `MAX_PENDING_FORWARD_WAITERS` still
/// queued behind them — `run` stops spawning once the first is reached)
/// times each one's own worst case
/// (`KEY_TRANSFER_ATTEMPTS` x `FORWARD_TIMEOUT`) — and, tenth-pass
/// follow-up (2026-09-04), that worst case only applies to the *first*
/// forward to hit an unreachable target: once one has failed permanently,
/// the ones queued behind it make a single attempt each until the target
/// answers again (`RECENT_FORWARD_FAILURES`), so a dead target drains its
/// queue at one `FORWARD_TIMEOUT` per forward, not three.
async fn forward_with_retries(
    node_context: NodeContext,
    target: ForwardTarget,
    write: OwnedForwardedWrite,
) {
    let mut connection = target.connection.lock().await;
    let attempts = forward_attempts_for(&target.addr, &target.token);

    for attempt in 1..=attempts {
        // Issue #474: re-checked before every attempt, not just once —
        // the wait for the lock above and each failed attempt's timeout
        // are exactly the windows in which the target goes stale.
        if target.revoked.load(Ordering::SeqCst) {
            return;
        }
        match write.attempt(&node_context, &target, &mut connection).await {
            Ok(()) => {
                clear_forward_failure(&target.addr, &target.token);
                return;
            }
            Err(error) => {
                eprintln!(
                    "WARN failed to forward a concurrent {} for a migrating key to {} \
                     (attempt {attempt}/{attempts}): {error}",
                    write.kind(),
                    target.addr
                );
            }
        }
    }

    record_forward_failure(&target.addr, &target.token);
    eprintln!(
        "WARN permanently failed to forward a concurrent {} for a migrating key to {} after \
         {attempts} attempt(s)",
        write.kind(),
        target.addr
    );
}

/// This node's own current view of cluster membership, if it has one yet
/// (see `NodeContext::known_ring`) says `key` isn't this node's to serve
/// anymore.
///
/// Not while the handoff that displaced `key` is still forwarding, though
/// (`migration_target_for`): `known_ring` flips as soon as *this node's*
/// share of a join is done, but discovery only publishes the joiner in `L`
/// once *every* ready node has reported `C` — which, with size-derived
/// timeouts (size-derived migration timeout), can be minutes after a small node finishes.
/// In that gap a client's `L` still names this node as the owner and a
/// refresh-and-retry gets the very same list, so rejecting here would make
/// the key plainly unavailable (an error, not a miss) for R=1. Serving it
/// locally — and forwarding `S`/`D` to the joiner, which the handlers
/// already do for exactly this window — is what keeps the join invisible
/// to clients.
///
/// Only until discovery has confirmed the join, though (issue #66):
/// from then on `L` does list the joiner, so a `W` is exactly what a
/// still-stale client needs — its refresh-and-retry lands on the joiner
/// — whereas serving locally would hand out this node's dead copy (which
/// the sweep is about to reclaim, and which writes sent straight to the
/// joiner no longer update): every read that reached this node in the
/// rest of the forwarding window missed (`N`) once the sweep had run.
/// Write forwarding keeps going for the whole window regardless.
///
/// And every key is the wrong node's until discovery has promoted this
/// node (`NodeContext::promoted`): a request that arrives before then came
/// over a connection a client opened to this address under an evicted
/// member's name, and a `W` — not a local `N` for a key the handoff hasn't
/// delivered yet — is what sends it to refresh and retry elsewhere.
/// How often `refresh_published_roster` asks discovery at most, and how
/// long one ask may take. A refresh happens only for a key the adopted
/// ring does not grant — in steady state a client with a stale list — so
/// a flood of such keys costs one fetch a second, and a key answered
/// while one is in flight waits for that fetch rather than starting its
/// own.
const ROSTER_REFRESH_COOLDOWN: Duration = Duration::from_secs(1);
const ROSTER_REFRESH_TIMEOUT: Duration = Duration::from_secs(1);

/// State of `refresh_published_roster`: one fetch in flight at a time,
/// and when the last one finished (whether or not it succeeded).
#[derive(Default)]
struct RosterRefresh {
    in_flight: AsyncMutex<()>,
    last: Mutex<Option<Instant>>,
    /// Bumped by the heartbeat loop each time it notes a roster
    /// (`note_heartbeat`): a fetch that started before such a note holds
    /// an older view than the heartbeat delivered meanwhile, and must not
    /// put it back — `latest_published` widens what this node serves, so
    /// an older roster could re-refuse a key the newer one grants until
    /// the next heartbeat.
    heartbeats: AtomicU64,
}

impl RosterRefresh {
    fn cooling_down(&self) -> bool {
        self.last
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .is_some_and(|at| at.elapsed() < ROSTER_REFRESH_COOLDOWN)
    }

    /// The heartbeat loop just noted a roster — see `heartbeats`.
    fn note_heartbeat(&self) {
        self.heartbeats.fetch_add(1, Ordering::SeqCst);
    }
}

/// Brings `NodeContext::latest_published` up to what discovery publishes
/// now, by asking it for the list clients route by (`L`), when the last
/// ask is older than `ROSTER_REFRESH_COOLDOWN`. `L`, not `T`: the node
/// roster lists every registered node, a `Waiting` or `Joining` one
/// included, and a ring with such a node in it grants this node fewer
/// keys than the published list does — the refresh would then refuse,
/// for the rest of a heartbeat, exactly the keys it exists to serve.
/// The heartbeat loop learns a membership
/// change only on its next tick, up to `HEARTBEAT_INTERVAL` after
/// discovery published it — and withholds adopting it for as long as a
/// join is pending here — while a client that fetched `L` in between
/// already routes by it; asked for a key it does not own under its
/// adopted ring, this node asks discovery before answering `W`. Bounded
/// by `ROSTER_REFRESH_TIMEOUT`; a failed or slow ask leaves the view as
/// it was and starts the cooldown too, so an unreachable discovery costs
/// a misrouted key one bounded wait a second, not one each.
async fn refresh_published_roster(node_context: &NodeContext) {
    let refresh = &node_context.roster_refresh;
    if refresh.cooling_down() {
        return;
    }
    let _in_flight = refresh.in_flight.lock().await;
    // The fetch that was in flight while this waited counts for it.
    if refresh.cooling_down() {
        return;
    }
    let heartbeats_before = refresh.heartbeats.load(Ordering::SeqCst);
    let fetched = timeout(
        ROSTER_REFRESH_TIMEOUT,
        fetch_published_roster_once(node_context, &node_context.discovery_addr),
    )
    .await;
    *refresh
        .last
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(Instant::now());
    if let Ok(Ok(Some((names, replication)))) = fetched
        // A heartbeat ack that landed while this fetch ran is the newer
        // view; what the fetch returned must not replace it.
        && refresh.heartbeats.load(Ordering::SeqCst) == heartbeats_before
    {
        note_published_roster(&node_context.latest_published, &names, replication);
    }
}

/// One `L` to discovery at `addr`: the roster clients route by — names
/// and replication — or `None` while discovery withholds it (`B`).
async fn fetch_published_roster_once(
    node_context: &NodeContext,
    addr: &str,
) -> io::Result<Option<(Vec<String>, usize)>> {
    let stream = connect_and_authenticate(node_context, addr, AuthPeer::Discovery).await?;
    let mut stream = tokio::io::BufReader::new(stream);
    stream.write_all(b"L\n").await?;
    read_published_roster(&mut stream).await
}

/// `wrong_node` for a request that will be answered `W` if it holds:
/// before it is, the published roster is refreshed
/// (`refresh_published_roster`) and the key judged again, so a key this
/// node owns under what discovery publishes now is served rather than
/// refused. A node discovery has not promoted yet refuses without
/// asking: nothing discovery publishes grants it a key.
async fn wrong_node_refreshed(node_context: &NodeContext, key: &Key) -> bool {
    let key_hash = KeyHash::of(key);
    if !wrong_node_hashed(node_context, key_hash) {
        return false;
    }
    if !node_context.promoted.load(Ordering::SeqCst) {
        return true;
    }
    refresh_published_roster(node_context).await;
    wrong_node_hashed(node_context, key_hash)
}

/// `wrong_node_refreshed` for the keys of one `m`/`o` frame: one refresh
/// for the frame if any key came out wrong, then those keys judged again.
async fn wrong_nodes_refreshed(node_context: &NodeContext, hashes: &[KeyHash]) -> Vec<bool> {
    let mut wrong: Vec<bool> = hashes
        .iter()
        .map(|hash| wrong_node_hashed(node_context, *hash))
        .collect();
    if wrong.iter().any(|wrong| *wrong) && node_context.promoted.load(Ordering::SeqCst) {
        refresh_published_roster(node_context).await;
        for (wrong, hash) in wrong.iter_mut().zip(hashes) {
            if *wrong {
                *wrong = wrong_node_hashed(node_context, *hash);
            }
        }
    }
    wrong
}

/// `wrong_node_hashed` by key — what the request arms used before every
/// `W` came to ask discovery first (`wrong_node_refreshed`); tests still
/// judge a key by the rings alone with it.
#[cfg(test)]
fn wrong_node(node_context: &NodeContext, key: &Key) -> bool {
    wrong_node_hashed(node_context, KeyHash::of(key))
}

/// `wrong_node` for the non-idempotent commands (`i`, `k`, `x`): true
/// unless this node is the key's *primary* under the adopted ring, not
/// merely one of its owners. A plain write is accepted by every owner
/// because the client fans it out to all of them; an increment or a
/// compare-and-set runs once, on the primary, and the result is then
/// written to the other owners as a plain `S`. Accepting it on a replica
/// too let a client with a stale ring (after a join, the old primary is
/// still an owner at rank 2) and a client with the fresh ring both run
/// the same `put_if_absent`, both win the same CAS, or both get the same
/// counter value, for as long as the stale client kept its ring. A `W`
/// here sends the stale client to refresh and retry on the primary.
///
/// The unconfirmed-join exception stays as it is: until discovery lists
/// the joiner, clients cannot route to it, so the displaced node keeps
/// serving exactly what `wrong_node` lets it serve.
///
/// Judged by the adopted ring when it grants the key at all, and by the
/// newest published ring (`NodeContext::latest_published`) when only
/// that one does — the entrant after a leave or an eviction, whose own
/// ring still lags: it is the key's primary under what discovery
/// publishes, and the client already routes by it.
fn not_the_primary(node_context: &NodeContext, key: &Key) -> bool {
    let key_hash = KeyHash::of(key);
    if wrong_node_hashed(node_context, key_hash) {
        return true;
    }
    if serving_locally_for_unconfirmed_join(node_context, key_hash) {
        return false;
    }
    let primary_under = |membership: &Membership| {
        membership
            .ring
            .is_owner_hashed(key_hash, &node_context.name, 1)
    };
    let adopted = node_context
        .known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .clone();
    let Some(adopted) = adopted else {
        return false; // no ring adopted: everything is this node's, as for a plain write
    };
    if adopted
        .ring
        .is_owner_hashed(key_hash, &node_context.name, adopted.replication)
    {
        return !primary_under(&adopted);
    }
    !node_context
        .latest_published
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .is_some_and(|published| primary_under(published))
}

/// `not_the_primary` for a request that will be answered `W` if it
/// holds: the published roster is refreshed first, as
/// `wrong_node_refreshed` does for a plain write.
async fn not_the_primary_refreshed(node_context: &NodeContext, key: &Key) -> bool {
    if !not_the_primary(node_context, key) {
        return false;
    }
    if !node_context.promoted.load(Ordering::SeqCst) {
        return true;
    }
    refresh_published_roster(node_context).await;
    not_the_primary(node_context, key)
}

/// Issue #601: whether this node owns `key` under the membership it has
/// adopted (`known_ring`, anywhere in the key's top-R) — what the `U` arm
/// tells the cache so a handoff write for a key already owned is not
/// taken for one that arrived ahead of its ring (`Cache::handoff_set`'s
/// `ahead_of_ring`). Nothing adopted yet, or not an owner: the key is
/// ahead of its ring. Unlike `wrong_node` this ignores `promoted` and the
/// unconfirmed-join exception — it asks which ring covers the key, not
/// whether to serve it.
fn owns_under_known_ring(node_context: &NodeContext, key: &Key) -> bool {
    node_context
        .known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .is_some_and(|membership| {
            membership
                .ring
                .is_owner(key, &node_context.name, membership.replication)
        })
}

/// `wrong_node` for a key whose hash is already known — what the
/// multi-key arms use so a frame's (potentially huge) shared namespace is
/// hashed once, not once per key.
fn wrong_node_hashed(node_context: &NodeContext, key_hash: KeyHash) -> bool {
    if !node_context.promoted.load(Ordering::SeqCst) {
        return true;
    }
    let displaced = node_context
        .known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .is_some_and(|membership| {
            // Client-side replication: this node serves a key when it's anywhere in the
            // key's top-R, not only when it's the primary.
            !membership
                .ring
                .is_owner_hashed(key_hash, &node_context.name, membership.replication)
        });

    displaced
        && !serving_locally_for_unconfirmed_join(node_context, key_hash)
        && !owns_under_latest_published(node_context, key_hash)
}

/// Whether this node owns the key under the newest roster discovery
/// published (`NodeContext::latest_published`), which the adopted ring
/// may lag by up to a heartbeat — longer while a join is pending here.
/// Only ever widens what this node accepts: a key the adopted ring grants
/// is never re-examined, and the key is served from this node's own store
/// either way (a copy it does not hold yet is a miss, as for any new
/// owner until re-replication).
fn owns_under_latest_published(node_context: &NodeContext, key_hash: KeyHash) -> bool {
    node_context
        .latest_published
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .is_some_and(|membership| {
            membership
                .ring
                .is_owner_hashed(key_hash, &node_context.name, membership.replication)
        })
}

/// `wrong_node`'s exception: a handoff this node ran is still forwarding
/// `key` to a joiner discovery hasn't confirmed yet (see
/// `ActiveMigration::confirmed`), so this node is the only owner a
/// client's `L` can name and must keep serving the key itself.
fn serving_locally_for_unconfirmed_join(node_context: &NodeContext, key_hash: KeyHash) -> bool {
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    // Same lazy expiry as `migration_target_for`.
    if slot.as_ref().is_some_and(ActiveMigration::expired) {
        *slot = None;
    }
    slot.as_ref().is_some_and(|active| {
        !active.confirmed
            && active.forwarding_open()
            && active
                .after_ring
                .is_owner_hashed(key_hash, &active.joining_name, active.replication)
    })
}

/// If a handoff is currently in flight and `key` is one it's moving (per
/// its `after_ring`), returns where to forward it — for `handle_connection`
/// to also propagate a client's `S`/`D` for that key there, so the
/// joining node doesn't end up serving a stale value once promoted (see
/// the staged-join handoff design).
fn migration_targets_for(node_context: &NodeContext, key: &Key) -> Vec<ForwardTarget> {
    migration_targets_for_hashed(node_context, KeyHash::of(key))
}

/// Where a handoff frame this node received (`U`, `u`) goes on: only to
/// the slot's joiner while discovery has not confirmed its join, and only
/// for a key that joiner owns. A handoff is sent by a node working from
/// a roster — a decommissioning node, a survivor re-replicating, an old
/// owner relaying for its own joiner — and every confirmed joiner is in
/// that roster, so the sender reached it directly; relaying there again
/// only sent frames around in circles (a leaver's drain came back to it
/// through its entrant's relay and overwrote the newer write it held
/// meanwhile). The unconfirmed joiner is the one node no roster names
/// yet, and the one this node must cover.
fn unconfirmed_join_target_for(node_context: &NodeContext, key: &Key) -> Option<ForwardTarget> {
    let key_hash = KeyHash::of(key);
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if slot.as_ref().is_some_and(ActiveMigration::expired) {
        *slot = None;
    }
    let active = slot.as_ref()?;
    if active.confirmed
        || !active.forwarding_open()
        || !active
            .after_ring
            .is_owner_hashed(key_hash, &active.joining_name, active.replication)
    {
        return None;
    }
    Some(ForwardTarget {
        addr: active.joining_addr.clone(),
        connection: Arc::clone(&active.forward_connection),
        token: active.joining_token.clone(),
        revoked: Arc::clone(&active.forward_revoked),
        as_handoff: true,
    })
}

/// Issue #975: whether the join handoff this node is running — in flight,
/// or completed and not yet confirmed by discovery — moved `key` away from
/// this node: under the handoff's ring the key's owners include its joiner
/// or a lingering joiner, and not this node. Until discovery confirms the
/// join, the handoff's ring is the newest membership this node knows, so
/// a copy that arrives for a key it does not own under that ring is one
/// the join took (a sender working from an older roster). Once the join is
/// confirmed nothing is judged here: discovery may have published rings
/// since that the slot's ring does not reflect — an eviction promoting
/// this node for a key the joiner used to own — and a copy arriving then
/// is just as likely that promotion, which the slot's ring would call
/// taken (a chaos run marked 94 fresh copies that way). A key this node
/// does not own under the handoff's ring but no joiner owns either was
/// never this node's to mark (a ring newer than the handoff's, a leaver's,
/// may be giving it the key). The key joins `marked_keys`, so an abandon
/// rolls the mark back with the handoff's own.
fn join_took(node_context: &NodeContext, key: &Key) -> bool {
    let key_hash = KeyHash::of(key);
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if slot.as_ref().is_some_and(ActiveMigration::expired) {
        *slot = None;
    }
    let Some(active) = slot.as_mut() else {
        return false;
    };
    if active.remnant || active.confirmed {
        return false;
    }
    let ring = &active.after_ring;
    let replication = active.replication;
    if ring.is_owner_hashed(key_hash, &node_context.name, replication) {
        return false;
    }
    let taken = ring.is_owner_hashed(key_hash, &active.joining_name, replication)
        || active
            .lingering
            .iter()
            .any(|lingering| ring.is_owner_hashed(key_hash, &lingering.joining_name, replication));
    if taken {
        // Copied: `key` is sliced from the received frame, and the slot keeps
        // it until the join is confirmed or abandoned.
        active.marked_keys.push(Key::new(
            Bytes::copy_from_slice(&key.namespace),
            Bytes::copy_from_slice(&key.name),
        ));
    }
    taken
}

/// `migration_targets_for` for a key whose hash is already known — see
/// `wrong_node_hashed`.
///
/// Every join this node still owes a forwarding window: the slot's own
/// joiner, and (issue #564) each earlier confirmed joiner a later `M`
/// pushed into `ActiveMigration::lingering`. A joiner is a destination
/// whenever it is in the key's top-R under the *slot's* ring — the ring
/// that contains every confirmed joiner — not only as its new primary.
fn migration_targets_for_hashed(
    node_context: &NodeContext,
    key_hash: KeyHash,
) -> Vec<ForwardTarget> {
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());

    // Issue #3: a completed handoff keeps forwarding until the grace
    // passes (discovery publishes the joiner — or abandons the join —
    // well within it). Expired entries are cleared lazily here.
    if slot.as_ref().is_some_and(ActiveMigration::expired) {
        *slot = None;
    }

    let Some(active) = slot.as_mut() else {
        return Vec::new();
    };
    active
        .lingering
        .retain(|lingering| lingering.forwarding_open());

    let mut targets = Vec::new();
    // Issue #62: an unconfirmed completed slot outlives its grace (it
    // is still holding its marks back from the sweep), but forwarding
    // ends with the grace regardless.
    if active.forwarding_open()
        && active
            .after_ring
            .is_owner_hashed(key_hash, &active.joining_name, active.replication)
    {
        targets.push(ForwardTarget {
            addr: active.joining_addr.clone(),
            connection: Arc::clone(&active.forward_connection),
            token: active.joining_token.clone(),
            revoked: Arc::clone(&active.forward_revoked),
            // The joiner refuses plain frames until it is promoted — see
            // `ForwardTarget::as_handoff`.
            as_handoff: true,
        });
    }
    for lingering in &active.lingering {
        if active
            .after_ring
            .is_owner_hashed(key_hash, &lingering.joining_name, active.replication)
        {
            targets.push(lingering.target());
        }
    }
    targets
}

/// Issue #564: where a clear must also go for the earlier joiners that are
/// still inside their forwarding grace. Always every one of them — a clear
/// is not tied to a key.
fn lingering_clear_targets(node_context: &NodeContext) -> Vec<ForwardTarget> {
    let mut slot = node_context
        .active_migration
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let Some(active) = slot.as_mut() else {
        return Vec::new();
    };
    active
        .lingering
        .retain(|lingering| lingering.forwarding_open());
    active
        .lingering
        .iter()
        .map(LingeringForward::target)
        .collect()
}

/// Issue #124: if a decommission is in flight and this node owned the
/// key, returns the forward target for the node that newly enters the
/// key's top-R once this node is gone — a concurrent client write must
/// reach it, or the copy handed over by the drain-out transfer goes
/// stale the moment discovery publishes the post-leave roster (the
/// exact mirror of `migration_target_for`'s join-side reasoning). Takes
/// the key's hash — see `wrong_node_hashed`; reached through
/// `handoff_targets_for`.
fn leave_target_for_hashed(node_context: &NodeContext, key_hash: KeyHash) -> Option<ForwardTarget> {
    let leaving = node_context
        .leaving
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let leave = leaving.as_ref()?;
    let entrant = leave.entrant_for(key_hash, &node_context.name)?;
    leave.forward_target(&entrant)
}

/// Where a clear must also go while a decommission is in flight: every
/// survivor, since any of them is the entrant for some of this node's
/// keys and a clear is not tied to a key (the leave-side twin of
/// `lingering_clear_targets`). Each target shares the entrant's
/// forwarding connection, so the clear is queued behind the writes
/// `leave_target_for` already queued for it. Nothing in flight: empty.
fn leave_clear_targets(node_context: &NodeContext) -> Vec<ForwardTarget> {
    let leaving = node_context
        .leaving
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let Some(leave) = leaving.as_ref() else {
        return Vec::new();
    };
    let mut survivors: Vec<&String> = leave
        .addresses
        .keys()
        .filter(|name| **name != node_context.name)
        .collect();
    survivors.sort();
    survivors
        .into_iter()
        .filter_map(|name| leave.forward_target(name))
        .collect()
}

/// Where a client write of `key` must also go for an eviction's
/// re-replication in flight (or inside its grace): the owners the ring
/// change newly promoted that this node is an eligible sender for — see
/// `RereplicationForward`. An expired window is cleared here, lazily, as
/// `migration_targets_for` clears an expired handoff slot.
///
/// Issue #973: a promoted owner is a target only while it still owns the
/// key under the newest membership this node has adopted. The window is
/// a snapshot; a join completed inside it (this node's own `M` handoff
/// adopts the post-join ring at once) can take the key away from the
/// owner the snapshot promoted, and a write forwarded there after that
/// lands on the dead copy the join left, releases its mark and leaves a
/// live copy nobody forwards to again — stale until the node owned the
/// key once more and served it (a shortened TTL that was then removed on
/// the owners expired it instead, and the SDK read a miss from the
/// primary it had been handed on to). The adopted ring is never older
/// than the window's own `after_ring`: both triggers of a pass adopt the
/// ring first (`adopt_membership`, the join flip in `run_migration`).
fn rereplication_targets_for_hashed(
    node_context: &NodeContext,
    key_hash: KeyHash,
) -> Vec<ForwardTarget> {
    let mut slot = node_context
        .rereplication_forward
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if slot
        .as_ref()
        .is_some_and(|window| !window.forwarding_open())
    {
        *slot = None;
    }
    let Some(window) = slot.as_ref() else {
        return Vec::new();
    };
    let adopted = node_context
        .known_ring
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .map(Arc::clone);
    rereplication_targets(
        &window.before_ring,
        &window.after_ring,
        key_hash,
        window.replication,
        &node_context.name,
    )
    .iter()
    .filter(|name| {
        adopted.as_ref().is_none_or(|membership| {
            membership
                .ring
                .is_owner_hashed(key_hash, name, membership.replication)
        })
    })
    .filter_map(|name| window.forward_target(name))
    .collect()
}

/// Where a clear must also go while an eviction's re-replication is in
/// flight (or inside its grace): every member of the ring after the
/// change except this node, since any of them is the owner the change
/// promoted for some of the keys this node sends, and a clear is not
/// tied to a key (the re-replication twin of `leave_clear_targets`).
/// Each target shares the window's forwarding connection, so the clear
/// is queued behind the writes `rereplication_targets_for_hashed`
/// already mirrored to it: a write this node acknowledged and queued for
/// a promoted owner must not land there after the owner's own clear.
/// Nothing in flight: empty.
fn rereplication_clear_targets(node_context: &NodeContext) -> Vec<ForwardTarget> {
    let mut slot = node_context
        .rereplication_forward
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if slot
        .as_ref()
        .is_some_and(|window| !window.forwarding_open())
    {
        *slot = None;
    }
    let Some(window) = slot.as_ref() else {
        return Vec::new();
    };
    let mut members: Vec<&String> = window
        .after_ring
        .nodes()
        .iter()
        .filter(|name| **name != node_context.name)
        .collect();
    members.sort();
    members
        .into_iter()
        .filter_map(|name| window.forward_target(name))
        .collect()
}

/// Every window a client write of `key` must be mirrored through as a
/// handoff frame (an unconditional `U`, a `u`): the decommission's
/// entrant (`leave_target_for`) and the re-replication's newly promoted
/// owners (`rereplication_targets_for_hashed`). Empty when neither is in
/// flight — the common case.
fn handoff_targets_for(node_context: &NodeContext, key: &Key) -> Vec<ForwardTarget> {
    handoff_targets_for_hashed(node_context, KeyHash::of(key))
}

/// `handoff_targets_for` for a key whose hash is already known.
fn handoff_targets_for_hashed(node_context: &NodeContext, key_hash: KeyHash) -> Vec<ForwardTarget> {
    let mut targets: Vec<ForwardTarget> = leave_target_for_hashed(node_context, key_hash)
        .into_iter()
        .collect();
    targets.extend(rereplication_targets_for_hashed(node_context, key_hash));
    targets
}

/// Forwards a client's `D` for `key` to `target`, mirroring
/// `set_on_joining_node` but for deletes — see `migration_target_for` and
/// `ForwardTarget`. Accepts either `D\n` (the key was present there too)
/// or `N\n` (it hadn't arrived yet, e.g. this delete raced ahead of the
/// migration task's own send of it) as a successful delivery. Bounded by
/// `FORWARD_TIMEOUT` as a single whole, same reasoning as
/// `set_on_joining_node`, and reuses `target.connection` the same way.
///
/// Tenth-pass audit (2026-09-02): test-only now — see
/// `set_on_joining_node`'s doc comment.
#[cfg(test)]
async fn delete_on_joining_node(
    node_context: &NodeContext,
    target: &ForwardTarget,
    key: &Key,
) -> io::Result<()> {
    forward_on_shared_connection(node_context, target, ForwardedWrite::Delete { key }).await
}

async fn report_complete(
    node_context: &NodeContext,
    joining_name: &str,
    generation: Option<u64>,
) -> io::Result<()> {
    // One budget for the whole call (dial, TLS, auth, C/A round trip), not
    // `connect_and_authenticate`'s own per-leg bounds stacked in front of a
    // second `OUTBOUND_IO_TIMEOUT` for the exchange: a discovery that is
    // merely slow at each leg could otherwise hold this for twice as long.
    timeout(OUTBOUND_IO_TIMEOUT, async {
        let mut stream = connect_and_authenticate(
            node_context,
            &node_context.discovery_addr,
            AuthPeer::Discovery,
        )
        .await?;

        stream
            .write_all(&complete_message(
                &node_context.name,
                joining_name,
                &node_context.token,
                generation,
            ))
            .await?;

        let mut ack = [0u8; 2];
        stream.read_exact(&mut ack).await?;

        if &ack != b"A\n" {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "discovery server did not acknowledge C",
            ));
        }

        io::Result::Ok(())
    })
    .await
    .map_err(|_| {
        io::Error::new(
            io::ErrorKind::TimedOut,
            "reporting migration completion to discovery timed out",
        )
    })?
}

