    /// `(connection index, key, value)` per `s` frame `spawn_s_frame_joiner`
    /// received.
    type JoinerFrames = Arc<std::sync::Mutex<Vec<(usize, Vec<u8>, Vec<u8>)>>>;

    /// A fake joining node: accepts connections and, on each, reads
    /// namespaced `s` frames (`s <ns> <key> <value>\n<ns><key><value>`) or
    /// the `U` handoff frames a join's forwards are sent as
    /// (`handoff_message`), recording `(connection index, key, value)` and
    /// acking `S` — until
    /// `unacked_after` frames have been read on connection 0, after which
    /// it closes that connection *without* acking the frame just read.
    fn spawn_s_frame_joiner(listener: TcpListener, unacked_after: Option<usize>) -> JoinerFrames {
        let received = Arc::new(std::sync::Mutex::new(Vec::new()));
        let recorded = Arc::clone(&received);
        tokio::spawn(async move {
            let mut connection_index = 0usize;
            loop {
                let Ok((connection, _)) = listener.accept().await else {
                    return;
                };
                let recorded = Arc::clone(&recorded);
                let this_connection = connection_index;
                connection_index += 1;
                tokio::spawn(async move {
                    let mut reader = tokio::io::BufReader::new(connection);
                    let mut on_this_connection = 0usize;
                    loop {
                        let Ok(header) = read_peer_line(&mut reader).await else {
                            return;
                        };
                        let fields: Vec<usize> = header
                            .trim_end()
                            .split(' ')
                            .skip(1)
                            .map(|field| field.parse().unwrap())
                            .collect();
                        // `(body length, key start, value start)`: a `U`
                        // body leads with the token, then namespace, key,
                        // value (`handoff_message`).
                        let (body_length, key_start, value_start) = if header.starts_with("s ") {
                            (
                                fields[0] + fields[1] + fields[2],
                                fields[0],
                                fields[0] + fields[1],
                            )
                        } else if header.starts_with("U ") {
                            let (namespace, key, value, token) =
                                (fields[0], fields[1], fields[2], fields[3]);
                            (
                                token + namespace + key + value,
                                token + namespace,
                                token + namespace + key,
                            )
                        } else {
                            panic!("unexpected frame {header:?}");
                        };
                        let mut body = vec![0u8; body_length];
                        reader.read_exact(&mut body).await.unwrap();
                        let key = body[key_start..value_start].to_vec();
                        let value = body[value_start..].to_vec();
                        recorded.lock().unwrap().push((this_connection, key, value));
                        on_this_connection += 1;
                        if this_connection == 0 && unacked_after == Some(on_this_connection) {
                            return;
                        }
                        reader.get_mut().write_all(b"S\n").await.unwrap();
                    }
                });
            }
        });
        received
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_large_multi_set_during_a_join_forwards_every_key_not_just_the_first_few_thousand() {
        // The `MultiSet` arm used to hand each matching key to `forward_tx`
        // as its own task in a loop that never yields. With the runtime
        // single-threaded, `run`'s consumer cannot drain the channel
        // meanwhile, so everything past 4352 keys hit the drop branch and
        // never reached the joiner. The keys are now queued for the target
        // (coalesced by key), and one drainer sends them.
        const KEYS: usize = 256 + 4096 + 1_500;

        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let received = spawn_s_frame_joiner(joining_listener, None);

        // R=2 over two members: the joiner is in every key's top-R.
        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let mut active = test_active_migration(None);
        active.joining_addr = joining_addr;
        active.after_ring = after_ring;
        active.acked_entries = None;
        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(Some(active))),
        );

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(FORWARD_CHANNEL_CAPACITY);
        // Stands in for `run`'s consumer, which cannot run while the
        // connection task is busy in its loop.
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        let pair_lens = vec!["5 1"; KEYS].join(" ");
        let mut frame = format!("o 2 {KEYS} {pair_lens}\nns").into_bytes();
        for index in 0..KEYS {
            frame.extend_from_slice(format!("k{index:04}").as_bytes());
            frame.push(b'v');
        }
        assert!(frame.len() < MAX_REQUEST_SIZE);
        client.write_all(&frame).await.unwrap();
        client.shutdown().await.unwrap();
        let mut response = Vec::new();
        client.read_to_end(&mut response).await.unwrap();
        assert!(response.starts_with(format!("O {KEYS} S").as_bytes()));
        connection_task.await.unwrap().unwrap();

        // The forward runs after the client was answered; wait for it.
        timeout(Duration::from_secs(20), async {
            while received.lock().unwrap().len() < KEYS {
                sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("every key of the MultiSet must reach the joining node");

        let received = received.lock().unwrap().clone();
        assert_eq!(received.len(), KEYS, "no key may be delivered twice");
        // One drainer: one connection, keys in frame order.
        assert!(received.iter().all(|(connection, _, _)| *connection == 0));
        for (index, (_, key, value)) in received.iter().enumerate() {
            assert_eq!(key, format!("k{index:04}").as_bytes());
            assert_eq!(value, b"v");
        }

        drop(forward_relay);
        drop(request_tx);
        cache_task.await.unwrap();
    }

    // ---- coalescing forward queues (the fix for forwards dropped when a
    // target is slow: the queue is bounded by distinct keys, not by writes) --

    fn forward_set(name: &str, value: &'static str) -> OwnedForwardedWrite {
        OwnedForwardedWrite::Set {
            key: Key::new(
                Bytes::from_static(b"ns"),
                Bytes::copy_from_slice(name.as_bytes()),
            ),
            value: Bytes::from_static(value.as_bytes()),
            ttl: None,
        }
    }

    fn forward_delete(name: &str) -> OwnedForwardedWrite {
        OwnedForwardedWrite::Delete {
            key: Key::new(
                Bytes::from_static(b"ns"),
                Bytes::copy_from_slice(name.as_bytes()),
            ),
        }
    }

    fn forward_put_if_absent(name: &str, value: &'static str) -> OwnedForwardedWrite {
        OwnedForwardedWrite::HandoffSet {
            key: Key::new(
                Bytes::from_static(b"ns"),
                Bytes::copy_from_slice(name.as_bytes()),
            ),
            value: Bytes::from_static(value.as_bytes()),
            ttl: None,
            if_absent: true,
        }
    }

    fn test_forward_target(addr: &str) -> ForwardTarget {
        ForwardTarget {
            addr: addr.to_string(),
            connection: Arc::new(AsyncMutex::new(None)),
            token: "tok-joiner-0".to_string(),
            revoked: Arc::new(AtomicBool::new(false)),
            as_handoff: false,
        }
    }

    fn test_target_queue() -> TargetQueue {
        TargetQueue::new(
            test_node_context(
                "ready-node",
                "tk-ready-node",
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
            ),
            test_forward_target("127.0.0.1:9"),
        )
    }

    /// What a drainer would send, in order, as `(kind, name, value)`.
    fn drain_all(queue: &mut TargetQueue) -> Vec<String> {
        let mut sent = Vec::new();
        while let Some(write) = queue.pop() {
            sent.push(match write {
                OwnedForwardedWrite::Set { key, value, .. } => {
                    format!(
                        "set {} {}",
                        String::from_utf8_lossy(&key.name),
                        String::from_utf8_lossy(&value)
                    )
                }
                OwnedForwardedWrite::Delete { key } => {
                    format!("del {}", String::from_utf8_lossy(&key.name))
                }
                OwnedForwardedWrite::HandoffSet {
                    key,
                    value,
                    if_absent,
                    ..
                } => format!(
                    "pia{} {} {}",
                    if if_absent { "" } else { "(overwrite)" },
                    String::from_utf8_lossy(&key.name),
                    String::from_utf8_lossy(&value)
                ),
                OwnedForwardedWrite::HandoffDelete { key } => {
                    format!("hdel {}", String::from_utf8_lossy(&key.name))
                }
                OwnedForwardedWrite::Clear(_) => "clear".to_string(),
            });
        }
        sent
    }

    #[test]
    fn a_later_write_to_a_key_replaces_the_one_still_waiting() {
        let mut queue = test_target_queue();
        queue.push(forward_set("a", "1"));
        queue.push(forward_set("b", "1"));
        queue.push(forward_set("a", "2"));
        queue.push(forward_delete("b"));
        queue.push(forward_set("a", "3"));

        // One entry per key, each the last write to it, in the order the
        // keys first appeared.
        assert_eq!(drain_all(&mut queue), ["set a 3", "del b"]);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn forwards_to_a_lingering_joiner_are_queued_into_handoff_frames() {
        // A lingering joiner's target (`ForwardTarget::as_handoff`) answers
        // a plain `S` with `W` while its own ring lags the slot's, so its
        // forwards go out as `U`/`u`; a put-if-absent relay and a clear are
        // what they were. The slot's own joiner still gets plain frames.
        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
        );
        let queues = ForwardQueues::default();

        let lingering = ForwardTarget {
            as_handoff: true,
            ..test_forward_target("127.0.0.1:9")
        };
        let id = queues
            .push(
                &node_context,
                lingering,
                [
                    forward_set("a", "1"),
                    forward_delete("b"),
                    forward_put_if_absent("c", "1"),
                    OwnedForwardedWrite::Clear(ClearScope::All),
                    forward_set("a", "2"),
                ],
            )
            .await
            .expect("first push starts a drainer");
        let sent = drain_all(queues.targets.lock().unwrap().get_mut(&id).unwrap());
        assert_eq!(
            sent,
            [
                "pia(overwrite) a 1",
                "hdel b",
                "pia c 1",
                "clear",
                "pia(overwrite) a 2"
            ]
        );

        let own_joiner = test_forward_target("127.0.0.1:11");
        let id = queues
            .push(
                &node_context,
                own_joiner,
                [forward_set("a", "1"), forward_delete("b")],
            )
            .await
            .expect("first push starts a drainer");
        let sent = drain_all(queues.targets.lock().unwrap().get_mut(&id).unwrap());
        assert_eq!(sent, ["set a 1", "del b"]);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_lingering_joiner_target_sends_handoff_frames_once_it_stops_being_the_slots_own() {
        // The same connection serves a joiner first as the slot's own and
        // later as a lingering one; the frame is decided per push, by the
        // target that resolved it, not by the queue's first target.
        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
        );
        let queues = ForwardQueues::default();
        let own = test_forward_target("127.0.0.1:9");
        let lingering = ForwardTarget {
            as_handoff: true,
            ..own.duplicate()
        };
        let id = queues
            .push(&node_context, own, [forward_set("a", "1")])
            .await
            .expect("first push starts a drainer");
        assert!(
            queues
                .push(&node_context, lingering, [forward_set("b", "1")])
                .await
                .is_none()
        );
        let sent = drain_all(queues.targets.lock().unwrap().get_mut(&id).unwrap());
        assert_eq!(sent, ["set a 1", "pia(overwrite) b 1"]);
    }

    #[test]
    fn the_queue_is_bounded_by_distinct_keys_not_by_writes() {
        let mut queue = test_target_queue();
        for round in 0..200 {
            for key in 0..100 {
                queue.push(forward_set(
                    &format!("k{key}"),
                    if round % 2 == 0 { "even" } else { "odd" },
                ));
            }
        }
        assert_eq!(queue.ops.len(), 100);
        assert_eq!(queue.slots.len(), 100);
    }

    #[test]
    fn queuing_a_frame_of_many_keys_under_a_large_namespace_hashes_it_once() {
        // The keys of one `o` frame share the namespace allocation. The
        // slot map used to hash the whole namespace on every push and
        // pop (`Key`'s derived `Hash`): 100,000 keys under a 100 KB
        // namespace cost about 20 GB of hashing on the thread that
        // serves every connection, an 8 s stall. With the canonical hash
        // computed once per namespace run this is bounded by the keys'
        // own bytes.
        let mut queue = test_target_queue();
        let namespace = Bytes::from(vec![b'n'; 100_000]);
        let started = Instant::now();
        for i in 0..100_000u32 {
            queue.push(OwnedForwardedWrite::Set {
                key: Key::new(namespace.clone(), Bytes::from(i.to_le_bytes().to_vec())),
                value: Bytes::new(),
                ttl: None,
            });
        }
        // A second write to each key coalesces into its slot.
        for i in 0..100_000u32 {
            queue.push(OwnedForwardedWrite::Set {
                key: Key::new(namespace.clone(), Bytes::from(i.to_le_bytes().to_vec())),
                value: Bytes::from_static(b"2"),
                ttl: None,
            });
        }
        assert_eq!(queue.ops.len(), 100_000);
        let mut popped = 0;
        while queue.pop().is_some() {
            popped += 1;
        }
        assert_eq!(popped, 100_000);
        assert!(queue.slots.is_empty());
        assert!(
            started.elapsed() < Duration::from_secs(5),
            "queuing and draining 100,000 keys under a 100 KB namespace took {:?}",
            started.elapsed()
        );
    }

    #[test]
    fn slot_keys_compare_by_content_across_namespace_allocations() {
        // The same key from two frames (two allocations of the same
        // namespace bytes) must share a slot; the pointer check is only
        // a fast path.
        let mut hasher = KeyHasher::default();
        let first = Key::new(Bytes::from(vec![b'n'; 64]), Bytes::from_static(b"k"));
        let second = Key::new(Bytes::from(vec![b'n'; 64]), Bytes::from_static(b"k"));
        let other = Key::new(Bytes::from(vec![b'm'; 64]), Bytes::from_static(b"k"));
        assert_eq!(
            SlotKey::of(&mut hasher, &first),
            SlotKey::of(&mut hasher, &second)
        );
        assert_ne!(
            SlotKey::of(&mut hasher, &first),
            SlotKey::of(&mut hasher, &other)
        );

        let mut queue = test_target_queue();
        queue.push(OwnedForwardedWrite::Set {
            key: first,
            value: Bytes::from_static(b"1"),
            ttl: None,
        });
        queue.push(OwnedForwardedWrite::Set {
            key: second,
            value: Bytes::from_static(b"2"),
            ttl: None,
        });
        assert_eq!(
            queue.ops.len(),
            1,
            "the second write replaces the first's slot"
        );
    }

    #[test]
    fn a_clear_is_a_barrier_that_nothing_is_coalesced_across() {
        let mut queue = test_target_queue();
        queue.push(forward_set("a", "before"));
        queue.push(OwnedForwardedWrite::Clear(ClearScope::All));
        queue.push(forward_set("a", "after"));
        queue.push(forward_set("a", "after2"));

        // Replacing "before" with "after" would apply it ahead of the clear
        // and the clear would then wipe it.
        assert_eq!(
            drain_all(&mut queue),
            ["set a before", "clear", "set a after2"]
        );
    }

    #[test]
    fn a_put_if_absent_relay_is_not_coalesced_across() {
        let mut queue = test_target_queue();
        queue.push(forward_set("a", "client"));
        queue.push(forward_put_if_absent("a", "relayed"));
        queue.push(forward_delete("a"));

        // Folding the delete into the first entry would send delete, then
        // the relay, which would store its older value on the target.
        assert_eq!(
            drain_all(&mut queue),
            ["set a client", "pia a relayed", "del a"]
        );
    }

    #[test]
    fn a_write_after_the_waiting_one_was_taken_is_queued_behind_it() {
        let mut queue = test_target_queue();
        queue.push(forward_set("a", "1"));
        let in_flight = queue.pop();
        assert!(in_flight.is_some());
        assert!(queue.slots.is_empty(), "the taken write's slot is released");

        // The first write may already be on the wire: the new one must
        // follow it, not replace something that has left the queue.
        queue.push(forward_set("a", "2"));
        assert_eq!(drain_all(&mut queue), ["set a 2"]);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn exactly_one_drainer_is_started_per_queue_until_it_is_deactivated() {
        let queues = ForwardQueues::default();
        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
        );
        let target = test_forward_target("127.0.0.1:9");
        let connection = Arc::clone(&target.connection);

        let id = queues
            .push(&node_context, target.duplicate(), [forward_set("a", "1")])
            .await
            .expect("the first write starts a drainer");
        assert_eq!(id, Arc::as_ptr(&connection) as usize);
        assert!(
            queues
                .push(&node_context, target.duplicate(), [forward_set("b", "1")])
                .await
                .is_none(),
            "a drainer is already running"
        );

        // A drainer that could not be handed over leaves the writes queued
        // and lets the next write start one.
        queues.deactivate(id);
        assert!(
            queues
                .push(&node_context, target.duplicate(), [forward_set("c", "1")])
                .await
                .is_some()
        );
        let mut drained = 0;
        while queues.next(id).is_some() {
            drained += 1;
        }
        assert_eq!(drained, 3);
        assert!(
            queues.targets.lock().unwrap().is_empty(),
            "an empty queue is removed"
        );
    }

    fn namespaced_set(namespace: &Bytes, name: &str, value: &'static str) -> OwnedForwardedWrite {
        OwnedForwardedWrite::Set {
            key: Key::new(namespace.clone(), Bytes::copy_from_slice(name.as_bytes())),
            value: Bytes::from_static(value.as_bytes()),
            ttl: None,
        }
    }

    #[test]
    fn the_queue_charges_each_write_and_a_shared_namespace_once() {
        let mut queue = test_target_queue();
        let namespace = Bytes::from(vec![b'n'; 1000]);
        let entry =
            |name: &str, value: &str| name.len() + value.len() + FORWARD_ENTRY_OVERHEAD_BYTES;

        queue.push(namespaced_set(&namespace, "a", "1"));
        queue.push(namespaced_set(&namespace, "bb", "22"));
        queue.push(namespaced_set(&namespace, "ccc", "333"));
        // Three keys of one frame share its namespace allocation: it is
        // pinned once, so it is charged once.
        assert_eq!(
            queue.bytes,
            entry("a", "1") + entry("bb", "22") + entry("ccc", "333") + namespace.len()
        );

        // Coalescing replaces the entry's charge, it does not add to it.
        queue.push(namespaced_set(&namespace, "a", "1-longer"));
        assert_eq!(
            queue.bytes,
            entry("a", "1-longer") + entry("bb", "22") + entry("ccc", "333") + namespace.len()
        );

        // A write under its own copy of the same name is another
        // allocation, charged on its own.
        let own_copy = Bytes::copy_from_slice(&namespace);
        queue.push(namespaced_set(&own_copy, "d", "4"));
        assert_eq!(
            queue.bytes,
            entry("a", "1-longer")
                + entry("bb", "22")
                + entry("ccc", "333")
                + entry("d", "4")
                + 2 * namespace.len()
        );

        // Popping releases each entry, and the namespace with its last sharer.
        queue.pop();
        queue.pop();
        assert_eq!(
            queue.bytes,
            entry("ccc", "333") + entry("d", "4") + 2 * namespace.len()
        );
        queue.pop();
        assert_eq!(queue.bytes, entry("d", "4") + own_copy.len());
        queue.pop();
        assert_eq!(queue.bytes, 0);
        assert!(queue.namespaces.is_empty());
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_push_waits_for_room_in_a_full_queue_and_a_pop_makes_it() {
        let queues = Arc::new(ForwardQueues::default());
        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
        );
        let target = test_forward_target("127.0.0.1:9");

        // One write that fills the bound on its own (admitted: the queue
        // was empty), with the drainer deliberately not started.
        let filling = OwnedForwardedWrite::Set {
            key: Key::unnamespaced(Bytes::from_static(b"big")),
            value: Bytes::from(vec![
                0_u8;
                MAX_FORWARD_QUEUE_BYTES
                    - FORWARD_ENTRY_OVERHEAD_BYTES
                    - 3
            ]),
            ttl: None,
        };
        let id = queues
            .push(&node_context, target.duplicate(), [filling])
            .await
            .expect("the first write starts a drainer");
        assert_eq!(
            queues.targets.lock().unwrap()[&id].bytes,
            MAX_FORWARD_QUEUE_BYTES
        );

        // The next write does not fit: its push waits ...
        let waiting = tokio::spawn({
            let queues = Arc::clone(&queues);
            let target = target.duplicate();
            async move {
                queues
                    .push(&node_context, target, [forward_set("a", "1")])
                    .await
            }
        });
        tokio::time::sleep(Duration::from_millis(50)).await;
        assert!(!waiting.is_finished(), "a push into a full queue must wait");
        assert_eq!(queues.targets.lock().unwrap()[&id].ops.len(), 1);

        // ... until the drainer takes the write that filled the queue.
        let (_, _, popped) = queues.next(id).expect("the filling write");
        assert!(matches!(popped, OwnedForwardedWrite::Set { .. }));
        let started = tokio::time::timeout(Duration::from_secs(5), waiting)
            .await
            .expect("the waiting push completes once there is room")
            .unwrap();
        assert!(started.is_none(), "the queue already has its drainer");
        assert_eq!(queues.targets.lock().unwrap()[&id].ops.len(), 1);
        // The entry, plus its "ns" namespace charged once.
        assert_eq!(
            queues.targets.lock().unwrap()[&id].bytes,
            entry_bytes(&forward_set("a", "1")) + b"ns".len()
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_push_into_a_full_queue_with_no_drainer_is_admitted_and_starts_one() {
        // `deactivate` leaves a queue without a drainer when the drainer
        // could not be handed to `run` (forward_tx full, the waiter cap
        // reached) or died. Its writes stay. A push into it that did not
        // fit used to wait for room a drainer would make — and there was
        // none to make it, so the push, and the client connection behind
        // it, hung until the node shut down.
        let queues = Arc::new(ForwardQueues::default());
        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
        );
        let target = test_forward_target("127.0.0.1:9");

        let filling = OwnedForwardedWrite::Set {
            key: Key::unnamespaced(Bytes::from_static(b"big")),
            value: Bytes::from(vec![
                0_u8;
                MAX_FORWARD_QUEUE_BYTES
                    - FORWARD_ENTRY_OVERHEAD_BYTES
                    - 3
            ]),
            ttl: None,
        };
        let id = queues
            .push(&node_context, target.duplicate(), [filling])
            .await
            .expect("the first write starts a drainer");
        // The drainer could not be started: the queue keeps its write
        // and has no drainer.
        queues.deactivate(id);
        assert_eq!(queues.targets.lock().unwrap()[&id].ops.len(), 1);
        assert!(!queues.targets.lock().unwrap()[&id].draining);

        // The next write does not fit, but nothing would ever make room:
        // it is admitted, and this push starts the drainer.
        let started = tokio::time::timeout(
            Duration::from_secs(5),
            queues.push(&node_context, target.duplicate(), [forward_set("a", "1")]),
        )
        .await
        .expect("a push into a queue with no drainer must not wait");
        assert_eq!(started, Some(id), "this push starts the drainer");
        assert_eq!(queues.targets.lock().unwrap()[&id].ops.len(), 2);
        assert!(queues.targets.lock().unwrap()[&id].draining);

        // With a drainer again, a write that does not fit waits as before.
        let waiting = tokio::spawn({
            let queues = Arc::clone(&queues);
            let target = target.duplicate();
            async move {
                queues
                    .push(&node_context, target, [forward_set("b", "2")])
                    .await
            }
        });
        tokio::time::sleep(Duration::from_millis(50)).await;
        assert!(
            !waiting.is_finished(),
            "a push into a full, draining queue waits"
        );
        let (_, _, popped) = queues.next(id).expect("the filling write");
        assert!(matches!(popped, OwnedForwardedWrite::Set { .. }));
        tokio::time::timeout(Duration::from_secs(5), waiting)
            .await
            .expect("the waiting push completes once there is room")
            .unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn forwards_to_a_stalled_target_are_all_delivered_once_it_answers_none_dropped() {
        // Before: every forward was its own task behind a bounded channel,
        // and past 256 + 4096 outstanding the rest were dropped, so a
        // joiner that was busy receiving its handoff missed thousands of
        // writes (observed under chaos load: ~10k dropped per node while a
        // killed node's replacement joined). Now the writes wait in a queue
        // bounded by distinct keys, and each key is delivered once, with
        // its last value.
        const KEYS: usize = 256 + 4096 + 3_000;
        const REWRITES: usize = 3;

        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let received = spawn_s_frame_joiner(joining_listener, None);

        let node_context = test_node_context(
            "ready-node",
            "tk-ready-node",
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
        );
        // `run`'s consumer, stalled: the drainer sits in the channel until
        // the test takes it out, so everything below queues.
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(1);
        let config = ConnectionConfig {
            idle_timeout: IDLE_TIMEOUT,
            auth_secret: None,
            tls_acceptor: None,
            node_context: None,
            migration_tx: mpsc::channel(1).0,
            forward_tx,
            forward_queues: Arc::new(ForwardQueues::default()),
            in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
        };
        let target = test_forward_target(&joining_addr);

        for round in 0..REWRITES {
            for key in 0..KEYS {
                let value: &'static str = ["v0", "v1", "v2"][round];
                spawn_forward(
                    &config,
                    node_context.clone(),
                    target.duplicate(),
                    forward_set(&format!("k{key:05}"), value),
                )
                .await;
            }
        }
        assert_eq!(
            config
                .forward_queues
                .targets
                .lock()
                .unwrap()
                .values()
                .next()
                .unwrap()
                .ops
                .len(),
            KEYS,
            "writes to the same key coalesce while the target is stalled"
        );

        let drainer = forward_rx
            .recv()
            .await
            .expect("one drainer was handed to run");
        assert!(forward_rx.try_recv().is_err(), "and only one");
        drainer.await;

        let received = received.lock().unwrap().clone();
        assert_eq!(
            received.len(),
            KEYS,
            "every key reaches the target exactly once"
        );
        assert!(
            received.iter().all(|(_, _, value)| value == b"v2"),
            "with its last value"
        );
        for (index, (_, key, _)) in received.iter().enumerate() {
            assert_eq!(
                key,
                format!("k{index:05}").as_bytes(),
                "in first-write order"
            );
        }
        assert!(config.forward_queues.targets.lock().unwrap().is_empty());
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_multi_set_forwards_owned_keys_to_the_joining_node() {
        // Issue #176: `MultiSet` (`o`) used to answer `MultiAck` without
        // ever consulting `migration_target_for` — unlike `Set`, a bulk
        // write for a key mid-handoff never reached the joining node, so
        // the value was lost the moment `known_ring` flipped. This drives
        // an `o` for two keys through `handle_connection` with a handoff
        // in flight and checks both land on the joiner as forwarded `S`
        // frames.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();
            let mut received = Vec::new();
            // Two forwarded SETs, sequential on the one shared connection
            // (mirrors `forwarded_writes_to_a_joining_node_reuse_one_connection`).
            for _ in 0..2 {
                let mut buffer = [0u8; 256];
                let bytes_read = connection.read(&mut buffer).await.unwrap();
                assert!(bytes_read > 0);
                received.extend_from_slice(&buffer[..bytes_read]);
                connection.write_all(b"S\n").await.unwrap();
            }
            received
        });

        // Two members, R=2: the joiner is in every key's top-R
        // regardless of hash, so both keys must forward.
        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));

        let node_context = NodeContext {
            gates: Default::default(),
            name: "ready-node".to_string(),
            token: "tk-ready-node".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            // The transfer is still running (completed_at: None) — same
            // as `migration_target_for`'s "still moving keys" case, the
            // simplest state that keeps forwarding open.
            active_migration: Arc::new(Mutex::new(Some(ActiveMigration {
                joining_name: "joiner-0".to_string(),
                joining_addr: joining_addr.clone(),
                joining_token: "tok-joiner-0".to_string(),
                after_ring,
                replication: 2,
                generation: None,
                completed_at: None,
                forwarding_grace: Duration::from_secs(60),
                acked_entries: None,
                abort_requested: Arc::new(AtomicBool::new(false)),
                marked_keys: Vec::new(),
                confirmed: false,
                pre_completion_ring: None,
                pending_clears: PendingClears::default(),
                forward_connection: Arc::new(AsyncMutex::new(None)),
                forward_revoked: Arc::new(AtomicBool::new(false)),
                lingering: Vec::new(),
                remnant: false,
            }))),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        // Stands in for `run`'s own loop draining `forward_tx` — see
        // `ConnectionConfig::forward_tx` (issue #219: per-write forwards,
        // which is what `MultiSet` triggers here, no longer share
        // `migration_tx` with the bulk-migration task; compare
        // `migrate_command_transfers_matching_keys_and_reports_completion`,
        // which relays `migration_tx` instead).
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        client
            .write_all(b"o 0 2 5 2 5 2\nkey-av1key-bv2")
            .await
            .unwrap();
        client.shutdown().await.unwrap();

        let expected = b"O 2 S S\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);

        let received = joining_task.await.unwrap();
        assert_eq!(
            received,
            [
                handoff_message(&key(b"key-a"), b"v1", None, false, "tok-joiner-0"),
                handoff_message(&key(b"key-b"), b"v2", None, false, "tok-joiner-0"),
            ]
            .concat(),
            "both owned keys from the MultiSet must be forwarded to the joining node"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn handoff_set_if_absent_is_relayed_to_the_joining_node_as_if_absent() {
        // Regression (pass-7 audit): a put-if-absent handoff (`U ... A`, the
        // re-replication-after-eviction form, issue #266) applied here while
        // this node is mid-join-handoff used to NOT be relayed to the
        // joining owner at all. Re-replication computes its targets once, so
        // a node that joins while it runs never gets the key directly, and
        // this node's own handoff snapshot can miss it too — the key could
        // be stranded on the joiner permanently. It must be relayed, but as
        // another `U ... A` (if_absent), never an unconditional overwrite,
        // so the joiner keeps any value it already holds.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();
            let mut received = Vec::new();
            let mut buffer = [0u8; 256];
            let bytes_read = connection.read(&mut buffer).await.unwrap();
            assert!(bytes_read > 0);
            received.extend_from_slice(&buffer[..bytes_read]);
            connection.write_all(b"S\n").await.unwrap();
            received
        });

        // Two members, R=2: the joiner is in every key's top-R, so the
        // applied handoff must relay.
        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));

        let node_context = NodeContext {
            gates: Default::default(),
            name: "ready-node".to_string(),
            token: "tk-ready-node".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(Some(ActiveMigration {
                joining_name: "joiner-0".to_string(),
                joining_addr: joining_addr.clone(),
                joining_token: "tok-joiner-0".to_string(),
                after_ring,
                replication: 2,
                generation: None,
                completed_at: None,
                forwarding_grace: Duration::from_secs(60),
                acked_entries: None,
                abort_requested: Arc::new(AtomicBool::new(false)),
                marked_keys: Vec::new(),
                confirmed: false,
                pre_completion_ring: None,
                pending_clears: PendingClears::default(),
                forward_connection: Arc::new(AsyncMutex::new(None)),
                forward_revoked: Arc::new(AtomicBool::new(false)),
                lingering: Vec::new(),
                remnant: false,
            }))),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // `U 0 5 2 13 A\n<token>key-av1`: ns=0, key="key-a" (5), value="v1"
        // (2), token="tk-ready-node" (13), `A` = if_absent.
        client
            .write_all(b"U 0 5 2 13 A\ntk-ready-nodekey-av1")
            .await
            .unwrap();
        client.shutdown().await.unwrap();

        let expected = b"S\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);

        let received = joining_task.await.unwrap();
        // Relayed to the joiner as another if_absent `U` (the `A` marker),
        // with the joiner's own token ("tok-joiner-0", 12 bytes) — not an
        // unconditional `S` that would clobber a value the joiner may hold.
        assert_eq!(
            received,
            b"U 0 5 2 12 A\ntok-joiner-0key-av1".to_vec(),
            "an applied if_absent handoff must relay to the joiner as an if_absent U"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn decommission_multi_set_forwards_owned_keys_to_the_entrant() {
        // Issue #176: the decommission-drain mirror of the test above —
        // `leave_target_for` must see a `MultiSet`'s owned keys too, or a
        // bulk write racing a drain-out is lost once the post-leave
        // roster publishes.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        // R=1 over {leaver, peer}: whichever keys the leaver owns before
        // leaving move to the peer once leaver drops out — the only
        // member left.
        let before_ring = Arc::new(HashRing::new(vec![
            "leaver".to_string(),
            "peer".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec!["peer".to_string()]));

        // Two keys the "leaver" owns pre-leave, found the same way
        // `a_decommission_hands_off_owned_keys_and_leaves` samples them —
        // consistent hashing means not every name qualifies.
        let mut owned_keys = Vec::new();
        let mut index = 0u32;
        while owned_keys.len() < 2 {
            let name = format!("key-{index}");
            if before_ring.is_owner(&key(name.as_bytes()), "leaver", 1) {
                owned_keys.push(name);
            }
            index += 1;
            assert!(index < 1000, "expected at least two owned keys in range");
        }

        let mut addresses = HashMap::new();
        addresses.insert("peer".to_string(), peer_addr);
        let mut tokens = HashMap::new();
        tokens.insert("peer".to_string(), "tok-peer".to_string());

        let node_context = NodeContext {
            gates: Default::default(),
            name: "leaver".to_string(),
            token: "tk-leaver".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(Some(LeaveState {
                before_ring,
                after_ring,
                replication: 1,
                addresses,
                tokens,
                connections: Mutex::new(HashMap::new()),
            }))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        // Stands in for `run`'s own loop draining `forward_tx` — see
        // issue #219 (`ConnectionConfig::forward_tx`); per-write forwards
        // like this decommission-drain `MultiSet` mirror no longer share
        // `migration_tx` with the bulk-migration task.
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        let name_a = &owned_keys[0];
        let name_b = &owned_keys[1];
        let request = format!(
            "o 0 2 {} 2 {} 2\n{name_a}v1{name_b}v2",
            name_a.len(),
            name_b.len()
        );
        client.write_all(request.as_bytes()).await.unwrap();
        client.shutdown().await.unwrap();

        let expected = b"O 2 S S\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        assert_eq!(
            frames.len(),
            2,
            "both owned keys must forward to the entrant"
        );
        // Issue #295: the entrant's own token ("tok-peer") now leads the
        // body.
        let expected_a = format!("U 0 {} 2 8\ntok-peer{name_a}v1", name_a.len()).into_bytes();
        let expected_b = format!("U 0 {} 2 8\ntok-peer{name_b}v2", name_b.len()).into_bytes();
        assert!(frames.contains(&expected_a));
        assert!(frames.contains(&expected_b));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn decommission_batch_touch_forwards_the_touched_keys_to_the_entrant() {
        // The decommission-drain mirror of `a_batch_touch_forwards_each_
        // touched_key_as_a_set_and_a_miss_forwards_nothing`: a touch
        // racing a drain-out must reach the entrant, or its copy keeps the
        // TTL it was handed. The keys are in the cache before the
        // connection opens, so nothing but the touch is forwarded.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        let before_ring = Arc::new(HashRing::new(vec![
            "leaver".to_string(),
            "peer".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec!["peer".to_string()]));

        let mut owned_keys = Vec::new();
        let mut index = 0u32;
        while owned_keys.len() < 2 {
            let name = format!("key-{index}");
            if before_ring.is_owner(&key(name.as_bytes()), "leaver", 1) {
                owned_keys.push(name);
            }
            index += 1;
            assert!(index < 1000, "expected at least two owned keys in range");
        }
        for (name, value) in owned_keys.iter().zip([&b"v1"[..], b"v2"]) {
            send_command(
                &request_tx,
                Command::Set {
                    key: key(name.as_bytes()),
                    value: Bytes::copy_from_slice(value),
                    ttl: None,
                },
            )
            .await;
        }

        let mut addresses = HashMap::new();
        addresses.insert("peer".to_string(), peer_addr);
        let mut tokens = HashMap::new();
        tokens.insert("peer".to_string(), "tok-peer".to_string());

        let node_context = NodeContext {
            gates: Default::default(),
            name: "leaver".to_string(),
            token: "tk-leaver".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(Some(LeaveState {
                before_ring,
                after_ring,
                replication: 1,
                addresses,
                tokens,
                connections: Mutex::new(HashMap::new()),
            }))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });
        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        let (name_a, name_b) = (&owned_keys[0], &owned_keys[1]);
        let request = format!(
            "y 0 2 {} {} 60\n{name_a}{name_b}",
            name_a.len(),
            name_b.len()
        );
        client.write_all(request.as_bytes()).await.unwrap();
        client.shutdown().await.unwrap();

        let expected = b"Y 2 S S\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        assert_eq!(frames.len(), 2, "both touched keys must reach the entrant");
        let ttl = Some(Duration::from_secs(60));
        assert!(frames.contains(&handoff_message(
            &key(name_a.as_bytes()),
            b"v1",
            ttl,
            false,
            "tok-peer"
        )));
        assert!(frames.contains(&handoff_message(
            &key(name_b.as_bytes()),
            b"v2",
            ttl,
            false,
            "tok-peer"
        )));
    }

    #[test]
    fn leave_clear_targets_names_every_survivor_the_roster_can_reach() {
        let before_ring = Arc::new(HashRing::new(vec![
            "leaver".to_string(),
            "peer-a".to_string(),
            "peer-b".to_string(),
            "peer-c".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec![
            "peer-a".to_string(),
            "peer-b".to_string(),
            "peer-c".to_string(),
        ]));
        let mut addresses = HashMap::new();
        addresses.insert("leaver".to_string(), "127.0.0.1:1".to_string());
        addresses.insert("peer-a".to_string(), "127.0.0.1:2".to_string());
        addresses.insert("peer-b".to_string(), "127.0.0.1:3".to_string());
        addresses.insert("peer-c".to_string(), "127.0.0.1:4".to_string());
        let mut tokens = HashMap::new();
        tokens.insert("leaver".to_string(), "tok-leaver".to_string());
        tokens.insert("peer-a".to_string(), "tok-a".to_string());
        tokens.insert("peer-b".to_string(), "tok-b".to_string());
        // peer-c: no token in the roster — not a target.
        let node_context = NodeContext {
            gates: Default::default(),
            name: "leaver".to_string(),
            token: "tk-leaver".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: mpsc::channel(1).0,
            leaving: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        // No decommission in flight: nothing to forward to.
        assert!(leave_clear_targets(&node_context).is_empty());

        *node_context.leaving.lock().unwrap() = Some(LeaveState {
            before_ring,
            after_ring,
            replication: 2,
            addresses,
            tokens,
            connections: Mutex::new(HashMap::new()),
        });
        let targets = leave_clear_targets(&node_context);
        let addrs: Vec<&str> = targets.iter().map(|target| target.addr.as_str()).collect();
        // Every survivor with an address and a token, never this node.
        assert_eq!(addrs, vec!["127.0.0.1:2", "127.0.0.1:3"]);
        assert!(targets.iter().all(|target| !target.as_handoff));
        // The same shared connection a key's own forward uses, so the
        // queue keeps the clear behind that write.
        let via_key = {
            let leaving = node_context.leaving.lock().unwrap();
            leaving.as_ref().unwrap().forward_target("peer-a").unwrap()
        };
        assert!(Arc::ptr_eq(&via_key.connection, &targets[0].connection));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn decommission_forwards_a_clear_behind_the_write_it_queued_for_the_entrant() {
        // A client whose ring still names this draining node writes a key
        // here and then clears the namespace on every node it knows. The
        // write is queued for the entrant as a `U`; the clear used to go
        // only to a join's targets, so the entrant applied the client's
        // direct clear first and the late `U` brought the key back there,
        // on that one owner. Now the clear follows the write on the same
        // queue.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        let before_ring = Arc::new(HashRing::new(vec![
            "leaver".to_string(),
            "peer".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec!["peer".to_string()]));
        let owned = (0u32..1000)
            .map(|index| format!("key-{index}"))
            .find(|name| before_ring.is_owner(&key(name.as_bytes()), "leaver", 1))
            .expect("an owned key in range");

        let mut addresses = HashMap::new();
        addresses.insert("leaver".to_string(), "127.0.0.1:1".to_string());
        addresses.insert("peer".to_string(), peer_addr);
        let mut tokens = HashMap::new();
        tokens.insert("peer".to_string(), "tok-peer".to_string());

        let node_context = NodeContext {
            gates: Default::default(),
            name: "leaver".to_string(),
            token: "tk-leaver".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(Some(LeaveState {
                before_ring,
                after_ring,
                replication: 1,
                addresses,
                tokens,
                connections: Mutex::new(HashMap::new()),
            }))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // The write, then the clear of its (default) namespace.
        let request = format!("S {} 2\n{owned}v1c 0\n", owned.len());
        client.write_all(request.as_bytes()).await.unwrap();
        client.shutdown().await.unwrap();

        let expected = b"S\nC\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);

        // Both forwards are queued before their acks; delivery is async.
        for _ in 0..500 {
            if frames.lock().unwrap().len() >= 2 {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        assert_eq!(
            frames.len(),
            2,
            "the write and then the clear must reach the entrant: {frames:?}"
        );
        assert!(
            frames[0].starts_with(b"U "),
            "the write goes first, as a handoff: {:?}",
            frames[0]
        );
        assert_eq!(
            frames[1],
            b"f 0 8\ntok-peer".to_vec(),
            "the clear follows on the same connection, as a handoff"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_forwarded_clear_that_removed_something_follows_the_writes_queued_for_the_entrant() {
        // This draining node took a write (from a client, or relayed by
        // the node whose joiner it is) and queued it for its entrant.
        // The clear then reaches it forwarded (`f`), from the node that
        // forwards to it; it must follow that write on the entrant's
        // queue, or the write lands there after the entrant's own clear.
        // A forwarded clear that removed nothing here is not passed on:
        // nothing is queued it must follow, and that is what ends a
        // clear circling between two decommissions pointing at each
        // other.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        let before_ring = Arc::new(HashRing::new(vec![
            "leaver".to_string(),
            "peer".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec!["peer".to_string()]));
        let owned = (0u32..1000)
            .map(|index| format!("key-{index}"))
            .find(|name| before_ring.is_owner(&key(name.as_bytes()), "leaver", 1))
            .expect("an owned key in range");

        let mut addresses = HashMap::new();
        addresses.insert("leaver".to_string(), "127.0.0.1:1".to_string());
        addresses.insert("peer".to_string(), peer_addr);
        let mut tokens = HashMap::new();
        tokens.insert("peer".to_string(), "tok-peer".to_string());

        let node_context = NodeContext {
            gates: Default::default(),
            name: "leaver".to_string(),
            token: "tk-leaver".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(Some(LeaveState {
                before_ring,
                after_ring,
                replication: 1,
                addresses,
                tokens,
                connections: Mutex::new(HashMap::new()),
            }))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });
        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // The write (relayed here as a handoff, as the node whose
        // confirmed joiner this is relays it), then the forwarded clear,
        // then the same clear again, which finds nothing.
        let n = owned.len();
        let mut reply = [0_u8; 2];
        for (frame, expected_reply) in [
            (format!("U 0 {n} 2 9\ntk-leaver{owned}v1"), b"S\n"),
            ("f 0 9 A\ntk-leaver".to_string(), b"C\n"),
            ("f 0 9 A\ntk-leaver".to_string(), b"C\n"),
        ] {
            client.write_all(frame.as_bytes()).await.unwrap();
            tokio::time::timeout(Duration::from_secs(5), client.read_exact(&mut reply))
                .await
                .expect("a reply within 5 s")
                .unwrap();
            assert_eq!(&reply, expected_reply, "{frame:?}");
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
        client.shutdown().await.unwrap();

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        assert_eq!(
            frames,
            vec![
                format!("U 0 {n} 2 8\ntok-peer{owned}v1").into_bytes(),
                b"f 0 8 A\ntok-peer".to_vec(),
            ],
            "the clear that removed the key follows it to the entrant; the one that found \
             nothing stays here"
        );
    }

    /// A `RereplicationForward` for tests: `dead` was evicted, `me` is the
    /// surviving old owner of every key and `peer` the owner the change
    /// promoted (R = 2 over two names), reachable at `peer_addr`.
    fn rereplication_window(
        peer_addr: &str,
        completed_at: Option<Instant>,
    ) -> RereplicationForward {
        let mut addresses = HashMap::new();
        addresses.insert("me".to_string(), "127.0.0.1:1".to_string());
        addresses.insert("peer".to_string(), peer_addr.to_string());
        let mut tokens = HashMap::new();
        tokens.insert("me".to_string(), "tk-me".to_string());
        tokens.insert("peer".to_string(), "tok-peer".to_string());
        RereplicationForward {
            before_ring: Arc::new(HashRing::new(vec!["dead".to_string(), "me".to_string()])),
            after_ring: Arc::new(HashRing::new(vec!["me".to_string(), "peer".to_string()])),
            replication: 2,
            addresses,
            tokens,
            connections: Mutex::new(HashMap::new()),
            completed_at,
            grace: FORWARDING_GRACE_BASE,
        }
    }

    #[test]
    fn rereplication_targets_for_follow_the_window_and_clear_it_once_the_grace_has_passed() {
        let node_context = NodeContext {
            gates: Default::default(),
            name: "me".to_string(),
            token: "tk-me".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: mpsc::channel(1).0,
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };
        let k = key(b"any");

        // No window: nothing to mirror.
        assert!(handoff_targets_for(&node_context, &k).is_empty());

        // The pass is running: the promoted owner, as a handoff target.
        *node_context.rereplication_forward.lock().unwrap() =
            Some(rereplication_window("127.0.0.1:2", None));
        let targets = handoff_targets_for(&node_context, &k);
        assert_eq!(targets.len(), 1);
        assert_eq!(targets[0].addr, "127.0.0.1:2");
        assert_eq!(targets[0].token, "tok-peer");
        assert!(
            !targets[0].as_handoff,
            "a `U`/`u` frame, not a join's relay"
        );
        // Each target shares one connection, so forwards stay in order.
        assert!(Arc::ptr_eq(
            &targets[0].connection,
            &handoff_targets_for(&node_context, &k)[0].connection
        ));

        // Done a moment ago: still open, the clients have not refreshed.
        *node_context.rereplication_forward.lock().unwrap() =
            Some(rereplication_window("127.0.0.1:2", Some(Instant::now())));
        assert_eq!(handoff_targets_for(&node_context, &k).len(), 1);

        // The grace has passed: closed, and the slot is cleared.
        *node_context.rereplication_forward.lock().unwrap() = Some(rereplication_window(
            "127.0.0.1:2",
            Some(Instant::now() - FORWARDING_GRACE_BASE - Duration::from_secs(1)),
        ));
        assert!(handoff_targets_for(&node_context, &k).is_empty());
        assert!(node_context.rereplication_forward.lock().unwrap().is_none());

        // A node that was not an old owner of the key is no sender for it.
        let other = NodeContext {
            gates: Default::default(),
            name: "peer".to_string(),
            rereplication_forward: Arc::new(Mutex::new(Some(rereplication_window(
                "127.0.0.1:2",
                None,
            )))),
            ..node_context
        };
        assert!(handoff_targets_for(&other, &k).is_empty());
    }

    #[test]
    fn rereplication_targets_skip_a_promoted_owner_a_later_join_displaced() {
        // Issue #973: the window promoted `peer` for the keys `dead` held;
        // a join of `newer` adopted inside the window takes some of those
        // keys from `peer` again. A write of such a key must not be
        // forwarded to `peer` any more — it would land on the dead copy
        // the join left there and revive it — while a key `peer` still
        // owns under the adopted ring is forwarded as before.
        let node_context = NodeContext {
            gates: Default::default(),
            name: "me".to_string(),
            token: "tk-me".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: mpsc::channel(1).0,
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(Some(rereplication_window(
                "127.0.0.1:2",
                Some(Instant::now()),
            )))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };
        let adopted = Arc::new(HashRing::new(vec![
            "me".to_string(),
            "peer".to_string(),
            "newer".to_string(),
        ]));
        let before = HashRing::new(vec!["dead".to_string(), "me".to_string()]);
        // Keys this node sends for (an old owner under the window's
        // before-ring), split by whether `peer` still owns them once
        // `newer` is in.
        let mut kept = None;
        let mut taken = None;
        for i in 0..200 {
            let k = key(format!("k{i}").as_bytes());
            let hash = KeyHash::of(&k);
            if !before.is_owner_hashed(hash, "me", 2) {
                continue;
            }
            if adopted.is_owner_hashed(hash, "peer", 2) {
                kept.get_or_insert(k);
            } else {
                taken.get_or_insert(k);
            }
            if kept.is_some() && taken.is_some() {
                break;
            }
        }
        let (kept, taken) = (
            kept.expect("a key peer keeps"),
            taken.expect("a key newer takes"),
        );

        // Before the join is adopted the snapshot alone decides.
        assert_eq!(handoff_targets_for(&node_context, &kept).len(), 1);
        assert_eq!(handoff_targets_for(&node_context, &taken).len(), 1);

        *node_context.known_ring.lock().unwrap() = Some(Arc::new(Membership {
            ring: adopted,
            replication: 2,
        }));
        let targets = handoff_targets_for(&node_context, &kept);
        assert_eq!(targets.len(), 1, "peer still owns it: forwarded");
        assert_eq!(targets[0].addr, "127.0.0.1:2");
        assert!(
            handoff_targets_for(&node_context, &taken).is_empty(),
            "newer took it from peer: no forward to the displaced copy"
        );
    }

    #[test]
    fn rereplication_clear_targets_name_every_other_member_while_the_window_is_open() {
        let node_context = NodeContext {
            gates: Default::default(),
            name: "me".to_string(),
            token: "tk-me".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: mpsc::channel(1).0,
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };
        assert!(rereplication_clear_targets(&node_context).is_empty());

        *node_context.rereplication_forward.lock().unwrap() =
            Some(rereplication_window("127.0.0.1:2", None));
        let targets = rereplication_clear_targets(&node_context);
        assert_eq!(
            targets.len(),
            1,
            "every member of the ring after the change but this node"
        );
        assert_eq!(targets[0].addr, "127.0.0.1:2");
        assert_eq!(targets[0].token, "tok-peer");
        // The same connection the mirrored writes use, so the clear
        // queues behind them.
        assert!(Arc::ptr_eq(
            &targets[0].connection,
            &handoff_targets_for(&node_context, &key(b"any"))[0].connection
        ));

        *node_context.rereplication_forward.lock().unwrap() = Some(rereplication_window(
            "127.0.0.1:2",
            Some(Instant::now() - FORWARDING_GRACE_BASE - Duration::from_secs(1)),
        ));
        assert!(rereplication_clear_targets(&node_context).is_empty());
        assert!(node_context.rereplication_forward.lock().unwrap().is_none());
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_survivor_forwards_a_clear_to_the_promoted_owner_behind_the_write_it_mirrored() {
        // After `dead` was evicted, `me` mirrors a client's write of a key
        // to `peer`, the owner the change promoted. The client then
        // clears every node it knows — `peer` directly, and `me`. The
        // mirrored write used to be the only thing on `peer`'s queue, so
        // it could land after `peer`'s own clear and leave the cleared
        // key on that one owner; the clear now follows it on the same
        // connection. A forwarded clear (`f`) that removed something
        // here follows too.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        let node_context = NodeContext {
            gates: Default::default(),
            name: "me".to_string(),
            token: "tk-me".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(Some(rereplication_window(
                &peer_addr, None,
            )))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });
        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // The client's write and clear, then a handoff write and a
        // forwarded clear that removes it, then the same forwarded clear
        // again, which removes nothing.
        let mut reply = [0_u8; 2];
        for (frame, expected_reply) in [
            (&b"S 3 2\nkeyv1"[..], &b"S\n"[..]),
            (b"c 0\n", b"C\n"),
            (b"U 0 3 2 5\ntk-mekeyv2", b"S\n"),
            (b"f 0 5 A\ntk-me", b"C\n"),
            (b"f 0 5 A\ntk-me", b"C\n"),
        ] {
            client.write_all(frame).await.unwrap();
            tokio::time::timeout(Duration::from_secs(5), client.read_exact(&mut reply))
                .await
                .expect("a reply within 5 s")
                .unwrap();
            assert_eq!(&reply, expected_reply, "{frame:?}");
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
        client.shutdown().await.unwrap();

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        assert_eq!(
            frames,
            vec![
                b"U 0 3 2 8\ntok-peerkeyv1".to_vec(),
                b"f 0 8\ntok-peer".to_vec(),
                b"U 0 3 2 8\ntok-peerkeyv2".to_vec(),
                b"f 0 8 A\ntok-peer".to_vec(),
            ],
            "each clear follows the write queued before it; the forwarded clear that found \
             nothing stays here"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_survivor_mirrors_client_writes_to_the_owner_an_eviction_promoted() {
        // After `dead` was evicted, `me` re-replicates its keys to `peer`
        // (put-if-absent, read as it goes). A client still routing by the
        // old node list writes to `me` only — its leg to `dead` fails and
        // is swallowed — so without this mirror `peer` kept whatever the
        // pass handed it: the write, delete or increment acknowledged here
        // was missing on that owner until the key was written again.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        let node_context = NodeContext {
            gates: Default::default(),
            name: "me".to_string(),
            token: "tk-me".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(Some(rereplication_window(
                &peer_addr, None,
            )))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // A set, then a delete of the same key.
        client.write_all(b"S 3 2\nkeyv1D 3\nkey").await.unwrap();
        client.shutdown().await.unwrap();

        let expected = b"S\nD\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);

        for _ in 0..500 {
            if frames.lock().unwrap().len() >= 2 {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        assert_eq!(
            frames.len(),
            2,
            "the write and the delete must reach the promoted owner: {frames:?}"
        );
        // An unconditional `U` (no trailing `A`): the client's write is
        // newer than anything the pass carries.
        assert_eq!(frames[0], b"U 0 3 2 8\ntok-peerkeyv1");
        assert_eq!(frames[1], b"u 0 3 8\ntok-peerkey");
    }

    /// Issue #833: runs `exchanges` (a request frame and the reply it must
    /// get, and how many frames it must forward to each peer) through one
    /// client connection of a node that has both kinds of
    /// forward open at once — a join in flight, whose joiner is a
    /// migration target (`migration_targets_for`), and an eviction mirror,
    /// whose promoted owner is a handoff target (`handoff_targets_for`).
    /// Each exchange waits for its own forwards to arrive before the next
    /// one starts, since the forward queue replaces a queued write with a
    /// later one to the same key. Returns the frames each of the two peers
    /// recorded; a write that forgets one of the two forwards leaves one
    /// peer short, and a no-op that forwards anyway adds a frame.
    async fn frames_forwarded_to_joiner_and_promoted_owner(
        exchanges: &[(&[u8], &[u8], usize)],
    ) -> (Vec<Vec<u8>>, Vec<Vec<u8>>) {
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let joiner_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joiner_addr = joiner_listener.local_addr().unwrap().to_string();
        let (joiner_frames, joiner_task) = spawn_recording_peer(joiner_listener);
        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (peer_frames, peer_task) = spawn_recording_peer(peer_listener);

        let node_context = NodeContext {
            gates: Default::default(),
            name: "me".to_string(),
            token: "tk-me".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            // Two members at R = 2: the joiner is in every key's top-R.
            active_migration: Arc::new(Mutex::new(Some(ActiveMigration {
                joining_name: "joiner-0".to_string(),
                joining_addr: joiner_addr,
                joining_token: "tok-joiner-0".to_string(),
                after_ring: Arc::new(HashRing::new(vec![
                    "me".to_string(),
                    "joiner-0".to_string(),
                ])),
                replication: 2,
                generation: None,
                completed_at: None,
                forwarding_grace: Duration::from_secs(60),
                acked_entries: None,
                abort_requested: Arc::new(AtomicBool::new(false)),
                marked_keys: Vec::new(),
                confirmed: false,
                pre_completion_ring: None,
                pending_clears: PendingClears::default(),
                forward_connection: Arc::new(AsyncMutex::new(None)),
                forward_revoked: Arc::new(AtomicBool::new(false)),
                lingering: Vec::new(),
                remnant: false,
            }))),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(Some(rereplication_window(
                &peer_addr, None,
            )))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });
        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        let mut expected_frames = 0;
        for (request, expected_reply, forwards) in exchanges {
            client.write_all(request).await.unwrap();
            let mut reply = vec![0u8; expected_reply.len()];
            let read = tokio::time::timeout(Duration::from_secs(5), client.read_exact(&mut reply))
                .await
                .unwrap_or_else(|_| {
                    panic!(
                        "no reply within 5 s to {}",
                        String::from_utf8_lossy(request)
                    )
                });
            read.unwrap();
            assert_eq!(
                reply,
                *expected_reply,
                "reply to {}",
                String::from_utf8_lossy(request)
            );
            expected_frames += forwards;
            for _ in 0..500 {
                if joiner_frames.lock().unwrap().len() >= expected_frames
                    && peer_frames.lock().unwrap().len() >= expected_frames
                {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        }
        client.shutdown().await.unwrap();
        connection_task.await.unwrap().unwrap();

        joiner_task.abort();
        peer_task.abort();
        drop(forward_relay);
        drop(request_tx);
        cache_task.await.unwrap();

        let joiner_frames = joiner_frames.lock().unwrap().clone();
        let peer_frames = peer_frames.lock().unwrap().clone();
        (joiner_frames, peer_frames)
    }

    /// The frames a write to `name` forwards to the joiner and to the
    /// promoted owner, in that order: each as the handoff frame carrying
    /// that peer's own token.
    fn expected_forwards(name: &[u8], frame: impl Fn(&Key, &str) -> Vec<u8>) -> (Vec<u8>, Vec<u8>) {
        let key = key(name);
        (frame(&key, "tok-joiner-0"), frame(&key, "tok-peer"))
    }

    fn set_forward(name: &[u8], value: &'static [u8]) -> (Vec<u8>, Vec<u8>) {
        expected_forwards(name, |key, token| {
            handoff_message(key, value, None, false, token)
        })
    }

    fn set_forward_with_ttl(
        name: &[u8],
        value: &'static [u8],
        ttl: Duration,
    ) -> (Vec<u8>, Vec<u8>) {
        expected_forwards(name, |key, token| {
            handoff_message(key, value, Some(ttl), false, token)
        })
    }

    fn delete_forward(name: &[u8]) -> (Vec<u8>, Vec<u8>) {
        expected_forwards(name, handoff_delete_message)
    }

    /// Splits the pairs `set_forward` / `delete_forward` return into what
    /// each peer must have recorded.
    fn per_peer(forwards: Vec<(Vec<u8>, Vec<u8>)>) -> (Vec<Vec<u8>>, Vec<Vec<u8>>) {
        forwards.into_iter().unzip()
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_set_is_forwarded_to_the_joiner_and_to_the_promoted_owner() {
        let (joiner, peer) =
            frames_forwarded_to_joiner_and_promoted_owner(&[(b"S 3 2\nkeyv1", b"S\n", 1)]).await;
        let (expected_joiner, expected_peer) = per_peer(vec![set_forward(b"key", b"v1")]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_set_forwards_its_ttl_so_the_copy_still_expires() {
        let (joiner, peer) =
            frames_forwarded_to_joiner_and_promoted_owner(&[(b"S 3 2 60\nkeyv1", b"S\n", 1)]).await;
        let (expected_joiner, expected_peer) = per_peer(vec![set_forward_with_ttl(
            b"key",
            b"v1",
            Duration::from_secs(60),
        )]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_delete_is_forwarded_even_when_this_node_held_nothing() {
        // A delete can race ahead of the handoff that would have brought
        // the key here, so the forward does not depend on the reply.
        let (joiner, peer) =
            frames_forwarded_to_joiner_and_promoted_owner(&[(b"D 3\nkey", b"N\n", 1)]).await;
        let (expected_joiner, expected_peer) = per_peer(vec![delete_forward(b"key")]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn an_incr_forwards_its_result_as_a_set_and_a_no_op_forwards_nothing() {
        // The result goes out as the absolute value, never as `i` itself.
        // A miss (`N`) and a non-numeric value (`T`) changed nothing and
        // forward nothing; the closing set shows where the frames end.
        let (joiner, peer) = frames_forwarded_to_joiner_and_promoted_owner(&[
            (b"i 0 1 1\na", b"N\n", 0),
            (b"S 1 1\na5", b"S\n", 1),
            (b"i 0 1 2\na", b"I 1\n7", 1),
            (b"S 1 3\nbabc", b"S\n", 1),
            (b"i 0 1 1\nb", b"T\n", 0),
            (b"S 3 1\nendz", b"S\n", 1),
        ])
        .await;
        let (expected_joiner, expected_peer) = per_peer(vec![
            set_forward(b"a", b"5"),
            set_forward(b"a", b"7"),
            set_forward(b"b", b"abc"),
            set_forward(b"end", b"z"),
        ]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_cas_set_forwards_its_value_only_when_the_condition_held() {
        let (joiner, peer) = frames_forwarded_to_joiner_and_promoted_owner(&[
            (b"k 0 3 2 A\nkeyv1", b"S\n", 1),
            (b"k 0 3 2 A\nkeyv2", b"N\n", 0),
            (b"S 3 1\nendz", b"S\n", 1),
        ])
        .await;
        let (expected_joiner, expected_peer) =
            per_peer(vec![set_forward(b"key", b"v1"), set_forward(b"end", b"z")]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_cas_delete_forwards_a_delete_only_when_the_digest_matched() {
        let hex = |value: &[u8]| -> String {
            crate::cache::content_digest(value)
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect()
        };
        let wrong = format!("x 0 3 {}\nkey", hex(b"other"));
        let right = format!("x 0 3 {}\nkey", hex(b"v1"));
        let (joiner, peer) = frames_forwarded_to_joiner_and_promoted_owner(&[
            (b"S 3 2\nkeyv1", b"S\n", 1),
            (wrong.as_bytes(), b"N\n", 0),
            (right.as_bytes(), b"D\n", 1),
            (b"S 3 1\nendz", b"S\n", 1),
        ])
        .await;
        let (expected_joiner, expected_peer) = per_peer(vec![
            set_forward(b"key", b"v1"),
            delete_forward(b"key"),
            set_forward(b"end", b"z"),
        ]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_touch_forwards_its_result_as_a_set_and_a_miss_forwards_nothing() {
        // The new TTL goes out with the value the touch left, as a `Set`
        // (never as `t` itself); `G` or not makes no difference to what
        // is forwarded, and a touch that found no key changed nothing.
        let (joiner, peer) = frames_forwarded_to_joiner_and_promoted_owner(&[
            (b"S 3 2\nkeyv1", b"S\n", 1),
            (b"t 0 3 60\nkey", b"S\n", 1),
            (b"t 0 3 G\nkey", b"V 2\nv1", 1),
            (b"t 0 4 30\nnope", b"N\n", 0),
            (b"S 3 1\nendz", b"S\n", 1),
        ])
        .await;
        let (expected_joiner, expected_peer) = per_peer(vec![
            set_forward(b"key", b"v1"),
            set_forward_with_ttl(b"key", b"v1", Duration::from_secs(60)),
            set_forward(b"key", b"v1"),
            set_forward(b"end", b"z"),
        ]);
        assert_eq!(joiner, expected_joiner, "joiner");
        assert_eq!(peer, expected_peer, "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_batch_touch_forwards_each_touched_key_as_a_set_and_a_miss_forwards_nothing() {
        // Like the single-key touch: the new TTL goes out with the value
        // each touched key holds, as a `Set`, to the joiner and to the
        // promoted owner; `G` or not makes no difference to what is
        // forwarded, and a key that was not there changed nothing.
        let (joiner, peer) = frames_forwarded_to_joiner_and_promoted_owner(&[
            (b"S 4 2\nkey1v1", b"S\n", 1),
            (b"S 4 2\nkey2v2", b"S\n", 1),
            (b"y 0 3 4 4 4 60\nkey1key2nope", b"Y 3 S S N\n", 2),
            (b"y 0 3 4 4 4 G\nkey1key2nope", b"M 3 2 2 -\nv1v2", 2),
        ])
        .await;
        let (expected_joiner, expected_peer) = per_peer(vec![
            set_forward(b"key1", b"v1"),
            set_forward(b"key2", b"v2"),
            set_forward_with_ttl(b"key1", b"v1", Duration::from_secs(60)),
            set_forward_with_ttl(b"key2", b"v2", Duration::from_secs(60)),
            set_forward(b"key1", b"v1"),
            set_forward(b"key2", b"v2"),
        ]);
        let sorted = |mut frames: Vec<Vec<u8>>| {
            frames.sort();
            frames
        };
        assert_eq!(sorted(joiner), sorted(expected_joiner), "joiner");
        assert_eq!(sorted(peer), sorted(expected_peer), "promoted owner");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_relayed_delete_keeps_the_key_out_when_the_handoff_copy_lands_after_it() {
        // The receiving side of the race a joiner (or an eviction's newly
        // promoted owner) sees: an old owner relays a client's delete as
        // `u` while another sender's transfer, which read the key before
        // that delete, delivers it put-if-absent (`U … A`) a moment
        // later. On one node, over the wire, in that order: the delete
        // answers `N` (nothing held yet), the put-if-absent is a success
        // for its sender (`S`) but stores nothing, and a read finds the
        // key absent.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));
        let node_context = NodeContext {
            gates: Default::default(),
            name: "entrant".to_string(),
            token: "tk-entrant".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(None)),
            rereplication_forward: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // The relayed delete, the late put-if-absent copy, then a read;
        // each handoff frame carries this node's token (issue #295).
        let request = b"u 0 3 10\ntk-entrantkeyU 0 3 2 10 A\ntk-entrantkeyv0G 3\nkey";
        client.write_all(request).await.unwrap();
        client.shutdown().await.unwrap();

        let expected = b"N\nS\nN\n";
        let mut response = vec![0u8; expected.len()];
        tokio::time::timeout(Duration::from_secs(5), client.read_exact(&mut response))
            .await
            .expect("three replies within 5 s")
            .unwrap();
        assert_eq!(
            response, expected,
            "the delete finds nothing, the put-if-absent is acked without storing, the read misses"
        );

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn decommission_forwards_handoff_frames_it_receives_to_the_entrant() {
        // A draining node can be handed a key by `U`/`u` rather than `S`/`D`:
        // by a lingering joiner's old owner (`ForwardTarget::as_handoff`),
        // by a peer whose own drain-out chains into this one, or by a
        // survivor re-replicating after an eviction. Those arms used to
        // relay only to a join in progress, never to the decommission's
        // entrant, so a write landing after this node's drain snapshot
        // stayed here and left with it (an old value on the entrant, or a
        // deleted key coming back). Same mirror as the `S`/`D` arms, same
        // frame onward — a put-if-absent `U` stays put-if-absent.
        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let peer_addr = peer_listener.local_addr().unwrap().to_string();
        let (frames, peer_task) = spawn_recording_peer(peer_listener);

        let before_ring = Arc::new(HashRing::new(vec![
            "leaver".to_string(),
            "peer".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec!["peer".to_string()]));

        let mut owned_keys = Vec::new();
        let mut index = 0u32;
        while owned_keys.len() < 3 {
            let name = format!("key-{index}");
            if before_ring.is_owner(&key(name.as_bytes()), "leaver", 1) {
                owned_keys.push(name);
            }
            index += 1;
            assert!(index < 1000, "expected at least three owned keys in range");
        }

        let mut addresses = HashMap::new();
        addresses.insert("peer".to_string(), peer_addr);
        let mut tokens = HashMap::new();
        tokens.insert("peer".to_string(), "tok-peer".to_string());

        let node_context = NodeContext {
            gates: Default::default(),
            name: "leaver".to_string(),
            token: "tk-leaver".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: request_tx.clone(),
            leaving: Arc::new(Mutex::new(Some(LeaveState {
                before_ring,
                after_ring,
                replication: 1,
                addresses,
                tokens,
                connections: Mutex::new(HashMap::new()),
            }))),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        let (forward_tx, mut forward_rx) = mpsc::channel::<MigrationTask>(4);
        let forward_relay = tokio::spawn(async move {
            while let Some(task) = forward_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));

        // The leaver's own token ("tk-leaver") authorizes each inbound
        // frame (issue #295): an unconditional `U`, a put-if-absent `U`,
        // and a `u` for a key this node never held.
        let name_a = &owned_keys[0];
        let name_b = &owned_keys[1];
        let name_c = &owned_keys[2];
        let request = format!(
            "U 0 {} 2 9\ntk-leaver{name_a}v1U 0 {} 2 9 A\ntk-leaver{name_b}v2u 0 {} 9\ntk-leaver{name_c}",
            name_a.len(),
            name_b.len(),
            name_c.len()
        );
        client.write_all(request.as_bytes()).await.unwrap();
        client.shutdown().await.unwrap();

        let expected = b"S\nS\nN\n";
        let mut response = vec![0u8; expected.len()];
        client.read_exact(&mut response).await.unwrap();
        assert_eq!(response, expected);

        connection_task.await.unwrap().unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
        drop(forward_relay);
        peer_task.abort();

        let frames = frames.lock().unwrap().clone();
        // The two handoffs that changed this node's store go on to the
        // entrant; the `u` found nothing here (`N`), so there is nothing
        // of it to leave with this node, and it is not relayed.
        assert_eq!(
            frames.len(),
            2,
            "the handoffs that changed something must forward to the entrant: {frames:?}"
        );
        let expected_a = format!("U 0 {} 2 8\ntok-peer{name_a}v1", name_a.len()).into_bytes();
        let expected_b = format!("U 0 {} 2 8 A\ntok-peer{name_b}v2", name_b.len()).into_bytes();
        assert!(frames.contains(&expected_a), "unconditional U: {frames:?}");
        assert!(frames.contains(&expected_b), "put-if-absent U: {frames:?}");
    }

    #[tokio::test(flavor = "current_thread")]
