    #[test]
    fn set_message_without_a_ttl_omits_the_third_header_field() {
        assert_eq!(
            set_message(&key(b"name"), b"Alice", None),
            b"S 4 5\nnameAlice".to_vec()
        );
    }

    #[test]
    fn set_message_with_a_ttl_rounds_up_to_whole_seconds() {
        assert_eq!(
            set_message(&key(b"name"), b"Alice", Some(Duration::from_millis(4100))),
            b"S 4 5 5\nnameAlice".to_vec()
        );
        // Under a second left must not go out as 0: the receiving copy would
        // be stored already expired.
        assert_eq!(
            set_message(&key(b"name"), b"Alice", Some(Duration::from_millis(900))),
            b"S 4 5 1\nnameAlice".to_vec()
        );
        // An expiring touch forwarded as a set keeps its 0.
        assert_eq!(
            set_message(&key(b"name"), b"Alice", Some(Duration::ZERO)),
            b"S 4 5 0\nnameAlice".to_vec()
        );
    }

    #[test]
    fn handoff_message_rounds_a_sub_second_ttl_up_and_keeps_zero() {
        let token = "0123456789abcdef";
        let one = handoff_message(
            &key(b"name"),
            b"Alice",
            Some(Duration::from_millis(900)),
            false,
            token,
        );
        assert!(
            one.starts_with(b"U 0 4 5 16 1\n"),
            "{:?}",
            String::from_utf8_lossy(&one)
        );
        let zero = handoff_message(&key(b"name"), b"Alice", Some(Duration::ZERO), false, token);
        assert!(
            zero.starts_with(b"U 0 4 5 16 0\n"),
            "{:?}",
            String::from_utf8_lossy(&zero)
        );
    }

    #[test]
    fn set_message_for_a_namespaced_key_uses_the_lowercase_frame() {
        // Issue #105: namespace length leads, namespace bytes lead the body.
        let namespaced = Key::new(Bytes::from_static(b"users"), Bytes::from_static(b"name"));
        assert_eq!(
            set_message(&namespaced, b"Alice", Some(Duration::from_secs(4))),
            b"s 5 4 5 4\nusersnameAlice".to_vec()
        );
        assert_eq!(delete_message(&namespaced), b"d 5 4\nusersname".to_vec());
        // The default namespace keeps the legacy frames byte-for-byte, so a
        // mixed-version handoff still works for un-namespaced traffic.
        assert_eq!(delete_message(&key(b"name")), b"D 4\nname".to_vec());
    }

