    // ── migration-generation-guard: `M`'s generation vs. same-name retries ──

    #[test]
    fn migration_guard_new_answers_a_same_generation_retry_with_duplicate_acked() {
        // A discovery retry of the exact same handoff (lost `A` ack): same
        // `joining_name` *and* the same `generation` — must re-ack
        // idempotently, not be treated as a supersede.
        let slot = Arc::new(Mutex::new(Some(ActiveMigration {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            after_ring: Arc::new(HashRing::new(vec![
                "ready-node".to_string(),
                "joiner-0".to_string(),
            ])),
            replication: 2,
            generation: Some(7),
            completed_at: None,
            forwarding_grace: Duration::ZERO,
            acked_entries: Some(42),
            abort_requested: Arc::new(AtomicBool::new(false)),
            marked_keys: Vec::new(),
            confirmed: false,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering: Vec::new(),
            remnant: false,
        })));

        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));
        let outcome = MigrationGuard::new(
            Arc::clone(&slot),
            "joiner-0".to_string(),
            "127.0.0.1:9".to_string(),
            "tok-joiner-0".to_string(),
            after_ring,
            2,
            Some(7),
            &[],
            &known_ring,
            &RingHistory::default(),
        );

        assert!(
            matches!(outcome, MigrationOutcome::DuplicateAcked(42)),
            "a retry of the same handoff at the same generation must re-ack idempotently"
        );
        assert!(
            !slot
                .lock()
                .unwrap()
                .as_ref()
                .unwrap()
                .abort_requested
                .load(Ordering::SeqCst),
            "a benign retry must not abort the handoff"
        );
    }

    #[test]
    fn migration_guard_new_supersedes_a_still_transferring_handoff_at_a_new_generation() {
        // Same `joining_name`, but the incoming `M` carries a different
        // generation: a crash + fast restart of the joining node under the
        // same identity, racing the still-running handoff for the old
        // instance. The stale handoff can't be handed the slot
        // synchronously (only its own `run_migration` unwind can safely
        // drop it mid-transfer), so this must reject with `Conflict` while
        // also flagging the stale handoff to stop.
        let slot = Arc::new(Mutex::new(Some(ActiveMigration {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            after_ring: Arc::new(HashRing::new(vec![
                "ready-node".to_string(),
                "joiner-0".to_string(),
            ])),
            replication: 2,
            generation: Some(1),
            completed_at: None,
            forwarding_grace: Duration::ZERO,
            acked_entries: Some(0),
            abort_requested: Arc::new(AtomicBool::new(false)),
            marked_keys: Vec::new(),
            confirmed: false,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering: Vec::new(),
            remnant: false,
        })));

        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));
        let outcome = MigrationGuard::new(
            Arc::clone(&slot),
            "joiner-0".to_string(),
            "127.0.0.1:11".to_string(),
            "tok-joiner-0-v2".to_string(),
            after_ring,
            2,
            Some(2),
            &[],
            &known_ring,
            &RingHistory::default(),
        );

        assert!(
            matches!(outcome, MigrationOutcome::Conflict),
            "a still-transferring handoff at an old generation must not be clobbered \
             synchronously"
        );
        let existing = slot.lock().unwrap();
        let active = existing
            .as_ref()
            .expect("the stale handoff's slot must be left in place for its own unwind");
        assert_eq!(
            active.generation,
            Some(1),
            "the stale handoff itself must be untouched, not overwritten"
        );
        assert!(
            active.abort_requested.load(Ordering::SeqCst),
            "the superseded handoff must be told to stop"
        );
    }

    #[test]
    fn migration_guard_new_treats_a_completed_handoff_at_a_new_generation_like_a_different_joiner_supersede()
     {
        // Same scenario as `migration_guard_new_reverts_known_ring_for_an_
        // implicitly_abandoned_handoff`, but the previous handoff is
        // superseded by the *same* `joining_name` at a new generation
        // instead of a genuinely different name. Once the old handoff has
        // completed (forwarding grace or not), this must fall into the
        // exact same issue #62/#93 supersede logic a different name does:
        // `joined` says whether it was confirmed, and if not, its marks
        // come back and `known_ring` reverts.
        let before_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "other-node".to_string(),
        ]));
        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "other-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let pre_completion_ring = Arc::new(Membership {
            ring: Arc::clone(&before_ring),
            replication: 2,
        });
        let known_ring: KnownRing = Arc::new(Mutex::new(Some(Arc::new(Membership {
            ring: Arc::clone(&after_ring),
            replication: 2,
        }))));
        let slot = Arc::new(Mutex::new(Some(ActiveMigration {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            after_ring: Arc::clone(&after_ring),
            replication: 2,
            generation: Some(1),
            completed_at: Some(Instant::now()),
            forwarding_grace: forwarding_grace(0),
            acked_entries: Some(0),
            abort_requested: Arc::new(AtomicBool::new(false)),
            marked_keys: vec![key(b"key-3")],
            confirmed: false,
            pre_completion_ring: Some(Arc::clone(&pre_completion_ring)),
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering: Vec::new(),
            remnant: false,
        })));

        // `M` for joiner-0 again at generation 2 (a fresh join after a
        // crash + fast restart); the roster doesn't list joiner-0, so its
        // previous, completed-but-unconfirmed instance was abandoned.
        let joined = vec![("ready-node".to_string(), "127.0.0.1:1".to_string())];
        let outcome = MigrationGuard::new(
            Arc::clone(&slot),
            "joiner-0".to_string(),
            "127.0.0.1:11".to_string(),
            "tok-joiner-0-v2".to_string(),
            Arc::clone(&after_ring),
            2,
            Some(2),
            &joined,
            &known_ring,
            &RingHistory::default(),
        );

        let _guard = match outcome {
            MigrationOutcome::New { restore, guard } => {
                assert_eq!(
                    restore,
                    vec![key(b"key-3")],
                    "the old instance's dead copies must come back"
                );
                guard
            }
            _ => panic!(
                "a completed handoff superseded by a new generation must accept the new join"
            ),
        };

        assert!(
            Arc::ptr_eq(
                known_ring.lock().unwrap().as_ref().unwrap(),
                &pre_completion_ring,
            ),
            "known_ring must revert to the pre-join snapshot, exactly like a different-joiner \
             supersede"
        );
        assert_eq!(
            slot.lock().unwrap().as_ref().unwrap().generation,
            Some(2),
            "the slot must now track the new handoff's own generation"
        );
    }

    /// Issue #564 helpers: a completed, confirmed handoff to `name`, as the
    /// slot would hold it right before the next `M`.
    fn completed_slot_for(
        name: &str,
        addr: &str,
        after_ring: Arc<HashRing>,
        grace: Duration,
        confirmed: bool,
    ) -> ActiveMigration {
        ActiveMigration {
            joining_name: name.to_string(),
            joining_addr: addr.to_string(),
            joining_token: format!("tok-{name}"),
            after_ring,
            replication: 2,
            generation: Some(1),
            completed_at: Some(Instant::now()),
            forwarding_grace: grace,
            acked_entries: Some(0),
            abort_requested: Arc::new(AtomicBool::new(false)),
            marked_keys: Vec::new(),
            confirmed,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering: Vec::new(),
            remnant: false,
        }
    }

    fn node_context_over(slot: Arc<Mutex<Option<ActiveMigration>>>) -> NodeContext {
        NodeContext {
            gates: Default::default(),
            name: "ready-node".to_string(),
            token: "tk-ready-node".to_string(),
            discovery_addr: "127.0.0.1:0".to_string(),
            active_migration: slot,
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx: mpsc::channel(1).0,
            leaving: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        }
    }

    /// Of the first 2000 test keys, those for which `owner` is in the
    /// top-2 of `ring`.
    fn keys_owned_by(ring: &HashRing, owner: &str) -> Vec<Key> {
        (0..2000)
            .map(|i| key(format!("key-{i}").as_bytes()))
            .filter(|candidate| ring.is_owner_hashed(KeyHash::of(candidate), owner, 2))
            .collect()
    }

    #[test]
    fn a_confirmed_previous_joiner_keeps_receiving_forwards_after_the_next_m() {
        // Issue #564: the next join's `M` replaces the slot, but the earlier
        // joiner is confirmed and its forwarding grace is still open, so a
        // client that still writes to the old owners must keep reaching it
        // — for the keys it owns now, and only those.
        let ring_one = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "other-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let ring_two = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "other-node".to_string(),
            "joiner-0".to_string(),
            "joiner-1".to_string(),
        ]));
        let slot = Arc::new(Mutex::new(Some(completed_slot_for(
            "joiner-0",
            "127.0.0.1:9",
            Arc::clone(&ring_one),
            Duration::from_secs(60),
            true,
        ))));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));
        let joined = vec![
            ("ready-node".to_string(), "127.0.0.1:1".to_string()),
            ("joiner-0".to_string(), "127.0.0.1:9".to_string()),
        ];
        let _guard = match MigrationGuard::new(
            Arc::clone(&slot),
            "joiner-1".to_string(),
            "127.0.0.1:11".to_string(),
            "tok-joiner-1".to_string(),
            Arc::clone(&ring_two),
            2,
            Some(1),
            &joined,
            &known_ring,
            &RingHistory::default(),
        ) {
            MigrationOutcome::New { guard, .. } => guard,
            _ => panic!("a completed handoff must not block the next join"),
        };
        let node_context = node_context_over(Arc::clone(&slot));

        // A key owned by joiner-0 but not joiner-1 is still forwarded to
        // joiner-0 (the slot's own joiner doesn't own it).
        let only_old = keys_owned_by(&ring_two, "joiner-0")
            .into_iter()
            .find(|candidate| !ring_two.is_owner_hashed(KeyHash::of(candidate), "joiner-1", 2))
            .expect("a key owned by joiner-0 alone");
        // As `U`/`u` frames: the lingering joiner is a confirmed member
        // whose own ring may lag the slot's (`ForwardTarget::as_handoff`).
        let targets: Vec<(String, bool)> = migration_targets_for(&node_context, &only_old)
            .into_iter()
            .map(|target| (target.addr, target.as_handoff))
            .collect();
        assert_eq!(targets, vec![("127.0.0.1:9".to_string(), true)]);

        // A key both own goes to both, the slot's own joiner first — both
        // as `U`/`u` frames: the slot's own joiner refuses plain frames
        // until it is promoted.
        let both = keys_owned_by(&ring_two, "joiner-0")
            .into_iter()
            .find(|candidate| ring_two.is_owner_hashed(KeyHash::of(candidate), "joiner-1", 2))
            .expect("a key owned by both joiners");
        let targets: Vec<(String, bool)> = migration_targets_for(&node_context, &both)
            .into_iter()
            .map(|target| (target.addr, target.as_handoff))
            .collect();
        assert_eq!(
            targets,
            vec![
                ("127.0.0.1:11".to_string(), true),
                ("127.0.0.1:9".to_string(), true)
            ]
        );

        // The earlier joiner's forwards are not revoked by the takeover.
        let slot_guard = slot.lock().unwrap();
        let active = slot_guard.as_ref().unwrap();
        assert_eq!(active.lingering.len(), 1);
        assert!(!active.lingering[0].forward_revoked.load(Ordering::SeqCst));
    }

    #[test]
    fn a_previous_joiner_is_not_kept_when_abandoned_or_out_of_grace_or_restarted() {
        let ring_one = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let ring_two = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
            "joiner-1".to_string(),
        ]));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));

        // (previous confirmed?, its grace, joiner name of the new M, roster
        // lists the previous joiner?, its forwards must be revoked?) — a
        // slot whose grace is already over is cleared lazily before the new
        // `M` looks at it, with nothing left to revoke.
        let cases = [
            (false, Duration::from_secs(60), "joiner-1", false, true), // abandoned
            (true, Duration::ZERO, "joiner-1", true, false),           // grace over
            (true, Duration::from_secs(60), "joiner-0", true, true),   // same name, new generation
        ];
        for (confirmed, grace, new_name, listed, must_revoke) in cases {
            let slot = Arc::new(Mutex::new(Some(completed_slot_for(
                "joiner-0",
                "127.0.0.1:9",
                Arc::clone(&ring_one),
                grace,
                confirmed,
            ))));
            let revoked = Arc::clone(&slot.lock().unwrap().as_ref().unwrap().forward_revoked);
            let joined = if listed {
                vec![("joiner-0".to_string(), "127.0.0.1:9".to_string())]
            } else {
                Vec::new()
            };
            let outcome = MigrationGuard::new(
                Arc::clone(&slot),
                new_name.to_string(),
                "127.0.0.1:11".to_string(),
                "tok-new".to_string(),
                Arc::clone(&ring_two),
                2,
                Some(2),
                &joined,
                &known_ring,
                &RingHistory::default(),
            );
            assert!(matches!(outcome, MigrationOutcome::New { .. }));
            assert!(
                slot.lock().unwrap().as_ref().unwrap().lingering.is_empty(),
                "case ({confirmed}, {grace:?}, {new_name}) must not keep the old joiner"
            );
            assert_eq!(
                revoked.load(Ordering::SeqCst),
                must_revoke,
                "case ({confirmed}, {grace:?}, {new_name}): revocation of the old joiner's forwards"
            );
        }
    }

    #[test]
    fn adopt_membership_revokes_a_lingering_joiner_that_discovery_evicted() {
        // Issue #564 with #267/#474: a lingering joiner that leaves the
        // roster is gone; its queued forwards must not reach whoever gets
        // its address next.
        let ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
            "joiner-1".to_string(),
        ]));
        let mut current = completed_slot_for(
            "joiner-1",
            "127.0.0.1:11",
            Arc::clone(&ring),
            Duration::from_secs(60),
            true,
        );
        let lingering_revoked = Arc::new(AtomicBool::new(false));
        current.lingering.push(LingeringForward {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            completed_at: Instant::now(),
            forwarding_grace: Duration::from_secs(60),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::clone(&lingering_revoked),
        });
        let slot = Arc::new(Mutex::new(Some(current)));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));

        // joiner-0 is still listed: kept.
        adopt_membership(
            &known_ring,
            &slot,
            "disc:1",
            vec![
                "ready-node".to_string(),
                "joiner-0".to_string(),
                "joiner-1".to_string(),
            ],
            2,
        );
        assert_eq!(slot.lock().unwrap().as_ref().unwrap().lingering.len(), 1);
        assert!(!lingering_revoked.load(Ordering::SeqCst));

        // joiner-0 is gone from the roster: revoked and dropped.
        adopt_membership(
            &known_ring,
            &slot,
            "disc:1",
            vec!["ready-node".to_string(), "joiner-1".to_string()],
            2,
        );
        assert!(slot.lock().unwrap().as_ref().unwrap().lingering.is_empty());
        assert!(lingering_revoked.load(Ordering::SeqCst));
    }

    #[test]
    fn a_slot_stays_while_a_lingering_joiner_is_inside_its_grace_and_clears_go_to_it() {
        let ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
            "joiner-1".to_string(),
        ]));
        // The slot's own grace is over and its join confirmed...
        let mut current = completed_slot_for(
            "joiner-1",
            "127.0.0.1:11",
            Arc::clone(&ring),
            Duration::ZERO,
            true,
        );
        // ...but an earlier joiner still owes writes.
        current.lingering.push(LingeringForward {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            completed_at: Instant::now(),
            forwarding_grace: Duration::from_secs(60),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
        });
        assert!(
            !current.expired(),
            "a slot with a lingering joiner inside its grace must not be cleared"
        );
        let slot = Arc::new(Mutex::new(Some(current)));
        let node_context = node_context_over(Arc::clone(&slot));

        let addrs: Vec<String> = lingering_clear_targets(&node_context)
            .into_iter()
            .map(|target| target.addr)
            .collect();
        assert_eq!(addrs, vec!["127.0.0.1:9".to_string()]);

        // Once the lingering joiner's grace is over too, the slot expires.
        slot.lock().unwrap().as_mut().unwrap().lingering[0].forwarding_grace = Duration::ZERO;
        assert!(lingering_clear_targets(&node_context).is_empty());
        assert!(slot.lock().unwrap().as_ref().unwrap().expired());
    }

    #[test]
    fn migration_guard_new_treats_a_legacy_generation_as_matching_any_generation() {
        // Rolling upgrade: the handoff already occupying this slot was
        // started by an `M` with no `generation` field (an old discovery
        // process, or a pre-#421(c) peer) — `existing.generation` is
        // `None`. A retry of that same handoff from a since-upgraded
        // discovery process now carries a `generation`. Neither side can
        // tell from generation info alone whether this is really the same
        // handoff, so `None` must not be treated as "definitely
        // different" — same-name is still enough, matching the
        // pre-generation-check behavior this fn had before.
        let slot = Arc::new(Mutex::new(Some(ActiveMigration {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            after_ring: Arc::new(HashRing::new(vec![
                "ready-node".to_string(),
                "joiner-0".to_string(),
            ])),
            replication: 2,
            generation: None,
            completed_at: None,
            forwarding_grace: Duration::ZERO,
            acked_entries: Some(99),
            abort_requested: Arc::new(AtomicBool::new(false)),
            marked_keys: Vec::new(),
            confirmed: false,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering: Vec::new(),
            remnant: false,
        })));

        let after_ring = Arc::new(HashRing::new(vec![
            "ready-node".to_string(),
            "joiner-0".to_string(),
        ]));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));
        let outcome = MigrationGuard::new(
            Arc::clone(&slot),
            "joiner-0".to_string(),
            "127.0.0.1:9".to_string(),
            "tok-joiner-0".to_string(),
            after_ring,
            2,
            Some(5),
            &[],
            &known_ring,
            &RingHistory::default(),
        );

        assert!(
            matches!(outcome, MigrationOutcome::DuplicateAcked(99)),
            "a legacy (generation-less) existing handoff must still match a same-name retry"
        );
        assert!(
            !slot
                .lock()
                .unwrap()
                .as_ref()
                .unwrap()
                .abort_requested
                .load(Ordering::SeqCst),
            "a benign retry must not abort the handoff"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_transfers_matching_keys_and_reports_completion() {
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;

        // A fake joining node: accepts one connection, expects a SET (no
        // auth configured), and acks it.
        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let joining_received: Arc<std::sync::Mutex<Vec<u8>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let joining_received_task = Arc::clone(&joining_received);
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let bytes_read = connection.read(&mut buffer).await.unwrap();
            joining_received_task
                .lock()
                .unwrap()
                .extend_from_slice(&buffer[..bytes_read]);
            connection.write_all(b"S\n").await.unwrap();
        });

        // A fake discovery server: accepts one connection, expects C, acks
        // it.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();
        let discovery_received: Arc<std::sync::Mutex<Vec<u8>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let discovery_received_task = Arc::clone(&discovery_received);
        let discovery_task = tokio::spawn(async move {
            let (mut connection, _) = discovery_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let bytes_read = connection.read(&mut buffer).await.unwrap();
            discovery_received_task
                .lock()
                .unwrap()
                .extend_from_slice(&buffer[..bytes_read]);
            connection.write_all(b"A\n").await.unwrap();
        });

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        // Stands in for `run`'s own loop, which is what normally drains
        // `migration_tx` and spawns what it receives (see
        // `ConnectionConfig::migration_tx`) — `handle_connection` itself no
        // longer spawns `run_migration` directly.
        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        // No other Joined nodes: the after-join ring has only the joining
        // node in it, so every key (including "name") routes to it.
        // Chosen so HRW ranks it above "ready-node" for both test keys
        // ("name", "age") — the transfer set must be non-empty.
        let joining_name = "joiner-107";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-107";
        // Tenth-pass audit (2026-09-02), issue #421(c): a trailing
        // generation field, exercising the path where this node must
        // echo it back unchanged on its own `C` report — see the
        // assertion below and `complete_message`'s doc comment. The
        // sibling tests `migrate_command_accepts_a_different_joining_node_once_the_handoff_completed`
        // and `migrate_command_reuses_one_connection_for_every_key`
        // deliberately keep the legacy, generation-free `M` header, so
        // the two together cover both wire forms end to end.
        let generation = 42u64;
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {} {generation}\n",
            joining_name.len(),
            joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(joining_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());

        client.write_all(&migrate_message).await.unwrap();

        let mut ack = [0u8; 4];
        client.read_exact(&mut ack).await.unwrap();
        assert_eq!(&ack, b"A 1\n");

        for _ in 0..1000 {
            if !discovery_received.lock().unwrap().is_empty() {
                break;
            }
            tokio::time::sleep(Duration::from_millis(1)).await;
        }

        // Issue #266: run_migration's own bulk transfer now sends a
        // put-if-absent `U … A`, not a plain `S` — see its doc comment.
        let expected_set = handoff_message(&key(b"name"), b"Alice", None, true, joining_token);
        assert_eq!(*joining_received.lock().unwrap(), expected_set);
        assert_eq!(
            *discovery_received.lock().unwrap(),
            complete_message(
                "ready-node",
                "joiner-107",
                "tk-ready-node",
                Some(generation)
            ),
            "the M's own generation must come back unchanged on C (issue #421(c))"
        );

        joining_task.await.unwrap();
        discovery_task.await.unwrap();
        // Ends `connection_task` (dropping its `node_context`'s
        // `request_tx` clone) before awaiting `cache_task`, which needs
        // every sender dropped to see its channel close — otherwise this
        // deadlocks until `handle_connection`'s own idle timeout breaks
        // it, wasting `IDLE_TIMEOUT` (30s) on every run for nothing (the
        // same class of ordering bug `run`'s shutdown path had).
        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_with_the_wrong_token_is_rejected_and_transfers_nothing() {
        // Security regression (issue #34, node side): the shared secret only
        // proves "cluster member", so an `M` from any client holding it must
        // NOT be honored unless it echoes this node's own membership token —
        // otherwise a client could make the node stream its cache to an
        // attacker-chosen address. A wrong token must be rejected outright,
        // no migration started, no `SET` forwarded anywhere.
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;

        // An address the node would stream keys to if it (wrongly) honored
        // the `M`. Nothing must ever connect here.
        let attacker_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let attacker_addr = attacker_listener.local_addr().unwrap().to_string();
        let attacker_connected = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let attacker_flag = Arc::clone(&attacker_connected);
        let attacker_task = tokio::spawn(async move {
            if attacker_listener.accept().await.is_ok() {
                attacker_flag.store(true, Ordering::SeqCst);
            }
        });

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr: "127.0.0.1:1".to_string(),
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        let joining_name = "joiner-107";
        let wrong_token = "tk-not-mine";
        let joining_token = "tok-joiner-107";
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            joining_name.len(),
            attacker_addr.len(),
            joining_token.len(),
            wrong_token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(wrong_token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(attacker_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());
        client.write_all(&migrate_message).await.unwrap();

        // The node rejects with `R\n` (MigrationRejected) and closes the
        // connection — the read returns EOF right after the rejection.
        let mut response = Vec::new();
        client.read_to_end(&mut response).await.unwrap();
        assert_eq!(response, b"R\n");

        // Give any (wrongly) spawned migration a chance to dial out.
        tokio::time::sleep(Duration::from_millis(50)).await;
        assert!(
            !attacker_connected.load(Ordering::SeqCst),
            "a rejected M must never stream keys to the attacker address"
        );

        attacker_task.abort();
        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_re_acks_a_duplicate_m_for_the_same_joining_node() {
        // Regression: a discovery retry of `M` after a lost ack
        // (`send_migrate_with_retry`) used to hit the same `R\n` rejection
        // as a genuinely conflicting migration, burning the retry's fixed
        // attempt budget against the still-running original handoff and
        // stalling the join until discovery's own migration timeout. It
        // must instead be re-acked with the same entry count, and only one
        // migration must ever run.
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;

        // A fake joining node: accepts exactly one connection. If the
        // duplicate `M` wrongly started a second migration, a second SET
        // would arrive here and the assertion on `joining_received` below
        // would see it duplicated.
        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let joining_received: Arc<std::sync::Mutex<Vec<u8>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let joining_received_task = Arc::clone(&joining_received);
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let bytes_read = connection.read(&mut buffer).await.unwrap();
            joining_received_task
                .lock()
                .unwrap()
                .extend_from_slice(&buffer[..bytes_read]);
            connection.write_all(b"S\n").await.unwrap();
        });

        // A fake discovery server: accepts one connection, expects one C
        // (not two — only one migration should ever run), acks it.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();
        let discovery_task = tokio::spawn(async move {
            let (mut connection, _) = discovery_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let bytes_read = connection.read(&mut buffer).await.unwrap();
            connection.write_all(b"A\n").await.unwrap();
            buffer[..bytes_read].to_vec()
        });

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        let joining_name = "joiner-107";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-107";
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            joining_name.len(),
            joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(joining_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());

        client.write_all(&migrate_message).await.unwrap();
        let mut ack = [0u8; 4];
        client.read_exact(&mut ack).await.unwrap();
        assert_eq!(&ack, b"A 1\n");

        // The discovery retry: identical `M`, sent only after the first
        // ack was read, so the original `M`'s handler has already stamped
        // `acked_entries` by the time this one is processed.
        client.write_all(&migrate_message).await.unwrap();
        let mut second_ack = [0u8; 4];
        client.read_exact(&mut second_ack).await.unwrap();
        assert_eq!(
            &second_ack, b"A 1\n",
            "a duplicate M for the same joining node must be re-acked with the same count"
        );

        let complete = discovery_task.await.unwrap();
        assert_eq!(
            complete,
            // Tenth-pass audit (2026-09-02), issue #421(c): this test's
            // own `M` (above) carries no generation field — the legacy
            // form an old, not-yet-upgraded discovery server sends — so
            // the `C` it produces must fall back to the legacy,
            // generation-free form too.
            complete_message("ready-node", "joiner-107", "tk-ready-node", None),
            "exactly one migration must run and report completion"
        );

        joining_task.await.unwrap();
        // Issue #266: run_migration's own bulk transfer now sends a
        // put-if-absent `U … A`, not a plain `S` — see its doc comment.
        let expected_set = handoff_message(&key(b"name"), b"Alice", None, true, joining_token);
        assert_eq!(
            *joining_received.lock().unwrap(),
            expected_set,
            "the joining node must receive the transfer exactly once"
        );

        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_accepts_a_different_joining_node_once_the_handoff_completed() {
        // Issue #62: a completed handoff (still within its forwarding
        // window) must not block the next join — discovery serializes
        // joins, so a second `M` means the first join was decided. (A
        // genuinely in-flight conflict is still rejected — see
        // `migration_guard_rejects_a_still_active_conflicting_migration`.)
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        // No keys in the cache: the active migration has nothing to
        // transfer, so it needs no joining-node connection at all — only
        // a discovery connection to report `C` on. Its slot stays
        // occupied by "joiner-a" for `forwarding_grace(0)` (60s base)
        // after completion, long past this test's lifetime.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();
        let discovery_task = tokio::spawn(async move {
            let (mut connection, _) = discovery_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let _ = connection.read(&mut buffer).await.unwrap();
            connection.write_all(b"A\n").await.unwrap();
        });

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        let first_joining_addr = "127.0.0.1:1";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-a";
        let mut first_migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            "joiner-a".len(),
            first_joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        first_migrate_message.extend_from_slice(token.as_bytes());
        first_migrate_message.extend_from_slice(b"joiner-a");
        first_migrate_message.extend_from_slice(first_joining_addr.as_bytes());
        first_migrate_message.extend_from_slice(joining_token.as_bytes());

        client.write_all(&first_migrate_message).await.unwrap();
        let mut first_ack = [0u8; 4];
        client.read_exact(&mut first_ack).await.unwrap();
        assert_eq!(&first_ack, b"A 0\n");

        let second_joining_addr = "127.0.0.1:2";
        let second_joining_token = "tok-joiner-b";
        let mut second_migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            "joiner-b".len(),
            second_joining_addr.len(),
            second_joining_token.len(),
            token.len()
        )
        .into_bytes();
        second_migrate_message.extend_from_slice(token.as_bytes());
        second_migrate_message.extend_from_slice(b"joiner-b");
        second_migrate_message.extend_from_slice(second_joining_addr.as_bytes());
        second_migrate_message.extend_from_slice(second_joining_token.as_bytes());

        // Only once the first handoff has reported `C` (its slot is
        // stamped completed before that report goes out).
        discovery_task.await.unwrap();

        client.write_all(&second_migrate_message).await.unwrap();
        let mut second_ack = [0u8; 4];
        client.read_exact(&mut second_ack).await.unwrap();
        assert_eq!(
            &second_ack, b"A 0\n",
            "an M for the next joining node must be accepted once the previous handoff completed"
        );

        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    fn completed_forwarding_slot(marked: &[&str]) -> ActiveMigration {
        ActiveMigration {
            joining_name: "joiner-0".to_string(),
            joining_addr: "127.0.0.1:9".to_string(),
            joining_token: "tok-joiner-0".to_string(),
            after_ring: Arc::new(HashRing::new(vec![
                "ready-node".to_string(),
                "joiner-0".to_string(),
            ])),
            replication: 2,
            generation: None,
            completed_at: Some(Instant::now()),
            forwarding_grace: forwarding_grace(0),
            acked_entries: Some(0),
            abort_requested: Arc::new(AtomicBool::new(false)),
            marked_keys: marked
                .iter()
                .map(|key| Key::from(Bytes::copy_from_slice(key.as_bytes())))
                .collect(),
            confirmed: false,
            pre_completion_ring: None,
            pending_clears: PendingClears::default(),
            forward_connection: Arc::new(AsyncMutex::new(None)),
            forward_revoked: Arc::new(AtomicBool::new(false)),
            lingering: Vec::new(),
            remnant: false,
        }
    }

    fn new_guard_for_joiner_1(
        slot: &Arc<Mutex<Option<ActiveMigration>>>,
        joined: &[(String, String)],
        known_ring: &KnownRing,
    ) -> MigrationOutcome {
        MigrationGuard::new(
            Arc::clone(slot),
            "joiner-1".to_string(),
            "127.0.0.1:10".to_string(),
            "tok-joiner-1".to_string(),
            Arc::new(HashRing::new(vec![
                "ready-node".to_string(),
                "joiner-1".to_string(),
            ])),
            2,
            None,
            joined,
            known_ring,
            &RingHistory::default(),
        )
    }

    #[test]
    fn migration_guard_accepts_the_next_join_while_a_completed_handoff_is_still_forwarding() {
        // Issue #62: back-to-back joins. The previous joiner is in the new
        // `M`'s roster, so its dead copies stay marked (nothing to
        // restore) and the slot moves on to the new joiner.
        let slot = Arc::new(Mutex::new(Some(completed_forwarding_slot(&["dead"]))));
        let joined = vec![
            ("ready-node".to_string(), "127.0.0.1:1".to_string()),
            ("joiner-0".to_string(), "127.0.0.1:9".to_string()),
        ];
        let known_ring: KnownRing = Arc::new(Mutex::new(None));

        // Kept alive: dropping an uncompleted guard clears the slot.
        let _guard = match new_guard_for_joiner_1(&slot, &joined, &known_ring) {
            MigrationOutcome::New { restore, guard } => {
                assert!(restore.is_empty());
                guard
            }
            _ => panic!("expected a new guard"),
        };
        assert_eq!(
            slot.lock().unwrap().as_ref().unwrap().joining_name,
            "joiner-1"
        );
    }

    #[test]
    fn migration_guard_restores_dead_copies_of_a_handoff_whose_joiner_never_joined() {
        // Issue #62: the new `M`'s roster lacks the previous joiner — that
        // join was abandoned (and this node missed the `X`), so the keys
        // it marked dead are handed back to be unmarked.
        let slot = Arc::new(Mutex::new(Some(completed_forwarding_slot(&[
            "dead-a", "dead-b",
        ]))));
        let joined = vec![("ready-node".to_string(), "127.0.0.1:1".to_string())];
        let known_ring: KnownRing = Arc::new(Mutex::new(None));

        let _guard = match new_guard_for_joiner_1(&slot, &joined, &known_ring) {
            MigrationOutcome::New { restore, guard } => {
                assert_eq!(restore, vec![key(b"dead-a"), key(b"dead-b")]);
                guard
            }
            _ => panic!("expected a new guard"),
        };
        assert_eq!(
            slot.lock().unwrap().as_ref().unwrap().joining_name,
            "joiner-1"
        );
    }

    #[test]
    fn an_unconfirmed_completed_slot_outlives_its_grace_but_stops_forwarding() {
        // Issue #62: past the grace, forwarding is over, but the slot (and
        // so its marks) stays until the join is decided.
        let (request_tx, _request_rx) = mpsc::channel(1);
        let node_context = NodeContext {
            gates: Default::default(),
            name: "ready-node".to_string(),
            token: "tk-ready-node".to_string(),
            discovery_addr: "127.0.0.1:1".to_string(),
            active_migration: Arc::new(Mutex::new(None)),
            known_ring: Arc::new(Mutex::new(None)),
            latest_published: Arc::new(Mutex::new(None)),
            roster_refresh: Arc::default(),
            promoted: Arc::new(AtomicBool::new(true)),
            auth_secret: None,
            tls_connector: None,
            request_tx,
            leaving: Arc::new(Mutex::new(None)),
            active_rereplication: Arc::new(Mutex::new(None)),
            ring_history: RingHistory::default(),
            rereplication_tx: mpsc::channel(1).0,
            rereplication_forward: Arc::new(Mutex::new(None)),
            shutdown_rx: watch::channel(false).1,
        };
        let mut stale = completed_forwarding_slot(&["dead"]);
        stale.completed_at = Some(Instant::now() - forwarding_grace(0) - Duration::from_secs(1));
        *node_context.active_migration.lock().unwrap() = Some(stale);

        assert!(migration_targets_for(&node_context, &key(b"key-0")).is_empty());
        assert!(
            node_context.active_migration.lock().unwrap().is_some(),
            "an unconfirmed slot must keep holding its marks"
        );

        // Once confirmed, the same stale slot is cleared lazily as before.
        node_context
            .active_migration
            .lock()
            .unwrap()
            .as_mut()
            .unwrap()
            .confirmed = true;
        assert!(migration_targets_for(&node_context, &key(b"key-0")).is_empty());
        assert!(node_context.active_migration.lock().unwrap().is_none());
    }

    #[test]
    fn adopt_membership_confirms_a_completed_handoff_once_the_roster_lists_its_joiner() {
        let known_ring: KnownRing = Arc::new(Mutex::new(None));
        let slot: Arc<Mutex<Option<ActiveMigration>>> =
            Arc::new(Mutex::new(Some(completed_forwarding_slot(&["dead"]))));

        // Roster without the joiner: neither adopted nor confirmed.
        adopt_membership(&known_ring, &slot, "d", vec!["ready-node".to_string()], 2);
        assert!(!slot.lock().unwrap().as_ref().unwrap().confirmed);
        assert!(known_ring.lock().unwrap().is_none());

        // Roster with the joiner: both.
        adopt_membership(
            &known_ring,
            &slot,
            "d",
            vec!["joiner-0".to_string(), "ready-node".to_string()],
            2,
        );
        assert!(slot.lock().unwrap().as_ref().unwrap().confirmed);
        assert!(known_ring.lock().unwrap().is_some());
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_cancel_after_completion_restores_the_dead_copies() {
        // Issue #62: this node finished its share (the key is marked dead)
        // and reported `C`; discovery then abandons the join (another
        // source couldn't take the `M`) and sends `X`. The copy must come
        // back — and must not have been swept in the meantime.
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;

        // A fake joining node that acks the one SET.
        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let _ = connection.read(&mut buffer).await.unwrap();
            connection.write_all(b"S\n").await.unwrap();
        });

        // A fake discovery server that acks the `C`, and signals it.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();
        let (completed_tx, completed_rx) = oneshot::channel();
        let discovery_task = tokio::spawn(async move {
            let (mut connection, _) = discovery_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let _ = connection.read(&mut buffer).await.unwrap();
            connection.write_all(b"A\n").await.unwrap();
            completed_tx.send(()).unwrap();
        });

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });
        let active_migration: Arc<Mutex<Option<ActiveMigration>>> = Arc::new(Mutex::new(None));

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::clone(&active_migration),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        // R=1, so the sender is displaced: "name" is marked dead once sent.
        let joining_name = "joiner-107";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-107";
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            joining_name.len(),
            joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(joining_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());
        client.write_all(&migrate_message).await.unwrap();
        let mut ack = [0u8; 4];
        client.read_exact(&mut ack).await.unwrap();
        assert_eq!(&ack, b"A 1\n");

        completed_rx.await.unwrap();
        joining_task.await.unwrap();
        discovery_task.await.unwrap();
        // `completed()` runs right after `C` is acked; wait for the stamp.
        for _ in 0..200 {
            if active_migration
                .lock()
                .unwrap()
                .as_ref()
                .is_some_and(|active| active.completed_at.is_some())
            {
                break;
            }
            sleep(Duration::from_millis(5)).await;
        }
        {
            let slot = active_migration.lock().unwrap();
            let active = slot.as_ref().expect("the completed slot must linger");
            assert!(active.completed_at.is_some());
            assert!(!active.confirmed);
            assert_eq!(active.marked_keys, vec![key(b"name")]);
        }
        // What `run_sweep` does while the join is undecided: TTL only.
        assert_eq!(
            send_command(
                &request_tx,
                Command::Sweep {
                    marked: false,
                    owned: None
                }
            )
            .await,
            Response::Swept(0)
        );

        let mut cancel_message = format!("X {} {}\n", joining_name.len(), token.len()).into_bytes();
        cancel_message.extend_from_slice(token.as_bytes());
        cancel_message.extend_from_slice(joining_name.as_bytes());
        client.write_all(&cancel_message).await.unwrap();
        let mut cancel_ack = [0u8; 2];
        client.read_exact(&mut cancel_ack).await.unwrap();
        assert_eq!(&cancel_ack, b"A\n");

        assert!(active_migration.lock().unwrap().is_none());
        // The mark is gone: a full sweep reclaims nothing and the key is
        // still served.
        assert_eq!(
            send_command(
                &request_tx,
                Command::Sweep {
                    marked: true,
                    owned: None
                }
            )
            .await,
            Response::Swept(0)
        );
        assert_eq!(
            send_command(&request_tx, Command::Get { key: key(b"name") }).await,
            Response::Value(Bytes::from_static(b"Alice"))
        );

        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_cancelled_mid_transfer_rolls_back_marks_and_skips_completion() {
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;

        // A fake joining node: accepts the SET but withholds its ack until
        // told to, via `release_rx` — so the test can be sure `X` is fully
        // processed before `run_migration`'s `set_on_joining_node` call
        // for this key ever returns, making this deterministic regardless
        // of relative timing.
        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let (set_received_tx, set_received_rx) = oneshot::channel();
        let (release_tx, release_rx) = oneshot::channel::<()>();
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let _ = connection.read(&mut buffer).await.unwrap();
            set_received_tx.send(()).unwrap();
            release_rx.await.unwrap();
            connection.write_all(b"S\n").await.unwrap();
        });

        // A fake discovery server: must receive nothing — a cancelled
        // migration doesn't report completion.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        // Stands in for `run`'s own loop, which is what normally drains
        // `migration_tx` and spawns what it receives (see
        // `ConnectionConfig::migration_tx`) — `handle_connection` itself no
        // longer spawns `run_migration` directly.
        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        // Chosen so HRW ranks it above "ready-node" for both test keys
        // ("name", "age") — the transfer set must be non-empty.
        let joining_name = "joiner-107";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-107";
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            joining_name.len(),
            joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(joining_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());

        client.write_all(&migrate_message).await.unwrap();

        let mut ack = [0u8; 4];
        client.read_exact(&mut ack).await.unwrap();
        assert_eq!(&ack, b"A 1\n");

        // The joining node has the SET in hand but hasn't acked it yet, so
        // `run_migration` is still blocked on that ack — send the cancel
        // now, on the same connection (a fresh one-shot connection, as
        // discovery would really use, is equivalent from the node's side).
        set_received_rx.await.unwrap();

        let mut cancel_message = format!("X {} {}\n", joining_name.len(), token.len()).into_bytes();
        cancel_message.extend_from_slice(token.as_bytes());
        cancel_message.extend_from_slice(joining_name.as_bytes());
        client.write_all(&cancel_message).await.unwrap();

        let mut cancel_ack = [0u8; 2];
        client.read_exact(&mut cancel_ack).await.unwrap();
        assert_eq!(&cancel_ack, b"A\n");

        // Only now let the joining node's ack through, so `run_migration`
        // resumes with `abort_requested` already set.
        release_tx.send(()).unwrap();
        joining_task.await.unwrap();

        // Nothing should ever connect to "discovery" — poll briefly for
        // the absence of a connection rather than asserting instantly.
        let no_completion_reported =
            timeout(Duration::from_millis(200), discovery_listener.accept())
                .await
                .is_err();
        assert!(
            no_completion_reported,
            "a cancelled migration must not report completion"
        );

        assert_eq!(
            send_command(&request_tx, Command::Get { key: key(b"name") }).await,
            Response::Value(Bytes::from_static(b"Alice"))
        );
        assert_eq!(
            send_command(
                &request_tx,
                Command::Sweep {
                    marked: true,
                    owned: None
                }
            )
            .await,
            Response::Swept(0)
        );

        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_reuses_one_connection_for_every_key() {
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;
        send_command(
            &request_tx,
            Command::Set {
                key: key(b"age"),
                value: Bytes::from_static(b"30"),
                ttl: None,
            },
        )
        .await;

        // A fake joining node: accepts exactly one connection and expects
        // both SETs on it — `run_migration` must reuse one connection
        // across keys rather than reconnecting per key (see its own doc
        // comment on the ephemeral-port exhaustion that used to cause).
        let joining_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = joining_listener.local_addr().unwrap().to_string();
        let joining_received: Arc<std::sync::Mutex<Vec<u8>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let joining_received_task = Arc::clone(&joining_received);
        let joining_task = tokio::spawn(async move {
            let (mut connection, _) = joining_listener.accept().await.unwrap();

            for _ in 0..2 {
                let mut buffer = [0u8; 256];
                let bytes_read = connection.read(&mut buffer).await.unwrap();
                joining_received_task
                    .lock()
                    .unwrap()
                    .extend_from_slice(&buffer[..bytes_read]);
                connection.write_all(b"S\n").await.unwrap();
            }

            let second_connection =
                timeout(Duration::from_millis(200), joining_listener.accept()).await;
            assert!(
                second_connection.is_err(),
                "expected the same connection to be reused for both keys"
            );
        });

        // A fake discovery server: accepts one connection, expects C, acks
        // it.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();
        let discovery_received: Arc<std::sync::Mutex<Vec<u8>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let discovery_received_task = Arc::clone(&discovery_received);
        let discovery_task = tokio::spawn(async move {
            let (mut connection, _) = discovery_listener.accept().await.unwrap();
            let mut buffer = [0u8; 256];
            let bytes_read = connection.read(&mut buffer).await.unwrap();
            discovery_received_task
                .lock()
                .unwrap()
                .extend_from_slice(&buffer[..bytes_read]);
            connection.write_all(b"A\n").await.unwrap();
        });

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        // Stands in for `run`'s own loop, which is what normally drains
        // `migration_tx` and spawns what it receives (see
        // `ConnectionConfig::migration_tx`) — `handle_connection` itself no
        // longer spawns `run_migration` directly.
        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        // Chosen so HRW ranks it above "ready-node" for both test keys
        // ("name", "age") — the transfer set must be non-empty.
        let joining_name = "joiner-107";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-107";
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            joining_name.len(),
            joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(joining_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());

        client.write_all(&migrate_message).await.unwrap();

        let mut ack = [0u8; 4];
        client.read_exact(&mut ack).await.unwrap();
        assert_eq!(&ack, b"A 2\n");

        for _ in 0..1000 {
            if !discovery_received.lock().unwrap().is_empty() {
                break;
            }
            tokio::time::sleep(Duration::from_millis(1)).await;
        }

        // Issue #266: run_migration's own bulk transfer now sends a
        // put-if-absent `U … A`, not a plain `S` — see its doc comment.
        let expected_name = handoff_message(&key(b"name"), b"Alice", None, true, joining_token);
        let expected_age = handoff_message(&key(b"age"), b"30", None, true, joining_token);
        let received = joining_received.lock().unwrap().clone();
        assert!(
            received
                .windows(expected_name.len())
                .any(|window| window == expected_name.as_slice()),
            "expected the joining node to receive the SET for \"name\""
        );
        assert!(
            received
                .windows(expected_age.len())
                .any(|window| window == expected_age.as_slice()),
            "expected the joining node to receive the SET for \"age\""
        );
        assert_eq!(
            *discovery_received.lock().unwrap(),
            // This test's own `M` (below) is the legacy, generation-free
            // form (issue #421(c)) — see the analogous note on
            // `migrate_command_re_acks_a_duplicate_m_for_the_same_joining_node`.
            complete_message("ready-node", "joiner-107", "tk-ready-node", None)
        );

        joining_task.await.unwrap();
        discovery_task.await.unwrap();
        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    #[tokio::test(flavor = "current_thread")]
    async fn migrate_command_gives_up_and_rolls_back_after_permanent_transfer_failure() {
        let (request_tx, request_rx) = mpsc::channel(1);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        send_command(
            &request_tx,
            Command::Set {
                key: key(b"name"),
                value: Bytes::from_static(b"Alice"),
                ttl: None,
            },
        )
        .await;

        // A joining node address nothing is listening on: every connect
        // attempt fails immediately, so `run_migration` exhausts
        // `KEY_TRANSFER_ATTEMPTS` and gives up on the whole migration.
        let dead_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let joining_addr = dead_listener.local_addr().unwrap().to_string();
        drop(dead_listener);

        // A fake discovery server: must receive nothing — a migration
        // that permanently failed to transfer a key must not report
        // completion.
        let discovery_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = discovery_listener.local_addr().unwrap().to_string();

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);

        // Stands in for `run`'s own loop, which is what normally drains
        // `migration_tx` and spawns what it receives (see
        // `ConnectionConfig::migration_tx`) — `handle_connection` itself no
        // longer spawns `run_migration` directly.
        let (migration_tx, mut migration_rx) = mpsc::channel::<MigrationTask>(1);
        let migration_relay = tokio::spawn(async move {
            while let Some(task) = migration_rx.recv().await {
                task.await;
            }
        });

        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(NodeContext {
                    gates: Default::default(),
                    name: "ready-node".to_string(),
                    token: "tk-ready-node".to_string(),
                    discovery_addr,
                    active_migration: Arc::new(Mutex::new(None)),
                    known_ring: Arc::new(Mutex::new(None)),
                    latest_published: Arc::new(Mutex::new(None)),
                    roster_refresh: Arc::default(),
                    promoted: Arc::new(AtomicBool::new(true)),
                    auth_secret: None,
                    tls_connector: None,
                    request_tx: request_tx.clone(),
                    leaving: Arc::new(Mutex::new(None)),
                    active_rereplication: Arc::new(Mutex::new(None)),
                    ring_history: RingHistory::default(),
                    rereplication_tx: mpsc::channel(1).0,
                    rereplication_forward: Arc::new(Mutex::new(None)),
                    shutdown_rx: watch::channel(false).1,
                }),
                migration_tx,
                forward_tx: mpsc::channel(1).0,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx.clone(),
        ));

        // Chosen so HRW ranks it above "ready-node" for both test keys
        // ("name", "age") — the transfer set must be non-empty.
        let joining_name = "joiner-107";
        let token = "tk-ready-node";
        let joining_token = "tok-joiner-107";
        let mut migrate_message = format!(
            "M {} {} {} 0 1 {}\n",
            joining_name.len(),
            joining_addr.len(),
            joining_token.len(),
            token.len()
        )
        .into_bytes();
        migrate_message.extend_from_slice(token.as_bytes());
        migrate_message.extend_from_slice(joining_name.as_bytes());
        migrate_message.extend_from_slice(joining_addr.as_bytes());
        migrate_message.extend_from_slice(joining_token.as_bytes());

        client.write_all(&migrate_message).await.unwrap();

        let mut ack = [0u8; 4];
        client.read_exact(&mut ack).await.unwrap();
        assert_eq!(&ack, b"A 1\n");

        // Nothing should ever connect to "discovery".
        let no_completion_reported =
            timeout(Duration::from_millis(200), discovery_listener.accept())
                .await
                .is_err();
        assert!(
            no_completion_reported,
            "a migration that permanently failed to transfer a key must not report completion"
        );

        assert_eq!(
            send_command(&request_tx, Command::Get { key: key(b"name") }).await,
            Response::Value(Bytes::from_static(b"Alice"))
        );
        assert_eq!(
            send_command(
                &request_tx,
                Command::Sweep {
                    marked: true,
                    owned: None
                }
            )
            .await,
            Response::Swept(0)
        );

        client.shutdown().await.unwrap();
        let _ = connection_task.await;
        migration_relay.await.unwrap();
        drop(request_tx);
        cache_task.await.unwrap();
    }

    /// Parses a `J <name-length> <port> <token-length>\n<name><token>`
    /// message (the only one whose shape the test doesn't already know,
    /// since its name is a random UUID generated inside `send_heartbeats`)
    /// and asserts every subsequent message in `received` is the matching
    /// `H <name-length> <r> <token-length>\n<name><token>` heartbeat for
    /// that same name and token — `r=0` (unknown), since none of these
    /// tests give it a `KnownRing` with a membership belief set.
    fn assert_join_then_heartbeats(received: &[Vec<u8>], port: u16) {
        assert!(
            received.len() >= 4,
            "expected a join plus at least 3 heartbeats, got {}",
            received.len()
        );

        let join = String::from_utf8(received[0].clone()).unwrap();
        let header_end = join.find('\n').unwrap();
        let mut header = join[..header_end].split(' ');
        assert_eq!(header.next(), Some("J"));

        let name_length: usize = header.next().unwrap().parse().unwrap();
        let sent_port: u16 = header.next().unwrap().parse().unwrap();
        let token_length: usize = header.next().unwrap().parse().unwrap();
        assert_eq!(header.next(), None);
        assert_eq!(sent_port, port);

        let body = &join[header_end + 1..];
        let name = &body[..name_length];
        let token = &body[name_length..];
        assert_eq!(body.len(), name_length + token_length);

        let expected_heartbeat = format!("H {} 0 {}\n{name}{token}", name.len(), token.len());
        for message in &received[1..] {
            assert_eq!(message, expected_heartbeat.as_bytes());
        }
    }

    #[tokio::test(flavor = "current_thread")]
    async fn send_heartbeats_stops_immediately_when_already_shut_down() {
        let (_shutdown_tx, shutdown_rx) = watch::channel(true);
        // Explicit `let` + `drop`, not `mpsc::channel(4).1` inline: a
        // discarded temporary in the argument list of a directly
        // `.await`ed call lives until the `.await` completes (Rust's
        // temporary-lifetime-extension rule for `f(..).await;`), so the
        // sender half would stay alive for this whole call — keeping
        // `rereplication_rx` open and `send_heartbeats` waiting on it
        // forever, well past when `tasks` empties. Every other
        // `send_heartbeats` test sidesteps this by wrapping the call in
        // `tokio::spawn(..)`, which is never itself `.await`ed.
        let (rereplication_tx, rereplication_rx) = mpsc::channel::<RereplicationTask>(4);
        drop(rereplication_tx);

        send_heartbeats(
            HeartbeatConfig {
                discovery_addrs: vec!["127.0.0.1:1".to_string()],
                port: 8356,
                interval: Duration::from_secs(60),
                auth_secret: None,
                tls_connector: None,
            },
            test_node_context(
                "test-node",
                "tk-test-node",
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
            ),
            rereplication_rx,
            shutdown_rx,
        )
        .await;
    }

    #[tokio::test(flavor = "current_thread")]
    async fn send_heartbeats_sends_periodic_heartbeats_on_one_connection() {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let discovery_addr = listener.local_addr().unwrap().to_string();

        let received: Arc<std::sync::Mutex<Vec<Vec<u8>>>> =
            Arc::new(std::sync::Mutex::new(Vec::new()));
        let fake_discovery_received = Arc::clone(&received);

        let fake_discovery = tokio::spawn(async move {
            let (mut connection, _) = listener.accept().await.unwrap();
            let mut buffer = [0u8; 128];
            let mut first = true;

            loop {
                match connection.read(&mut buffer).await {
                    Ok(0) | Err(_) => return,
                    Ok(bytes_read) => {
                        fake_discovery_received
                            .lock()
                            .unwrap()
                            .push(buffer[..bytes_read].to_vec());

                        // The first message is J (join); every one after
                        // that is H (heartbeat, once promoted).
                        let ack: &[u8] = if first { b"R\n" } else { b"A\n" };
                        first = false;

                        if connection.write_all(ack).await.is_err() {
                            return;
                        }
                    }
                }
            }
        });

        let (shutdown_tx, shutdown_rx) = watch::channel(false);
        let heartbeat_task = tokio::spawn(send_heartbeats(
            HeartbeatConfig {
                discovery_addrs: vec![discovery_addr],
                port: 8356,
                interval: Duration::from_millis(20),
                auth_secret: None,
                tls_connector: None,
            },
            test_node_context(
                "test-node",
                "tk-test-node",
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
            ),
            mpsc::channel::<RereplicationTask>(4).1,
            shutdown_rx,
        ));

        sleep(Duration::from_millis(150)).await;

        shutdown_tx.send_replace(true);
        heartbeat_task.await.unwrap();
        fake_discovery.abort();

        assert_join_then_heartbeats(&received.lock().unwrap(), 8356);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn abandon_wait_for_a_still_transferring_slot_stops_at_shutdown() {
        let slot = Arc::new(Mutex::new(Some(test_active_migration(None))));
        let (shutdown_tx, shutdown_rx) = watch::channel(false);
        let mut node_context = test_node_context(
            "test-node",
            "tk-test-node",
            Arc::new(Mutex::new(None)),
            Arc::clone(&slot),
        );
        node_context.shutdown_rx = shutdown_rx;

        let waiter = tokio::spawn(async move {
            let started = Instant::now();
            wait_for_migration_slot_to_clear(&node_context, "joiner-0").await;
            started.elapsed()
        });

        sleep(Duration::from_millis(250)).await;
        assert!(
            !waiter.is_finished(),
            "the slot is still held, so the wait must still be polling"
        );
        shutdown_tx.send_replace(true);

        let waited = timeout(Duration::from_secs(2), waiter)
            .await
            .expect("the wait must return promptly once shutdown is signalled")
            .unwrap();
        assert!(
            waited < MIGRATION_ABANDON_DRAIN_WAIT,
            "shutdown must cut the wait short of its {}s bound (took {waited:?})",
            MIGRATION_ABANDON_DRAIN_WAIT.as_secs()
        );
        assert!(
            slot.lock().unwrap().is_some(),
            "stopping at shutdown must not clear the slot itself"
        );
    }

    /// Issue #474: every way a slot stops being the handoff this node
    /// forwards for must revoke the forwards already resolved against it.
    #[test]
    fn abandoning_a_handoff_revokes_its_queued_forwards() {
        for completed_at in [None, Some(Instant::now())] {
            let slot = Arc::new(Mutex::new(Some(test_active_migration(completed_at))));
            let revoked = Arc::clone(&slot.lock().unwrap().as_ref().unwrap().forward_revoked);
            let node_context = test_node_context(
                "test-node",
                "tk-test-node",
                Arc::new(Mutex::new(None)),
                Arc::clone(&slot),
            );

            abandon_migration(&node_context, "joiner-0");

            assert!(
                revoked.load(Ordering::SeqCst),
                "abandon must revoke forwards (completed_at={completed_at:?})"
            );
        }
    }

    /// Issue #474, narrowed by #564: a superseded handoff keeps forwarding
    /// only when its join was confirmed, its grace is open, and it is not
    /// the same joiner restarting (possibly at another address). In every
    /// other case the forwards already resolved against it must be revoked.
    #[test]
    fn superseding_a_handoff_that_is_not_kept_revokes_its_queued_forwards() {
        // (previous confirmed and listed in the roster?, joiner name of the
        // new `M`)
        for (confirmed, new_name) in [(false, "joiner-1"), (true, "joiner-0")] {
            let mut previous = test_active_migration(Some(Instant::now()));
            previous.confirmed = confirmed;
            // A generation, so that the same name at generation 2 is a new
            // join rather than a retry of this one.
            previous.generation = Some(1);
            let revoked = Arc::clone(&previous.forward_revoked);
            let slot = Arc::new(Mutex::new(Some(previous)));
            let known_ring: KnownRing = Arc::new(Mutex::new(None));
            let joined = vec![("test-node".to_string(), "127.0.0.1:1".to_string())];

            let outcome = MigrationGuard::new(
                Arc::clone(&slot),
                new_name.to_string(),
                "127.0.0.1:10".to_string(),
                "tok-new".to_string(),
                Arc::new(HashRing::new(vec![
                    "test-node".to_string(),
                    new_name.to_string(),
                ])),
                2,
                Some(2),
                &joined,
                &known_ring,
                &RingHistory::default(),
            );

            assert!(matches!(outcome, MigrationOutcome::New { .. }));
            assert!(
                revoked.load(Ordering::SeqCst),
                "the superseded slot's forwards must be revoked \
                 (confirmed={confirmed}, new joiner {new_name})"
            );
            assert!(
                slot.lock().unwrap().as_ref().unwrap().lingering.is_empty(),
                "nothing may linger (confirmed={confirmed}, new joiner {new_name})"
            );
            let fresh = Arc::clone(&slot.lock().unwrap().as_ref().unwrap().forward_revoked);
            assert!(
                !fresh.load(Ordering::SeqCst),
                "the new slot starts un-revoked"
            );
        }
    }

    /// The counterpart: a confirmed handoff whose grace is open and whose
    /// joiner is a different node is *not* revoked when the next `M` takes
    /// the slot (issue #564); it moves to `lingering` with the same flag.
    #[test]
    fn superseding_a_confirmed_handoff_inside_its_grace_does_not_revoke_it() {
        let mut previous = test_active_migration(Some(Instant::now()));
        previous.confirmed = true;
        let revoked = Arc::clone(&previous.forward_revoked);
        let slot = Arc::new(Mutex::new(Some(previous)));
        let known_ring: KnownRing = Arc::new(Mutex::new(None));
        let joined = vec![
            ("test-node".to_string(), "127.0.0.1:1".to_string()),
            ("joiner-0".to_string(), "127.0.0.1:9".to_string()),
        ];

        let outcome = MigrationGuard::new(
            Arc::clone(&slot),
            "joiner-1".to_string(),
            "127.0.0.1:10".to_string(),
            "tok-joiner-1".to_string(),
            Arc::new(HashRing::new(vec![
                "test-node".to_string(),
                "joiner-0".to_string(),
                "joiner-1".to_string(),
            ])),
            2,
            None,
            &joined,
            &known_ring,
            &RingHistory::default(),
        );

        assert!(matches!(outcome, MigrationOutcome::New { .. }));
        assert!(
            !revoked.load(Ordering::SeqCst),
            "a joiner still owed its forwarding window must not be revoked"
        );
        let guard = slot.lock().unwrap();
        let active = guard.as_ref().unwrap();
        assert_eq!(active.lingering.len(), 1);
        assert!(Arc::ptr_eq(&active.lingering[0].forward_revoked, &revoked));
        assert!(
            !active.forward_revoked.load(Ordering::SeqCst),
            "the new slot starts un-revoked"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn multi_key_frames_hash_the_namespace_once_not_once_per_key() {
        // A namespace may be ~1 MiB and every key of an `m`/`o` frame
        // shares it. The ownership checks (`wrong_node`,
        // `migration_target_for`, `leave_target_for`) used to FNV the
        // whole namespace per key, so one frame of tiny keys cost
        // (keys x namespace length) of hashing on the single thread.
        // Counted in FNV'd bytes, not wall-clock.
        const NAMESPACE_LEN: usize = 20_000;
        const KEYS: usize = 200;

        let (request_tx, request_rx) = mpsc::channel(4);
        let cache_task = tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

        // A known ring (so `wrong_node` really consults it) and a join
        // handoff in flight whose joiner is in every key's top-R (so the
        // forwarding checks run for every stored key too).
        let known_ring: KnownRing = Arc::new(Mutex::new(Some(Arc::new(Membership {
            ring: Arc::new(HashRing::new(vec!["test-node".to_string()])),
            replication: 1,
        }))));
        let mut active = test_active_migration(None);
        active.acked_entries = None;
        let node_context = test_node_context(
            "test-node",
            "tok-test-node",
            known_ring,
            Arc::new(Mutex::new(Some(active))),
        );

        let namespace = vec![b'n'; NAMESPACE_LEN];
        let names: Vec<String> = (0..KEYS).map(|index| format!("k{index:03}")).collect();
        let names_len: usize = names.iter().map(String::len).sum();

        let mut frames = Vec::new();
        let key_lens: Vec<String> = names.iter().map(|name| name.len().to_string()).collect();
        frames.extend_from_slice(
            format!("m {NAMESPACE_LEN} {KEYS} {}\n", key_lens.join(" ")).as_bytes(),
        );
        frames.extend_from_slice(&namespace);
        for name in &names {
            frames.extend_from_slice(name.as_bytes());
        }
        let pair_lens: Vec<String> = names
            .iter()
            .map(|name| format!("{} 1", name.len()))
            .collect();
        frames.extend_from_slice(
            format!("o {NAMESPACE_LEN} {KEYS} {}\n", pair_lens.join(" ")).as_bytes(),
        );
        frames.extend_from_slice(&namespace);
        for name in &names {
            frames.extend_from_slice(name.as_bytes());
            frames.push(b'v');
        }

        let (mut client, server) = tcp_pair().await;
        let (_shutdown_tx, shutdown_rx) = watch::channel(false);
        // Large enough to take every forward, never drained.
        let (forward_tx, _forward_rx) = mpsc::channel::<MigrationTask>(2 * KEYS);

        let before = crate::hash_ring::hashed_bytes();
        let connection_task = tokio::spawn(handle_connection(
            ServerStream::Plain(server),
            test_client_addr(),
            request_tx.clone(),
            ConnectionConfig {
                idle_timeout: IDLE_TIMEOUT,
                auth_secret: None,
                tls_acceptor: None,
                node_context: Some(node_context),
                migration_tx: mpsc::channel(1).0,
                forward_tx,
                forward_queues: Arc::new(ForwardQueues::default()),
                in_flight_bytes: InFlightBudget::new(DEFAULT_MAX_IN_FLIGHT_BYTES),
            },
            shutdown_rx,
        ));
        client.write_all(&frames).await.unwrap();
        client.shutdown().await.unwrap();
        let mut response = Vec::new();
        client.read_to_end(&mut response).await.unwrap();
        connection_task.await.unwrap().unwrap();
        let hashed = crate::hash_ring::hashed_bytes() - before;
        drop(request_tx);
        cache_task.await.unwrap();

        // Both frames were served (the `o` acked every key as stored).
        assert!(response.starts_with(b"M "), "unexpected reply to the `m`");
        assert!(
            response.windows(3).any(|window| window == b"O 2"),
            "unexpected reply to the `o`"
        );

        // Two frames, each paying the namespace once plus the key names,
        // with slack; per-key hashing would be at least KEYS x NAMESPACE_LEN.
        let per_frame = 4 + NAMESPACE_LEN + names_len;
        assert!(hashed >= NAMESPACE_LEN, "the ring was never consulted");
        assert!(
            hashed <= 2 * per_frame * 2,
            "{hashed} bytes hashed for two frames of {KEYS} keys under a {NAMESPACE_LEN}-byte \
             namespace"
        );
    }

    /// A peer that accepts connections and then never answers: with
    /// `ack_auth` it answers the `A` handshake (`On`) and goes silent on
    /// whatever follows, otherwise it is silent from the start.
    fn spawn_unresponsive_peer(
        listener: TcpListener,
        ack_auth: bool,
    ) -> tokio::task::JoinHandle<()> {
        tokio::spawn(async move {
            let mut held = Vec::new();
            loop {
                let Ok((mut connection, _)) = listener.accept().await else {
                    return;
                };
                if ack_auth {
                    let mut buffer = [0u8; 64];
                    let _ = connection.read(&mut buffer).await;
                    let _ = connection.write_all(b"On\n").await;
                }
                // Held open (never read from again, never answered).
                held.push(connection);
            }
        })
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_dead_copy_is_not_re_replicated_to_the_joiner_whose_handoff_took_it() {
        // Issue #975: while the join is unconfirmed the marks are held and
        // the pass may hand dead copies on (issue #970) — but never to the
        // joiner that took them: it holds the key from the handoff, and a
        // put-if-absent landing after a client expired or deleted it there
        // brought it back. Another new owner still gets the dead copy.
        async fn run(target: &str, confirmed: bool) -> Vec<Vec<u8>> {
            let (request_tx, request_rx) = mpsc::channel(4);
            let cache_task =
                tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));
            // Two members before and after, R=2: node-a owns every key under
            // both rings and `target` is new for every key.
            let before_ring = HashRing::new(vec!["node-a".to_string(), "gone".to_string()]);
            let after_ring = HashRing::new(vec!["node-a".to_string(), target.to_string()]);
            let replication = 2;
            let dead = key(b"dead-copy");
            let live = key(b"live-copy");
            for name in [&dead, &live] {
                send_command(
                    &request_tx,
                    Command::Set {
                        key: name.clone(),
                        value: Bytes::from_static(b"v"),
                        ttl: None,
                    },
                )
                .await;
            }
            send_command(&request_tx, Command::MarkMigrated { key: dead.clone() }).await;

            let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let peer_addr = peer_listener.local_addr().unwrap().to_string();
            let (frames, peer_task) = spawn_rereplication_recording_peer(peer_listener);

            // The handoff that marked `dead` was to "joiner": completed,
            // confirmed or not.
            let slot = ActiveMigration {
                joining_name: "joiner".to_string(),
                joining_addr: peer_addr.clone(),
                joining_token: "tok-joiner".to_string(),
                after_ring: Arc::new(HashRing::new(vec![
                    "node-a".to_string(),
                    "joiner".to_string(),
                ])),
                replication,
                generation: None,
                completed_at: Some(Instant::now()),
                forwarding_grace: Duration::from_secs(60),
                acked_entries: Some(0),
                abort_requested: Arc::new(AtomicBool::new(false)),
                marked_keys: vec![dead.clone()],
                confirmed,
                pre_completion_ring: None,
                pending_clears: PendingClears::default(),
                forward_connection: Arc::new(AsyncMutex::new(None)),
                forward_revoked: Arc::new(AtomicBool::new(false)),
                lingering: Vec::new(),
                remnant: false,
            };
            let mut node_context = test_node_context(
                "node-a",
                "tok-a",
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(Some(slot))),
            );
            node_context.request_tx = request_tx.clone();
            node_context.auth_secret = None;

            let addresses = HashMap::from([(target.to_string(), peer_addr)]);
            let tokens = HashMap::from([(target.to_string(), format!("tok-{target}"))]);
            let abort_requested = Arc::new(AtomicBool::new(false));
            let (_shutdown_tx, mut shutdown_rx) = watch::channel(false);
            run_rereplication(
                &node_context,
                &before_ring,
                &after_ring,
                replication,
                &addresses,
                &tokens,
                &abort_requested,
                &mut shutdown_rx,
            )
            .await;
            tokio::time::sleep(Duration::from_millis(100)).await;

            drop(node_context);
            drop(request_tx);
            cache_task.await.unwrap();
            peer_task.abort();
            frames.lock().unwrap().clone()
        }
        fn keys_in(frames: &[Vec<u8>]) -> Vec<&'static str> {
            ["dead-copy", "live-copy"]
                .into_iter()
                .filter(|name| {
                    frames
                        .iter()
                        .any(|frame| frame.ends_with(format!("{name}v").as_bytes()))
                })
                .collect()
        }

        // Unconfirmed, the target is the joiner: the live copy only.
        assert_eq!(keys_in(&run("joiner", false).await), vec!["live-copy"]);
        // Unconfirmed, another new owner: it gets the dead copy too.
        assert_eq!(
            keys_in(&run("other", false).await),
            vec!["dead-copy", "live-copy"]
        );
        // Confirmed: the marks are released and dead copies stay out either way.
        assert_eq!(keys_in(&run("joiner", true).await), vec!["live-copy"]);
        assert_eq!(keys_in(&run("other", true).await), vec!["live-copy"]);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn run_rereplication_stops_at_shutdown_even_with_a_peer_mid_leg() {
        // The dial/auth leg (silent peer) and the send leg (peer that acks
        // auth, then goes silent) are each bounded by OUTBOUND_IO_TIMEOUT
        // (10 s), but shutdown was only looked at *between* attempts, so
        // an unresponsive target held the exit for a whole leg. Shutdown
        // must now cut the in-flight leg short.
        for ack_auth in [false, true] {
            let (request_tx, request_rx) = mpsc::channel(4);
            let cache_task =
                tokio::spawn(run_cache(request_rx, MAX_CACHE_MEMORY_BYTES, Vec::new()));

            // R=2, node-c evicted: some key's old top-2 is {node-a, node-c},
            // so node-a must send it to node-b.
            let before_ring = HashRing::new(vec![
                "node-a".to_string(),
                "node-b".to_string(),
                "node-c".to_string(),
            ]);
            let after_ring = HashRing::new(vec!["node-a".to_string(), "node-b".to_string()]);
            let replication = 2;
            let stored = (0..500)
                .map(|index| key(format!("key-{index}").as_bytes()))
                .find(|candidate| {
                    rereplication_targets(
                        &before_ring,
                        &after_ring,
                        KeyHash::of(candidate),
                        replication,
                        "node-a",
                    ) == vec!["node-b".to_string()]
                })
                .expect("some key moves to node-b");
            let (response_tx, response_rx) = oneshot::channel();
            request_tx
                .send(CacheRequest {
                    command: Command::Set {
                        key: stored,
                        value: Bytes::from_static(b"v"),
                        ttl: None,
                    },
                    response_tx,
                })
                .await
                .unwrap();
            response_rx.await.unwrap();

            let peer_listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let peer_addr = peer_listener.local_addr().unwrap().to_string();
            let peer_task = spawn_unresponsive_peer(peer_listener, ack_auth);

            let mut node_context = test_node_context(
                "node-a",
                "tok-a",
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
            );
            node_context.request_tx = request_tx.clone();
            node_context.auth_secret = Some(Bytes::from_static(b"secret"));

            let addresses = HashMap::from([("node-b".to_string(), peer_addr)]);
            let tokens = HashMap::from([("node-b".to_string(), "tok-b".to_string())]);
            let abort_requested = Arc::new(AtomicBool::new(false));
            let (shutdown_tx, shutdown_rx) = watch::channel(false);

            let started = Instant::now();
            let rereplication = tokio::spawn({
                let abort_requested = Arc::clone(&abort_requested);
                let mut shutdown_rx = shutdown_rx;
                async move {
                    run_rereplication(
                        &node_context,
                        &before_ring,
                        &after_ring,
                        replication,
                        &addresses,
                        &tokens,
                        &abort_requested,
                        &mut shutdown_rx,
                    )
                    .await;
                }
            });

            // Long enough to be inside the dial/auth or send leg.
            sleep(Duration::from_millis(300)).await;
            assert!(!rereplication.is_finished(), "ack_auth={ack_auth}");
            shutdown_tx.send_replace(true);

            timeout(Duration::from_secs(3), rereplication)
                .await
                .expect(
                    "shutdown must cut the in-flight leg short, not wait out OUTBOUND_IO_TIMEOUT",
                )
                .unwrap();
            assert!(started.elapsed() < Duration::from_secs(3));

            peer_task.abort();
            drop(request_tx);
            cache_task.await.unwrap();
        }
    }

    #[tokio::test(flavor = "current_thread", start_paused = true)]
    async fn join_heartbeat_task_aborts_a_task_that_outlives_the_wait() {
        let stuck = tokio::spawn(std::future::pending::<()>());

        let started = tokio::time::Instant::now();
        join_heartbeat_task(stuck, HEARTBEAT_SHUTDOWN_WAIT)
            .await
            .unwrap();

        assert_eq!(started.elapsed(), HEARTBEAT_SHUTDOWN_WAIT);
    }

    #[tokio::test(flavor = "current_thread", start_paused = true)]
    async fn join_heartbeat_task_returns_as_soon_as_the_task_finishes() {
        let quick = tokio::spawn(async {
            sleep(Duration::from_millis(50)).await;
        });

        let started = tokio::time::Instant::now();
        join_heartbeat_task(quick, HEARTBEAT_SHUTDOWN_WAIT)
            .await
            .unwrap();

        assert!(started.elapsed() < HEARTBEAT_SHUTDOWN_WAIT);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn join_heartbeat_task_still_reports_a_task_that_panicked() {
        let panicked = tokio::spawn(async {
            panic!("heartbeat task panics");
        });

        let error = join_heartbeat_task(panicked, HEARTBEAT_SHUTDOWN_WAIT)
            .await
            .unwrap_err();

        assert!(error.to_string().contains("heartbeat task failed"));
    }

